WW2.events['medal-of-honor'] = [
  {"id": "1941-12-07-van-valkenburgh-franklin", "date": "1941-12-07", "title": "Captain Franklin Van Valkenburgh", "type": "loss", "theater": "Navy", "location": {"name": "Pearl Harbor, Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For conspicuous devotion to duty, extraordinary courage and complete disregard of his own life, during the attack on the Fleet in Pearl Harbor T.H., by Japanese forces on 7 December 1941. As commanding officer of the U.S.S. Arizona, Capt. Van Valkenburgh gallantly fought his ship until the U.S.S. Arizona blew up from magazine explosions and a direct bomb hit on the bridge which resulted in the loss of his life.", "facts": [["Recipient", "Franklin Van Valkenburgh"], ["Rank", "Captain"], ["Service", "Navy"], ["Place of action", "Pearl Harbor, Hawaii"], ["Awarded", "Posthumously"]], "wiki": {"Franklin Van Valkenburgh": "Franklin_Van_Valkenburgh"}},
  {"id": "1941-12-07-bennion-mervyn-s", "date": "1941-12-07", "title": "Captain Mervyn S. Bennion", "type": "loss", "theater": "Navy", "location": {"name": "USS West Virginia (BB-48), Pearl Harbor", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For conspicuous devotion to duty, extraordinary courage, and complete disregard of his own life, above and beyond the call of duty, during the attack on the Fleet in Pearl Harbor, by Japanese forces on 7 December 1941. As Commanding Officer of the USS West Virginia, after being mortally wounded, Capt. Bennion evidenced apparent concern only in fighting and saving his ship, and strongly protested against being carried from the bridge.", "facts": [["Recipient", "Mervyn S. Bennion"], ["Rank", "Captain"], ["Service", "Navy"], ["Place of action", "USS West Virginia (BB-48), Pearl Harbor"], ["Awarded", "Posthumously"]], "wiki": {"Mervyn S. Bennion": "Mervyn_S._Bennion"}},
  {"id": "1941-12-07-finn-john-w", "date": "1941-12-07", "title": "Chief Aviation ordnanceman John W. Finn", "type": "attack", "theater": "Navy", "location": {"name": "Naval Air Station, Kaneohe Bay, Oahu, Hawaii", "lat": 21.4628, "lng": -157.8103}, "zoom": 9, "summary": "For extraordinary heroism, distinguished service, and devotion above and beyond the call of duty. During the first attack by Japanese airplanes on the Naval Air Station, Kaneohe Bay, Territory of Hawaii, on December 7, 1941, he promptly secured and manned a .50 caliber machine gun mounted on an instruction stand in a completely exposed section of the parking ramp, which was under heavy enemy machine gun strafing fire. Although painfully wounded many times, he continued to man this gun and to return the enemy's fire vigorously and with telling effect throughout the enemy strafing and bombing attacks and with complete disregard for his own personal safety. It was only by specific orders that he was persuaded to leave his post to seek medical attention. Following first-aid treatment, although obviously suffering much pain and moving with great difficulty, he returned to the squadron area and actively supervised the rearming of returning planes. …", "facts": [["Recipient", "John W. Finn"], ["Rank", "Chief Aviation ordnanceman"], ["Service", "Navy"], ["Place of action", "Naval Air Station, Kaneohe Bay, Oahu, Hawaii"]], "wiki": {"John W. Finn": "John_William_Finn"}},
  {"id": "1941-12-07-hill-edwin-j", "date": "1941-12-07", "title": "Chief Boatswain Edwin J. Hill", "type": "loss", "theater": "Navy", "location": {"name": "Pearl Harbor, Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For distinguished conduct in the line of his profession, extraordinary courage, and disregard of his own safety during the attack on the Fleet in Pearl Harbor, by Japanese forces on December 7, 1941. During the height of the strafing and bombing, Chief Boatswain Hill led his men of the linehandling details of the U.S.S. Nevada to the quays, cast off the lines and swam back to his ship. Later, while on the forecastle, attempting to let go the anchors, he was blown overboard and killed by the explosion of several bombs.", "facts": [["Recipient", "Edwin J. Hill"], ["Rank", "Chief Boatswain"], ["Service", "Navy"], ["Place of action", "Pearl Harbor, Hawaii"], ["Awarded", "Posthumously"]], "wiki": {"Edwin J. Hill": "Edwin_J._Hill"}},
  {"id": "1941-12-07-reeves-thomas-j", "date": "1941-12-07", "title": "Chief Radioman Thomas J. Reeves", "type": "loss", "theater": "Navy", "location": {"name": "USS California (BB-44), Pearl Harbor", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For distinguished conduct in the line of his profession, extraordinary courage and disregard of his own safety during the attack on the Fleet in Pearl Harbor, by Japanese forces on 7 December 1941. After the mechanized ammunition hoists were put out of action in the U.S.S. California, Reeves, on his own initiative, in a burning passageway, assisted in the maintenance of an ammunition supply by hand to the antiaircraft guns until he was overcome by smoke and fire, which resulted in his death.", "facts": [["Recipient", "Thomas J. Reeves"], ["Rank", "Chief Radioman"], ["Service", "Navy"], ["Place of action", "USS California (BB-44), Pearl Harbor"], ["Awarded", "Posthumously"]], "wiki": {"Thomas J. Reeves": "Thomas_James_Reeves"}},
  {"id": "1941-12-07-tomich-peter", "date": "1941-12-07", "title": "Chief Watertender Peter Tomich", "type": "loss", "theater": "Navy", "location": {"name": "USS Utah (BB-31), Pearl Harbor, Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For distinguished conduct in the line of his profession and extraordinary courage and disregard of his own safety during the attack on the Fleet in Pearl Harbor by the Japanese forces on 7 December 1941. Despite realizing that the ship was capsizing as a result of enemy bombing and torpedoing, Tomich remained at his post in the engineering plant of the U.S.S. Utah until he saw that all boilers were secured and all fireroom personnel had left their stations, and by so doing, lost his own life.", "facts": [["Recipient", "Peter Tomich"], ["Rank", "Chief Watertender"], ["Service", "Navy"], ["Place of action", "USS Utah (BB-31), Pearl Harbor, Hawaii"], ["Awarded", "Posthumously"]], "wiki": {"Peter Tomich": "Peter_Tomich"}},
  {"id": "1941-12-07-young-cassin", "date": "1941-12-07", "title": "Commander Cassin Young", "type": "attack", "theater": "Navy", "location": {"name": "USS Vestal, Pearl Harbor, Territory of Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For distinguished conduct in action, outstanding heroism and utter disregard of his own safety, above and beyond the call of duty, as Commanding Officer of the U.S.S. Vestal, during the attack on the Fleet in Pearl Harbor, Territory of Hawaii, by enemy Japanese forces on December 7, 1941. Commander Young proceeded to the bridge and later took personal command of the 3-inch antiaircraft gun. When blown overboard by the blast of the forward magazine explosion of the U.S.S. Arizona, to which the U.S.S. Vestal was moored, he swam back to his ship. The entire forward part of the U.S.S. Arizona was a blazing inferno with oil afire on the water between the two ships; as a result of several bomb hits, the U.S.S. Vestal was afire in several places, was settling and taking on a list. …", "facts": [["Recipient", "Cassin Young"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "USS Vestal, Pearl Harbor, Territory of Hawaii"]], "wiki": {"Cassin Young": "Cassin_Young"}},
  {"id": "1941-12-07-flaherty-francis-c", "date": "1941-12-07", "title": "Ensign Francis C. Flaherty", "type": "loss", "theater": "Navy", "location": {"name": "Pearl Harbor, Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For conspicuous devotion to duty and extraordinary courage and complete disregard of his own life, above and beyond the call of duty, during the attack on the Fleet in Pearl Harbor, by Japanese forces on 7 December 1941. When it was seen that the U.S.S. Oklahoma was going to capsize and the order was given to abandon ship, Ens. Flaherty remained in a turret, holding a flashlight so the remainder of the turret crew could see to escape, thereby sacrificing his own life.", "facts": [["Recipient", "Francis C. Flaherty"], ["Rank", "Ensign"], ["Service", "Navy"], ["Place of action", "Pearl Harbor, Hawaii"], ["Awarded", "Posthumously"]], "wiki": {"Francis C. Flaherty": "Francis_C._Flaherty"}},
  {"id": "1941-12-07-jones-herbert-c", "date": "1941-12-07", "title": "Ensign Herbert C. Jones", "type": "loss", "theater": "Navy", "location": {"name": "Pearl Harbor, Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For conspicuous devotion to duty, extraordinary courage, and complete disregard of his own life, above and beyond the call of duty, during the attack on the Fleet in Pearl Harbor, by Japanese forces on 7 December 1941. Ens. Jones organized and led a party, which was supplying ammunition to the antiaircraft battery of the U.S.S. California after the mechanical hoists were put out of action when he was fatally wounded by a bomb explosion. When 2 men attempted to take him from the area which was on fire, he refused to let them do so, saying in words to the effect, \"Leave me alone! I am done for. Get out of here before the magazines go off.", "facts": [["Recipient", "Herbert C. Jones"], ["Rank", "Ensign"], ["Service", "Navy"], ["Place of action", "Pearl Harbor, Hawaii"], ["Awarded", "Posthumously"]], "wiki": {"Herbert C. Jones": "Herbert_C._Jones"}},
  {"id": "1941-12-07-cannon-george-h", "date": "1941-12-07", "title": "First Lieutenant George H. Cannon", "type": "loss", "theater": "Marine Corps", "location": {"name": "Sand Island, Midway Atoll", "lat": 28.2075, "lng": -177.35}, "zoom": 9, "summary": "For distinguished conduct in the line of his profession, extraordinary courage, and disregard of his own condition during the bombardment of Sand Island, Midway Islands, by Japanese forces on December 7, 1941. Lieutenant Cannon, Battery Commander of Battery \"H\", Sixth Defense Battalion, Fleet Marine Force, U. S. Marine Corps, was at his Command Post when he was mortally wounded by enemy shell fire. He refused to be evacuated from his post until after his men, who had been wounded by the same shell were evacuated, and directed the reorganization of his Command Post until forcibly removed, and as a result of his utter disregard of his own condition he died from loss of blood. /S/ FRANKLIN D. ROOSEVELT", "facts": [["Recipient", "George H. Cannon"], ["Rank", "First Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Sand Island, Midway Atoll"], ["Awarded", "Posthumously"]], "wiki": {"George H. Cannon": "George_H._Cannon"}},
  {"id": "1941-12-07-pharris-jackson-c", "date": "1941-12-07", "title": "Gunner Jackson C. Pharris", "type": "attack", "theater": "Navy", "location": {"name": "Pearl Harbor, Territory of Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while attached to the U.S.S. California during the surprise enemy Japanese aerial attack on Pearl Harbor, Territory of Hawaii, December 7, 1941. In charge of the ordnance repair party on the third deck when the first Japanese torpedo struck almost directly under his station, Lt. (then Gunner) Pharris was stunned and severely injured by the concussion which hurled him to the overhead and back to the deck. Quickly recovering, he acted on his own initiative to set up a hand-supply ammunition train for the antiaircraft guns. With water and oil rushing in where the port bulkhead had been torn up from the deck, with many of the remaining crewmembers overcome by oil fumes, and the ship without power and listing heavily to port as a result of a second torpedo hit, Lt. Pharris ordered the shipfitters to counterflood. …", "facts": [["Recipient", "Jackson C. Pharris"], ["Rank", "Gunner"], ["Service", "Navy"], ["Place of action", "Pearl Harbor, Territory of Hawaii"]], "wiki": {"Jackson C. Pharris": "Jackson_C._Pharris"}},
  {"id": "1941-12-07-bulkeley-john-d", "date": "1941-12-07", "title": "Lieutenant Commander John D. Bulkeley", "type": "attack", "theater": "Navy", "location": {"name": "Philippine waters (approx.)", "lat": 12.0, "lng": 123.0}, "zoom": 6, "summary": "For extraordinary heroism, distinguished service, and conspicuous gallantry above and beyond the call of duty as commander of Motor Torpedo Boat Squadron 3, in Philippine waters during the period 1941 to 1942. The remarkable achievement of LCDR Bulkeley's command in damaging or destroying a notable number of Japanese enemy planes, surface combatant and merchant ships, and in dispersing landing parties and land-based enemy forces during the 4 months and 8 days of operation without benefit of repairs, overhaul, or maintenance facilities for his squadron, is believed to be without precedent in this type of warfare. His dynamic forcefulness and daring in offensive action, his brilliantly planned and skillfully executed attacks, supplemented by a unique resourcefulness and ingenuity, characterize him as an outstanding leader of men and a gallant and intrepid seaman. These qualities coupled with a complete disregard for his own personal safety reflect great credit upon him and the Naval Service.", "facts": [["Recipient", "John D. Bulkeley"], ["Rank", "Lieutenant Commander"], ["Service", "Navy"], ["Place of action", "Philippine waters"]], "wiki": {"John D. Bulkeley": "John_D._Bulkeley"}},
  {"id": "1941-12-07-fuqua-samuel-g", "date": "1941-12-07", "title": "Lieutenant Commander Samuel G. Fuqua", "type": "attack", "theater": "Navy", "location": {"name": "Pearl Harbor, Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For distinguished conduct in action, outstanding heroism, and utter disregard of his own safety, above and beyond the call of duty during the attack on the Fleet in Pearl Harbor, by Japanese forces on 7 December 1941. Upon the commencement of the attack, Lieutenant Commander Fuqua rushed to the quarterdeck of the U.S.S. Arizona to which he was attached where he was stunned and knocked down by the explosion of a large bomb which hit the quarterdeck, penetrated several decks, and started a severe fire. Upon regaining consciousness, he began to direct the fighting of the fire and the rescue of wounded and injured personnel. Almost immediately there was a tremendous explosion forward, which made the ship appear to rise out of the water, shudder and settle down by the bow rapidly. The whole forward part of the ship was enveloped in flames which were spreading rapidly, and wounded and burned men were pouring out of the ship to the quarterdeck. …", "facts": [["Recipient", "Samuel G. Fuqua"], ["Rank", "Lieutenant Commander"], ["Service", "Navy"], ["Place of action", "Pearl Harbor, Hawaii"]], "wiki": {"Samuel G. Fuqua": "Samuel_G._Fuqua"}},
  {"id": "1941-12-07-ross-donald-k", "date": "1941-12-07", "title": "Machinist Donald K. Ross", "type": "attack", "theater": "Navy", "location": {"name": "Pearl Harbor, Territory of Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For distinguished conduct in the line of his profession, extraordinary courage and disregard of his own life during the attack on the Fleet in Pearl Harbor, Territory of Hawaii, by Japanese forces on 7 December 1941. When his station in the forward dynamo room of the U.S.S. Nevada became almost untenable due to smoke, steam, and heat, Machinist Ross forced his men to leave that station and performed all the duties himself until blinded and unconscious. Upon being rescued and resuscitated, he returned and secured the forward dynamo room and proceeded to the after dynamo room where he was later again rendered unconscious by exhaustion. Again recovering consciousness he returned to his station where he remained until directed to abandon it.", "facts": [["Recipient", "Donald K. Ross"], ["Rank", "Machinist"], ["Service", "Navy"], ["Place of action", "Pearl Harbor, Territory of Hawaii"]], "wiki": {"Donald K. Ross": "Donald_K._Ross"}},
  {"id": "1941-12-07-scott-robert-r", "date": "1941-12-07", "title": "Machinist's Mate First class Robert R. Scott", "type": "loss", "theater": "Navy", "location": {"name": "Pearl Harbor, Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For conspicuous devotion to duty, extraordinary courage and complete disregard of his own life, above and beyond the call of duty, during the attack on the Fleet in Pearl Harbor by Japanese forces on 7 December 1941. The compartment, in the U.S.S. California, in which the air compressor, to which Scott was assigned as his battle station, was flooded as the result of a torpedo hit. The remainder of the personnel evacuated that compartment but Scott refused to leave, saying words to the effect \"This is my station and I will stay and give them air as long as the guns are going.", "facts": [["Recipient", "Robert R. Scott"], ["Rank", "Machinist's Mate First class"], ["Service", "Navy"], ["Place of action", "Pearl Harbor, Hawaii"], ["Awarded", "Posthumously"]], "wiki": {"Robert R. Scott": "Robert_R._Scott"}},
  {"id": "1941-12-07-kidd-isaac-c", "date": "1941-12-07", "title": "Rear Admiral Isaac C. Kidd", "type": "loss", "theater": "Navy", "location": {"name": "Pearl Harbor, Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For conspicuous devotion to duty, extraordinary courage, and complete disregard of his own life, during the attack on the fleet in Pearl Harbor, Territory of Hawaii, by Japanese Forces on December 7, 1941. Rear Adm. Kidd immediately went to the bridge and, as Commander Battleship Division One, courageously discharged his duties as senior officer present afloat until the USS Arizona, his flagship, blew up from magazine explosions and a direct bomb hit on the bridge, which resulted in the loss of his life.", "facts": [["Recipient", "Isaac C. Kidd"], ["Rank", "Rear Admiral"], ["Service", "Navy"], ["Place of action", "Pearl Harbor, Hawaii"], ["Awarded", "Posthumously"]], "wiki": {"Isaac C. Kidd": "Isaac_C._Kidd"}},
  {"id": "1941-12-07-ward-james-r", "date": "1941-12-07", "title": "Seaman First Class James R. Ward", "type": "loss", "theater": "Navy", "location": {"name": "Pearl Harbor, Hawaii", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For conspicuous devotion to duty, extraordinary courage and complete disregard of his life, above and beyond the call of duty, during the attack on the Fleet in Pearl Harbor by Japanese forces on 7 December 1941. When it was seen that the U.S.S. Oklahoma was going to capsize and the order was given to abandon ship, Ward remained in a turret holding a flashlight so the remainder of the turret crew could see to escape, thereby sacrificing his own life.", "facts": [["Recipient", "James R. Ward"], ["Rank", "Seaman First Class"], ["Service", "Navy"], ["Place of action", "Pearl Harbor, Hawaii"], ["Awarded", "Posthumously"]], "wiki": {"James R. Ward": "James_R._Ward"}},
  {"id": "1941-12-08-elrod-henry-t", "date": "1941-12-08", "title": "Captain Henry T. Elrod", "type": "loss", "theater": "Marine Corps", "location": {"name": "Wake Island", "lat": 19.2953, "lng": 166.6311}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while attached to Marine Fighting Squadron TWO HUNDRED ELEVEN, during action against enemy Japanese land, surface and aerial units at Wake Island, from 8 to 23 December 1941. Engaging vastly superior forces of enemy bombers and warships on 9 and 12 December, Captain Elrod shot down two of a flight of twenty-two hostile planes and, executing repeated bombing and strafing runs at extremely low altitude and close range, succeeded in inflicting deadly damage upon a large Japanese vessel, thereby sinking the first major warship to be destroyed by small caliber bombs delivered from a fighter-type aircraft. …", "facts": [["Recipient", "Henry T. Elrod"], ["Rank", "Captain"], ["Service", "Marine Corps"], ["Place of action", "Wake Island"], ["Awarded", "Posthumously"]], "wiki": {"Henry T. Elrod": "Henry_T._Elrod"}},
  {"id": "1942-01-01-galer-robert-e", "date": "1942-01-01", "title": "Major Robert E. Galer", "type": "attack", "theater": "Marine Corps", "location": {"name": "Solomon Islands area (approx.)", "lat": -9.0, "lng": 159.0}, "zoom": 6, "summary": "For conspicuous heroism and courage above and beyond the call of duty as leader of a marine fighter squadron in aerial combat with enemy Japanese forces in the Solomon Islands area. Leading his squadron repeatedly in daring and aggressive raids against Japanese aerial forces, vastly superior in numbers, Maj. Galer availed himself of every favorable attack opportunity, individually shooting down 11 enemy bomber and fighter aircraft over a period of 29 days. Though suffering the extreme physical strain attendant upon protracted fighter operations at an altitude above 25,000 feet, the squadron under his zealous and inspiring leadership shot down a total of 27 Japanese planes. His superb airmanship, his outstanding skill and personal valor reflect great credit upon Maj. Galer's gallant fighting spirit and upon the U.S. Naval Service.", "facts": [["Recipient", "Robert E. Galer"], ["Rank", "Major"], ["Service", "Marine Corps"], ["Place of action", "Solomon Islands area"]], "wiki": {"Robert E. Galer": "Robert_E._Galer"}, "approx": true},
  {"id": "1942-01-12-nininger-alexander-r", "date": "1942-01-12", "title": "Second Lieutenant Alexander R. Nininger", "type": "loss", "theater": "Army", "location": {"name": "Near Abucay, Bataan, Philippines", "lat": 14.7222, "lng": 120.5354}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy near Abucay, Bataan, Philippine Islands, on 12 January 1942. This officer, though assigned to another company not then engaged in combat, voluntarily attached himself to Company K, same regiment, while that unit was being attacked by enemy force superior in firepower. Enemy snipers in trees and foxholes had stopped a counterattack to regain part of position. In hand-to-hand fighting which followed, 2d Lt. Nininger repeatedly forced his way to and into the hostile position. Though exposed to heavy enemy fire, he continued to attack with rifle and hand grenades and succeeded in destroying several enemy groups in foxholes and enemy snipers. Although wounded 3 times, he continued his attacks until he was killed after pushing alone far within the enemy position. When his body was found after recapture of the position, 1 enemy officer and 2 enemy soldiers lay dead around him.", "facts": [["Recipient", "Alexander R. Nininger"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Near Abucay, Bataan, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Alexander R. Nininger": "Alexander_R._Nininger"}},
  {"id": "1942-01-16-calugas-jose", "date": "1942-01-16", "title": "Sergeant Jose Calugas", "type": "attack", "theater": "Army", "location": {"name": "Culis, Bataan Province, Philippines (approx.)", "lat": 14.75, "lng": 120.45}, "zoom": 9, "summary": "On January 16, 1942, his unit was covering the withdrawal of a portion of the U.S. Army Forces Far East (USAFFE), with the 26th Cavalry Regiment of the Philippine Scouts and the 31st Infantry Regiment. Calugas was working as a mess sergeant in charge of a group of soldiers who were preparing the day's meals, known as KP duty. He noticed that one of his unit's 75 mm M1917 field guns had been silenced, and its crew killed. Without orders, he ran the 1000 yd across the shell-swept area to the inactive gun position. Once there, he organized a squad of volunteers who returned Japanese artillery fire. The position remained under constant and heavy fire for the rest of the afternoon. While Calugas and his squad maintained a steady fire on the enemy positions, other soldiers had time to dig in and defend the line. As the day ended and combat subsided, he returned to KP. …", "facts": [["Recipient", "Jose Calugas"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Culis, Bataan Province, Philippines"]], "wiki": {"Jose Calugas": "Jose_Calugas"}},
  {"id": "1942-02-03-bianchi-willibald-c", "date": "1942-02-03", "title": "First Lieutenant Willibald C. Bianchi", "type": "loss", "theater": "Army", "location": {"name": "Near Bagac, Bataan Province, Philippines", "lat": 14.5951, "lng": 120.3918}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy on 3 February 1942, near Bagac, Province of Bataan, Philippine Islands. When the rifle platoon of another company was ordered to wipe out 2 strong enemy machinegun nests, 1st Lt. Bianchi voluntarily and of his own initiative, advanced with the platoon leading part of the men. When wounded early in the action by 2 bullets through the left hand, he did not stop for first aid but discarded his rifle and began firing a pistol. He located a machinegun nest and personally silenced it with grenades. When wounded the second time by 2 machinegun bullets through the chest muscles, 1st Lt. Bianchi climbed to the top of an American tank, manned its antiaircraft machinegun, and fired into strongly held enemy position until knocked completely off the tank by a third severe wound.", "facts": [["Recipient", "Willibald C. Bianchi"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Bagac, Bataan Province, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Willibald C. Bianchi": "Willibald_C._Bianchi"}},
  {"id": "1942-02-04-rooks-albert-h", "date": "1942-02-04", "title": "Captain Albert H. Rooks", "type": "loss", "theater": "Navy", "location": {"name": "USS Houston on the Java Sea", "lat": -5, "lng": 110}, "zoom": 9, "summary": "For extraordinary heroism, outstanding courage, gallantry in action and distinguished service in the line of his profession, as commanding officer of the U.S.S. Houston during the period 4 to February 27, 1942, while in action with superior Japanese enemy aerial and surface forces. While proceeding to attack an enemy amphibious expedition, as a unit in a mixed force, Houston was heavily attacked by bombers; after evading 4 attacks, she was heavily hit in a fifth attack, lost 60 killed and had 1 turret wholly disabled. Capt. Rooks made his ship again seaworthy and sailed within 3 days to escort an important reinforcing convoy from Darwin to Koepang, Timor, Netherlands East Indies. While so engaged, another powerful air attack developed which by Houston's marked efficiency was fought off without much damage to the convoy. The commanding general of all forces in the area thereupon canceled the movement and Capt. Rooks escorted the convoy back to Darwin. …", "facts": [["Recipient", "Albert H. Rooks"], ["Rank", "Captain"], ["Service", "Navy"], ["Place of action", "USS Houston on the Java Sea"], ["Awarded", "Posthumously"]], "wiki": {"Albert H. Rooks": "Albert_H._Rooks"}},
  {"id": "1942-02-20-o-hare-edward-h", "date": "1942-02-20", "title": "Lieutenant Edward H. O'Hare", "type": "attack", "theater": "Navy", "location": {"name": "Off Papua New Guinea", "lat": -6, "lng": 147}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity in aerial combat, at grave risk of his life above and beyond the call of duty, as section leader and pilot of Fighting Squadron 3 on February 20, 1942. Having lost the assistance of his teammates, Lieutenant O'Hare interposed his fighter between his ship and an advancing enemy formation of 9 attacking twin-engine heavy bombers. Without hesitation, alone and unaided, he repeatedly attacked this enemy formation, at close range in the face of intense combined machine gun and cannon fire. Despite this concentrated opposition, Lieutenant O'Hare, by his gallant and courageous action, his extremely skilful marksmanship in making the most of every shot of his limited amount of ammunition, shot down 5 enemy bombers and severely damaged a sixth before they reached the bomb release point. As a result of his gallant action—one of the most daring, if not the most daring, single action in the history of combat aviation—he undoubtedly saved his carrier from serious damage.", "facts": [["Recipient", "Edward H. O'Hare"], ["Rank", "Lieutenant"], ["Service", "Navy"], ["Place of action", "Off Papua New Guinea"]], "wiki": {"Edward H. O'Hare": "Edward_O'Hare"}},
  {"id": "1942-03-12-wainwright-iv-jonathan-m", "date": "1942-03-12", "title": "Lieutenant General Jonathan M. Wainwright IV", "type": "attack", "theater": "Navy", "location": {"name": "Philippines (approx.)", "lat": 12.0, "lng": 122.5}, "zoom": 6, "summary": "Distinguished himself by intrepid and determined leadership against greatly superior enemy forces. At the repeated risk of life above and beyond the call of duty in his position, he frequented the firing line of his troops where his presence provided the example and incentive that helped make the gallant efforts of these men possible. The final stand on beleaguered Corregidor, for which he was in an important measure personally responsible, commanded the admiration of the Nation's allies. It reflected the high morale of American arms in the face of overwhelming odds. His courage and resolution were a vitally needed inspiration to the then sorely pressed freedom-loving peoples of the world.", "facts": [["Recipient", "Jonathan M. Wainwright IV"], ["Rank", "Lieutenant General"], ["Service", "Navy"], ["Place of action", "Philippines"], ["Awarded", "G.O. No. 80, 19 September 1945"]], "wiki": {"Jonathan M. Wainwright IV": "Jonathan_M._Wainwright_(general)"}},
  {"id": "1942-04-01-macarthur-douglas", "date": "1942-04-01", "title": "General Douglas MacArthur", "type": "attack", "theater": "Army", "location": {"name": "Bataan Peninsula, Philippines", "lat": 14.68, "lng": 120.45}, "zoom": 9, "summary": "For conspicuous leadership in preparing the Philippine Islands to resist conquest, for gallantry and intrepidity above and beyond the call of duty in action against invading Japanese forces, and for the heroic conduct of defensive and offensive operations on the Bataan Peninsula. He mobilized, trained, and led an army which has received world acclaim for its gallant defense against a tremendous superiority of enemy forces in men and arms. His utter disregard of personal danger under heavy fire and aerial bombardment, his calm judgment in each crisis, inspired his troops, galvanized the spirit of resistance of the Filipino people, and confirmed the faith of the American people in their Armed Forces.", "facts": [["Recipient", "Douglas MacArthur"], ["Rank", "General"], ["Service", "Army"], ["Place of action", "Bataan Peninsula, Philippines"]], "wiki": {"Douglas MacArthur": "Douglas_MacArthur"}},
  {"id": "1942-04-01-antrim-richard-n", "date": "1942-04-01", "title": "Lieutenant Richard N. Antrim", "type": "attack", "theater": "Navy", "location": {"name": "Makassar, Celebes, Netherlands East Indies", "lat": -5.1331, "lng": 119.4136}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while interned as a prisoner of war of the enemy Japanese in the city of Makassar, Celebes, Netherlands East Indies, in April 1942. Acting instantly on behalf of a naval officer who was subjected to a vicious clubbing by a frenzied Japanese guard venting his insane wrath upon the helpless prisoner, Comdr. (then Lt.) Antrim boldly intervened, attempting to quiet the guard and finally persuading him to discuss the charges against the officer. With the entire Japanese force assembled and making extraordinary preparations for the threatened beating, and with the tension heightened by 2,700 Allied prisoners rapidly closing in, Comdr. Antrim courageously appealed to the fanatic enemy, risking his own life in a desperate effort to mitigate the punishment. When the other had been beaten unconscious by 15 blows of a hawser and was repeatedly kicked by 3 soldiers to a point beyond which he could not survive, Comdr. …", "facts": [["Recipient", "Richard N. Antrim"], ["Rank", "Lieutenant"], ["Service", "Navy"], ["Place of action", "Makassar, Celebes, Netherlands East Indies"]], "wiki": {"Richard N. Antrim": "Richard_Antrim"}, "approx": true},
  {"id": "1942-04-18-doolittle-jimmy", "date": "1942-04-18", "title": "Lieutenant Colonel Jimmy Doolittle", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Over Japan (approx.)", "lat": 35.5, "lng": 138.0}, "zoom": 6, "summary": "For conspicuous leadership above and beyond the call of duty, involving personal valor and intrepidity at an extreme hazard to life. With the apparent certainty of being forced to land in enemy territory or to perish at sea, Lt. Col. Doolittle personally led a squadron of Army bombers, manned by volunteer crews, in a highly destructive raid on the Japanese mainland.\" He was also promoted to brigadier general.", "facts": [["Recipient", "Jimmy Doolittle"], ["Rank", "Lieutenant Colonel"], ["Service", "Army Air Forces"], ["Place of action", "Over Japan"]], "wiki": {"Jimmy Doolittle": "Jimmy_Doolittle"}},
  {"id": "1942-05-04-powers-john-j", "date": "1942-05-04", "title": "Lieutenant John J. Powers", "type": "loss", "theater": "Navy", "location": {"name": "Over the Coral Sea and adjacent waters (approx.)", "lat": -15.0, "lng": 155.0}, "zoom": 6, "summary": "For distinguished and conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty, while pilot of an airplane of Bombing Squadron 5, Lt. Powers participated, with his squadron, in 5 engagements with Japanese forces in the Coral Sea area and adjacent waters during the period 4 to 8 May 1942. Three attacks were made on enemy objectives at or near Tulagi on 4 May. In these attacks he scored a direct hit which instantly demolished a large enemy gunboat or destroyer and is credited with 2 close misses, 1 of which severely damaged a large aircraft tender, the other damaging a 20,000-ton transport. He fearlessly strafed a gunboat, firing all his ammunition into it amid intense antiaircraft fire. This gunboat was then observed to be leaving a heavy oil slick in its wake and later was seen beached on a nearby island. On 7 May, an attack was launched against an enemy airplane carrier and other units of the enemy's invasion force. …", "facts": [["Recipient", "John J. Powers"], ["Rank", "Lieutenant"], ["Service", "Navy"], ["Place of action", "Over the Coral Sea and adjacent waters"], ["Awarded", "Posthumously"]], "wiki": {"John J. Powers": "John_James_Powers"}},
  {"id": "1942-05-07-peterson-oscar-v", "date": "1942-05-07", "title": "Chief Watertender Oscar V. Peterson", "type": "loss", "theater": "Navy", "location": {"name": "USS Neosho (AO-23), Battle of the Coral Sea (approx.)", "lat": -16.0, "lng": 158.0}, "zoom": 6, "summary": "For extraordinary courage and conspicuous heroism above and beyond the call of duty while in charge of a repair party during an attack on the U.S.S. Neosho by enemy Japanese aerial forces on 7 May 1942. Lacking assistance because of injuries to the other members of his repair party and severely wounded himself, Peterson, with no concern for his own life, closed the bulkhead stop valves and in so doing received additional burns which resulted in his death. His spirit of self-sacrifice and loyalty, characteristic of a fine seaman, was in keeping with the highest traditions of the U.S. Naval Service. He gallantly gave his life in the service of his country.", "facts": [["Recipient", "Oscar V. Peterson"], ["Rank", "Chief Watertender"], ["Service", "Navy"], ["Place of action", "USS Neosho (AO-23), Battle of the Coral Sea"], ["Awarded", "Posthumously"]], "wiki": {"Oscar V. Peterson": "Oscar_V._Peterson"}},
  {"id": "1942-05-07-hall-william-e", "date": "1942-05-07", "title": "Lieutenant, Junior Grade William E. Hall", "type": "attack", "theater": "Navy", "location": {"name": "Coral Sea (approx.)", "lat": -18, "lng": 158}, "zoom": 6, "summary": "For extreme courage and conspicuous heroism in combat above and beyond the call of duty as pilot of a scouting plane in action against enemy Japanese forces in the Coral Sea on 7 and 8 May 1942. In a resolute and determined attack on 7 May, Lt. (j.g.) Hall dived his plane at an enemy Japanese aircraft carrier, contributing materially to the destruction of that vessel. On 8 May, facing heavy and fierce fighter opposition, he again displayed extraordinary skill as an airman and the aggressive spirit of a fighter in repeated and effectively executed counterattacks against a superior number of enemy planes in which 3 enemy aircraft were destroyed. Though seriously wounded in this engagement, Lt. (j.g.) Hall, maintaining the fearless and indomitable tactics pursued throughout these actions, succeeded in landing his plane safe.", "facts": [["Recipient", "William E. Hall"], ["Rank", "Lieutenant, Junior Grade"], ["Service", "Navy"], ["Place of action", "Coral Sea"]], "wiki": {"William E. Hall": "William_E._Hall"}},
  {"id": "1942-05-08-ricketts-milton-e", "date": "1942-05-08", "title": "Lieutenant Milton E. Ricketts", "type": "loss", "theater": "Navy", "location": {"name": "USS Yorktown, Battle of the Coral Sea (approx.)", "lat": -15.5, "lng": 155.0}, "zoom": 6, "summary": "For extraordinary and distinguished gallantry above and beyond the call of duty as Officer-in-Charge of the Engineering Repair Party of the U.S.S. Yorktown in action against enemy Japanese forces in the Battle of the Coral Sea on 8 May 1942. During the severe bombarding of the Yorktown by enemy Japanese forces, an aerial bomb passed through and exploded directly beneath the compartment in which Lt. Ricketts' battle station was located, killing, wounding or stunning all of his men and mortally wounding him. Despite his ebbing strength, Lt. Ricketts promptly opened the valve of a near-by fireplug, partially led out the fire hose and directed a heavy stream of water into the fire before dropping dead beside the hose. His courageous action, which undoubtedly prevented the rapid spread of fire to serious proportions, and his unflinching devotion to duty were in keeping with the highest traditions of the U.S. Naval Service. He gallantly gave his life for his country.", "facts": [["Recipient", "Milton E. Ricketts"], ["Rank", "Lieutenant"], ["Service", "Navy"], ["Place of action", "USS Yorktown, Battle of the Coral Sea"], ["Awarded", "Posthumously"]], "wiki": {"Milton E. Ricketts": "Milton_Ernest_Ricketts"}},
  {"id": "1942-05-10-bauer-harold-w", "date": "1942-05-10", "title": "Lieutenant Colonel Harold W. Bauer", "type": "loss", "theater": "Marine Corps", "location": {"name": "South Pacific area (approx.)", "lat": -9.0, "lng": 158.0}, "zoom": 9, "summary": "For extraordinary heroism and conspicuous courage as Squadron Commander of Marine Fighting Squadron TWO TWELVE in the South Pacific Area during the period May 10 to November 14, 1942. Volunteering to pilot a fighter plane in defense of our positions on Guadalcanal, Solomon Islands, Lieutenant Colonel Bauer participated in two air battles against enemy bombers and fighters outnumbering our force more than two-to-one, boldly engaged the enemy and destroyed one Japanese bomber in the engagement of September 28 and shot down four enemy fighter planes in flames on October 3 leaving a fifth smoking badly. After successfully leading twenty-six planes in the over-water ferry flight of more than six hundred miles on October 16, Lieutenant Colonel Bauer, while circling to land, sighted a squadron of enemy planes attacking the USS McFarland. …", "facts": [["Recipient", "Harold W. Bauer"], ["Rank", "Lieutenant Colonel"], ["Service", "Marine Corps"], ["Place of action", "South Pacific area"], ["Awarded", "Posthumously"]], "wiki": {"Harold W. Bauer": "Harold_W._Bauer"}},
  {"id": "1942-06-04-fleming-richard-e", "date": "1942-06-04", "title": "Captain Richard E. Fleming", "type": "loss", "theater": "Marine Corps", "location": {"name": "Midway Atoll", "lat": 28.2075, "lng": -177.35}, "zoom": 9, "summary": "For extraordinary heroism and conspicuous intrepidity above and beyond the call of duty as Flight Officer, Marine Scout-Bombing Squadron TWO FORTY-ONE during action against enemy Japanese forces in the Battle of Midway on June 4 and 5, 1942. When his squadron Commander was shot down during the initial attack upon an enemy aircraft carrier, Captain Fleming led the remainder of the division with such fearless determination that he dived his own plane to the perilously low altitude of four hundred feet before releasing his bomb. Although his craft was riddled by 179 hits in the blistering hail of fire that burst upon him from Japanese fighter guns and antiaircraft batteries, he pulled out with only two minor wounds inflicted upon himself. On the night of June 4, when the Squadron Commander lost his way and became separated from the others, Captain Fleming brought his own plane in for a safe landing at its base despite hazardous weather conditions and total darkness. …", "facts": [["Recipient", "Richard E. Fleming"], ["Rank", "Captain"], ["Service", "Marine Corps"], ["Place of action", "Midway Atoll"], ["Awarded", "Posthumously"]], "wiki": {"Richard E. Fleming": "Richard_E._Fleming"}},
  {"id": "1942-08-01-smith-john-l", "date": "1942-08-01", "title": "Major John L. Smith", "type": "attack", "theater": "Marine Corps", "location": {"name": "Solomon Islands area (approx.)", "lat": -9.0, "lng": 159.0}, "zoom": 6, "summary": "For conspicuous gallantry and heroic achievement in aerial combat above and beyond the call of duty as Commanding Officer of Marine Fighting Squadron TWO TWENTY-THREE, during operations against enemy Japanese forces in the Solomon Islands Area, August – September, 1942. Repeatedly risking his life in aggressive and daring attacks, Major Smith led his squadron against a determined force, greatly superior in numbers, personally shooting down sixteen Japanese planes between August 21 and September 15, 1942. In spite of the limited combat experience of many of the pilots of this squadron, they achieved the notable record of a total of eighty-three enemy aircraft destroyed in this period, mainly attributable to the thorough training under Major Smith and to his intrepid and inspiring leadership. His bold tactics and indomitable fighting spirit and the valiant and zealous fortitude of the men of his command not only rendered the enemy's attacks ineffective and costly to them but contributed to the security of our advance base. …", "facts": [["Recipient", "John L. Smith"], ["Rank", "Major"], ["Service", "Marine Corps"], ["Place of action", "Solomon Islands area"]], "wiki": {"John L. Smith": "John_Smith_(flying_ace)"}, "approx": true},
  {"id": "1942-08-06-pease-jr-harl", "date": "1942-08-06", "title": "Captain Harl Pease Jr.", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Near Rabaul, New Britain", "lat": -4.2, "lng": 152.1833}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy on 6–7 August 1942. When 1 engine of the bombardment airplane of which he was pilot failed during a bombing mission over New Guinea, Capt. Pease was forced to return to a base in Australia. Knowing that all available airplanes of his group were to participate the next day in an attack on an enemy-held airdrome near Rabaul, New Britain, although he was not scheduled to take part in this mission, Capt. Pease selected the most serviceable airplane at this base and prepared it for combat, knowing that it had been found and declared unserviceable for combat missions. With the members of his combat crew, who volunteered to accompany him, he rejoined his squadron at Port Moresby, New Guinea, at 1 a.m. on 7 August, after having flown almost continuously since early the preceding morning. With only 3 hours' rest, he took off with his squadron for the attack. …", "facts": [["Recipient", "Harl Pease Jr."], ["Rank", "Captain"], ["Service", "Army Air Forces"], ["Place of action", "Near Rabaul, New Britain"], ["Awarded", "Posthumously, G.O. No. 59, November 4, 1942"]], "wiki": {"Harl Pease Jr.": "Harl_Pease"}},
  {"id": "1942-08-07-vandegrift-alexander-a", "date": "1942-08-07", "title": "Major General Alexander A. Vandegrift", "type": "attack", "theater": "Marine Corps", "location": {"name": "Battle of Guadalcanal, Solomon Islands", "lat": -9.4456, "lng": 160.0203}, "zoom": 9, "summary": "For outstanding and heroic accomplishment above and beyond the call of duty as commanding officer of the 1st Marine Division in operations against enemy Japanese forces in the Solomon Islands during the period from 7 August to 9 December 1942. With the adverse factors of weather, terrain, and disease making his task a difficult and hazardous undertaking, and with his command eventually including sea, land, and air forces of Army, Navy and Marine Corps, Maj. Gen. Vandegrift achieved marked success in commanding the initial landings of the U. S. forces in the Solomon Islands and in their subsequent occupation. His tenacity, courage, and resourcefulness prevailed against a strong, determined, and experienced enemy, and the gallant fighting spirit of the men under his inspiring leadership enabled them to withstand aerial, land, and sea bombardment, to surmount all obstacles, and leave a disorganized and ravaged enemy. …", "facts": [["Recipient", "Alexander A. Vandegrift"], ["Rank", "Major General"], ["Service", "Marine Corps"], ["Place of action", "Battle of Guadalcanal, Solomon Islands"]], "wiki": {"Alexander A. Vandegrift": "Alexander_Vandegrift"}},
  {"id": "1942-08-17-thomason-clyde-a", "date": "1942-08-17", "title": "Sergeant Clyde A. Thomason", "type": "loss", "theater": "Marine Corps", "location": {"name": "Makin Atoll", "lat": 3.1678, "lng": 172.8258}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while a member of the Second Marine Raider Battalion in action against the Japanese-held island of Makin on August 17–18, 1942. Landing the advance element of the assault echelon, Sergeant Thomason disposed his men with keen judgment and discrimination and by his exemplary leadership and great personal valor, exhorted them to like fearless efforts. On one occasion, he dauntlessly walked up to a house which concealed an enemy Japanese sniper, forced in the door and shot the man before he could resist. Later in the action, while leading an assault on enemy position, he gallantly gave up his life in the service of his country. His courage and loyal devotion to duty in the face of grave peril were in keeping with the finest traditions of the United States Naval Service.", "facts": [["Recipient", "Clyde A. Thomason"], ["Rank", "Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Makin Atoll"], ["Awarded", "Posthumously"]], "wiki": {"Clyde A. Thomason": "Clyde_A._Thomason"}},
  {"id": "1942-09-12-bailey-kenneth-d", "date": "1942-09-12", "title": "Major Kenneth D. Bailey", "type": "loss", "theater": "Marine Corps", "location": {"name": "Henderson Field, Guadalcanal, Solomon Islands", "lat": -9.59, "lng": 160.235}, "zoom": 9, "summary": "For extraordinary courage and heroic conduct above and beyond the call of duty as Commanding Officer of Company C, First Marine Raider Battalion, during the enemy Japanese attack on Henderson Field, Guadalcanal, Solomon Islands, on September 12–13, 1942. Completely reorganized following the severe engagement of the night before, Major Bailey's company, within an hour after taking its assigned position as battalion reserve between the main line and the coveted airport, was threatened on the right flank by the penetration of the enemy into a gap in the main line. In addition to repulsing this threat, while steadily improving his own desperately held position, he used every weapon at his command to cover the forced withdrawal of the main line before a hammering assault by superior enemy forces. …", "facts": [["Recipient", "Kenneth D. Bailey"], ["Rank", "Major"], ["Service", "Marine Corps"], ["Place of action", "Henderson Field, Guadalcanal, Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"Kenneth D. Bailey": "Kenneth_D._Bailey"}},
  {"id": "1942-09-13-edson-merritt-a", "date": "1942-09-13", "title": "Colonel Merritt A. Edson", "type": "attack", "theater": "Marine Corps", "location": {"name": "Guadalcanal, Solomon Islands", "lat": -9.59, "lng": 160.235}, "zoom": 9, "summary": "For extraordinary heroism and conspicuous intrepidity above and beyond the call of duty as Commanding Officer of the 1st Marine Raider Battalion, with Parachute Battalion attached, during action against enemy Japanese forces in the Solomon Islands on the night of 13–14 September 1942. After the airfield on Guadalcanal had been seized from the enemy on August 8, Col. Edson, with a force of 800 men, was assigned to the occupation and defense of a ridge dominating the jungle on either side of the airport. Facing a formidable Japanese attack which, augmented by infiltration, had crashed through our front lines, he, by skillful handling of his troops, successfully withdrew his forward units to a reserve line with minimum casualties. When the enemy, in a subsequent series of violent assaults, engaged our force in desperate hand-to-hand combat with bayonets, rifles, pistols, grenades, and knives, Col. Edson, although continuously exposed to hostile fire throughout the night, personally directed defense of the reserve position against a fanatical foe of greatly superior numbers. …", "facts": [["Recipient", "Merritt A. Edson"], ["Rank", "Colonel"], ["Service", "Marine Corps"], ["Place of action", "Guadalcanal, Solomon Islands"]], "wiki": {"Merritt A. Edson": "Merritt_A._Edson"}},
  {"id": "1942-09-27-munro-douglas-a", "date": "1942-09-27", "title": "Signalman First class Douglas A. Munro", "type": "loss", "theater": "Coast Guard", "location": {"name": "Off Point Cruz, Guadalcanal, Solomon Islands", "lat": -9.4333, "lng": 159.95}, "zoom": 9, "summary": "For extraordinary heroism and conspicuous gallantry in action above and beyond the call of duty as Officer-in-Charge of a group of Higgins boats, engaged in the evacuation of a Battalion of Marines trapped by enemy Japanese forces at Point Cruz, Guadalcanal, on September 27, 1942. After making preliminary plans for the evacuation of nearly 500 beleaguered Marines, Munro, under constant risk of his life, daringly led five of his small craft toward the shore. As he closed the beach, he signaled the others to land, and then in order to draw the enemy's fire and protect the heavily loaded boats, he valiantly placed his craft with its two small guns as a shield between the beachhead and the Japanese. When the perilous task of evacuation was nearly completed, Munro was killed by enemy fire, but his crew, two of whom were wounded, carried on until the last boat had loaded and cleared the beach. …", "facts": [["Recipient", "Douglas A. Munro"], ["Rank", "Signalman First class"], ["Service", "Coast Guard"], ["Place of action", "Off Point Cruz, Guadalcanal, Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"Douglas A. Munro": "Douglas_Albert_Munro"}},
  {"id": "1942-10-09-foss-joseph-j", "date": "1942-10-09", "title": "Captain Joseph J. Foss", "type": "attack", "theater": "Marine Corps", "location": {"name": "Over Guadalcanal, Solomon Islands (approx.)", "lat": -9.59, "lng": 160.235}, "zoom": 6, "summary": "For outstanding heroism and courage above and beyond the call of duty as Executive Officer of a Marine Fighting Squadron, at Guadalcanal, Solomon Islands. Engaging in almost daily combat with the enemy from October 9 to November 19, 1942, Captain Foss personally shot down 23 Japanese aircraft and damaged others so severely that their destruction was extremely probable. In addition, during this period, he successfully led a large number of escort missions, skillfully covering reconnaissance, bombing and photographic planes as well as surface craft. On January 15, 1943, he added three more enemy aircraft to his already brilliant successes for a record of aerial combat achievement unsurpassed in this war. Boldly searching out an approaching enemy force on January 25, Captain Foss led his eight F4F Marine planes and four Army P-38s into action and, undaunted by tremendously superior numbers, intercepted and struck with such force that four Japanese fighters were shot down and the bombers were turned back without releasing a single bomb. …", "facts": [["Recipient", "Joseph J. Foss"], ["Rank", "Captain"], ["Service", "Marine Corps"], ["Place of action", "Over Guadalcanal, Solomon Islands"]], "wiki": {"Joseph J. Foss": "Joe_Foss"}},
  {"id": "1942-10-11-scott-norman", "date": "1942-10-11", "title": "Rear Admiral Norman Scott", "type": "loss", "theater": "Navy", "location": {"name": "Off Savo Island", "lat": -9.1333, "lng": 159.8167}, "zoom": 9, "summary": "For extraordinary heroism and conspicuous intrepidity above and beyond the call of duty during action against enemy Japanese forces off Savo Island on the night of 11–12 October and again on the night of 12–13 November 1942. In the earlier action, intercepting a Japanese Task Force intent upon storming our island positions and landing reinforcements at Guadalcanal, Rear Adm. Scott, with courageous skill and superb coordination of the units under his command, destroyed 8 hostile vessels and put the others to flight. Again challenged, a month later, by the return of a stubborn and persistent foe, he led his force into a desperate battle against tremendous odds, directing close-range operations against the invading enemy until he himself was killed in the furious bombardment by their superior firepower. On each of these occasions his dauntless initiative, inspiring leadership and judicious foresight in a crisis of grave responsibility contributed decisively to the rout of a powerful invasion fleet and to the consequent frustration of a formidable Japanese offensive. …", "facts": [["Recipient", "Norman Scott"], ["Rank", "Rear Admiral"], ["Service", "Navy"], ["Place of action", "Off Savo Island"], ["Awarded", "Posthumously"]], "wiki": {"Norman Scott": "Norman_Scott_(admiral)"}},
  {"id": "1942-10-24-basilone-john", "date": "1942-10-24", "title": "Sergeant John Basilone", "type": "attack", "theater": "Marine Corps", "location": {"name": "Lunga area, Guadalcanal, Solomon Islands", "lat": -9.4167, "lng": 160.0333}, "zoom": 9, "summary": "For extraordinary heroism and conspicuous gallantry in action against enemy Japanese forces, above and beyond the call of duty, while serving with the 1st Battalion, 7th Marines, 1st Marine Division in the Lunga Area, Guadalcanal, Solomon Islands, on 24 and 25 October 1942. While the enemy was hammering at the Marines' defensive positions, Sgt. BASILONE, in charge of 2 sections of heavy machine guns, fought valiantly to check the savage and determined assault. In a fierce frontal attack with the Japanese blasting his guns with grenades and mortar fire, one of Sgt. BASILONE'S sections, with its gun crews, was put out of action, leaving only 2 men able to carry on. Moving an extra gun into position, he placed it in action, then, under continual fire, repaired another and personally manned it, gallantly holding his line until replacements arrived. A little later, with ammunition critically low and the supply lines cut off, Sgt. …", "facts": [["Recipient", "John Basilone"], ["Rank", "Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Lunga area, Guadalcanal, Solomon Islands"]], "wiki": {"John Basilone": "John_Basilone"}},
  {"id": "1942-10-26-paige-mitchell", "date": "1942-10-26", "title": "Platoon Sergeant Mitchell Paige", "type": "attack", "theater": "Marine Corps", "location": {"name": "Battle for Henderson Field, Guadalcanal, Solomon Islands", "lat": -9.4475, "lng": 160.0489}, "zoom": 9, "summary": "For extraordinary heroism and conspicuous gallantry in action above and beyond the call of duty while serving with the Second Battalion, Seventh Marines, First Marine Division, in combat against enemy Japanese forces in the Solomon Islands Area on October 26, 1942. When the enemy broke through the line directly in front of his position, Platoon Sergeant Paige, commanding a machine-gun section with fearless determination, continued to direct the fire of his gunners until all his men were either killed or wounded. Alone, against the deadly hail of Japanese shells, he manned his gun, and when it was destroyed, took over another, moving from gun to gun, never ceasing his withering fire against the advancing hordes until reinforcements finally arrived. Then, forming a new line, he dauntlessly and aggressively led a bayonet charge, driving the enemy back and preventing a break through in our lines. His great personal valor and unyielding devotion to duty were in keeping with the highest traditions of the United States Naval Service.", "facts": [["Recipient", "Mitchell Paige"], ["Rank", "Platoon Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Battle for Henderson Field, Guadalcanal, Solomon Islands"]], "wiki": {"Mitchell Paige": "Mitchell_Paige"}},
  {"id": "1942-11-01-casamento-anthony", "date": "1942-11-01", "title": "Corporal Anthony Casamento", "type": "attack", "theater": "Marine Corps", "location": {"name": "Guadalcanal, Solomon Islands", "lat": -9.59, "lng": 160.235}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with Company \"D\", First Battalion, Fifth Marines, First Marine Division on Guadalcanal, British Solomon Islands, in action against the enemy Japanese forces on November 1, 1942. Serving as a leader of a machine gun section, Corporal Casamento directed his unit to advance along a ridge near the Matanikau River where they engaged the enemy. He positioned his section to provide covering fire for two flanking units and to provide direct support for the main force of his company which was behind him. During the course of this engagement, all members of his section were either killed or severely wounded and he himself suffered multiple, grievous wounds. Nonetheless, Corporal Casamento continued to provide critical supporting fire for the attack and in defense of his position. Following the loss of all effective personnel, he set up, loaded, and manned his unit's machine gun, tenaciously holding the enemy forces at bay. …", "facts": [["Recipient", "Anthony Casamento"], ["Rank", "Corporal"], ["Service", "Marine Corps"], ["Place of action", "Guadalcanal, Solomon Islands"]], "wiki": {"Anthony Casamento": "Anthony_Casamento"}},
  {"id": "1942-11-08-craw-demas-t", "date": "1942-11-08", "title": "Colonel Demas T. Craw", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Near Port Lyautey, French Morocco", "lat": 34.25, "lng": -6.5833}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity in action above and beyond the call of duty. On November 8, 1942, near Port Lyautey, French Morocco, Col. Craw volunteered to accompany the leading wave of assault boats to the shore and pass through the enemy lines to locate the French commander with a view to suspending hostilities. This request was first refused as being too dangerous but upon the officer's insistence that he was qualified to undertake and accomplish the mission he was allowed to go. Encountering heavy fire while in the landing boat and unable to dock in the river because of shell fire from shore batteries, Col. Craw, accompanied by 1 officer and 1 soldier, succeeded in landing on the beach at Mehdia Plage under constant low-level strafing from 3 enemy planes. Riding in a bantam truck toward French headquarters, progress of the party was hindered by fire from our own naval guns. Nearing Port Lyautey, Col. …", "facts": [["Recipient", "Demas T. Craw"], ["Rank", "Colonel"], ["Service", "Army Air Forces"], ["Place of action", "Near Port Lyautey, French Morocco"], ["Awarded", "Posthumously"]], "wiki": {"Demas T. Craw": "Demas_T._Craw"}},
  {"id": "1942-11-08-wilbur-william-h", "date": "1942-11-08", "title": "Colonel William H. Wilbur", "type": "attack", "theater": "Army", "location": {"name": "Fedala, Morocco", "lat": 33.6833, "lng": -7.3833}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity in action above and beyond the call of duty. Col. Wilbur prepared the plan for making contact with French commanders in Casablanca and obtaining an armistice to prevent unnecessary bloodshed. On 8 November 1942, he landed at Fedala with the leading assault waves where opposition had developed into a firm and continuous defensive line across his route of advance. Commandeering a vehicle, he was driven toward the hostile defenses under incessant fire, finally locating a French officer who accorded him passage through the forward positions. He then proceeded in total darkness through 16 miles of enemy-occupied country intermittently subjected to heavy bursts of fire, and accomplished his mission by delivering his letters to appropriate French officials in Casablanca. Returning toward his command, Col. Wilbur detected a hostile battery firing effectively on our troops. He took charge of a platoon of American tanks and personally led them in an attack and capture of the battery. …", "facts": [["Recipient", "William H. Wilbur"], ["Rank", "Colonel"], ["Service", "Army"], ["Place of action", "Fedala, Morocco"]], "wiki": {"William H. Wilbur": "William_H._Wilbur"}},
  {"id": "1942-11-08-hamilton-pierpont-m", "date": "1942-11-08", "title": "Major Pierpont M. Hamilton", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Near Port Lyautey, French Morocco", "lat": 34.25, "lng": -6.5833}, "zoom": 9, "summary": "Major (Air Corps) Pierpont Morgan Hamilton, United States Army Air Forces, for conspicuous gallantry and intrepidity in action above and beyond the call of duty while serving as the Assistant Chief of Staff for Intelligence, Western Task Force, in North Africa during the landings of Operation Torch. On 8 November 1942, near Port Lyautey, French Morocco, Lieutenant Colonel Hamilton volunteered to accompany Colonel Demas Craw on a dangerous mission to the French commander, designed to bring about a cessation of hostilities. Driven away from the mouth of the Sebou River by heavy shelling from all sides, the landing boat was finally beached at Mehdia Plage despite continuous machinegun fire from three low-flying hostile planes. Driven in a light truck toward French headquarters, this courageous mission encountered intermittent firing, and as it neared Port Lyautey a heavy burst of machinegun fire was delivered upon the truck from pointblank range, killing Colonel Craw instantly. Although captured immediately, after this incident, Lieutenant Colonel Hamilton completed the mission.", "facts": [["Recipient", "Pierpont M. Hamilton"], ["Rank", "Major"], ["Service", "Army Air Forces"], ["Place of action", "Near Port Lyautey, French Morocco"]], "wiki": {"Pierpont M. Hamilton": "Pierpont_M._Hamilton"}},
  {"id": "1942-11-12-keppler-reinhardt-j", "date": "1942-11-12", "title": "Boatswain's Mate First class Reinhardt J. Keppler", "type": "loss", "theater": "Navy", "location": {"name": "USS San Francisco, Solomon Islands (approx.)", "lat": -9.25, "lng": 159.9}, "zoom": 9, "summary": "For extraordinary heroism and distinguished courage above and beyond the call of duty while serving aboard the U.S.S. San Francisco during action against enemy Japanese forces in the Solomon Islands, 12–November 13, 1942. When a hostile torpedo plane, during a daylight air raid, crashed on the after machine-gun platform, KEPPLER promptly assisted in the removal of the dead and, by his capable supervision of the wounded, undoubtedly helped save the lives of several shipmates who otherwise might have perished. That night, when the hangar was set afire during the great battle off Savo Island, he bravely led a hose into the starboard side of the stricken area and there, without assistance and despite frequent hits from terrific enemy bombardment, eventually brought the fire under control. Later, although mortally wounded, he labored valiantly in the midst of bursting shells, persistently directing fire-fighting operations and administrating to wounded personnel until he finally collapsed from loss of blood, aged 24. …", "facts": [["Recipient", "Reinhardt J. Keppler"], ["Rank", "Boatswain's Mate First class"], ["Service", "Navy"], ["Place of action", "USS San Francisco, Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"Reinhardt J. Keppler": "Reinhardt_J._Keppler"}},
  {"id": "1942-11-12-mccandless-bruce", "date": "1942-11-12", "title": "Commander Bruce McCandless", "type": "attack", "theater": "Navy", "location": {"name": "Battle off Savo Island (approx.)", "lat": -9.13, "lng": 159.81}, "zoom": 9, "summary": "For conspicuous gallantry and exceptionally distinguished service above and beyond the call of duty as communication officer of the U.S.S. San Francisco in combat with enemy Japanese forces in the battle off Savo Island, 12–13 November 1942. In the midst of a violent night engagement, the fire of a determined and desperate enemy seriously wounded Lt. Comdr. McCandless and rendered him unconscious, killed or wounded the admiral in command, his staff, the captain of the ship, the navigator, and all other personnel on the navigating and signal bridges. Faced with the lack of superior command upon his recovery, and displaying superb initiative, he promptly assumed command of the ship and ordered her course and gunfire against an overwhelmingly powerful force. With his superiors in other vessels unaware of the loss of their admiral, and challenged by his great responsibility, Lt. Comdr. McCandless boldly continued to engage the enemy and to lead our column of following vessels to a great victory. …", "facts": [["Recipient", "Bruce McCandless"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "Battle off Savo Island"]], "wiki": {"Bruce McCandless": "Bruce_McCandless"}},
  {"id": "1942-11-12-schonland-herbert-e", "date": "1942-11-12", "title": "Commander Herbert E. Schonland", "type": "attack", "theater": "Navy", "location": {"name": "Savo Island", "lat": -9.1333, "lng": 159.8167}, "zoom": 9, "summary": "For extreme heroism and courage above and beyond the call of duty as damage control officer of the U.S.S. San Francisco in action against greatly superior enemy forces in the battle off Savo Island, 12–13 November 1942. In the same violent night engagement in which all of his superior officers were killed or wounded, Lt. Comdr. Schonland was fighting valiantly to free the San Francisco of large quantities of water flooding the second deck compartments through numerous shell holes caused by enemy fire. Upon being informed that he was commanding officer, he ascertained that the conning of the ship was being efficiently handled, then directed the officer who had taken over that task to continue while he himself resumed the vitally important work of maintaining the stability of the ship. In water waist deep, he carried on his efforts in darkness illuminated only by hand lanterns until water in flooded compartments had been drained or pumped off and watertight integrity had again been restored to the San Francisco. …", "facts": [["Recipient", "Herbert E. Schonland"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "Savo Island"]], "wiki": {"Herbert E. Schonland": "Herbert_Emery_Schonland"}},
  {"id": "1942-11-12-callaghan-daniel-j", "date": "1942-11-12", "title": "Rear Admiral Daniel J. Callaghan", "type": "loss", "theater": "Navy", "location": {"name": "Naval Battle of Guadalcanal, Savo Sound, Solomon Islands", "lat": -9.1861, "lng": 159.895}, "zoom": 9, "summary": "For extraordinary heroism and conspicuous intrepidity above and beyond the call of duty during action against enemy Japanese forces off Savo Island on the night of 12–13 November 1942. Although out-balanced in strength and numbers by a desperate and determined enemy, Rear Admiral Callaghan, with ingenious tactical skill and superb coordination of the units under his command, led his forces into battle against tremendous odds, thereby contributing decisively to the rout of a powerful invasion fleet and to the consequent frustration of a formidable Japanese offensive. While faithfully directing close-range operations in the face of furious bombardment by superior enemy fire power, he was killed on the bridge of his Flagship. His courageous initiative, inspiring leadership, and judicious foresight in a crisis of grave responsibility were in keeping with the finest traditions of the United States Naval Service. He gallantly gave his life in the defense of his country.", "facts": [["Recipient", "Daniel J. Callaghan"], ["Rank", "Rear Admiral"], ["Service", "Navy"], ["Place of action", "Naval Battle of Guadalcanal, Savo Sound, Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"Daniel J. Callaghan": "Daniel_J._Callaghan"}},
  {"id": "1942-12-24-burr-elmer-j", "date": "1942-12-24", "title": "First Sergeant Elmer J. Burr", "type": "loss", "theater": "Army", "location": {"name": "Buna, New Guinea (approx.)", "lat": -8.66, "lng": 148.4}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity in action above and beyond the call of duty. During an attack near Buna, New Guinea, on 24 December 1942, 1st Sgt. Burr saw an enemy grenade strike near his company commander. Instantly and with heroic self-sacrifice he threw himself upon it, smothering the explosion with his body. 1st Sgt. Burr thus gave his life in saving that of his commander.", "facts": [["Recipient", "Elmer J. Burr"], ["Rank", "First Sergeant"], ["Service", "Army"], ["Place of action", "Buna, New Guinea"], ["Awarded", "Posthumously"]], "wiki": {"Elmer J. Burr": "Elmer_J._Burr"}},
  {"id": "1942-12-24-gruennert-kenneth-e", "date": "1942-12-24", "title": "Sergeant Kenneth E. Gruennert", "type": "loss", "theater": "Army", "location": {"name": "Near Buna, New Guinea (approx.)", "lat": -8.66, "lng": 148.4}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity in action above and beyond the call of duty. On 24 December 1942, near Buna, New Guinea, Sgt. Gruennert was second in command of a platoon with a mission to drive through the enemy lines to the beach 600 yards ahead. Within 150 yards of the objective, the platoon encountered 2 hostile pillboxes. Sgt. Gruennert advanced alone on the first and put it out of action with hand grenades and rifle fire, killing 3 of the enemy. Seriously wounded in the shoulder, he bandaged his wound under cover of the pillbox, refusing to withdraw to the aid station and leave his men. He then, with undiminished daring, and under extremely heavy fire, attacked the second pillbox. As he neared it he threw grenades which forced the enemy out where they were easy targets for his platoon. Before the leading elements of his platoon could reach him he was shot by enemy snipers. …", "facts": [["Recipient", "Kenneth E. Gruennert"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Buna, New Guinea"], ["Awarded", "Posthumously"]], "wiki": {"Kenneth E. Gruennert": "Kenneth_E._Gruennert"}},
  {"id": "1943-01-05-walker-kenneth-n", "date": "1943-01-05", "title": "Brigadier General Kenneth N. Walker", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Rabaul, New Britain", "lat": -4.2, "lng": 152.1833}, "zoom": 9, "summary": "For conspicuous leadership above and beyond the call of duty involving personal valor and intrepidity at an extreme hazard to life. As commander of the V Bomber Command during the period from 5 September 1942, to 5 January 1943, Brigadier General Walker repeatedly accompanied his units on bombing missions deep into enemy-held territory. From the lessons personally gained under combat conditions, he developed a highly efficient technique for bombing when opposed by enemy fighter airplanes and by antiaircraft fire. On 5 January 1943, in the face of extremely heavy antiaircraft fire and determined opposition by enemy fighters, he led an effective daylight bombing attack against the shipping in the harbor at Rabaul, New Britain, which resulted in direct hits on 9 enemy vessels. During this action his airplane was disabled and forced down by the attack of an overwhelming number of enemy fighters.", "facts": [["Recipient", "Kenneth N. Walker"], ["Rank", "Brigadier General"], ["Service", "Army Air Forces"], ["Place of action", "Rabaul, New Britain"], ["Awarded", "Posthumously"]], "wiki": {"Kenneth N. Walker": "Kenneth_Walker_(general)"}},
  {"id": "1943-01-10-gilmore-howard-w", "date": "1943-01-10", "title": "Commander Howard W. Gilmore", "type": "loss", "theater": "Navy", "location": {"name": "USS Growler, southwest Pacific (approx.)", "lat": -4.0, "lng": 151.5}, "zoom": 9, "summary": "For distinguished gallantry and valor above and beyond the call of duty as commanding officer of the U.S.S. Growler during her Fourth War Patrol in the Southwest Pacific from 10 January to 7 February 1943. Boldly striking at the enemy in spite of continuous hostile air and antisubmarine patrols, Comdr. Gilmore sank one Japanese freighter and damaged another by torpedo fire, successfully evading severe depth charges following each attack. In the darkness of night on 7 February, an enemy gunboat closed range and prepared to ram the Growler. Comdr. Gilmore daringly maneuvered to avoid the crash and rammed the attacker instead, ripping into her port side at 11 knots and bursting wide her plates. In the terrific fire of the sinking gunboat's heavy machineguns, Comdr. Gilmore calmly gave the order to clear the bridge, and refusing safety for himself, remained on deck while his men preceded him below. Struck down by the fusillade of bullets and having done his utmost against the enemy, in his final living moments, Comdr. …", "facts": [["Recipient", "Howard W. Gilmore"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "USS Growler, southwest Pacific"], ["Awarded", "Posthumously"]], "wiki": {"Howard W. Gilmore": "Howard_W._Gilmore"}},
  {"id": "1943-01-10-fournier-william-g", "date": "1943-01-10", "title": "Sergeant William G. Fournier", "type": "loss", "theater": "Army", "location": {"name": "Mount Austen, Guadalcanal, Solomon Islands", "lat": -8.7667, "lng": 160.7}, "zoom": 9, "summary": "For gallantry and intrepidity above and beyond the call of duty. As leader of a machinegun section charged with the protection of other battalion units, his group was attacked by a superior number of Japanese, his gunner killed, his assistant gunner wounded, and an adjoining guncrew put out of action. Ordered to withdraw from this hazardous position, Sgt. Fournier refused to retire but rushed forward to the idle gun and, with the aid of another soldier who joined him, held up the machinegun by the tripod to increase its field action. They opened fire and inflicted heavy casualties upon the enemy. While so engaged both these gallant soldiers were killed, but their sturdy defensive was a decisive factor in the following success of the attacking battalion.", "facts": [["Recipient", "William G. Fournier"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Mount Austen, Guadalcanal, Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"William G. Fournier": "William_G._Fournier"}},
  {"id": "1943-01-10-hall-lewis", "date": "1943-01-10", "title": "Technician 5th Grade Lewis Hall", "type": "loss", "theater": "Army", "location": {"name": "Mount Austen, Guadalcanal, Solomon Islands", "lat": -8.7667, "lng": 160.7}, "zoom": 9, "summary": "For gallantry and intrepidity above and beyond the call of duty. As leader of a machinegun squad charged with the protection of other battalion units, his group was attacked by a superior number of Japanese, his gunner killed, his assistant gunner wounded, and an adjoining guncrew put out of action. Ordered to withdraw from his hazardous position, he refused to retire but rushed forward to the idle gun and with the aid of another soldier who joined him and held up the machinegun by the tripod to increase its field of action he opened fire and inflicted heavy casualties upon the enemy. While so engaged both these gallant soldiers were killed, but their sturdy defense was a decisive factor in the following success of the attacking battalion.", "facts": [["Recipient", "Lewis Hall"], ["Rank", "Technician 5th Grade"], ["Service", "Army"], ["Place of action", "Mount Austen, Guadalcanal, Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"Lewis Hall": "Lewis_Hall_(soldier)"}},
  {"id": "1943-01-12-davis-charles-w", "date": "1943-01-12", "title": "Captain Charles W. Davis", "type": "attack", "theater": "Army", "location": {"name": "Guadalcanal, Solomon Islands", "lat": -9.59, "lng": 160.235}, "zoom": 9, "summary": "For distinguishing himself conspicuously by gallantry and intrepidity at the risk of his life above and beyond the call of duty in action with the enemy on Guadalcanal Island. On January 12, 1943, Maj. Davis (then Capt.), executive officer of an infantry battalion, volunteered to carry instructions to the leading companies of his battalion which had been caught in crossfire from Japanese machine guns. With complete disregard for his own safety, he made his way to the trapped units, delivered the instructions, supervised their execution, and remained overnight in this exposed position. On the following day, Maj. Davis again volunteered to lead an assault on the Japanese position which was holding up the advance. When his rifle jammed at its first shot, he drew his pistol and, waving his men on, led the assault over the top of the hill. Electrified by this action, another body of soldiers followed and seized the hill. …", "facts": [["Recipient", "Charles W. Davis"], ["Rank", "Captain"], ["Service", "Army"], ["Place of action", "Guadalcanal, Solomon Islands"]], "wiki": {"Charles W. Davis": "Charles_W._Davis"}},
  {"id": "1943-01-31-deblanc-jefferson-j", "date": "1943-01-31", "title": "Captain Jefferson J. DeBlanc", "type": "attack", "theater": "Marine Corps", "location": {"name": "Off Kolombangara Island, New Georgia Group, Solomon Islands", "lat": -7.9667, "lng": 157.0667}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Leader of a Section of Six Fighter Planes in Marine Fighting Squadron ONE HUNDRED TWELVE, during aerial operations against enemy Japanese forces off Kolombangara Island in the Solomons Group, 31 January 1943. Taking off with his section as escort for a strike force of dive bombers and torpedo planes ordered to attack Japanese surface vessels, First Lieutenant DeBlanc led his flight directly to the target area where, at 14,000 feet, our strike force encountered a large number Japanese Zeros protecting the enemy's surface craft. …", "facts": [["Recipient", "Jefferson J. DeBlanc"], ["Rank", "Captain"], ["Service", "Marine Corps"], ["Place of action", "Off Kolombangara Island, New Georgia Group, Solomon Islands"]], "wiki": {"Jefferson J. DeBlanc": "Jefferson_J._DeBlanc"}},
  {"id": "1943-03-08-watson-george", "date": "1943-03-08", "title": "Private George Watson", "type": "loss", "theater": "Army", "location": {"name": "At sea near New Guinea (approx.)", "lat": -5.0, "lng": 148.0}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity at the risk of life above and beyond the call of duty: Private George Watson, United States Army, distinguished himself by extraordinary heroism on 8 March 1943, while serving in the Pacific Command with the 2d Battalion, 29th Quartermaster Regiment, near Porlock Harbor, New Guinea. Private Watson was onboard a troop ship, the Dutch Steamer (United States Army Transport) Jacob, when it was attacked and hit by enemy bombers. Before it sank, the ship was abandoned. Private Watson, instead of seeking to save himself, remained in deep waters long enough to assist several soldiers who could not swim to reach the safety of a life raft. This heroic action, which subsequently cost him his life, resulted in saving the lives of several of his comrades. Weakened by continuous physical exertion and overcome by muscular fatigue, Private Watson drowned when the suction of the sinking ship dragged him beneath the surface of the swirling waters. …", "facts": [["Recipient", "George Watson"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "At sea near New Guinea"], ["Awarded", "Posthumously"]], "wiki": {"George Watson": "George_Watson_(Medal_of_Honor)"}},
  {"id": "1943-03-18-mathis-jack-w", "date": "1943-03-18", "title": "First Lieutenant Jack W. Mathis", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Over Vegesack, Germany (approx.)", "lat": 53.1686, "lng": 8.625}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy over Vegesack, Germany, on March 18, 1943. 1st Lt. Mathis, as leading bombardier of his squadron, flying through intense and accurate antiaircraft fire, was just starting his bomb run, upon which the entire squadron depended for accurate bombing, when he was hit by the enemy antiaircraft fire. His right arm was shattered above the elbow, a large wound was torn in his side and abdomen, and he was knocked from his bomb sight to the rear of the bombardier's compartment. Realizing that the success of the mission depended upon him, 1st Lt. Mathis, by sheer determination and willpower, though mortally wounded, dragged himself back to his sights, released his bombs, then died at his post of duty. As the result of this action the airplanes of his bombardment squadron placed their bombs directly upon the assigned target for a perfect attack against the enemy. 1st Lt. …", "facts": [["Recipient", "Jack W. Mathis"], ["Rank", "First Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Over Vegesack, Germany"], ["Awarded", "Posthumously, G.O. No. 38, July 12, 1943"]], "wiki": {"Jack W. Mathis": "Jack_W._Mathis"}},
  {"id": "1943-04-07-swett-james-e", "date": "1943-04-07", "title": "First Lieutenant James E. Swett", "type": "attack", "theater": "Marine Corps", "location": {"name": "Solomon Islands area (approx.)", "lat": -9.0, "lng": 159.0}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty, as a division leader in Marine Fighting Squadron TWO TWENTY-ONE in action against enemy Japanese aerial forces in the Solomon Islands Area, April 7, 1943. In a daring flight to intercept a wave of 150 Japanese planes, First Lieutenant Swett unhesitatingly hurled his four-plane division into action against a formation of fifteen enemy bombers and during his dive personally exploded three hostile planes in mid-air with accurate and deadly fire. Although separated from his division while clearing the heavy concentration of anti-aircraft fire, he boldly attacked six enemy bombers, engaged the first four in turn, and unaided, shot them down in flames. Exhausting his ammunition as he closed the fifth Japanese bomber, he relentlessly drove his attack against terrific opposition which partially disabled his engine, shattered the windscreen and slashed his face. …", "facts": [["Recipient", "James E. Swett"], ["Rank", "First Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Solomon Islands area"]], "wiki": {"James E. Swett": "James_E._Swett"}},
  {"id": "1943-04-09-booker-robert-d", "date": "1943-04-09", "title": "Private Robert D. Booker", "type": "loss", "theater": "Army", "location": {"name": "Near Fondouk, Tunisia (approx.)", "lat": 35.57, "lng": 9.85}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty in action. On 9 April 1943 in the vicinity of Fondouk, Tunisia, Pvt. Booker, while engaged in action against the enemy, carried a light machinegun and a box of ammunition over 200 yards of open ground. He continued to advance despite the fact that 2 enemy machineguns and several mortars were using him as an individual target. Although enemy artillery also began to register on him, upon reaching his objective he immediately commenced firing. After being wounded he silenced 1 enemy machinegun and was beginning to fire at the other when he received a second mortal wound. With his last remaining strength he encouraged the members of his squad and directed their fire. Pvt. Booker acted without regard for his own safety. His initiative and courage against insurmountable odds are an example of the highest standard of self-sacrifice and fidelity to duty.", "facts": [["Recipient", "Robert D. Booker"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Fondouk, Tunisia"], ["Awarded", "Posthumously"]], "wiki": {"Robert D. Booker": "Robert_D._Booker"}},
  {"id": "1943-04-24-nelson-william-l", "date": "1943-04-24", "title": "Sergeant William L. Nelson", "type": "loss", "theater": "Army", "location": {"name": "Djebel Dardys, Northwest of Sedjenane, Tunisia (approx.)", "lat": 37.1, "lng": 9.15}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life, above and beyond the call of duty in action involving actual conflict at Djebel Dardys, northwest of Sedjenane, Tunisia. On the morning of April 24, 1943, Sgt. WILLIAM NELSON led his section of heavy mortars to a forward position where he placed his guns and men. Under intense enemy artillery, mortar, and small-arms fire, he advanced alone to a chosen observation position from which he directed the laying of a concentrated mortar barrage which successfully halted an initial enemy counterattack. Although mortally wounded in the accomplishment of his mission, and with his duty clearly completed, Sgt. WILLIAM NELSON crawled to a still more advanced observation point and continued to direct the fire of his section. Dying of hand grenade wounds and only 50 yards from the enemy, Sgt. WILLIAM NELSON encouraged his section to continue their fire and by doing so they took a heavy toll of enemy lives. The skill which Sgt. …", "facts": [["Recipient", "William L. Nelson"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Djebel Dardys, Northwest of Sedjenane, Tunisia"], ["Awarded", "Posthumously"]], "wiki": {"William L. Nelson": "William_L._Nelson_(Medal_of_Honor)"}},
  {"id": "1943-04-28-minue-nicholas", "date": "1943-04-28", "title": "Private Nicholas Minue", "type": "loss", "theater": "Army", "location": {"name": "Near MedjezelBab, Tunisia (approx.)", "lat": 36.65, "lng": 9.61}, "zoom": 9, "summary": "For distinguishing himself conspicuously by gallantry and intrepidity at the loss of his life above and beyond the call of duty in action with the enemy on 28 April 1943, in the vicinity of Majaz al Bab, Tunisia. When the advance of the assault elements of Company A was held up by flanking fire from an enemy machinegun nest, Pvt. Minue voluntarily, alone, and unhesitatingly, with complete disregard of his own welfare, charged the enemy entrenched position with fixed bayonet. Pvt. Minue assaulted the enemy under a withering machinegun and rifle fire, killing approximately 10 enemy machinegunners and riflemen. After completely destroying this position, Pvt. Minue continued forward, routing enemy riflemen from dugout positions until he was fatally wounded. The courage, fearlessness and aggressiveness displayed by Pvt. Minue in the face of inevitable death was unquestionably the factor that gave his company the offensive spirit that was necessary for advancing and driving the enemy from the entire sector.", "facts": [["Recipient", "Nicholas Minue"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near MedjezelBab, Tunisia"], ["Awarded", "Posthumously, G.O. No. 24, March 25, 1944"]], "wiki": {"Nicholas Minue": "Nicholas_Minue"}},
  {"id": "1943-05-01-smith-maynard-h", "date": "1943-05-01", "title": "Sergeant Maynard H. Smith", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Over Brest, France (approx.)", "lat": 48.39, "lng": -4.49}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity in action above and beyond the call of duty. The aircraft of which Sgt. Smith was a gunner was subjected to intense enemy antiaircraft fire and determined fighter aircraft attacks while returning from a mission over enemy-occupied continental Europe on 1 May 1943. The aircraft was hit several times by antiaircraft fire and cannon shells of the fighter aircraft, 2 of the crewmen were seriously wounded, the aircraft's oxygen system shot out, and several vital control cables severed when intense fires were ignited simultaneously in the radio compartment and waist sections. The situation became so acute that 3 of the crewmen bailed out into the comparative safety of the sea. Sgt. Smith, then on his first combat mission, elected to fight the fire by himself, administered first aid to the wounded tail gunner, manned the waist guns, and fought the intense flames alternately. …", "facts": [["Recipient", "Maynard H. Smith"], ["Rank", "Sergeant"], ["Service", "Army Air Forces"], ["Place of action", "Over Brest, France"]], "wiki": {"Maynard H. Smith": "Maynard_Harrison_Smith"}},
  {"id": "1943-05-26-martinez-joe-p", "date": "1943-05-26", "title": "Private Joe P. Martinez", "type": "loss", "theater": "Army", "location": {"name": "Attu, Aleutians (approx.)", "lat": 52.9, "lng": 173.2}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy. Over a period of several days, repeated efforts to drive the enemy from a key defensive position high in the snow-covered precipitous mountains between East Arm Holtz Bay and Chichagof Harbor had failed. On 26 May 1943, troop dispositions were readjusted and a trial coordinated attack on this position by a reinforced battalion was launched. Initially successful, the attack hesitated. In the face of severe hostile machine gun, rifle, and mortar fire, Pvt. Martinez, an automatic rifleman, rose to his feet and resumed his advance. Occasionally he stopped to urge his comrades on. His example inspired others to follow. After a most difficult climb, Pvt. Martinez eliminated resistance from part of the enemy position by BAR fire and hand grenades, thus assisting the advance of other attacking elements. This success only partially completed the action. …", "facts": [["Recipient", "Joe P. Martinez"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Attu, Aleutians"], ["Awarded", "Posthumously, G.O. No. 71, October 27, 1943"]], "wiki": {"Joe P. Martinez": "Joe_P._Martínez"}},
  {"id": "1943-06-16-zeamer-jr-jay", "date": "1943-06-16", "title": "Captain Jay Zeamer Jr.", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Over Buka area, Solomon Islands (approx.)", "lat": -5.25, "lng": 154.62}, "zoom": 6, "summary": "In April 1943, Zeamer and the crew had been approached about a solo, 1200 mi round-trip photo-mapping mission of the western coast of Bougainville, with emphasis on Empress Augusta Bay where any marine landings would be made. Such maps were considered vital to a future invasion of the island in support of coalescing plans for the reduction of Rabaul. It was presented as a volunteer mission because extended mapping runs would require straight and level flight runs of up to 22 minutes deep through hostile territory. The necessary weather for such a run proved elusive for two months, until mid-June. When the 8th PRS was unable to get the necessary photos on June 15, Zeamer was contacted again. At 04:00 the next morning, 16 June 1943, after intense preparations in the days before, the crew headed for Bougainville. …", "facts": [["Recipient", "Jay Zeamer Jr."], ["Rank", "Captain"], ["Service", "Army Air Forces"], ["Place of action", "Over Buka area, Solomon Islands"], ["Awarded", "G.O. No. 1, January 4, 1944"]], "wiki": {"Jay Zeamer Jr.": "Jay_Zeamer_Jr."}},
  {"id": "1943-06-16-sarnoski-joseph-r", "date": "1943-06-16", "title": "Second Lieutenant Joseph R. Sarnoski", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Over Buka area, Solomon Islands (approx.)", "lat": -5.25, "lng": 154.62}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity in action above and beyond the call of duty. On 16 June 1943, 2d Lt. Sarnoski volunteered as bombardier of a crew on an important photographic mapping mission covering the heavily defended Buka area, Solomon Islands. When the mission was nearly completed, about 20 enemy fighters intercepted. At the nose guns, 2d Lt. Sarnoski fought off the first attackers, making it possible for the pilot to finish the plotted course. When a coordinated frontal attack by the enemy extensively damaged his bomber, and seriously injured 5 of the crew, 2d Lt. Sarnoski, though wounded, continued firing and shot down 2 enemy planes. A 20-millimeter shell which burst in the nose of the bomber knocked him into the catwalk under the cockpit. With indomitable fighting spirit, he crawled back to his post and kept on firing until he collapsed on his guns. 2d Lt. Sarnoski by resolute defense of his aircraft at the price of his life, made possible the completion of a vitally important mission.", "facts": [["Recipient", "Joseph R. Sarnoski"], ["Rank", "Second Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Over Buka area, Solomon Islands"], ["Awarded", "Posthumously, G.O. No. 85, December 17, 1943"]], "wiki": {"Joseph R. Sarnoski": "Joseph_Sarnoski"}},
  {"id": "1943-07-06-van-voorhis-bruce-a", "date": "1943-07-06", "title": "Commander Bruce A. Van Voorhis", "type": "loss", "theater": "Navy", "location": {"name": "Greenwich Island, battle of the Solomon Islands (approx.)", "lat": 1.07, "lng": 154.77}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Squadron Commander of Bombing Squadron 102 and as Plane Commander of a PB4Y-I Patrol Bomber operating against the enemy on Japanese-held Kapingamarangi Atoll during the battle of the Solomon Islands, July 6, 1943. Fully aware of the limited chance of surviving an urgent mission, voluntarily undertaken to prevent a surprise Japanese attack against our forces, Lt. Comdr. Van Voorhis took off in total darkness on a perilous 700-mile flight without escort or support. Successful in reaching his objective despite treacherous and varying winds, low visibility and difficult terrain, he fought a lone but relentless battle under fierce antiaircraft fire and overwhelming aerial opposition. Forced lower and lower by pursuing planes, he coolly persisted in his mission of destruction. …", "facts": [["Recipient", "Bruce A. Van Voorhis"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "Greenwich Island, battle of the Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"Bruce A. Van Voorhis": "Bruce_Van_Voorhis"}},
  {"id": "1943-07-09-parle-john-j", "date": "1943-07-09", "title": "Ensign John J. Parle", "type": "loss", "theater": "Navy", "location": {"name": "Aboard a landing ship, USS LST 375, off Sicily (approx.)", "lat": 37.08, "lng": 14.24}, "zoom": 9, "summary": "For valor and courage above and beyond the call of duty as Officer-in-Charge of Small Boats in the USS LST-375 during the amphibious assault on the island of Sicily, 9–10 July 1943. Realizing that a detonation of explosives would prematurely disclose to the enemy the assault about to be carried out, and with full knowledge of the peril involved, Ens. Parle unhesitatingly risked his life to extinguish a smoke pot accidentally ignited in a boat carrying charges of high explosives, detonating fuses and ammunition. Undaunted by fire and blinding smoke, he entered the craft, quickly snuffed out a burning fuse, and after failing in his desperate efforts to extinguish the fire pot, finally seized it with both hands and threw it over the side. Although he succumbed a week later from smoke and fumes inhaled, Ens. Parle's heroic self-sacrifice prevented grave damage to the ship and personnel and insured the security of a vital mission. He gallantly gave his life in the service of his country.", "facts": [["Recipient", "John J. Parle"], ["Rank", "Ensign"], ["Service", "Navy"], ["Place of action", "Aboard a landing ship, USS LST 375, off Sicily"], ["Awarded", "Posthumously"]], "wiki": {"John J. Parle": "John_Joseph_Parle"}},
  {"id": "1943-07-11-craig-robert", "date": "1943-07-11", "title": "Second Lieutenant Robert Craig", "type": "loss", "theater": "Army", "location": {"name": "Near Favoratta, Sicily (approx.)", "lat": 37.13, "lng": 13.88}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty, on 11 July 1943, at Favoratta, Sicily. Second Lt. Craig voluntarily undertook the perilous task of locating and destroying a hidden enemy machine gun which had halted the advance of his company. Attempts by three other officers to locate the weapon had resulted in failure, with each officer receiving wounds. Second Lt. Craig located the gun and snaked his way to a point within 35 yards of the hostile position before being discovered. Charging headlong into the furious automatic fire, he reached the gun, stood over it, and killed the three crew members with his carbine. With this obstacle removed, his company continued its advance. Shortly thereafter, while advancing down the forward slope of a ridge, 2d Lt. Craig and his platoon, in a position devoid of cover and concealment, encountered the fire of approximately 100 enemy soldiers. …", "facts": [["Recipient", "Robert Craig"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Near Favoratta, Sicily"], ["Awarded", "Posthumously"]], "wiki": {"Robert Craig": "Robert_Craig_(Medal_of_Honor)"}},
  {"id": "1943-07-17-waybur-david-c", "date": "1943-07-17", "title": "First Lieutenant David C. Waybur", "type": "attack", "theater": "Army", "location": {"name": "Near Agrigento, Sicily", "lat": 37.3125, "lng": 13.575}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of life above and beyond the call of duty in action involving actual conflict with the enemy. Commander of a reconnaissance platoon, 1st Lt. Waybur volunteered to lead a 3-vehicle patrol into enemy-held territory to locate an isolated Ranger unit. Proceeding under cover of darkness, over roads known to be heavily mined, and strongly defended by road blocks and machinegun positions, the patrol's progress was halted at a bridge which had been destroyed by enemy troops and was suddenly cut off from its supporting vehicles by 4 enemy tanks. Although hopelessly outnumbered and out-gunned, and himself and his men completely exposed, he quickly dispersed his vehicles and ordered his gunners to open fire with their .30 and .50 caliber machineguns. …", "facts": [["Recipient", "David C. Waybur"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Agrigento, Sicily"]], "wiki": {"David C. Waybur": "David_C._Waybur"}},
  {"id": "1943-07-27-petrarca-frank-j", "date": "1943-07-27", "title": "Private First Class Frank J. Petrarca", "type": "loss", "theater": "Army", "location": {"name": "Horseshoe Hill, New Georgia, Solomon Islands", "lat": -8.25, "lng": 157.5}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity in action above and beyond the call of duty. Pfc. Petrarca advanced with the leading troop element to within 100 yards of the enemy fortifications where mortar and small-arms fire caused a number of casualties. Singling out the most seriously wounded, he worked his way to the aid of Pfc. Scott, lying within 75 yards of the enemy, whose wounds were so serious that he could not even be moved out of the direct line of fire. Pfc Petrarca fearlessly administered first aid to Pfc. Scott and 2 other soldiers and shielded the former until his death. On 29 July 1943, Pfc. Petrarca. during an intense mortar barrage, went to the aid of his sergeant who had been partly buried in a foxhole under the debris of a shell explosion, dug him out, restored him to consciousness and caused his evacuation. …", "facts": [["Recipient", "Frank J. Petrarca"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Horseshoe Hill, New Georgia, Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"Frank J. Petrarca": "Frank_J._Petrarca"}},
  {"id": "1943-07-28-morgan-john-c", "date": "1943-07-28", "title": "Second Lieutenant John C. Morgan", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Over Germany (approx.)", "lat": 51.0, "lng": 10.0}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty, while participating on a bombing mission over enemy-occupied continental Europe, 28 July 1943. Prior to reaching the German coast on the way to the target, the B17 aircraft in which 2d Lt. (sic) Morgan was serving as co-pilot was attacked by a large force of enemy fighters, during which the oxygen system to the tail, waist, and radio gun positions was knocked out. A frontal attack placed a cannon shell through the windshield, totally shattering it, and the pilot's skull was split open by a .303 caliber shell, leaving him in a crazed condition. The pilot fell over the steering wheel, tightly clamping his arms around it. 2d Lt. Morgan at once grasped the controls from his side and, by sheer strength, pulled the aircraft back into formation despite the frantic struggles of the semiconscious pilot. The interphone had been destroyed, rendering it impossible to call for help. …", "facts": [["Recipient", "John C. Morgan"], ["Rank", "Second Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Over Germany"]], "wiki": {"John C. Morgan": "John_C._Morgan"}},
  {"id": "1943-07-29-scott-robert-s", "date": "1943-07-29", "title": "First Lieutenant Robert S. Scott", "type": "attack", "theater": "Army", "location": {"name": "Near Munda Air Strip, New Georgia, Solomon Islands", "lat": -8.25, "lng": 157.5}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty near Munda Airstrip, New Georgia, Solomon Islands, on 29 July 1943. After 27 days of bitter fighting, the enemy held a hilltop salient which commanded the approach to Munda Airstrip. Our troops were exhausted from prolonged battle and heavy casualties, but Lt. Scott advanced with the leading platoon of his company to attack the enemy position, urging his men forward in the face of enemy rifle and enemy machinegun fire. He had pushed forward alone to a point midway across the barren hilltop within 75 yards of the enemy when the enemy launched a desperate counterattack, which if successful would have gained undisputed possession of the hill. Enemy riflemen charged out on the plateau, firing and throwing grenades as they moved to engage our troops. The company withdrew, but Lt. Scott, with only a blasted tree stump for cover, stood his ground against the wild enemy assault. …", "facts": [["Recipient", "Robert S. Scott"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Munda Air Strip, New Georgia, Solomon Islands"], ["Awarded", "G.O. No. 81, 14 October 1944"]], "wiki": {"Robert S. Scott": "Robert_S._Scott"}},
  {"id": "1943-07-31-young-rodger-w", "date": "1943-07-31", "title": "Private Rodger W. Young", "type": "loss", "theater": "Army", "location": {"name": "New Georgia, Solomon Islands", "lat": -8.25, "lng": 157.5}, "zoom": 9, "summary": "On July 31, 1943, the infantry company of which Pvt. Young was a member, was ordered to make a limited withdrawal from the battle line in order to adjust the battalion's position for the night. At this time, Pvt. Young's platoon was engaged with the enemy in a dense jungle where observation was very limited. The platoon suddenly was pinned down by intense fire from a Japanese machinegun concealed on higher ground only 75 yards away. The initial burst wounded Pvt. Young. As the platoon started to obey the order to withdraw, Pvt. Young called out that he could see the enemy emplacement, whereupon he started creeping toward it. Another burst from the machine gun wounded him the second time. Despite the wounds, he continued his heroic advance, attracting enemy fire and answering with rifle fire. When he was close enough to his objective, he began throwing hand grenades, and while doing so was hit again and killed. Pvt. …", "facts": [["Recipient", "Rodger W. Young"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "New Georgia, Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"Rodger W. Young": "Rodger_Young"}},
  {"id": "1943-07-31-kisters-gerry-h", "date": "1943-07-31", "title": "Sergeant Gerry H. Kisters", "type": "attack", "theater": "Army", "location": {"name": "Near Gagliano, Sicily (approx.)", "lat": 37.71, "lng": 14.53}, "zoom": 9, "summary": "On 31 July 1943, near Gagliano, Sicily, a detachment of 1 officer and 9 enlisted men, including Sgt. Kisters, advancing ahead of the leading elements of U.S. troops to fill a large crater in the only available vehicle route through Gagliano, was taken under fire by 2 enemy machineguns. Sgt. Kisters and the officer, unaided and in the face of intense small arms fire, advanced on the nearest machinegun emplacement and succeeded in capturing the gun and its crew of 4. Although the greater part of the remaining small arms fire was now directed on the captured machinegun position, Sgt. Kisters voluntarily advanced alone toward the second gun emplacement. While creeping forward, he was struck 5 times by enemy bullets, receiving wounds in both legs and his right arm. Despite the wounds, he continued to advance on the enemy, and captured the second machinegun after killing 3 of its crew and forcing the fourth member to flee. …", "facts": [["Recipient", "Gerry H. Kisters"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Gagliano, Sicily"]], "wiki": {"Gerry H. Kisters": "Gerry_H._Kisters"}},
  {"id": "1943-08-01-kane-john-r", "date": "1943-08-01", "title": "Colonel John R. Kane", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Ploiești Raid, Romania (approx.)", "lat": 44.94, "lng": 26.03}, "zoom": 9, "summary": "For conspicuous gallantry in action and intrepidity at the risk of his life above and beyond the call of duty on 1 August 1943. On this date he led the third element of heavy bombardment aircraft in a mass low-level bombing attack against the vitally important enemy target of the Ploesti oil refineries. En route to the target, which necessitated a round-trip flight of over 2,400 miles, Col. Kane's element became separated from the leading portion of the massed formation in avoiding dense and dangerous cumulous cloud conditions over mountainous terrain. Rather than turn back from such a vital mission he elected to proceed to his target. Upon arrival at the target area it was discovered that another group had apparently missed its target and had previously attacked and damaged the target assigned to Col. Kane's element. …", "facts": [["Recipient", "John R. Kane"], ["Rank", "Colonel"], ["Service", "Army Air Forces"], ["Place of action", "Ploiești Raid, Romania"]], "wiki": {"John R. Kane": "John_R._Kane"}},
  {"id": "1943-08-01-johnson-leon-w", "date": "1943-08-01", "title": "Colonel Leon W. Johnson", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Ploiești Raid, Romania (approx.)", "lat": 44.94, "lng": 26.03}, "zoom": 9, "summary": "For conspicuous gallantry in action and intrepidity at the risk of his life above and beyond the call of duty on 1 August 1943. Col. Johnson, as commanding officer of a heavy bombardment group, led the formation of the aircraft of his organization constituting the fourth element of the mass low-level bombing attack of the 9th U.S. Air Force against the vitally important enemy target of the Ploesti oil refineries. While proceeding to the target on this 2,400-mile flight, his element became separated from the leading elements of the mass formation in maintaining the formation of the unit while avoiding dangerous cumulous cloud conditions encountered over mountainous territory. Though temporarily lost, he reestablished contact with the third element and continued on the mission with this reduced force to the prearranged point of attack, where it was discovered that the target assigned to Col. Johnson's group had been attacked and damaged by a preceding element. …", "facts": [["Recipient", "Leon W. Johnson"], ["Rank", "Colonel"], ["Service", "Army Air Forces"], ["Place of action", "Ploiești Raid, Romania"], ["Awarded", "G.O. No. 54, 7 September 1943"]], "wiki": {"Leon W. Johnson": "Leon_W._Johnson"}},
  {"id": "1943-08-01-baker-addison-e", "date": "1943-08-01", "title": "Lieutenant Colonel Addison E. Baker", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Over Ploiești, Romania (Operation Tidal Wave) (approx.)", "lat": 44.9411, "lng": 26.0225}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy on August 1, 1943. On this date he led his command, the 93d Heavy Bombardment Group, on a daring low-level attack against enemy oil refineries and installations at Ploesti, Rumania. Approaching the target, his aircraft was hit by a large caliber antiaircraft shell, seriously damaged and set on fire. Ignoring the fact he was flying over terrain suitable for safe landing, he refused to jeopardize the mission by breaking up the lead formation and continued unswervingly to lead his group to the target upon which he dropped his bombs with devastating effect. Only then did he leave formation, but his valiant attempts to gain sufficient altitude for the crew to escape by parachute were unavailing and his aircraft crashed in flames after his successful efforts to avoid other planes in formation. By extraordinary flying skill, gallant leadership and intrepidity, Lt. Col. Baker rendered outstanding, distinguished, and valorous service to our Nation.", "facts": [["Recipient", "Addison E. Baker"], ["Rank", "Lieutenant Colonel"], ["Service", "Army Air Forces"], ["Place of action", "Over Ploiești, Romania (Operation Tidal Wave)"], ["Awarded", "Posthumously, G.O. No. 20, March 11, 1944"]], "wiki": {"Addison E. Baker": "Addison_Baker"}},
  {"id": "1943-08-01-jerstad-john-l", "date": "1943-08-01", "title": "Major John L. Jerstad", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Ploiești Raid, Romania (approx.)", "lat": 44.94, "lng": 26.03}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty. On 1 August 1943, he served as pilot of the lead aircraft in his group in a daring low-level attack against enemy oil refineries and installations at Ploesti, Romania. Although he had completed more than his share of missions and was no longer connected with this group, so high was his conception of duty that he volunteered to lead the formation in the correct belief that his participation would contribute materially to success in this attack. Maj. Jerstad led the formation into attack with full realization of the extreme hazards involved and despite withering fire from heavy and light antiaircraft guns. Three miles from the target his airplane was hit, badly damaged, and set on fire. Ignoring the fact that he was flying over a field suitable for a forced landing, he kept on the course. …", "facts": [["Recipient", "John L. Jerstad"], ["Rank", "Major"], ["Service", "Army Air Forces"], ["Place of action", "Ploiești Raid, Romania"], ["Awarded", "Posthumously"]], "wiki": {"John L. Jerstad": "John_L._Jerstad"}},
  {"id": "1943-08-01-hughes-lloyd-herber", "date": "1943-08-01", "title": "Second Lieutenant Lloyd Herbert Hughes", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Ploiești Raid, Romania (approx.)", "lat": 44.94, "lng": 26.03}, "zoom": 9, "summary": "For conspicuous gallantry in action and intrepidity at the risk of his life above and beyond the call of duty. On August 1943, 2d Lt. Hughes served in the capacity of pilot of a heavy bombardment aircraft participating in a long and hazardous minimum-altitude attack against the Axis oil refineries of Ploesti, Rumania, launched from the northern shores of Africa. Flying in the last formation to attack the target, he arrived in the target area after previous flights had thoroughly alerted the enemy defenses. Approaching the target through intense and accurate antiaircraft fire and dense balloon barrages at dangerously low altitude, his plane received several direct hits from both large and small caliber antiaircraft guns which seriously damaged his aircraft, causing sheets of escaping gasoline to stream from the bomb bay and from the left wing. This damage was inflicted at a time prior to reaching the target when 2d Lt. Hughes could have made a forced landing in any of the grain fields readily available at that time. …", "facts": [["Recipient", "Lloyd Herbert Hughes"], ["Rank", "Second Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Ploiești Raid, Romania"], ["Awarded", "Posthumously"]], "wiki": {"Lloyd Herbert Hughes": "Lloyd_Herbert_Hughes"}},
  {"id": "1943-08-05-reese-james-w", "date": "1943-08-05", "title": "Private James W. Reese", "type": "loss", "theater": "Army", "location": {"name": "Mt. Vassillio, Sicily (approx.)", "lat": 37.79, "lng": 14.6}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of life, above and beyond the call of duty in action involving actual conflict with the enemy. When the enemy launched a counterattack which threatened the position of his company, Pvt. Reese, as the acting squad leader of a 60-mm. mortar squad, displaying superior leadership on his own initiative, maneuvered his squad forward to a favorable position, from which, by skillfully directing the fire of his weapon, he caused many casualties in the enemy ranks, and aided materially in repulsing the counterattack. When the enemy fire became so severe as to make his position untenable, he ordered the other members of his squad to withdraw to a safer position, but declined to seek safety for himself. So as to bring more effective fire upon the enemy, Pvt. Reese, without assistance, moved his mortar to a new position and attacked an enemy machinegun nest. …", "facts": [["Recipient", "James W. Reese"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Mt. Vassillio, Sicily"], ["Awarded", "Posthumously"]], "wiki": {"James W. Reese": "James_W._Reese"}},
  {"id": "1943-08-15-walsh-kenneth-a", "date": "1943-08-15", "title": "First Lieutenant Kenneth A. Walsh", "type": "attack", "theater": "Marine Corps", "location": {"name": "Solomon Islands area (approx.)", "lat": -9.0, "lng": 159.0}, "zoom": 6, "summary": "For extraordinary heroism and intrepidity above and beyond the call of duty as a pilot in Marine Fighting Squadron 124 in aerial combat against enemy Japanese forces in the Solomon Islands area. Determined to thwart the enemy's attempt to bomb Allied ground forces and shipping at Vella Lavella on 15 August 1943, 1st Lt. Walsh repeatedly dived his plane into an enemy formation outnumbering his own division 6 to 1 and, although his plane was hit numerous times, shot down 2 Japanese dive bombers and 1 fighter. After developing engine trouble on 30 August during a vital escort mission, 1st Lt. Walsh landed his mechanically disabled plane at Munda, quickly replaced it with another, and proceeded to rejoin his flight over Kahili. Separated from his escort group when he encountered approximately 50 Japanese Zeros, he unhesitatingly attacked, striking with relentless fury in his lone battle against a powerful force. …", "facts": [["Recipient", "Kenneth A. Walsh"], ["Rank", "First Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Solomon Islands area"]], "wiki": {"Kenneth A. Walsh": "Kenneth_A._Walsh"}},
  {"id": "1943-08-18-cheli-ralph", "date": "1943-08-18", "title": "Major Ralph Cheli", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Near Wewak, New Guinea", "lat": -3.55, "lng": 143.6333}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy. While Maj. Cheli was leading his squadron in a dive to attack the heavily defended Dagua Airdrome, intercepting enemy aircraft centered their fire on his plane, causing it to burst into flames while still 2 miles from the objective. His speed would have enabled him to gain necessary altitude to parachute to safety, but this action would have resulted in his formation becoming disorganized and exposed to the enemy. Although a crash was inevitable, he courageously elected to continue leading the attack in his blazing plane. From a minimum altitude, the squadron made a devastating bombing and strafing attack on the target. The mission completed, Maj. Cheli instructed his wingman to lead the formation and crashed into the sea.", "facts": [["Recipient", "Ralph Cheli"], ["Rank", "Major"], ["Service", "Army Air Forces"], ["Place of action", "Near Wewak, New Guinea"], ["Awarded", "Posthumously, G.O. No. 72, October 28, 1943"]], "wiki": {"Ralph Cheli": "Ralph_Cheli"}},
  {"id": "1943-09-04-hutchins-johnnie-d", "date": "1943-09-04", "title": "Seaman First class Johnnie D. Hutchins", "type": "loss", "theater": "Navy", "location": {"name": "Aboard a landing ship, USS LST 473, off Lae, New Guinea", "lat": -6.7303, "lng": 147.0008}, "zoom": 9, "summary": "For extraordinary heroism and conspicuous valor above and beyond the call of duty while serving on board a Landing Ship, Tank, during the assault on Lae, New Guinea, 4 September 1943. As the ship on which Hutchins was stationed approached the enemy-occupied beach under a veritable hail of fire from Japanese shore batteries and aerial bombardment, a hostile torpedo pierced the surf and bore down upon the vessel with deadly accuracy. In the tense split seconds before the helmsman could steer clear of the threatening missile, a bomb struck the pilot house, dislodged him from his station, and left the stricken ship helplessly exposed. Fully aware of the dire peril of the situation, Hutchins, although mortally wounded by the shattering explosion, quickly grasped the wheel and exhausted the last of his strength in maneuvering the vessel clear of the advancing torpedo. …", "facts": [["Recipient", "Johnnie D. Hutchins"], ["Rank", "Seaman First class"], ["Service", "Navy"], ["Place of action", "Aboard a landing ship, USS LST 473, off Lae, New Guinea"], ["Awarded", "Posthumously"]], "wiki": {"Johnnie D. Hutchins": "Johnnie_David_Hutchins"}},
  {"id": "1943-09-09-logan-james-m", "date": "1943-09-09", "title": "Sergeant James M. Logan", "type": "attack", "theater": "Army", "location": {"name": "Near Salerno, Italy", "lat": 40.6806, "lng": 14.7594}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty in action involving actual conflict on 9 September 1943 in the vicinity of Salerno, Italy. As a rifleman of an infantry company, Sgt. Logan landed with the first wave of the assault echelon on the beaches of the Gulf of Salerno, and after his company had advanced 800 yards inland and taken positions along the forward bank of an irrigation canal, the enemy began a serious counterattack from positions along a rock wall which ran parallel with the canal about 200 yards further inland. Voluntarily exposing himself to the fire of a machinegun located along the rock wall, which sprayed the ground so close to him that he was splattered with dirt and rock splinters from the impact of the bullets, Sgt. Logan killed the first 3 Germans as they came through a gap in the wall. He then attacked the machinegun. …", "facts": [["Recipient", "James M. Logan"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Salerno, Italy"]], "wiki": {"James M. Logan": "James_M._Logan"}},
  {"id": "1943-09-12-boyington-pappy", "date": "1943-09-12", "title": "Major Pappy Boyington", "type": "attack", "theater": "Marine Corps", "location": {"name": "Central Solomons area (approx.)", "lat": -8.0, "lng": 157.5}, "zoom": 9, "summary": "For extraordinary heroism above and beyond the call of duty as Commanding Officer of Marine Fighting Squadron TWO FOURTEEN in action against enemy Japanese forces in Central Solomons Area from September 12, 1943, to January 3, 1944. Consistently outnumbered throughout successive hazardous flights over heavily defended hostile territory, Major Boyington struck at the enemy with daring and courageous persistence, leading his squadron into combat with devastating results to Japanese shipping, shore installations and aerial forces. Resolute in his efforts to inflict crippling damage on the enemy, Major BOYINGTON led a formation of twenty-four fighters over Kahili on October 17, and persistently circling the airdrome where sixty hostile aircraft were grounded, boldly challenged the Japanese to send up planes. Under his brilliant command, our fighters shot down twenty enemy craft in the ensuing action without the loss of a single ship. …", "facts": [["Recipient", "Pappy Boyington"], ["Rank", "Major"], ["Service", "Marine Corps"], ["Place of action", "Central Solomons area"]], "wiki": {"Pappy Boyington": "Pappy_Boyington"}},
  {"id": "1943-09-13-kelly-charles-e", "date": "1943-09-13", "title": "Corporal Charles E. Kelly", "type": "attack", "theater": "Army", "location": {"name": "Near Altavilla, Italy (approx.)", "lat": 40.53, "lng": 15.13}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. On 13 September 1943, near Altavilla, Italy, Cpl. Kelly voluntarily joined a patrol which located and neutralized enemy machine gun positions. After this hazardous duty he volunteered to establish contact with a battalion of U.S. infantry which was believed to be located on Hill 315, a mile distant. He traveled over a route commanded by enemy observation and under sniper, mortar, and artillery fire; and later he returned with the correct information that the enemy occupied Hill 315 in organized positions. Immediately thereafter Cpl. Kelly, again a volunteer patrol member, assisted materially in the destruction of 2 enemy machinegun nests under conditions requiring great skill and courage. Having effectively fired his weapon until all the ammunition was exhausted, he secured permission to obtain more at an ammunition dump. Arriving at the dump, which was located near a storehouse on the extreme flank of his regiment's position, Cpl. …", "facts": [["Recipient", "Charles E. Kelly"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Near Altavilla, Italy"]], "wiki": {"Charles E. Kelly": "Charles_E._Kelly_(soldier)"}},
  {"id": "1943-09-13-bjorklund-arnold-l", "date": "1943-09-13", "title": "First Lieutenant Arnold L. Bjorklund", "type": "attack", "theater": "Army", "location": {"name": "Near Altavilla, Italy (approx.)", "lat": 40.53, "lng": 15.13}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of life above and beyond the call of duty in action with the enemy near Altavilla, Italy, September 13, 1943. When his company attacked a German position on Hill 424, the first platoon, led by 1st Lt. Bjorklund, moved forward on the right flank to the slope of the hill where it was pinned down by a heavy concentration of machinegun and rifle fire. Ordering his men to give covering fire, with only 3 hand grenades, he crept and crawled forward to a German machinegun position located on a terrace along the forward slope. Approaching within a few yards of the position, and while continuously exposed to enemy fire, he hurled 1 grenade into the nest, destroyed the gun and killed 3 Germans. …", "facts": [["Recipient", "Arnold L. Bjorklund"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Altavilla, Italy"]], "wiki": {"Arnold L. Bjorklund": "Arnold_L._Bjorklund"}},
  {"id": "1943-09-13-crawford-william-j", "date": "1943-09-13", "title": "Private William J. Crawford", "type": "attack", "theater": "Army", "location": {"name": "Near Altavilla, Italy (approx.)", "lat": 40.53, "lng": 15.13}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty in action with the enemy near Altavilla, Italy, 13 September 1943. When Company I attacked an enemy-held position on Hill 424, the 3rd Platoon, in which Pvt. Crawford was a squad scout, attacked as base platoon for the company. After reaching the crest of the hill, the platoon was pinned down by intense enemy machine-gun and small-arms fire. Locating 1 of these guns, which was dug in on a terrace on his immediate front, Pvt. Crawford, without orders and on his own initiative, moved over the hill under enemy fire to a point within a few yards of the gun emplacement and single-handedly destroyed the machine-gun and killed 3 of the crew with a hand grenade, thus enabling his platoon to continue its advance. When the platoon, after reaching the crest, was once more delayed by enemy fire, Pvt. …", "facts": [["Recipient", "William J. Crawford"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Altavilla, Italy"]], "wiki": {"William J. Crawford": "William_J._Crawford"}},
  {"id": "1943-09-22-childers-ernest", "date": "1943-09-22", "title": "Second Lieutenant Ernest Childers", "type": "attack", "theater": "Army", "location": {"name": "Oliveto, Italy (approx.)", "lat": 40.69, "lng": 15.23}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty in action on 22 September 1943, at Oliveto, Italy. Although 2d Lt. Childers previously had just suffered a fractured instep he, with 8 enlisted men, advanced up a hill toward enemy machinegun nests. The group advanced to a rock wall overlooking a cornfield and 2d Lt. Childers ordered a base of fire laid across the field so that he could advance. When he was fired upon by 2 enemy snipers from a nearby house he killed both of them. He moved behind the machinegun nests and killed all occupants of the nearer one. He continued toward the second one and threw rocks into it. When the 2 occupants of the nest raised up, he shot 1. The other was killed by 1 of the 8 enlisted men. 2d Lt. Childers continued his advance toward a house farther up the hill and, single-handed, captured an enemy mortar observer. …", "facts": [["Recipient", "Ernest Childers"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Oliveto, Italy"]], "wiki": {"Ernest Childers": "Ernest_Childers"}},
  {"id": "1943-09-23-slaton-james-d", "date": "1943-09-23", "title": "Corporal James D. Slaton", "type": "attack", "theater": "Army", "location": {"name": "Near Oliveto, Italy (approx.)", "lat": 40.69, "lng": 15.23}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of life above and beyond the call of duty in action with the enemy in the vicinity of Oliveto, Italy, on September 23, 1943. Cpl. Slaton was lead scout of an infantry squad which had been committed to a flank to knock out enemy resistance which had succeeded in pinning 2 attacking platoons to the ground. Working ahead of his squad, Cpl. Slaton crept upon an enemy machinegun nest and, assaulting it with his bayonet, succeeded in killing the gunner. When his bayonet stuck, he detached it from the rifle and killed another gunner with rifle fire. At that time he was fired upon by a machinegun to his immediate left. Cpl. Slaton then moved over open ground under constant fire to within throwing distance, and on his second try scored a direct hit on the second enemy machinegun nest, killing 2 enemy gunners. At that time a third machinegun fired on him 100 yards to his front, and Cpl. …", "facts": [["Recipient", "James D. Slaton"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Near Oliveto, Italy"]], "wiki": {"James D. Slaton": "James_D._Slaton"}},
  {"id": "1943-10-11-kearby-neel-e", "date": "1943-10-11", "title": "Colonel Neel E. Kearby", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Near Wewak, New Guinea", "lat": -3.55, "lng": 143.6333}, "zoom": 9, "summary": "Place and date: Near Wewak, New Guinea, 11 October 1943. For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy, Col. Kearby volunteered to lead a flight of 4 fighters to reconnoiter the strongly defended enemy base at Wewak. Having observed enemy installations and reinforcements at 4 airfields, and secured important tactical information, he saw an enemy fighter below him, made a diving attack and shot it down in flames. The small formation then sighted approximately 12 enemy bombers accompanied by 36 fighters. Although his mission had been completed, his fuel was running low, and the numerical odds were 12 to 1, he gave the signal to attack. Diving into the midst of the enemy airplanes he shot down 3 in quick succession. Observing 1 of his comrades with 2 enemy fighters in pursuit, he destroyed both enemy aircraft. …", "facts": [["Recipient", "Neel E. Kearby"], ["Rank", "Colonel"], ["Service", "Army Air Forces"], ["Place of action", "Near Wewak, New Guinea"]], "wiki": {"Neel E. Kearby": "Neel_E._Kearby"}},
  {"id": "1943-10-13-olson-arlo-l", "date": "1943-10-13", "title": "Captain Arlo L. Olson", "type": "loss", "theater": "Army", "location": {"name": "Crossing of the Volturno River, Italy (approx.)", "lat": 41.2, "lng": 14.2}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty. On October 13, 1943, when the drive across the Volturno River began, Capt. Olson and his company spearheaded the advance of the regiment through 30 miles of mountainous enemy territory in 13 days. Placing himself at the head of his men, Capt. Olson waded into the chest-deep water of the raging Volturno River and despite pointblank machine-gun fire aimed directly at him made his way to the opposite bank and threw 2 handgrenades into the gun position, killing the crew. When an enemy machinegun 150 yards distant opened fire on his company, Capt. Olson advanced upon the position in a slow, deliberate walk. Although 5 German soldiers threw handgrenades at him from a range of 5 yards, Capt. Olson dispatched them all, picked up a machine pistol and continued toward the enemy. …", "facts": [["Recipient", "Arlo L. Olson"], ["Rank", "Captain"], ["Service", "Army"], ["Place of action", "Crossing of the Volturno River, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Arlo L. Olson": "Arlo_L._Olson"}},
  {"id": "1943-10-17-van-noy-junior", "date": "1943-10-17", "title": "Private Junior Van Noy", "type": "loss", "theater": "Army", "location": {"name": "Near Finschafen, New Guinea", "lat": -6.6, "lng": 147.85}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy near Finschafen, New Guinea, on October 17, 1943. When wounded late in September, Pvt. Van Noy declined evacuation and continued on duty. On October 17, 1943 he was gunner in charge of a machinegun post only 5 yards from the water's edge when the alarm was given that 3 enemy barges loaded with troops were approaching the beach in the early morning darkness. One landing barge was sunk by Allied fire, but the other 2 beached 10 yards from Pvt. Van Noy's emplacement. Despite his exposed position, he poured a withering hail of fire into the debarking enemy troops. His loader was wounded by a grenade and evacuated. Pvt. Van Noy, also grievously wounded, remained at his post, ignoring calls of nearby soldiers urging him to withdraw, and continued to fire with deadly accuracy. He expended every round and was found, covered with wounds dead beside his gun. In this action Pvt. …", "facts": [["Recipient", "Junior Van Noy"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Finschafen, New Guinea"], ["Awarded", "Posthumously"]], "wiki": {"Junior Van Noy": "Junior_Van_Noy"}},
  {"id": "1943-11-01-hanson-robert-m", "date": "1943-11-01", "title": "First Lieutenant Robert M. Hanson", "type": "loss", "theater": "Marine Corps", "location": {"name": "Bougainville Island and New Britain Island", "lat": -6.2444, "lng": 155.3839}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as a fighter pilot attached to Marine Fighting Squadron TWO FIFTEEN in action against Japanese forces at Bougainville Islands, 1 November 1943, and New Britain Island, 24 January 1944. Undeterred by fierce opposition and fearless in the face of overwhelming odds, First Lieutenant Hanson fought the Japanese boldly and with daring aggressiveness. On 1 November, while flying cover for our landing operations at Empress Augusta Bay, he dauntlessly attacked six enemy torpedo bombers, forcing them to jettison their bombs and destroying one Japanese plane during the action. Cut off from his division while deep in enemy territory during a high cover flight over Simpson Harbor on 24 January, First Lieutenant Hanson waged a lone and gallant battle against hostile interceptors as they were orbiting to attack our bombers and, striking with devastating fury, brought down four Zeros and probably a fifth. …", "facts": [["Recipient", "Robert M. Hanson"], ["Rank", "First Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Bougainville Island and New Britain Island"], ["Awarded", "Posthumously"]], "wiki": {"Robert M. Hanson": "Robert_M._Hanson"}},
  {"id": "1943-11-01-owens-robert-a", "date": "1943-11-01", "title": "Sergeant Robert A. Owens", "type": "loss", "theater": "Marine Corps", "location": {"name": "Cape Torokina, Bougainville, Solomon Islands", "lat": -6.2475, "lng": 155.04}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with a marine division, in action against enemy Japanese forces during extremely hazardous landing operations at Cape Torokina, Bougainville, Solomon Islands, on 1 November 1943. Forced to pass within disastrous range of a strongly protected, well-camouflaged Japanese 75-mm. regimental gun strategically located on the beach, our landing units were suffering heavy losses in casualties and boats while attempting to approach the beach, and the success of the operations was seriously threatened. Observing the ineffectiveness of marine rifle and grenade attacks against the incessant, devastating fire of the enemy weapon and aware of the urgent need for prompt action, Sgt. Owens unhesitatingly determined to charge the gun bunker from the front and, calling on 4 of his comrades to assist him, carefully placed them to cover the fire of the 2 adjacent hostile bunkers. …", "facts": [["Recipient", "Robert A. Owens"], ["Rank", "Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Cape Torokina, Bougainville, Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"Robert A. Owens": "Robert_A._Owens"}},
  {"id": "1943-11-02-wilkins-raymond-h", "date": "1943-11-02", "title": "Major Raymond H. Wilkins", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Near Rabaul, New Britain", "lat": -4.2, "lng": 152.1833}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy near Rabaul, New Britain, on 2 November 1943. Leading his squadron in an attack on shipping in Simpson Harbor, during which intense antiaircraft fire was expected, Maj. Wilkins briefed his squadron so that his airplane would be in the position of greatest risk. His squadron was the last of 3 in the group to enter the target area. Smoke from bombs dropped by preceding aircraft necessitated a last-second revision of tactics on his part, which still enabled his squadron to strike vital shipping targets, but forced it to approach through concentrated fire, and increased the danger of Maj. Wilkins' left flank position. His airplane was hit almost immediately, the right wing damaged, and control rendered extremely difficult. Although he could have withdrawn, he held fast and led his squadron into the attack. He strafed a group of small harbor vessels, and then, at low level, attacked an enemy destroyer. …", "facts": [["Recipient", "Raymond H. Wilkins"], ["Rank", "Major"], ["Service", "Army Air Forces"], ["Place of action", "Near Rabaul, New Britain"], ["Awarded", "Posthumously"]], "wiki": {"Raymond H. Wilkins": "Raymond_H._Wilkins"}},
  {"id": "1943-11-07-thomas-herbert-j", "date": "1943-11-07", "title": "Sergeant Herbert J. Thomas", "type": "loss", "theater": "Marine Corps", "location": {"name": "Koromokina River, Bougainville, Solomon Islands", "lat": -6.2444, "lng": 155.3839}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the Third Marines, Third Marine Division, in action against enemy Japanese forces during the battle at the Koromokina River, Bougainville Island, Solomon Islands, on November 7, 1943. Although several of his men were struck by enemy bullets as he led his squad through dense jungle undergrowth in the face of severe hostile machine gun fire, Sergeant Thomas and his group fearlessly pressed forward into the center of the Japanese position and destroyed the crews of two machine guns by accurate rifle fire and grenades. Discovering a third gun more difficult to approach, he carefully placed his men closely around him in strategic positions from which they were to charge after he had thrown a grenade into the emplacement. …", "facts": [["Recipient", "Herbert J. Thomas"], ["Rank", "Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Koromokina River, Bougainville, Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"Herbert J. Thomas": "Herbert_Joseph_Thomas"}},
  {"id": "1943-11-09-gurke-henry", "date": "1943-11-09", "title": "Private First Class Henry Gurke", "type": "loss", "theater": "Marine Corps", "location": {"name": "Bougainville, Solomon Islands", "lat": -6.2444, "lng": 155.3839}, "zoom": 9, "summary": "For extraordinary heroism and courage above and beyond the call of duty while serving with the Third Marine Raider Battalion during action against the enemy Japanese Forces in the Solomon Islands area on November 9, 1943. While his platoon was engaged in the defense of a vital road block near Empress Augusta Bay on Bougainville Island, Private First Class Gurke, in company with another Marine, was delivering a fierce stream of fire against the main vanguard of the Japanese. Concluding from the increasing ferocity of grenade barrages that the enemy was determined to annihilate their shallow, two–man foxhole, he resorted to a bold and desperate measure for holding out despite the torrential hail of shells. When a Japanese grenade dropped squarely into the foxhole, Private First Class Gurke, mindful that his companion manned an automatic weapon of superior fire power and therefore could provide more effective resistance, thrust him roughly aside and flushing his own body over the missile to smother the explosion. …", "facts": [["Recipient", "Henry Gurke"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Bougainville, Solomon Islands"], ["Awarded", "Posthumously"]], "wiki": {"Henry Gurke": "Henry_Gurke"}},
  {"id": "1943-11-10-britt-maurice-l", "date": "1943-11-10", "title": "First Lieutenant Maurice L. Britt", "type": "attack", "theater": "Army", "location": {"name": "North of Mignano, Italy (approx.)", "lat": 41.4, "lng": 13.98}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty. Disdaining enemy hand grenades and close-range machine pistols, machineguns, and rifles, Lt. Britt inspired and led a handful of his men in repelling a bitter counterattack by approximately 100 Germans against his company positions north of Mignano, Italy, the morning of 10 November 1943. During the intense fire fight, Lt. Britt's canteen and field glasses were shattered; a bullet pierced his side; his chest, face, and hands were covered with grenade wounds. Despite his wounds, for which he refused to accept medical attention until ordered to do so by his battalion commander following the battle, he personally killed 5 and wounded an unknown number of Germans, wiped out one enemy machinegun crew, fired 5 clips of carbine and an undetermined amount of M1 rifle ammunition, and threw 32 fragmentation grenades. …", "facts": [["Recipient", "Maurice L. Britt"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "North of Mignano, Italy"]], "wiki": {"Maurice L. Britt": "Maurice_Britt"}},
  {"id": "1943-11-11-lindstrom-floyd-k", "date": "1943-11-11", "title": "Private First Class Floyd K. Lindstrom", "type": "loss", "theater": "Army", "location": {"name": "Near Mignano, Italy (approx.)", "lat": 41.4, "lng": 13.98}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. On 11 November 1943, this soldier's platoon was furnishing machinegun support for a rifle company attacking a hill near Mignano, Italy, when the enemy counterattacked, forcing the riflemen and half the machinegun platoon to retire to a defensive position. Pfc. Lindstrom saw that his small section was alone and outnumbered 5 to 1, yet he immediately deployed the few remaining men into position and opened fire with his single gun. The enemy centered fire on him with machinegun, machine pistols, and grenades. Unable to knock out the enemy nest from his original position, Pfc. Lindstrom picked up his own heavy machinegun and staggered 15 yards up the barren, rocky hillside to a new position, completely ignoring enemy small arms fire which was striking all around him. From this new site, only 10 yards from the enemy machinegun, he engaged it in an intense duel. …", "facts": [["Recipient", "Floyd K. Lindstrom"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Mignano, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Floyd K. Lindstrom": "Floyd_K._Lindstrom"}},
  {"id": "1943-11-19-cromwell-john-p", "date": "1943-11-19", "title": "Captain John P. Cromwell", "type": "loss", "theater": "Navy", "location": {"name": "USS Sculpin, off Truk Island", "lat": 7.415, "lng": 151.735}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Commander of a Submarine Coordinated Attack Group with Flag in the U.S.S. Sculpin, during the Ninth War Patrol of that vessel in enemy-controlled waters off Truk Island, November 19, 1943. Undertaking this patrol prior to the launching of our first large-scale offensive in the Pacific, Captain Cromwell, alone of the entire Task Group, possessed secret intelligence information of our submarine strategy and tactics, scheduled Fleet movements and specific attack plans. Constantly vigilant and precise in carrying out his secret orders, he moved his underseas flotilla inexorably forward despite savage opposition and established a line of submarines to southeastward of the main Japanese stronghold at Truk. Cool and undaunted as the submarine, rocked and battered by Japanese depth-charges, sustained terrific battle damage and sank to an excessive depth, he authorized the Sculpin to surface and engage the enemy in a gun-fight, thereby providing an opportunity for the crew to abandon ship. …", "facts": [["Recipient", "John P. Cromwell"], ["Rank", "Captain"], ["Service", "Navy"], ["Place of action", "USS Sculpin, off Truk Island"], ["Awarded", "Posthumously"]], "wiki": {"John P. Cromwell": "John_P._Cromwell"}},
  {"id": "1943-11-20-shoup-david-m", "date": "1943-11-20", "title": "Colonel David M. Shoup", "type": "attack", "theater": "Marine Corps", "location": {"name": "Betio Island, Tarawa Atoll, Gilbert Islands", "lat": 1.35, "lng": 172.9333}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as commanding officer of all Marine Corps troops in action against enemy Japanese forces on Betio Island, Tarawa Atoll, Gilbert Islands, from 20 to 22 November 1943. Although severely shocked by an exploding enemy shell soon after landing at the pier and suffering from a serious, painful leg wound which had become infected, Col. Shoup fearlessly exposed himself to the terrific and relentless artillery, machine gun, and rifle fire from hostile shore emplacements. Rallying his hesitant troops by his own inspiring heroism, he gallantly led them across the fringing reefs to charge the heavily fortified island and reinforce our hard-pressed, thinly held lines. Upon arrival on shore, he assumed command of all landed troops and, working without rest under constant, withering enemy fire during the next 2 days, conducted smashing attacks against unbelievably strong and fanatically defended Japanese positions despite innumerable obstacles and heavy casualties. …", "facts": [["Recipient", "David M. Shoup"], ["Rank", "Colonel"], ["Service", "Marine Corps"], ["Place of action", "Betio Island, Tarawa Atoll, Gilbert Islands"]], "wiki": {"David M. Shoup": "David_M._Shoup"}},
  {"id": "1943-11-20-bonnyman-jr-alexander", "date": "1943-11-20", "title": "First Lieutenant Alexander Bonnyman Jr.", "type": "loss", "theater": "Marine Corps", "location": {"name": "Betio Island, Tarawa Atoll, Gilbert Islands", "lat": 1.35, "lng": 172.9333}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Executive Officer of the 2d Battalion Shore Party, 8th Marines, 2d Marine Division, during the assault against enemy Japanese-held Tarawa in the Gilbert Islands, 20–22 November 1943. Acting on his own initiative when assault troops were pinned down at the far end of Betio Pier by the overwhelming fire of Japanese shore batteries, 1st Lt. Bonnyman repeatedly defied the blasting fury of the enemy bombardment to organize and lead the besieged men over the long, open pier to the beach and then, voluntarily obtaining flame throwers and demolitions, organized his pioneer shore party into assault demolitionists and directed the blowing of several hostile installations before the close of D-day. …", "facts": [["Recipient", "Alexander Bonnyman Jr."], ["Rank", "First Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Betio Island, Tarawa Atoll, Gilbert Islands"], ["Awarded", "Posthumously"]], "wiki": {"Alexander Bonnyman Jr.": "Alexander_Bonnyman_Jr."}},
  {"id": "1943-11-20-hawkins-william-d", "date": "1943-11-20", "title": "First Lieutenant William D. Hawkins", "type": "loss", "theater": "Marine Corps", "location": {"name": "Betio Island, Tarawa Atoll, Gilbert Islands", "lat": 1.35, "lng": 172.9333}, "zoom": 9, "summary": "For valorous and gallant conduct above and beyond the call of duty as Commanding Officer of a Scout Sniper Platoon attached to the Second Marines, Second Marine Division, in action against Japanese-held Tarawa in the Gilbert Islands, November 20 and 21, 1943. The first to disembark from the jeep lighter, First lieutenant Hawkins unhesitatingly moved forward under heavy enemy fire at the end of the Betio pier, neutralizing emplacements in coverage of troops assaulting the main breach positions. Fearlessly leading his men on to join the forces fighting desperately to gain a beachhead, he repeatedly risked his life throughout the day and night to direct and lead attacks on pill boxes and installations with grenades and demolition. …", "facts": [["Recipient", "William D. Hawkins"], ["Rank", "First Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Betio Island, Tarawa Atoll, Gilbert Islands"], ["Awarded", "Posthumously"]], "wiki": {"William D. Hawkins": "William_D._Hawkins"}},
  {"id": "1943-11-20-bordelon-william-j", "date": "1943-11-20", "title": "Staff Sergeant William J. Bordelon", "type": "loss", "theater": "Marine Corps", "location": {"name": "Betio Island, Tarawa Atoll, Gilbert Islands", "lat": 1.35, "lng": 172.9333}, "zoom": 9, "summary": "For valorous and gallant conduct above and beyond the call of duty as a member of an Assault Engineer Platoon of the First Battalion, Eighteenth Marines, tactically attached to the Second Marines, Second Marine Division, in action against the Japanese-held Atoll of Tarawa in the Gilbert Islands on November 20, 1943. Landing in the assault waves under withering enemy fire which killed all but four of the men in his tractor, Staff Sergeant Bordelon hurriedly made demolition charges and personally put two pill boxes out of action. Hit by enemy machine-gun fire just as a charge exploded in his hand while assaulting a third position, he courageously remained in action and, although out of demolition, provided himself with a rifle and furnished fire coverage for a group of men scaling the seawall. …", "facts": [["Recipient", "William J. Bordelon"], ["Rank", "Staff Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Betio Island, Tarawa Atoll, Gilbert Islands"], ["Awarded", "Posthumously"]], "wiki": {"William J. Bordelon": "William_J._Bordelon"}},
  {"id": "1943-11-29-hasemoto-mikio", "date": "1943-11-29", "title": "Private Mikio Hasemoto", "type": "loss", "theater": "Army", "location": {"name": "Near Cerasuolo, Italy (approx.)", "lat": 41.6, "lng": 14.08}, "zoom": 9, "summary": "Private Mikio Hasemoto distinguished himself by extraordinary heroism in action on 29 November 1943, in the vicinity of Cerasuolo, Italy. A force of approximately 40 enemy soldiers, armed with machine guns, machine pistols, rifles, and grenades, attacked the left flank of his platoon. Two enemy soldiers with machine guns advanced forward, firing their weapons. Private Hasemoto, an automatic rifleman, challenged these two machine gunners. After firing four magazines at the approaching enemy, his weapon was shot and damaged. Unhesitatingly, he ran 10 yards to the rear, secured another automatic rifle and continued to fire until his weapon jammed. At this point, Private Hasemoto and his squad leader had killed approximately 20 enemy soldiers. Again, Private Hasemoto ran through a barrage of enemy machine gun fire to pick up an M-1 rifle. Continuing their fire, Private Hasemoto and his squad leader killed 10 more enemy soldiers. With only three enemy soldiers left, he and his squad leader charged courageously forward, killing one, wounding one, and capturing another. …", "facts": [["Recipient", "Mikio Hasemoto"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Cerasuolo, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Mikio Hasemoto": "Mikio_Hasemoto"}},
  {"id": "1943-11-29-hayashi-shizuya", "date": "1943-11-29", "title": "Private Shizuya Hayashi", "type": "attack", "theater": "Army", "location": {"name": "Near Cerasuolo, Italy (approx.)", "lat": 41.6, "lng": 14.08}, "zoom": 9, "summary": "Private Shizuya Hayashi distinguished himself by extraordinary heroism in action on 29 November 1943, near Cerasuolo, Italy. During a flank assault on high ground held by the enemy, Private Hayashi rose alone in the face of grenade, rifle, and machine gun fire. Firing his automatic rifle from the hip, he charged and overtook an enemy machine gun position, killing seven men in the nest and two more as they fled. After his platoon advanced 200 yards from this point, an enemy antiaircraft gun opened fire on the men. Private Hayashi returned fire at the hostile position, killing nine of the enemy, taking four prisoners, and forcing the remainder of the force to withdraw from the hill. Private Hayashi's extraordinary heroism and devotion to duty are in keeping with the highest traditions of military service and reflect great credit on him, his unit, and the United States Army.", "facts": [["Recipient", "Shizuya Hayashi"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Cerasuolo, Italy"]], "wiki": {"Shizuya Hayashi": "Shizuya_Hayashi"}},
  {"id": "1943-11-29-ohata-allan-m", "date": "1943-11-29", "title": "Sergeant Allan M. Ohata", "type": "loss", "theater": "Army", "location": {"name": "Near Cerasuolo, Italy (approx.)", "lat": 41.6, "lng": 14.08}, "zoom": 9, "summary": "Sergeant Allan M. Ohata distinguished himself by extraordinary heroism in action on 29 and November 30, 1943, near Cerasuolo, Italy. Sergeant Ohata, his squad leader, and three men were ordered to protect his platoon's left flank against an attacking enemy force of 40 men, armed with machine guns, machine pistols, and rifles. He posted one of his men, an automatic rifleman, on the extreme left, 15 yards from his own position. Taking his position, Sergeant Ohata delivered effective fire against the advancing enemy. The man to his left called for assistance when his automatic rifle was shot and damaged. With utter disregard for his personal safety, Sergeant Ohata left his position and advanced 15 yards through heavy machine gun fire. Reaching his comrade's position, he immediately fired upon the enemy, killing 10 enemy soldiers and successfully covering his comrade's withdrawal to replace his damaged weapon. Sergeant Ohata and the automatic rifleman held their position and killed 37 enemy soldiers. …", "facts": [["Recipient", "Allan M. Ohata"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Cerasuolo, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Allan M. Ohata": "Allan_M._Ohata"}},
  {"id": "1943-12-20-vosler-forrest-l", "date": "1943-12-20", "title": "Technical Sergeant Forrest L. Vosler", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Over Bremen, Germany (approx.)", "lat": 53.0758, "lng": 8.8072}, "zoom": 6, "summary": "For conspicuous gallantry in action against the enemy above and beyond the call of duty while serving as a radio operator-air gunner on a heavy bombardment aircraft in a mission over Bremen, Germany, on 20 December 1943. After bombing the target, the aircraft in which T/Sgt. Vosler was serving was severely damaged by antiaircraft fire, forced out of formation, and immediately subjected to repeated vicious attacks by enemy fighters. Early in the engagement a 20-mm. cannon shell exploded in the radio compartment, painfully wounding T/Sgt. Vosler in the legs and thighs. At about the same time a direct hit on the tail of the ship seriously wounded the tail gunner and rendered the tail guns inoperative. Realizing the great need for firepower in protecting the vulnerable tail of the ship, T/Sgt. Vosler, with grim determination, kept up a steady stream of deadly fire. Shortly thereafter another 20-mm. enemy shell exploded, wounding T/Sgt. Vosler in the chest and about the face. …", "facts": [["Recipient", "Forrest L. Vosler"], ["Rank", "Technical Sergeant"], ["Service", "Army Air Forces"], ["Place of action", "Over Bremen, Germany"], ["Awarded", "G.O. No. 73, September 6, 1944"]], "wiki": {"Forrest L. Vosler": "Forrest_L._Vosler"}},
  {"id": "1944-01-06-dealey-samuel-d", "date": "1944-01-06", "title": "Commander Samuel D. Dealey", "type": "loss", "theater": "Navy", "location": {"name": "USS Harder, near Philippines (approx.)", "lat": 5.5, "lng": 120.5}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Commanding Officer of the U.S.S. Harder during her 5th War Patrol in Japanese-controlled waters. Floodlit by a bright moon and disclosed to an enemy destroyer escort which bore down with intent to attack, Comdr. Dealey quickly dived to periscope depth and waited for the pursuer to close range, then opened fire, sending the target and all aboard down in flames with his third torpedo. Plunging deep to avoid fierce depth charges, he again surfaced and, within 9 minutes after sighting another destroyer, had sent the enemy down tail first with a hit directly amidship. Evading detection, he penetrated the confined waters off Tawi Tawi with the Japanese Fleet base 6 miles away and scored death blows on 2 patrolling destroyers in quick succession. …", "facts": [["Recipient", "Samuel D. Dealey"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "USS Harder, near Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Samuel D. Dealey": "Samuel_David_Dealey"}, "approx": true},
  {"id": "1944-01-07-specker-joe-c", "date": "1944-01-07", "title": "Sergeant Joe C. Specker", "type": "loss", "theater": "Army", "location": {"name": "Mount Porchia, Italy (approx.)", "lat": 41.42, "lng": 13.93}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life, above and beyond the call of duty, in action involving actual conflict. On the night of 7 January 1944, Sgt. Specker, with his company, was advancing up the slope of Mount Porchio, Italy. He was sent forward on reconnaissance and on his return he reported to his company commander the fact that there was an enemy machinegun nest and several well-placed snipers directly in the path and awaiting the company. Sgt. Specker requested and was granted permission to place 1 of his machineguns in a position near the enemy machinegun. Voluntarily and alone he made his way up the mountain with a machinegun and a box of ammunition. He was observed by the enemy as he walked along and was severely wounded by the deadly fire directed at him. …", "facts": [["Recipient", "Joe C. Specker"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Mount Porchia, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Joe C. Specker": "Joe_C._Specker"}},
  {"id": "1944-01-11-howard-james-h", "date": "1944-01-11", "title": "Major James H. Howard", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Over Oschersleben, Germany (approx.)", "lat": 52.0167, "lng": 11.25}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy near Oschersleben, Germany, on 11 January 1944. On that day Col. Howard was the leader of a group of P-51 aircraft providing support for a heavy bomber formation on a long-range mission deep in enemy territory. As Col. Howard's group met the bombers in the target area the bomber force was attacked by numerous enemy fighters. Col. Howard, with his group, at once engaged the enemy and himself destroyed a German ME. 110. As a result of this attack Col. Howard lost contact with his group, and at once returned to the level of the bomber formation. He then saw that the bombers were being heavily attacked by enemy airplanes and that no other friendly fighters were at hand. While Col. Howard could have waited to attempt to assemble his group before engaging the enemy, he chose instead to attack single-handed a formation of more than 30 German airplanes. …", "facts": [["Recipient", "James H. Howard"], ["Rank", "Major"], ["Service", "Army Air Forces"], ["Place of action", "Over Oschersleben, Germany"]], "wiki": {"James H. Howard": "James_H._Howard"}},
  {"id": "1944-01-22-mccall-thomas-e", "date": "1944-01-22", "title": "Staff Sergeant Thomas E. McCall", "type": "attack", "theater": "Army", "location": {"name": "Near San Angelo, Italy (approx.)", "lat": 41.45, "lng": 13.8}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. On 22 January 1944, Company F had the mission of crossing the Rapido River in the vicinity of San Angelo, Italy, and attacking the well-prepared German positions to the west. For the defense of these positions the enemy had prepared a network of machinegun positions covering the terrain to the front with a pattern of withering machinegun fire, and mortar and artillery positions zeroed in on the defilade areas. S/Sgt. McCall commanded a machinegun section that was to provide added fire support for the riflemen. Under cover of darkness, Company F advanced to the river crossing site and under intense enemy mortar, artillery, and machinegun fire crossed an ice-covered bridge which was continually the target for enemy fire. Many casualties occurred on reaching the west side of the river and reorganization was imperative. Exposing himself to the deadly enemy machinegun and small arms fire that swept over the flat terrain, S/Sgt. …", "facts": [["Recipient", "Thomas E. McCall"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near San Angelo, Italy"]], "wiki": {"Thomas E. McCall": "Thomas_E._McCall"}},
  {"id": "1944-01-28-gibson-eric-g", "date": "1944-01-28", "title": "Technician 5th Grade Eric G. Gibson", "type": "loss", "theater": "Army", "location": {"name": "Near Isola Bella, Italy (approx.)", "lat": 41.57, "lng": 12.85}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. On January 28, 1944, near Isolabella, Italy, Tech. 5th Grade Gibson, company cook, led a squad of replacements through their initial baptism of fire, destroyed four enemy positions, killed 5 and captured 2 German soldiers, and secured the left flank of his company during an attack on a strongpoint. Placing himself 50 yards in front of his new men, Gibson advanced down the wide stream ditch known as the Fosso Femminamorta, keeping pace with the advance of his company. An enemy soldier allowed Tech. 5th Grade Gibson to come within 20 yards of his concealed position and then opened fire on him with a machine pistol. Despite the stream of automatic fire which barely missed him, Gibson charged the position, firing his submachine gun every few steps. Reaching the position, Gibson fired pointblank at his opponent, killing him. …", "facts": [["Recipient", "Eric G. Gibson"], ["Rank", "Technician 5th Grade"], ["Service", "Army"], ["Place of action", "Near Isola Bella, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Eric G. Gibson": "Eric_G._Gibson"}},
  {"id": "1944-01-30-hawks-lloyd-c", "date": "1944-01-30", "title": "Private First Class Lloyd C. Hawks", "type": "attack", "theater": "Army", "location": {"name": "Near Carano, Italy (approx.)", "lat": 41.55, "lng": 12.75}, "zoom": 9, "summary": "For gallantry and intrepidity at risk of life above and beyond the call of duty. On January 30, 1944, at 3 p.m., near Carano, Italy, Pfc. Hawks braved an enemy counterattack in order to rescue 2 wounded men who, unable to move, were lying in an exposed position within 30 yards of the enemy. Two riflemen, attempting the rescue, had been forced to return to their fighting holes by extremely severe enemy machinegun fire, after crawling only 10 yards toward the casualties. An aid man, whom the enemy could plainly identify as such, had been critically wounded in a similar attempt. Pfc. Hawks, nevertheless, crawled 50 yards through a veritable hail of machinegun bullets and flying mortar fragments to a small ditch, administered first aid to his fellow aid man who had sought cover therein, and continued toward the 2 wounded men 50 yards distant. An enemy machinegun bullet penetrated his helmet, knocking it from his head, momentarily stunning him. …", "facts": [["Recipient", "Lloyd C. Hawks"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Carano, Italy"]], "wiki": {"Lloyd C. Hawks": "Lloyd_C._Hawks"}},
  {"id": "1944-01-30-olson-truman-o", "date": "1944-01-30", "title": "Sergeant Truman O. Olson", "type": "loss", "theater": "Army", "location": {"name": "Near Cisterna di Littoria, Italy", "lat": 41.5908, "lng": 12.8283}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty. Sgt. Olson, a light machine gunner, elected to sacrifice his life to save his company from annihilation. On the night of 30 January 1944, after a 16-hour assault on entrenched enemy positions in the course of which over one-third of Company B became casualties, the survivors dug in behind a horseshoe elevation, placing Sgt. Olson and his crew, with the 1 available machinegun, forward of their lines and in an exposed position to bear the brunt of the expected German counterattack. Although he had been fighting without respite, Sgt. Olson stuck grimly to his post all night while his guncrew was cut down, 1 by 1, by accurate and overwhelming enemy fire. Weary from over 24 hours of continuous battle and suffering from an arm wound, received during the night engagement, Sgt. …", "facts": [["Recipient", "Truman O. Olson"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Cisterna di Littoria, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Truman O. Olson": "Truman_O._Olson"}},
  {"id": "1944-01-30-drowley-jesse-r", "date": "1944-01-30", "title": "Staff Sergeant Jesse R. Drowley", "type": "attack", "theater": "Army", "location": {"name": "Bougainville, Solomon Islands", "lat": -6.2444, "lng": 155.3839}, "zoom": 9, "summary": "For gallantry and intrepidity at the risk of his life above and beyond the call of duty in action with the enemy at Bougainville, Solomon Islands, 30 January 1944. S/Sgt. Drowley, a squad leader in a platoon whose mission during an attack was to remain under cover while holding the perimeter defense and acting as a reserve for assaulting echelon, saw 3 members of the assault company fall badly wounded. When intense hostile fire prevented aid from reaching the casualties, he fearlessly rushed forward to carry the wounded to cover. After rescuing 2 men, S/Sgt. Drowley discovered an enemy pillbox undetected by assaulting tanks that was inflicting heavy casualties upon the attacking force and was a chief obstacle to the success of the advance. Delegating the rescue of the third man to an assistant, he ran across open terrain to 1 of the tanks. …", "facts": [["Recipient", "Jesse R. Drowley"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Bougainville, Solomon Islands"]], "wiki": {"Jesse R. Drowley": "Jesse_R._Drowley"}},
  {"id": "1944-02-01-power-john-v", "date": "1944-02-01", "title": "First Lieutenant John V. Power", "type": "loss", "theater": "Marine Corps", "location": {"name": "Namur Island, Kwajalein Atoll, Marshall Islands", "lat": 9.3961, "lng": 167.4758}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as platoon leader, attached to the 4th Marine Division, during the landing and battle of Namur Island, Kwajalein Atoll, Marshall Islands, 1 February 1944. Severely wounded in the stomach while setting a demolition charge on a Japanese pillbox, 1st Lt. Power was steadfast in his determination to remain in action. Protecting his wound with his left hand and firing with his right, he courageously advanced as another hostile position was taken under attack, fiercely charging the opening made by the explosion and emptying his carbine into the pillbox. While attempting to reload and continue the attack, 1st Lt. Power was shot again in the stomach and head and collapsed in the doorway. His exceptional valor, fortitude and indomitable fighting spirit in the face of withering enemy fire were in keeping with the highest traditions of the U.S. Naval Service. He gallantly gave his life for his country.", "facts": [["Recipient", "John V. Power"], ["Rank", "First Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Namur Island, Kwajalein Atoll, Marshall Islands"], ["Awarded", "Posthumously"]], "wiki": {"John V. Power": "John_V._Power"}},
  {"id": "1944-02-01-dyess-aquilla-j", "date": "1944-02-01", "title": "Lieutenant Colonel Aquilla J. Dyess", "type": "loss", "theater": "Marine Corps", "location": {"name": "Namur Island, Kwajalein Atoll, Marshall Islands", "lat": 9.3961, "lng": 167.4758}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Commanding Officer of the First Battalion, Twenty-Fourth Marines, Reinforced, Fourth Marine Division, in action against enemy Japanese forces during the assault on Namur Island, Kwajalein Atoll, Marshall Islands, February 1 and 2, 1944. Undaunted by severe fire from automatic Japanese weapons, Lieutenant Colonel Dyess launched a powerful final attack on the second day of the assault, unhesitatingly posting himself between the opposing lines to point out objectives and avenues of approach and personally leading the advancing troops. Alert, and determined to quicken the pace of the offensive against increased enemy fire, he was constantly at the head of advance units, inspiring his men to push forward until the Japanese had been driven back to a small center of resistance and victory assured. …", "facts": [["Recipient", "Aquilla J. Dyess"], ["Rank", "Lieutenant Colonel"], ["Service", "Marine Corps"], ["Place of action", "Namur Island, Kwajalein Atoll, Marshall Islands"], ["Awarded", "Posthumously"]], "wiki": {"Aquilla J. Dyess": "Aquilla_J._Dyess"}},
  {"id": "1944-02-01-knappenberger-alton-w", "date": "1944-02-01", "title": "Private First Class Alton W. Knappenberger", "type": "attack", "theater": "Army", "location": {"name": "Near Cisterna di Littoria, Italy", "lat": 41.5908, "lng": 12.8283}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty in action involving actual conflict with the enemy, on February 1, 1944, near Cisterna di Littoria, Italy. When a heavy German counterattack was launched against his battalion, Pfc. Knappenberger crawled to an exposed knoll and went into position with his automatic rifle. An enemy machinegun 85 yards away opened fire, and bullets struck within 6 inches of him. Rising to a kneeling position, Pfc. Knappenberger opened fire on the hostile crew, knocked out the gun, killed 2 members of the crew, and wounded the third. While he fired at this hostile position, 2 Germans crawled to a point within 20 yards of the knoll and threw potato-masher grenades at him, but Pfc. Knappenberger killed them both with 1 burst from his automatic rifle. Later, a second machinegun opened fire upon his exposed position from a distance of 100 yards, and this weapon also was silenced by his well-aimed shots. …", "facts": [["Recipient", "Alton W. Knappenberger"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Cisterna di Littoria, Italy"]], "wiki": {"Alton W. Knappenberger": "Alton_W._Knappenberger"}},
  {"id": "1944-02-01-anderson-richard-b", "date": "1944-02-01", "title": "Private First Class Richard B. Anderson", "type": "loss", "theater": "Marine Corps", "location": {"name": "Roi Island, Kwajalein Atoll, Marshall Islands", "lat": 9.3961, "lng": 167.4758}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the Fourth Marine Division during action against enemy Japanese forces on Roi Island, Kwajalein Atoll, Marshall Islands, February 1, 1944. Entering a shell crater occupied by three other Marines, Private First Class Anderson was preparing to throw a grenade at an enemy position when it slipped from his hands and rolled toward the men at the bottom of the hole. With insufficient time to retrieve the armed weapon and throw it, Private First Class Anderson fearlessly chose to sacrifice himself and save his companions by hurling his body upon the grenade and taking the full impact of the explosion. His personal valor and exceptional spirit of loyalty in the face of almost certain death were in keeping with the highest traditions of the United States Naval Service. He gallantly gave his life for his country.", "facts": [["Recipient", "Richard B. Anderson"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Roi Island, Kwajalein Atoll, Marshall Islands"], ["Awarded", "Posthumously"]], "wiki": {"Richard B. Anderson": "Richard_B._Anderson"}},
  {"id": "1944-02-01-sorenson-richard-k", "date": "1944-02-01", "title": "Private Richard K. Sorenson", "type": "attack", "theater": "Marine Corps", "location": {"name": "Namur Island, Kwajalein Atoll, Marshall Islands", "lat": 9.3961, "lng": 167.4758}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with an assault battalion attached to the Fourth Marine Division during the battle of Namur Island, Kwajalein Atoll, Marshall Islands, on February 1–2, 1944. Putting up a brave defense against a particularly violent counterattack by the enemy during invasion operations, Private Sorenson and five other Marines occupying a shellhole were endangered by a Japanese grenade thrown into their midst. Unhesitatingly, and with complete disregard for his own safety, Private Sorenson hurled himself upon the deadly weapon, heroically taking the full impact of the explosion. As a result of his gallant action, he was severely wounded, but the lives of his comrades were saved. His great personal valor and exceptional spirit of self-sacrifice in the face of almost certain death were in keeping with the highest traditions of the United States Naval Service.", "facts": [["Recipient", "Richard K. Sorenson"], ["Rank", "Private"], ["Service", "Marine Corps"], ["Place of action", "Namur Island, Kwajalein Atoll, Marshall Islands"]], "wiki": {"Richard K. Sorenson": "Richard_K._Sorenson"}},
  {"id": "1944-02-03-powers-leo-j", "date": "1944-02-03", "title": "Private First Class Leo J. Powers", "type": "attack", "theater": "Army", "location": {"name": "Northwest of Cassino, Italy (approx.)", "lat": 41.49, "lng": 13.81}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. On 3 February 1944, this soldier's company was assigned the mission of capturing Hill 175, the key enemy strong point northwest of Cassino, Italy. The enemy, estimated to be at least 50 in strength, supported by machineguns emplaced in 3 pillboxes and mortar fire from behind the hill, was able to pin the attackers down and inflict 8 casualties. The company was unable to advance, but Pfc. Powers, a rifleman in 1 of the assault platoons, on his own initiative and in the face of the terrific fire, crawled forward to assault 1 of the enemy pillboxes which he had spotted. Armed with 2 handgrenades and well aware that if the enemy should see him it would mean almost certain death, Pfc. Powers crawled up the hill to within 15 yards of the enemy pillbox. …", "facts": [["Recipient", "Leo J. Powers"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Northwest of Cassino, Italy"]], "wiki": {"Leo J. Powers": "Leo_J._Powers"}},
  {"id": "1944-02-03-riordan-paul-f", "date": "1944-02-03", "title": "Second Lieutenant Paul F. Riordan", "type": "loss", "theater": "Army", "location": {"name": "Near Cassino, Italy", "lat": 41.49, "lng": 13.8332}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty. In the attack on the approaches to the city of Cassino on February 3, 1944, 2d Lt. Riordan led 1 of the assault platoons. Attacking Hill 175, his command was pinned down by enemy machinegun fire from the hill and from a pillbox about 45 yards to the right of the hill. In the face of intense fire, 2d Lt. Riordan moved out in full view of the enemy gunners to reach a position from where he could throw a handgrenade into the pillbox. Then, getting to his knees, he hurled the grenade approximately 45 yards, scoring a direct hit. The grenade killed 1 and wounded the other 2 Germans in the nest and silenced the gun. Another soldier then cleaned out the enemy pillboxes on the hill itself, and the company took its objective. Continuing the assault into Cassino itself on February 8, 1944, 2d Lt. …", "facts": [["Recipient", "Paul F. Riordan"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Near Cassino, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Paul F. Riordan": "Paul_F._Riordan"}},
  {"id": "1944-02-08-huff-paul-b", "date": "1944-02-08", "title": "Corporal Paul B. Huff", "type": "attack", "theater": "Army", "location": {"name": "Near Carano, Italy (approx.)", "lat": 41.55, "lng": 12.75}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty, in action on 8 February 1944, near Carano, Italy. Cpl. Huff volunteered to lead a 6-man patrol with the mission of determining the location and strength of an enemy unit which was delivering fire on the exposed right flank of his company. The terrain over which he had to travel consisted of exposed, rolling ground, affording the enemy excellent visibility. As the patrol advanced, its members were subjected to small arms and machinegun fire and a concentration of mortar fire, shells bursting within 5 to 10 yards of them and bullets striking the ground at their feet. Moving ahead of his patrol, Cpl. Huff drew fire from 3 enemy machineguns and a 20mm weapon. Realizing the danger confronting his patrol, he advanced alone under deadly fire through a minefield and arrived at a point within 75 yards of the nearest machinegun position. …", "facts": [["Recipient", "Paul B. Huff"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Near Carano, Italy"]], "wiki": {"Paul B. Huff": "Paul_B._Huff"}},
  {"id": "1944-02-15-gordon-nathan-g", "date": "1944-02-15", "title": "Lieutenant, Junior Grade Nathan G. Gordon", "type": "attack", "theater": "Navy", "location": {"name": "Bismarck Sea", "lat": -4, "lng": 148}, "zoom": 9, "summary": "For extraordinary heroism above and beyond the call of duty as commander of a Catalina patrol plane in rescuing personnel of the U.S. Army 5th Air Force shot down in combat over Kavieng Harbor in the Bismarck Sea, February 15, 1944. On air alert in the vicinity of Vitu Islands, Lt. (then Lt. j.g.) Gordon unhesitatingly responded to a report of the crash and flew boldly into the harbor, defying close-range fire from enemy shore guns to make 3 separate landings in full view of the Japanese and pick up 9 men, several of them injured. With his cumbersome flying boat dangerously overloaded, he made a brilliant takeoff despite heavy swells and almost total absence of wind and set a course for base, only to receive the report of another group stranded in a rubber life raft 600 yards from the enemy shore. …", "facts": [["Recipient", "Nathan G. Gordon"], ["Rank", "Lieutenant, Junior Grade"], ["Service", "Navy"], ["Place of action", "Bismarck Sea"]], "wiki": {"Nathan G. Gordon": "Nathan_Green_Gordon"}},
  {"id": "1944-02-17-johnston-william-j", "date": "1944-02-17", "title": "Private First Class William J. Johnston", "type": "attack", "theater": "Army", "location": {"name": "Anzio, Italy (approx.)", "lat": 41.45, "lng": 12.62}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty in action against the enemy. On 17 February 1944, near Padiglione, Italy, he observed and fired upon an attacking force of approximately 80 Germans, causing at least 25 casualties and forcing withdrawal of the remainder. All that day he manned his gun without relief, subject to mortar, artillery, and sniper fire. Two Germans individually worked so close to his position that his machinegun was ineffective, whereupon he killed 1 with his pistol, the second with a rifle taken from another soldier. When a rifleman protecting his gun position was killed by a sniper, he immediately moved the body and relocated the machinegun in that spot in order to obtain a better field of fire. He volunteered to cover the platoon's withdrawal and was the last man to leave that night. In his new position he maintained an all-night vigil, the next day causing 7 German casualties. …", "facts": [["Recipient", "William J. Johnston"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Anzio, Italy"]], "wiki": {"William J. Johnston": "William_J._Johnston"}},
  {"id": "1944-02-19-damato-anthony-p", "date": "1944-02-19", "title": "Corporal Anthony P. Damato", "type": "loss", "theater": "Marine Corps", "location": {"name": "Engebi Island, Eniwetok Atoll, Marshall Islands", "lat": 11.5, "lng": 162.3333}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with an assault company of the Second Battalion, Twenty-Second Marines, Fifth Amphibious Corps, in action against enemy Japanese forces on Eniwetok Atoll Marshall Islands, on the night of February 19,-20, 1944. Highly vulnerable to sudden attack by small, fanatical groups of Japanese still at large despite the efficient and determined efforts of our forces to clear the area, Corporal Damato lay with two comrades in a large foxhole in his company's defense perimeter which had been dangerously thinned by the forced withdrawal of nearly half of the available men. When one of the enemy approached the foxhole undetected and threw in a hand grenade, Corporal Damato desperately groped for it in the darkness. …", "facts": [["Recipient", "Anthony P. Damato"], ["Rank", "Corporal"], ["Service", "Marine Corps"], ["Place of action", "Engebi Island, Eniwetok Atoll, Marshall Islands"], ["Awarded", "Posthumously"]], "wiki": {"Anthony P. Damato": "Anthony_P._Damato"}},
  {"id": "1944-02-20-lawley-jr-william-r", "date": "1944-02-20", "title": "First Lieutenant William R. Lawley Jr.", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Over Europe (approx.)", "lat": 51.5, "lng": 9.0}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity in action above and beyond the call of duty, 20 February 1944, while serving as pilot of a B-17 aircraft on a heavy bombardment mission over enemy-occupied continental Europe. Coming off the target he was attacked by approximately 20 enemy fighters, shot out of formation, and his plane severely crippled. Eight crewmembers were wounded, the copilot was killed by a 20-mm. shell. One engine was on fire, the controls shot away, and 1st Lt. Lawley seriously and painfully wounded about the face. Forcing the copilot's body off the controls, he brought the plane out of a steep dive, flying with his left hand only. Blood covered the instruments and windshield and visibility was impossible. With a full bomb load the plane was difficult to maneuver and bombs could not be released because the racks were frozen. …", "facts": [["Recipient", "William R. Lawley Jr."], ["Rank", "First Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Over Europe"]], "wiki": {"William R. Lawley Jr.": "William_R._Lawley_Jr."}},
  {"id": "1944-02-20-truemper-walter-e", "date": "1944-02-20", "title": "Second Lieutenant Walter E. Truemper", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Over Germany (approx.)", "lat": 51.0, "lng": 10.0}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty in action against the enemy in connection with a bombing mission over enemy-occupied Europe on 20 February 1944. The aircraft on which 2d Lt. Truemper was serving as navigator was attacked by a squadron of enemy fighters with the result that the co-pilot was killed outright, the pilot wounded and rendered unconscious, the radio operator wounded and the plane severely damaged. Nevertheless, 2d Lt. Truemper and other members of the crew managed to right the plane and fly it back to their home station, where they contacted the control tower and reported the situation. 2d Lt. Truemper and the flight engineer volunteered to attempt to land the plane. Other members of the crew were ordered to jump, leaving 2d Lt. Truemper and the engineer aboard. After observing the distressed aircraft from another plane, 2d Lt. …", "facts": [["Recipient", "Walter E. Truemper"], ["Rank", "Second Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Over Germany"], ["Awarded", "Posthumously"]], "wiki": {"Walter E. Truemper": "Walter_E._Truemper"}},
  {"id": "1944-02-20-mathies-archibald", "date": "1944-02-20", "title": "Sergeant Archibald Mathies", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Over Germany (approx.)", "lat": 51.0, "lng": 10.0}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty in action against the enemy in connection with a bombing mission over enemy-occupied Europe on February 20, 1944. The aircraft on which Sgt. Mathies was serving as flight engineer and ball turret gunner was attacked by a squadron of enemy fighters with the result that the co-pilot was killed outright, the pilot wounded and rendered unconscious, the radio operator wounded and the plane severely damaged. Nevertheless, Sgt. Mathies and other members of the crew managed to right the plane and fly it back to their home station, where they contacted the control tower and reported the situation. Sgt. Mathies and the navigator volunteered to attempt to land the plane. Other members of the crew were ordered to jump, leaving Sgt. Mathies and the navigator aboard. After observing the distressed aircraft from another plane, Sgt. …", "facts": [["Recipient", "Archibald Mathies"], ["Rank", "Sergeant"], ["Service", "Army Air Forces"], ["Place of action", "Over Germany"], ["Awarded", "Posthumously"]], "wiki": {"Archibald Mathies": "Archibald_Mathies"}},
  {"id": "1944-02-22-montgomery-jack-c", "date": "1944-02-22", "title": "First Lieutenant Jack C. Montgomery", "type": "attack", "theater": "Army", "location": {"name": "Near, Padiglione, Italy (approx.)", "lat": 41.53, "lng": 12.7}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty on February 22, 1944, near Padiglione, Italy. Two hours before daybreak a strong force of enemy infantry established themselves in 3 echelons at 50 yards, 100 yards, and 300 yards, respectively, in front of the rifle platoons commanded by 1st Lt. Montgomery. The closest position, consisting of 4 machineguns and 1 mortar, threatened the immediate security of the platoon position. Seizing an M1 rifle and several hand grenades, 1st Lt. Montgomery crawled up a ditch to within hand grenade range of the enemy. Then climbing boldly onto a little mound, he fired his rifle and threw his grenades so accurately that he killed 8 of the enemy and captured the remaining 4. Returning to his platoon, he called for artillery fire on a house, in and around which he suspected that the majority of the enemy had entrenched themselves. …", "facts": [["Recipient", "Jack C. Montgomery"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near, Padiglione, Italy"]], "wiki": {"Jack C. Montgomery": "Jack_C._Montgomery"}},
  {"id": "1944-03-04-mcgill-troy-a", "date": "1944-03-04", "title": "Sergeant Troy A. McGill", "type": "loss", "theater": "Army", "location": {"name": "Los Negros Islands, Admiralty Group (approx.)", "lat": -2.02, "lng": 147.43}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty in action with the enemy at Los Negros Island, Admiralty Group, on 4 March 1944. In the early morning hours Sgt. McGill, with a squad of 8 men, occupied a revetment which bore the brunt of a furious attack by approximately 200 drink-crazed enemy troops. Although covered by crossfire from machine-guns on the right and left flank he could receive no support from the remainder of our troops stationed at his rear. All members of the squad were killed or wounded except Sgt. McGill and another man, whom he ordered to return to the next revetment. Courageously resolved to hold his position at all cost, he fired his weapon until it ceased to function. Then, with the enemy only 5 yards away, he charged from his foxhole in the face of certain death and clubbed the enemy with his rifle in hand-to-hand combat until he was killed. At dawn 105 enemy dead were found around his position. …", "facts": [["Recipient", "Troy A. McGill"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Los Negros Islands, Admiralty Group"], ["Awarded", "Posthumously"]], "wiki": {"Troy A. McGill": "Troy_A._McGill"}},
  {"id": "1944-04-11-michael-edward-s", "date": "1944-04-11", "title": "First Lieutenant Edward S. Michael", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Over Germany (approx.)", "lat": 51.0, "lng": 10.0}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty while serving as pilot of a B17 aircraft on a heavy-bombardment mission to Germany, April 11, 1944. The group in which 1st Lt. Michael was flying was attacked by a swarm of fighters. His plane was singled out and the fighters pressed their attacks home recklessly, completely disregarding the Allied fighter escort and their own intense flak. His plane was riddled from nose to tail with exploding cannon shells and knocked out of formation, with a large number of fighters following it down, blasting it with cannon fire as it descended. A cannon shell exploded in the cockpit, wounded the copilot, wrecked the instruments, and blew out the side window. 1st Lt. Michael was seriously and painfully wounded in the right thigh. Hydraulic fluid filmed over the windshield making visibility impossible, and smoke filled the cockpit. The controls failed to respond and 3,000 feet were lost before he succeeded in leveling off. …", "facts": [["Recipient", "Edward S. Michael"], ["Rank", "First Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Over Germany"]], "wiki": {"Edward S. Michael": "Edward_S._Michael"}},
  {"id": "1944-04-23-squires-john-c", "date": "1944-04-23", "title": "Private First Class John C. Squires", "type": "loss", "theater": "Army", "location": {"name": "Near Padiglione, Italy (approx.)", "lat": 41.53, "lng": 12.7}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. At the start of his company's attack on strongly held enemy positions in and around Spaccasassi Creek, near Padiglione, Italy, on the night of 23-April 24, 1944, Pfc. Squires, platoon messenger, participating in his first offensive action, braved intense artillery, mortar, and antitank gun fire in order to investigate the effects of an antitank mine explosion on the leading platoon. Despite shells which burst close to him, Pfc. Squires made his way 50 yards forward to the advance element, noted the situation, reconnoitered a new route of advance and informed his platoon leader of the casualties sustained and the alternate route. Acting without orders, he rounded up stragglers, organized a group of lost men into a squad and led them forward. When the platoon reached Spaccasassi Creek and established an outpost, Pfc. …", "facts": [["Recipient", "John C. Squires"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Padiglione, Italy"], ["Awarded", "Posthumously"]], "wiki": {"John C. Squires": "John_C._Squires"}},
  {"id": "1944-05-11-waugh-robert-t", "date": "1944-05-11", "title": "First Lieutenant Robert T. Waugh", "type": "loss", "theater": "Army", "location": {"name": "Near Tremensucli, Italy (approx.)", "lat": 41.26, "lng": 13.75}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty in action with the enemy. In the course of an attack upon an enemy-held hill on 11 May, 1st Lt. Waugh personally reconnoitered a heavily mined area before entering it with his platoon. Directing his men to deliver fire on 6 bunkers guarding this hill, 1st Lt. Waugh advanced alone against them, reached the first bunker, threw phosphorus grenades into it and as the defenders emerged, killed them with a burst from his tommygun. He repeated this process on the 5 remaining bunkers, killing or capturing the occupants. On the morning of 14 May, 1st Lt. Waugh ordered his platoon to lay a base of fire on 2 enemy pillboxes located on a knoll which commanded the only trail up the hill. He then ran to the first pillbox, threw several grenades into it, drove the defenders into the open, and killed them. …", "facts": [["Recipient", "Robert T. Waugh"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Tremensucli, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Robert T. Waugh": "Robert_T._Waugh"}},
  {"id": "1944-05-12-shea-charles-w", "date": "1944-05-12", "title": "Second Lieutenant Charles W. Shea", "type": "attack", "theater": "Army", "location": {"name": "Near Mount Damiano, Italy (approx.)", "lat": 41.33, "lng": 13.8}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty, on 12 May 1944, near Mount Damiano, Italy. As 2d Lt. Shea and his company were advancing toward a hill occupied by the enemy, three enemy machine guns suddenly opened fire, inflicting heavy casualties upon the company and halting its advance. 2d Lt. Shea immediately moved forward to eliminate these machine-gun nests in order to enable his company to continue its attack. The deadly hail of machine-gun fire at first pinned him down, but boldly continuing his advance, 2d Lt. Shea crept up to the first nest. Throwing several hand grenades, he forced the four enemy soldiers manning this position to surrender, and disarming them, he sent them to the rear. He then crawled to the second machine-gun position, and after a short firefight forced two more German soldiers to surrender. At this time, the third machine gun fired at him, and while deadly small-arms fire pitted the earth around him, 2d Lt. …", "facts": [["Recipient", "Charles W. Shea"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Near Mount Damiano, Italy"]], "wiki": {"Charles W. Shea": "Charles_W._Shea"}},
  {"id": "1944-05-23-schauer-henry", "date": "1944-05-23", "title": "Private First Class Henry Schauer", "type": "attack", "theater": "Army", "location": {"name": "Near Cisterna di Littoria, Italy", "lat": 41.5908, "lng": 12.8283}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. On May 23, 1944, at 12 noon, Pfc. (now T/Sgt.) Schauer left the cover of a ditch to engage 4 German snipers who opened fire on the patrol from its rear. Standing erect he walked deliberately 30 yards toward the enemy, stopped amid the fire from 4 rifles centered on him, and with 4 bursts from his BAR, each at a different range, killed all of the snipers. Catching sight of a fifth sniper waiting for the patrol behind a house chimney, Pfc. Schauer brought him down with another burst. Shortly after, when a heavy enemy artillery concentration and 2 machineguns temporarily halted the patrol, Pfc. Schauer again left cover to engage the enemy weapons single-handed. While shells exploded within 15 yards, showering dirt over him, and strings of grazing German tracer bullets whipped past him at chest level, Pfc. …", "facts": [["Recipient", "Henry Schauer"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Cisterna di Littoria, Italy"]], "wiki": {"Henry Schauer": "Henry_Schauer"}},
  {"id": "1944-05-23-dutko-john-w", "date": "1944-05-23", "title": "Private First Class John W. Dutko", "type": "loss", "theater": "Army", "location": {"name": "Near Ponte Rotto, Italy (approx.)", "lat": 41.58, "lng": 12.85}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty, on 23 May 1944, near Ponte Rotto, Italy. Pfc. Dutko left the cover of an abandoned enemy trench at the height of an artillery concentration in a single-handed attack upon 3 machineguns and an 88mm. mobile gun. Despite the intense fire of these 4 weapons which were aimed directly at him, Pfc. Dutko ran 10.0 yards through the impact area, paused momentarily in a shell crater, and then continued his l-man assault. Although machinegun bullets kicked up the dirt at his heels, and 88mm. shells exploded within 30 yards of him, Pfc. Dutko nevertheless made his way to a point within 30 yards of the first enemy machinegun and killed both gunners with a hand grenade. Although the second machinegun wounded him, knocking him to the ground, Pfc. Dutko regained his feet and advanced on the 88mm. gun, firing his Browning automatic rifle from the hip. …", "facts": [["Recipient", "John W. Dutko"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Ponte Rotto, Italy"], ["Awarded", "Posthumously"]], "wiki": {"John W. Dutko": "John_W._Dutko"}},
  {"id": "1944-05-23-kessler-patrick-l", "date": "1944-05-23", "title": "Private First Class Patrick L. Kessler", "type": "loss", "theater": "Army", "location": {"name": "Near Ponte Rotto, Italy (approx.)", "lat": 41.58, "lng": 12.85}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. Pfc. Kessler, acting without orders, raced 50 yd through a hail of machinegun fire, which had killed 5 of his comrades and halted the advance of his company, in order to form an assault group to destroy the machinegun. Ordering 3 men to act as a base of fire, he left the cover of a ditch and snaked his way to a point within 50 yd of the enemy machinegun before he was discovered, whereupon he plunged headlong into the furious chain of automatic fire. Reaching a spot within 6 ft of the emplacement he stood over it and killed both the gunner and his assistant, jumped into the gun position, overpowered and captured a third German after a short struggle. The remaining member of the crew escaped, but Pfc. Kessler wounded him as he ran. …", "facts": [["Recipient", "Patrick L. Kessler"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Ponte Rotto, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Patrick L. Kessler": "Patrick_L._Kessler"}},
  {"id": "1944-05-23-fowler-thomas-w", "date": "1944-05-23", "title": "Second Lieutenant Thomas W. Fowler", "type": "loss", "theater": "Army", "location": {"name": "Near Carano, Italy (approx.)", "lat": 41.55, "lng": 12.75}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty, on 23 May 1944, in the vicinity of Carano, Italy. In the midst of a full-scale armored-infantry attack, 2d Lt. Fowler, while on foot, came upon 2 completely disorganized infantry platoons held up in their advance by an enemy minefield. Although a tank officer, he immediately reorganized the infantry. He then made a personal reconnaissance through the minefield, clearing a path as he went, by lifting the antipersonnel mines out of the ground with his hands. After he had gone through the 75-yard belt of deadly explosives, he returned to the infantry and led them through the minefield, a squad at a time. As they deployed, 2d Lt. Fowler, despite small arms fire and the constant danger of antipersonnel mines, made a reconnaissance into enemy territory in search of a route to continue the advance. …", "facts": [["Recipient", "Thomas W. Fowler"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Near Carano, Italy"], ["Awarded", "Posthumously, G.O. No. 84, October 28, 1944"]], "wiki": {"Thomas W. Fowler": "Thomas_W._Fowler"}},
  {"id": "1944-05-23-hall-george-j", "date": "1944-05-23", "title": "Staff Sergeant George J. Hall", "type": "attack", "theater": "Army", "location": {"name": "Near Anzio, Italy (approx.)", "lat": 41.45, "lng": 12.62}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. Attacking across flat, open terrain under direct enemy observation, S/Sgt. Hall's company was pinned down by grazing fire from 3 enemy machineguns and harassing sniper fire. S/Sgt. Hall volunteered to eliminate these obstacles in the path of advance. Crawling along a plowed furrow through furious machinegun fire, he made his way to a point within hand grenade range of 1 of the enemy positions. He pounded the enemy with 4 hand grenades, and when the smoke had died away, S/Sgt. Hall and 2 dead Germans occupied the position, while 4 of the enemy were crawling back to our lines as prisoners. Discovering a quantity of German potato-masher grenades in the position, S/Sgt. Hall engaged the second enemy nest in a deadly exchange of grenades. Each time he exposed himself to throw a grenade the Germans fired machinegun bursts at him. The vicious duel finally ended in S/Sgt. …", "facts": [["Recipient", "George J. Hall"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Anzio, Italy"]], "wiki": {"George J. Hall": "George_J._Hall"}},
  {"id": "1944-05-23-dervishian-ernest-h", "date": "1944-05-23", "title": "Technical Sergeant Ernest H. Dervishian", "type": "attack", "theater": "Army", "location": {"name": "Near Cisterna, Italy (approx.)", "lat": 41.59, "lng": 12.83}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty on May 23, 1944, in the vicinity of Cisterna, Italy. 2d Lt. Dervishian (then Tech. Sgt.) and 4 members of his platoon found themselves far ahead of their company after an aggressive advance in the face of enemy artillery and sniper fire. Approaching a railroad embankment, they observed a force of German soldiers hiding in dugouts. 2d Lt. Dervishian, directing his men to cover him, boldly moved forward and firing his carbine forced 10 Germans to surrender. His men then advanced and captured 15 more Germans occupying adjacent dugouts. The prisoners were returned to the rear to be picked up by advancing units. From the railroad embankment, 2d Lt. Dervishian and his men then observed 9 Germans who were fleeing across a ridge. He and his men opened fire and 3 of the enemy were wounded. As his men were firing, 2d Lt. …", "facts": [["Recipient", "Ernest H. Dervishian"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Cisterna, Italy"]], "wiki": {"Ernest H. Dervishian": "Ernest_H._Dervishian"}},
  {"id": "1944-05-23-barfoot-van-t", "date": "1944-05-23", "title": "Technical Sergeant Van T. Barfoot", "type": "attack", "theater": "Army", "location": {"name": "Near Carano, Italy (approx.)", "lat": 41.55, "lng": 12.75}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of life above and beyond the call of duty on 23 May 1944, near Carano, Italy. With his platoon heavily engaged during an assault against forces well entrenched on commanding ground, 2d Lt. Barfoot (then Tech. Sgt.) moved off alone upon the enemy left flank. He crawled to the proximity of 1 machinegun nest and made a direct hit on it with a hand grenade, killing 2 and wounding 3 Germans. He continued along the German defense line to another machinegun emplacement, and with his tommygun killed 2 and captured 3 soldiers. Members of another enemy machinegun crew then abandoned their position and gave themselves up to Sgt. Barfoot. Leaving the prisoners for his support squad to pick up, he proceeded to mop up positions in the immediate area, capturing more prisoners and bringing his total count to 17. …", "facts": [["Recipient", "Van T. Barfoot"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Carano, Italy"]], "wiki": {"Van T. Barfoot": "Van_T._Barfoot"}},
  {"id": "1944-05-24-mills-james-h", "date": "1944-05-24", "title": "Private James H. Mills", "type": "attack", "theater": "Army", "location": {"name": "Near Cisterna di Littoria, Italy", "lat": 41.5908, "lng": 12.8283}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. Pvt. Mills, undergoing his baptism of fire, preceded his platoon down a draw to reach a position from which an attack could be launched against a heavily fortified strongpoint. After advancing about 300 yards, Pvt. Mills was fired on by a machinegun only 5 yards distant. He killed the gunner with 1 shot and forced the surrender of the assistant gunner. Continuing his advance, he saw a German soldier in a camouflaged position behind a large bush pulling the pin of a potato-masher grenade. Covering the German with his rifle, Pvt. Mills forced him to drop the grenade and captured him. When another enemy soldier attempted to throw a hand grenade into the draw, Pvt. Mills killed him with 1 shot. …", "facts": [["Recipient", "James H. Mills"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Cisterna di Littoria, Italy"]], "wiki": {"James H. Mills": "James_Henry_Mills"}},
  {"id": "1944-05-24-antolak-sylvester", "date": "1944-05-24", "title": "Sergeant Sylvester Antolak", "type": "loss", "theater": "Army", "location": {"name": "Near Cisterna di Littoria, Italy", "lat": 41.5908, "lng": 12.8283}, "zoom": 9, "summary": "Sergeant Sylvester Antolak, United States Army, for conspicuous gallantry and intrepidity in action above and beyond the call of duty on 24 May 1944, while serving with Company B, 1st Battalion, 15th Infantry Regiment, 3d Infantry Division, near Cisterna di Littoria, Italy. Sergeant Antolak charged 200 yards over flat, coverless terrain to destroy an enemy machinegun nest during the second day of the offensive which broke through the German cordon of steel around the Anzio beachhead. Fully 30 yards in advance of his squad, he ran into withering enemy machinegun, machine-pistol and rifle fire. Three times he was struck by bullets and knocked to the ground, but each time he struggled to his feet to continue his relentless advance. …", "facts": [["Recipient", "Sylvester Antolak"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Cisterna di Littoria, Italy"], ["Awarded", "Posthumously, G.O. No. 89 (October 19, 1945)"]], "wiki": {"Sylvester Antolak": "Sylvester_Antolak"}},
  {"id": "1944-05-26-newman-beryl-r", "date": "1944-05-26", "title": "First Lieutenant Beryl R. Newman", "type": "attack", "theater": "Army", "location": {"name": "Near Cisterna, Italy (approx.)", "lat": 41.59, "lng": 12.83}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty on 26 May 1944. Attacking the strongly held German Anzio-Nettuno defense line near Cisterna, Italy, 1st Lt. Newman, in the lead of his platoon, was suddenly fired upon by 2 enemy machineguns located on the crest of a hill about 100 yards to his front. The 4 scouts with him immediately hit the ground, but 1st Lt. Newman remained standing in order to see the enemy positions and his platoon then about 100 yards behind. Locating the enemy nests, 1st Lt. Newman called back to his platoon and ordered 1 squad to advance to him and the other to flank the enemy to the right. Then, still standing upright in the face of the enemy machinegun fire, 1st Lt. Newman opened up with his tommygun on the enemy nests. From this range, his fire was not effective in covering the advance of his squads, and 1 squad was pinned down by the enemy fire. …", "facts": [["Recipient", "Beryl R. Newman"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Cisterna, Italy"]], "wiki": {"Beryl R. Newman": "Beryl_Newman"}},
  {"id": "1944-05-27-lara-salvador-j", "date": "1944-05-27", "title": "Staff Sergeant Salvador J. Lara", "type": "attack", "theater": "Army", "location": {"name": "Aprilia, Italy (approx.)", "lat": 41.59, "lng": 12.65}, "zoom": 9, "summary": "Then-Pfc. Salvador Lara was bestowed the Medal of Honor to recognize his valorous actions in Aprilia, Italy, May 27–28, 1944. During the fight, May 27, he aggressively led his rifle squad in neutralizing multiple enemy strong points and inflicting large numbers of casualties on the enemy. The next morning, as his company resumed the attack, Lara sustained a severe leg wound, but did not stop to receive first aid. Lara continued his exemplary performance until he captured his objective.", "facts": [["Recipient", "Salvador J. Lara"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Aprilia, Italy"]], "wiki": {"Salvador J. Lara": "Salvador_J._Lara"}},
  {"id": "1944-05-28-davila-rudolph-b", "date": "1944-05-28", "title": "Staff Sergeant Rudolph B. Davila", "type": "attack", "theater": "Army", "location": {"name": "Near Artena, Italy (approx.)", "lat": 41.74, "lng": 12.91}, "zoom": 9, "summary": "In 1996, Hawaii Senator Daniel Akaka secured a Congressionally mandated review of records for Asian-Americans who had earned the Distinguished Service Cross in World War II. Congress reviewed the records to determine whether they were unfairly denied the military's highest award for valor. On June 21, 2000, President Bill Clinton, bestowed the Medal of Honor on Davila and 21 other World War II servicemen of Asian descent at a White House ceremony. Only seven of 22 recipients were still alive when the medals were handed out. Previously only two of the 40,000-plus Asian-Americans who served in World War II had been awarded the Medal of Honor. Army Secretary Louis Caldera inducted the soldiers into the Pentagon's Hall of Heroes on June 22. Harriet Davila, his wife, had died six months before, on December 25, 1999.", "facts": [["Recipient", "Rudolph B. Davila"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Artena, Italy"]], "wiki": {"Rudolph B. Davila": "Rudolph_B._Davila"}},
  {"id": "1944-05-29-galt-william-w", "date": "1944-05-29", "title": "Captain William W. Galt", "type": "loss", "theater": "Army", "location": {"name": "Villa Crocetta, Italy (approx.)", "lat": 41.55, "lng": 12.7}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty. Capt. Galt, Battalion S3, at a particularly critical period following 2 unsuccessful attacks by his battalion, of his own volition went forward and ascertained just how critical the situation was. He volunteered, at the risk of his life, personally to lead the battalion against the objective. When the lone remaining tank destroyer refused to go forward, Capt. Galt jumped on the tank destroyer and ordered it to precede the attack. As the tank destroyer moved forward, followed by a company of riflemen, Capt. Galt manned the .30-caliber machinegun in the turret of the tank destroyer, located and directed fire on an enemy 77mm. anti-tank gun, and destroyed it. Nearing the enemy positions, Capt. Galt stood fully exposed in the turret, ceaselessly firing his machinegun and tossing hand grenades into the enemy zigzag series of trenches despite the hail of sniper and machinegun bullets ricocheting off the tank destroyer. As the tank destroyer moved, Capt. …", "facts": [["Recipient", "William W. Galt"], ["Rank", "Captain"], ["Service", "Army"], ["Place of action", "Villa Crocetta, Italy"], ["Awarded", "Posthumously"]], "wiki": {"William W. Galt": "William_Wylie_Galt"}},
  {"id": "1944-05-31-smith-furman-l", "date": "1944-05-31", "title": "Private Furman L. Smith", "type": "loss", "theater": "Army", "location": {"name": "Near Lanuvio, Italy (approx.)", "lat": 41.67, "lng": 12.7}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty. In its attack on a strong point, an infantry company was held up by intense enemy fire. The group to which Pvt. Smith belonged was far in the lead when attacked by a force of 80 Germans. The squad leader and 1 other man were seriously wounded and other members of the group withdrew to the company position, but Pvt. Smith refused to leave his wounded comrades. He placed them in the shelter of shell craters and then alone faced a strong enemy counterattack, temporarily checking it by his accurate rifle fire at close range, killing and wounding many of the foe. Against overwhelming odds, he stood his ground until shot down and killed, rifle in hand.", "facts": [["Recipient", "Furman L. Smith"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Lanuvio, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Furman L. Smith": "Furman_L._Smith"}},
  {"id": "1944-06-02-christian-herbert-f", "date": "1944-06-02", "title": "Private Herbert F. Christian", "type": "loss", "theater": "Army", "location": {"name": "Near Valmontone, Italy (approx.)", "lat": 41.78, "lng": 12.92}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. On 2–3 June 1944, at 1 a.m., Pvt. Christian elected to sacrifice his life in order that his comrades might extricate themselves from an ambush. Braving massed fire of about 60 riflemen, 3 machineguns, and 3 tanks from positions only 30 yards distant, he stood erect and signaled to the patrol to withdraw. The whole area was brightly illuminated by enemy flares. Although his right leg was severed above the knee by cannon fire, Pvt. Christian advanced on his left knee and the bloody stump of his right thigh, firing his submachine gun. Despite excruciating pain, Pvt. Christian continued on his self-assigned mission. He succeeded in distracting the enemy and enabled his 12 comrades to escape. He killed 3 enemy soldiers almost at once. …", "facts": [["Recipient", "Herbert F. Christian"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Valmontone, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Herbert F. Christian": "Herbert_F._Christian"}},
  {"id": "1944-06-02-nakamine-shinyei", "date": "1944-06-02", "title": "Private Shinyei Nakamine", "type": "loss", "theater": "Army", "location": {"name": "Near La Torreto, Italy (approx.)", "lat": 41.6, "lng": 12.8}, "zoom": 9, "summary": "Private Shinyei Nakamine distinguished himself by extraordinary heroism in action on 2 June 1944, near La Torreto, Italy. During an attack, Private Nakamine's platoon became pinned down by intense machine gun crossfire from a small knoll 200 yards to the front. On his own initiative, Private Nakamine crawled toward one of the hostile weapons. Reaching a point 25 yards from the enemy, he charged the machine gun nest, firing his submachine gun, and killed three enemy soldiers and captured two. Later that afternoon, Private Nakamine discovered an enemy soldier on the right flank of his platoon's position. Crawling 25 yards from his position, Private Nakamine opened fire and killed the soldier. Then, seeing a machine gun nest to his front approximately 75 yards away, he returned to his platoon and led an automatic rifle team toward the enemy. Under covering fire from his team, Private Nakamine crawled to a point 25 yards from the nest and threw hand grenades at the enemy soldiers, wounding one and capturing four. …", "facts": [["Recipient", "Shinyei Nakamine"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near La Torreto, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Shinyei Nakamine": "Shinyei_Nakamine"}},
  {"id": "1944-06-02-kobashigawa-yeiki", "date": "1944-06-02", "title": "Technical Sergeant Yeiki Kobashigawa", "type": "attack", "theater": "Army", "location": {"name": "Near Lanuvio, Italy (approx.)", "lat": 41.67, "lng": 12.7}, "zoom": 9, "summary": "Technical Sergeant Yeiki Kobashigawa distinguished himself by extraordinary heroism in action on 2 June 1944, in the vicinity of Lanuvio, Italy. During an attack, Technical Sergeant Kobashigawa's platoon encountered strong enemy resistance from a series of machine guns providing supporting fire. Observing a machine gun nest 50 yards from his position, Technical Sergeant Kobashigawa crawled forward with one of his men, threw a grenade and then charged the enemy with his submachine gun while a fellow soldier provided covering fire. He killed one enemy soldier and captured two prisoners. Meanwhile, Technical Sergeant Kobashigawa and his comrade were fired upon by another machine gun 50 yards ahead. Directing a squad to advance to his first position, Technical Sergeant Kobashigawa again moved forward with a fellow soldier to subdue the second machine gun nest. After throwing grenades into the position, Technical Sergeant Kobashigawa provided close supporting fire while a fellow soldier charged, capturing four prisoners. …", "facts": [["Recipient", "Yeiki Kobashigawa"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Lanuvio, Italy"]], "wiki": {"Yeiki Kobashigawa": "Yeiki_Kobashigawa"}},
  {"id": "1944-06-03-johnson-elden-h", "date": "1944-06-03", "title": "Private Elden H. Johnson", "type": "loss", "theater": "Army", "location": {"name": "Near Valmontone, Italy (approx.)", "lat": 41.78, "lng": 12.92}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. Pvt. Johnson elected to sacrifice his life in order that his comrades might extricate themselves from an ambush. Braving the massed fire of about 60 riflemen, 3 machineguns, and 3 tanks from positions only 25 yards distant, he stood erect and signaled his patrol leader to withdraw. The whole area was brightly illuminated by enemy flares. Then, despite 20mm. machineguns, machine pistol, and rifle fire directed at him, Pvt. Johnson advanced beyond the enemy in a slow deliberate walk. Firing his automatic rifle from the hip, he succeeded in distracting the enemy and enabled his 12 comrades to escape. Advancing to within 5 yards of a machinegun, emptying his weapon, Pvt. Johnson killed its crew. Standing in full view of the enemy he reloaded and turned on the riflemen to the left, firing directly into their positions. He either killed or wounded 4 of them. A burst of machinegun fire tore into Pvt. …", "facts": [["Recipient", "Elden H. Johnson"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Valmontone, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Elden H. Johnson": "Elden_H._Johnson"}},
  {"id": "1944-06-04-david-albert-l", "date": "1944-06-04", "title": "Lieutenant, Junior Grade Albert L. David", "type": "attack", "theater": "Navy", "location": {"name": "Off French West Africa (approx.)", "lat": 14.6, "lng": -17.6}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while attached to the U.S.S. Pillsbury during the capture of an enemy German submarine off French West Africa, June 4, 1944. Taking a vigorous part in the skillfully coordinated attack on the U-505 at the end of a prolonged search by the Task Group, Lt. (then Lt. j.g.) David boldly led a party from the Pillsbury in boarding the hostile submarine as it circled erratically at 5 or 6 knots on the surface. Fully aware that the U-boat might at any moment sink or be blown up by exploding demolition and scuttling charges, he braved the added danger of enemy gunfire to plunge through the conning tower hatch and, with his small party, exerted every effort to keep the ship afloat and to assist the succeeding and more fully equipped salvage parties in making the U-505 seaworthy for the long tow across the Atlantic to a U.S. port. …", "facts": [["Recipient", "Albert L. David"], ["Rank", "Lieutenant, Junior Grade"], ["Service", "Navy"], ["Place of action", "Off French West Africa"]], "wiki": {"Albert L. David": "Albert_David"}},
  {"id": "1944-06-05-vance-jr-leon-r", "date": "1944-06-05", "title": "Lieutenant Colonel Leon R. Vance Jr.", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Over Wimereaux, France (approx.)", "lat": 50.77, "lng": 1.61}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty on 5 June 1944, when he led a Heavy Bombardment Group, in an attack against defended enemy coastal positions in the vicinity of Wimereaux, France. Approaching the target, his aircraft was hit repeatedly by antiaircraft fire which seriously crippled the ship, killed the pilot, and wounded several members of the crew, including Lt. Col. Vance, whose right foot was practically severed. In spite of his injury, and with 3 engines lost to the flak, he led his formation over the target, bombing it successfully. After applying a tourniquet to his leg with the aid of the radar operator, Lt. Col. Vance, realizing that the ship was approaching a stall altitude with the 1 remaining engine failing, struggled to a semi-upright position beside the copilot and took over control of the ship. Cutting the power and feathering the last engine he put the aircraft in glide sufficiently steep to maintain his airspeed. …", "facts": [["Recipient", "Leon R. Vance Jr."], ["Rank", "Lieutenant Colonel"], ["Service", "Army Air Forces"], ["Place of action", "Over Wimereaux, France"], ["Awarded", "Posthumously"]], "wiki": {"Leon R. Vance Jr.": "Leon_Vance"}},
  {"id": "1944-06-06-roosevelt-jr-theodore", "date": "1944-06-06", "title": "Brigadier General Theodore Roosevelt Jr.", "type": "loss", "theater": "Army", "location": {"name": "Utah Beach, Normandy invasion", "lat": 49.4181, "lng": -1.1764}, "zoom": 9, "summary": "For gallantry and intrepidity at the risk of his life above and beyond the call of duty on 6 June 1944, in France. After two verbal requests to accompany the leading assault elements in the Normandy invasion had been denied, Brig. Gen. Roosevelt's written request for this mission was approved and he landed with the first wave of the forces assaulting the enemy-held beaches. He repeatedly led groups from the beach, over the seawall and established them inland. His valor, courage, and presence in the very front of the attack and his complete unconcern at being under heavy fire inspired the troops to heights of enthusiasm and self-sacrifice. Although the enemy had the beach under constant direct fire, Brig. Gen. Roosevelt moved from one locality to another, rallying men around him, directed and personally led them against the enemy. Under his seasoned, precise, calm, and unfaltering leadership, assault troops reduced beach strong points and rapidly moved inland with minimum casualties. …", "facts": [["Recipient", "Theodore Roosevelt Jr."], ["Rank", "Brigadier General"], ["Service", "Army"], ["Place of action", "Utah Beach, Normandy invasion"], ["Awarded", "Posthumously"]], "wiki": {"Theodore Roosevelt Jr.": "Theodore_Roosevelt_Jr."}},
  {"id": "1944-06-06-monteith-jr-jimmie-w", "date": "1944-06-06", "title": "First Lieutenant Jimmie W. Monteith Jr.", "type": "loss", "theater": "Army", "location": {"name": "Near Colleville-sur-Mer, Normandy, France", "lat": 49.3492, "lng": -0.8422}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty on 6 June 1944, while serving with 16th Infantry Regiment, 1st Infantry Division, in action near Colleville-sur-Mer, France. First Lieutenant Monteith landed with the initial assault waves on the coast of France under heavy enemy fire. Without regard to his own personal safety he continually moved up and down the beach reorganizing men for further assault. He then led the assault over a narrow protective ledge and across the flat, exposed terrain to the comparative safety of a cliff. Retracing his steps across the field to the beach, he moved over to where two tanks were buttoned up and blind under violent enemy artillery and machinegun fire. Completely exposed to the intense fire, First Lieutenant Monteith led the tanks on foot through a minefield and into firing positions. Under his direction several enemy positions were destroyed. He then rejoined his company and under his leadership his men captured an advantageous position on the hill. …", "facts": [["Recipient", "Jimmie W. Monteith Jr."], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Colleville-sur-Mer, Normandy, France"], ["Awarded", "Posthumously"]], "wiki": {"Jimmie W. Monteith Jr.": "Jimmie_W._Monteith"}},
  {"id": "1944-06-06-barrett-carlton-w", "date": "1944-06-06", "title": "Private Carlton W. Barrett", "type": "attack", "theater": "Army", "location": {"name": "Near St. Laurent-sur-Mer, France", "lat": 49.3594, "lng": -0.8764}, "zoom": 9, "summary": "For gallantry and intrepidity at the risk of his life above and beyond the call of duty on 6 June 1944, in the vicinity of St. Laurent-sur-Mer, France. On the morning of D-day Pvt. Barrett, landing in the face of extremely heavy enemy fire, was forced to wade ashore through neck-deep water. Disregarding the personal danger, he returned to the surf again and again to assist his floundering comrades and save them from drowning. Refusing to remain pinned down by the intense barrage of small-arms and mortar fire poured at the landing points, Pvt. Barrett, working with fierce determination, saved many lives by carrying casualties to an evacuation boat lying offshore. In addition to his assigned mission as guide, he carried dispatches the length of the fire-swept beach; he assisted the wounded; he calmed the shocked; he arose as a leader in the stress of the occasion. …", "facts": [["Recipient", "Carlton W. Barrett"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near St. Laurent-sur-Mer, France"]], "wiki": {"Carlton W. Barrett": "Carlton_W._Barrett"}},
  {"id": "1944-06-06-pinder-jr-john-j", "date": "1944-06-06", "title": "Technician 5th Grade John J. Pinder Jr.", "type": "loss", "theater": "Army", "location": {"name": "Near Colleville-sur-Mer, France", "lat": 49.3492, "lng": -0.8422}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty on 6 June 1944, near Colleville-sur-Mer, France. On D-day, Technician 5th Grade Pinder landed on the coast 100 yards off shore under devastating enemy machinegun and artillery fire which caused severe casualties among the boatload. Carrying a vitally important radio, he struggled towards shore in waist-deep water. Only a few yards from his craft he was hit by enemy fire and was gravely wounded. Technician 5th Grade Pinder never stopped. He made shore and delivered the radio. Refusing to take cover afforded, or to accept medical attention for his wounds, Technician 5th Grade Pinder, though terribly weakened by loss of blood and in fierce pain, on 3 occasions went into the fire-swept surf to salvage communication equipment. He recovered many vital parts and equipment, including another workable radio. On the 3rd trip he was again hit, suffering machinegun bullet wounds in the legs. Still this valiant soldier would not stop for rest or medical attention. …", "facts": [["Recipient", "John J. Pinder Jr."], ["Rank", "Technician 5th Grade"], ["Service", "Army"], ["Place of action", "Near Colleville-sur-Mer, France"], ["Awarded", "Posthumously"]], "wiki": {"John J. Pinder Jr.": "John_J._Pinder_Jr."}},
  {"id": "1944-06-08-peregory-frank-d", "date": "1944-06-08", "title": "Technical Sergeant Frank D. Peregory", "type": "loss", "theater": "Army", "location": {"name": "Grandcampe, France (approx.)", "lat": 49.39, "lng": -1.04}, "zoom": 9, "summary": "After the assault had been postponed several times, on June 6, 1944, Peregory landed with the 116th at Omaha Beach as part of the Normandy Invasion, also known as D-Day. His unit was among the first wave of troops to assault the beach but despite fierce enemy resistance that included heavy shelling and machine gun fire, his unit made its way to the town of Grandcamp-Maisy, by June 8. While his unit advanced on the German defenses, the leading elements began receiving fire from German forces. The Germans were firmly entrenched on high ground overlooking the town and were able to inflict severe damage on Allied forces as they approached. Numerous attempts to neutralize the enemy position by supporting artillery and tank fire had proved ineffective until Technical Sergeant Peregoy risked his own life by advancing up the hill under heavy enemy fire. He worked his way to the crest of the hill, where he discovered an entrenchment which led to the main enemy fortifications 200 yards away. …", "facts": [["Recipient", "Frank D. Peregory"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Grandcampe, France"], ["Awarded", "Posthumously"]], "wiki": {"Frank D. Peregory": "Frank_D._Peregory"}},
  {"id": "1944-06-09-deglopper-charles-n", "date": "1944-06-09", "title": "Private First Class Charles N. DeGlopper", "type": "loss", "theater": "Army", "location": {"name": "Merderet River at la Fiere, France (approx.)", "lat": 49.41, "lng": -1.37}, "zoom": 9, "summary": "He was a member of Company C, 325th Glider Infantry, on 9 June 1944 advancing with the forward platoon to secure a bridgehead across the Merderet River at La Fière, France. At dawn the platoon had penetrated an outer line of machineguns and riflemen, but in so doing had become cut off from the rest of the company. Vastly superior forces began a decimation of the stricken unit and put in motion a flanking maneuver which would have completely exposed the American platoon in a shallow roadside ditch where it had taken cover. Detecting this danger, Pfc. DeGlopper volunteered to support his comrades by fire from his automatic rifle while they attempted a withdrawal through a break in a hedgerow 40 yards to the rear. Scorning a concentration of enemy automatic weapons and rifle fire, he walked from the ditch onto the road in full view of the Germans, and sprayed the hostile positions with assault fire. He was wounded, but he continued firing. …", "facts": [["Recipient", "Charles N. DeGlopper"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Merderet River at la Fiere, France"], ["Awarded", "Posthumously, G.O. No. 22, February 28, 1946"]], "wiki": {"Charles N. DeGlopper": "Charles_N._DeGlopper"}},
  {"id": "1944-06-09-gandara-joe", "date": "1944-06-09", "title": "Private Joe Gandara", "type": "loss", "theater": "Army", "location": {"name": "Amfreville, France (approx.)", "lat": 49.25, "lng": -0.24}, "zoom": 9, "summary": "Private Joe Gandara distinguished himself by acts of gallantry and intrepidity above and beyond the call of duty while serving with Company D, 2d Battalion, 507th Parachute Infantry Regiment, 82nd Airborne Division during combat operations against an armed enemy in Amfreville, France on June 9, 1944. On that day, Private Gandara’s detachment came under devastating enemy fire from a strong German force, pinning the men to the ground for a period of four hours. Private Gandara voluntarily advanced alone toward the enemy position. Firing his machinegun from his hip as he moved forward, he destroyed three hostile machineguns before he was fatally wounded. Private Gandara’s extraordinary heroism and selflessness at the cost of his own life, above and beyond the call of duty, are in keeping with the highest traditions of military service and reflect great credit upon himself, his unit and the United States Army.", "facts": [["Recipient", "Joe Gandara"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Amfreville, France"], ["Awarded", "Posthumously"]], "wiki": {"Joe Gandara": "Joe_Gandara"}},
  {"id": "1944-06-09-ehlers-walter-d", "date": "1944-06-09", "title": "Staff Sergeant Walter D. Ehlers", "type": "attack", "theater": "Army", "location": {"name": "Near Goville, France (approx.)", "lat": 49.25, "lng": -1.3}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty on 9–10 June 1944, near Goville, France. S/Sgt. Ehlers, always acting as the spearhead of the attack, repeatedly led his men against heavily defended enemy strong points exposing himself to deadly hostile fire whenever the situation required heroic and courageous leadership. Without waiting for an order, S/Sgt. Ehlers, far ahead of his men, led his squad against a strongly defended enemy strong point, personally killing 4 of an enemy patrol who attacked him en route. Then crawling forward under withering machinegun fire, he pounced upon the guncrew and put it out of action. Turning his attention to 2 mortars protected by the crossfire of 2 machineguns, S/Sgt. Ehlers led his men through this hail of bullets to kill or put to flight the enemy of the mortar section, killing 3 men himself. After mopping up the mortar positions, he again advanced on a machinegun, his progress effectively covered by his squad. …", "facts": [["Recipient", "Walter D. Ehlers"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Goville, France"]], "wiki": {"Walter D. Ehlers": "Walter_D._Ehlers"}},
  {"id": "1944-06-10-defranzo-arthur-f", "date": "1944-06-10", "title": "Staff Sergeant Arthur F. DeFranzo", "type": "loss", "theater": "Army", "location": {"name": "Near Vaubadon, France", "lat": 49.2072, "lng": -0.8369}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life, above and beyond the call of duty, on June 10, 1944, near Vaubadon, France. As scouts were advancing across an open field, the enemy suddenly opened fire with several machineguns and hit 1 of the men. S/Sgt. DeFranzo courageously moved out in the open to the aid of the wounded scout and was himself wounded but brought the man to safety. Refusing aid, S/Sgt. DeFranzo reentered the open field and led the advance upon the enemy. There were always at least 2 machineguns bringing unrelenting fire upon him, but S/Sgt. DeFranzo kept going forward, firing into the enemy and 1 by 1 the enemy emplacements became silent. While advancing he was again wounded, but continued on until he was within 100 yards of the enemy position and even as he fell, he kept firing his rifle and waving his men forward. When his company came up behind him, S/Sgt. …", "facts": [["Recipient", "Arthur F. DeFranzo"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Vaubadon, France"], ["Awarded", "Posthumously"]], "wiki": {"Arthur F. DeFranzo": "Arthur_F._DeFranzo"}},
  {"id": "1944-06-11-cole-robert-g", "date": "1944-06-11", "title": "Lieutenant Colonel Robert G. Cole", "type": "loss", "theater": "Army", "location": {"name": "Near Carentan, France", "lat": 49.3, "lng": -1.25}, "zoom": 9, "summary": "For gallantry and intrepidity at the risk of his own life, above and beyond the call of duty on 11 June 1944, in France. Lt. Col. Cole was personally leading his battalion in forcing the last 4 bridges on the road to Carentan when his entire unit was suddenly pinned to the ground by intense and withering enemy rifle, machinegun, mortar, and artillery fire placed upon them from well-prepared and heavily fortified positions within 150 yard of the foremost elements. After the devastating and unceasing enemy fire had for over 1 hour prevented any move and inflicted numerous casualties, Lt. Col. Cole, observing this almost hopeless situation, courageously issued orders to assault the enemy positions with fixed bayonets. With utter disregard for his own safety and completely ignoring the enemy fire, he rose to his feet in front of his battalion and with drawn pistol shouted to his men to follow him in the assault. …", "facts": [["Recipient", "Robert G. Cole"], ["Rank", "Lieutenant Colonel"], ["Service", "Army"], ["Place of action", "Near Carentan, France"], ["Awarded", "Posthumously"]], "wiki": {"Robert G. Cole": "Robert_G._Cole"}},
  {"id": "1944-06-14-butts-john-e", "date": "1944-06-14", "title": "Second Lieutenant John E. Butts", "type": "loss", "theater": "Army", "location": {"name": "Normandy, France (approx.)", "lat": 49.3, "lng": -0.8}, "zoom": 6, "summary": "John Edward Butts (August 4, 1922 – June 23, 1944) was a United States Army second lieutenant and rifle platoon leader who received the Medal of Honor posthumously for his actions above and beyond the call of duty during the Normandy Campaign in World War II.", "facts": [["Recipient", "John E. Butts"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Normandy, France"], ["Awarded", "Posthumously, G.O. No. 58, July 19, 1944"]], "wiki": {"John E. Butts": "John_E._Butts"}},
  {"id": "1944-06-14-wise-homer-l", "date": "1944-06-14", "title": "Staff Sergeant Homer L. Wise", "type": "attack", "theater": "Army", "location": {"name": "Magliano, Italy (approx.)", "lat": 42.6, "lng": 11.3}, "zoom": 9, "summary": "While his platoon was pinned down by enemy small-arms fire from both flanks, he left his position of comparative safety and assisted in carrying 1 of his men, who had been seriously wounded and who lay in an exposed position, to a point where he could receive medical attention. The advance of the platoon was resumed but was again stopped by enemy frontal fire. A German officer and 2 enlisted men, armed with automatic weapons, threatened the right flank. Fearlessly exposing himself, he moved to a position from which he killed all 3 with his submachinegun. Returning to his squad, he obtained an M1 rifle and several antitank grenades, then took up a position from which he delivered accurate fire on the enemy holding up the advance. As the battalion moved forward it was again stopped by enemy frontal and flanking fire. He procured an automatic rifle and, advancing ahead of his men, neutralized an enemy machinegun with his fire. …", "facts": [["Recipient", "Homer L. Wise"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Magliano, Italy"]], "wiki": {"Homer L. Wise": "Homer_L._Wise"}},
  {"id": "1944-06-16-mccard-robert-h", "date": "1944-06-16", "title": "Gunnery Sergeant Robert H. McCard", "type": "loss", "theater": "Marine Corps", "location": {"name": "Saipan, Mariana Islands", "lat": 15.1833, "lng": 145.75}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving as Platoon Sergeant of Company A, Fourth Tank Battalion, Fourth Marine Division, during the battle for enemy Japanese-held Saipan, Mariana Islands, on June 16, 1944. Cut off from the other units of his platoon when his tank was put out of action by a battery of enemy 77-mm. guns, Gunnery Sergeant McCard carried on resolutely, bringing all the tank's weapons to bear on the enemy, until the severity of hostile fire caused him to order his crew out the escape hatch while he courageously exposed himself to enemy guns by hurling hand grenades, in order to cover the evacuation of his men. …", "facts": [["Recipient", "Robert H. McCard"], ["Rank", "Gunnery Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Saipan, Mariana Islands"], ["Awarded", "Posthumously"]], "wiki": {"Robert H. McCard": "Robert_H._McCard"}},
  {"id": "1944-06-19-mccampbell-david", "date": "1944-06-19", "title": "Commander David McCampbell", "type": "attack", "theater": "Navy", "location": {"name": "First and second battles of the Philippine Sea (approx.)", "lat": 15.0, "lng": 137.0}, "zoom": 6, "summary": "The President of the United States take pleasure in presenting the Medal of Honor to Commander David McCampbell, United States Navy for service as set forth in the following Citation: For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as commander, Air Group Fifteen, during combat against enemy Japanese aerial forces in the First and Second Battles of the Philippine Sea. An inspiring leader, fighting boldly in the face of terrific odds, Commander McCampbell led his fighter planes against a force of eighty Japanese carrier-based aircraft bearing down on our Fleet on June 19, 1944. Striking fiercely in valiant defense of our surface force, he personally destroyed seven hostile planes during this single engagement in which the outnumbering attack force was utterly routed and virtually annihilated. During a major Fleet engagement with the enemy on October 24, Commander McCampbell, assisted by but one plane, intercepted and daringly attacked a formation of sixty hostile land-based craft approaching our forces. …", "facts": [["Recipient", "David McCampbell"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "First and second battles of the Philippine Sea"]], "wiki": {"David McCampbell": "David_McCampbell"}},
  {"id": "1944-06-19-baker-thomas-a", "date": "1944-06-19", "title": "Private Thomas A. Baker", "type": "loss", "theater": "Army", "location": {"name": "Saipan, Mariana Islands", "lat": 15.1833, "lng": 145.75}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty at Saipan, The Mariana Islands, 19 June to 7 July 1944. When his entire company was held up by fire from automatic weapons and small-arms fire from strongly fortified enemy positions that commanded the view of the company, Sgt. (then Pvt.) Baker voluntarily took a bazooka and dashed alone to within 100 yards of the enemy. Through heavy rifle and machine gun fire that was directed at him by the enemy, he knocked out the strong point, enabling his company to assault the ridge. Some days later while his company advanced across the open field flanked with obstructions and places of concealment for the enemy, Sgt. Baker again voluntarily took up a position in the rear to protect the company against a surprise attack and came upon two heavily fortified enemy pockets manned by two officers and ten enlisted men which had been bypassed. …", "facts": [["Recipient", "Thomas A. Baker"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Saipan, Mariana Islands"], ["Awarded", "Posthumously"]], "wiki": {"Thomas A. Baker": "Thomas_Baker_(Medal_of_Honor)"}},
  {"id": "1944-06-20-o-brien-william-j", "date": "1944-06-20", "title": "Lieutenant Colonel William J. O'Brien", "type": "loss", "theater": "Army", "location": {"name": "Saipan, Mariana Islands", "lat": 15.1833, "lng": 145.75}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty at Saipan, Marianas Islands, from 20 June through 7 July 1944. When assault elements of his platoon were held up by intense enemy fire, Lt. Col. O'Brien ordered 3 tanks to precede the assault companies in an attempt to knock out the strongpoint. Due to direct enemy fire the tanks' turrets were closed, causing the tanks to lose direction and to fire into our own troops. Lt. Col. O'Brien, with complete disregard for his own safety, dashed into full view of the enemy and ran to the leader's tank, and pounded on the tank with his pistol butt to attract 2 of the tank's crew and, mounting the tank fully exposed to enemy fire, Lt. Col. O'Brien personally directed the assault until the enemy strongpoint had been liquidated. On 28 June 1944, while his platoon was attempting to take a bitterly defended high ridge in the vicinity of Donnay, Lt. Col. …", "facts": [["Recipient", "William J. O'Brien"], ["Rank", "Lieutenant Colonel"], ["Service", "Army"], ["Place of action", "Saipan, Mariana Islands"], ["Awarded", "Posthumously"]], "wiki": {"William J. O'Brien": "William_J._O'Brien_(Medal_of_Honor)"}},
  {"id": "1944-06-23-kingsley-david-r", "date": "1944-06-23", "title": "Second Lieutenant David R. Kingsley", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Ploiești Raid, Romania (approx.)", "lat": 44.94, "lng": 26.03}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity in action at the risk of life above and beyond the call of duty, June 23, 1944 near Ploesti, Romania, while flying as bombardier of a B17 type aircraft. On the bomb run 2d Lt. Kingsley's aircraft was severely damaged by intense flak and forced to drop out of formation but the pilot proceeded over the target and 2d Lt. Kingsley successfully dropped his bombs, causing severe damage to vital installations. The damaged aircraft, forced to lose altitude and to lag behind the formation, was aggressively attacked by 3 Me 109 aircraft, causing more damage to the aircraft and severely wounding the tail gunner in the upper arm. The radio operator and engineer notified 2d Lt. Kingsley that the tail gunner had been wounded and that assistance was needed to check the bleeding. 2d Lt. Kingsley made his way back to the radio room, skillfully applied first aid to the wound, and succeeded in checking the bleeding. …", "facts": [["Recipient", "David R. Kingsley"], ["Rank", "Second Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Ploiești Raid, Romania"], ["Awarded", "Posthumously"]], "wiki": {"David R. Kingsley": "David_R._Kingsley"}},
  {"id": "1944-06-25-kelly-john-d", "date": "1944-06-25", "title": "Corporal John D. Kelly", "type": "loss", "theater": "Army", "location": {"name": "Fort du Roule, Cherbourg, France", "lat": 49.6306, "lng": -1.6137}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty. On 25 June 1944, in the vicinity of Fort du Roule, Cherbourg, France, when Cpl. Kelly's unit was pinned down by heavy enemy machinegun fire emanating from a deeply entrenched strongpoint on the slope leading up to the fort, Cpl. Kelly volunteered to attempt to neutralize the strongpoint. Arming himself with a pole charge about 10 feet long and with 15 pounds of explosive affixed, he climbed the slope under a withering blast of machinegun fire and placed the charge at the strongpoint's base. The subsequent blast was ineffective, and again, alone and unhesitatingly, he braved the slope to repeat the operation. This second blast blew off the ends of the enemy guns. Cpl. Kelly then climbed the slope a third time to place a pole charge at the strongpoint's rear entrance. …", "facts": [["Recipient", "John D. Kelly"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Fort du Roule, Cherbourg, France"], ["Awarded", "Posthumously"]], "wiki": {"John D. Kelly": "John_D._Kelly_(World_War_II_soldier)"}},
  {"id": "1944-06-25-ogden-carlos-c", "date": "1944-06-25", "title": "First Lieutenant Carlos C. Ogden", "type": "attack", "theater": "Army", "location": {"name": "Near Fort du Roule, France", "lat": 49.6306, "lng": -1.6137}, "zoom": 9, "summary": "On the morning of June 25, 1944, near Fort du Roule, guarding the approaches to Cherbourg, France, 1st Lt. Ogden's company was pinned down by fire from a German 88-mm. gun and 2 machineguns. Arming himself with an M-1 rifle, a grenade launcher, and a number of rifle and hand grenades, he left his company in position and advanced alone, under fire, up the slope toward the enemy emplacements. Struck on the head and knocked down by a glancing machinegun bullet, 1st Lt. Ogden, in spite of his painful wound and enemy fire from close range, continued up the hill. Reaching a vantage point, he silenced the 88mm. gun with a well-placed rifle grenade and then, with handgrenades, knocked out the 2 machineguns, again being painfully wounded. 1st Lt. Ogden's heroic leadership and indomitable courage in alone silencing these enemy weapons inspired his men to greater effort and cleared the way for the company to continue the advance and reach its objectives.", "facts": [["Recipient", "Carlos C. Ogden"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Fort du Roule, France"]], "wiki": {"Carlos C. Ogden": "Carlos_C._Ogden"}},
  {"id": "1944-06-25-epperson-harold-g", "date": "1944-06-25", "title": "Private First Class Harold G. Epperson", "type": "loss", "theater": "Marine Corps", "location": {"name": "Saipan, Mariana Islands", "lat": 15.1833, "lng": 145.75}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the 1st Battalion, 6th Marines, 2d Marine Division, in action against enemy Japanese forces on the Island of Saipan in the Marianas, on 25 June 1944. With his machinegun emplacement bearing the full brunt of a fanatic assault initiated by the Japanese under cover of predawn darkness, Pfc. Epperson manned his weapon with determined aggressiveness, fighting furiously in the defense of his battalion's position and maintaining a steady stream of devastating fire against rapidly infiltrating hostile troops to aid materially in annihilating several of the enemy and in breaking the abortive attack. Suddenly a Japanese soldier, assumed to be dead, sprang up and hurled a powerful hand grenade into the emplacement. Determined to save his comrades, Pfc. Epperson unhesitatingly chose to sacrifice himself and, diving upon the deadly missile, absorbed the shattering violence of the exploding charge in his own body. …", "facts": [["Recipient", "Harold G. Epperson"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Saipan, Mariana Islands"], ["Awarded", "Posthumously"]], "wiki": {"Harold G. Epperson": "Harold_G._Epperson"}},
  {"id": "1944-06-26-muranaga-kiyoshi-k", "date": "1944-06-26", "title": "Private First Class Kiyoshi K. Muranaga", "type": "loss", "theater": "Army", "location": {"name": "Near Suvereto, Italy (approx.)", "lat": 43.08, "lng": 10.68}, "zoom": 9, "summary": "Private First Class Kiyoshi K. Muranaga distinguished himself by extraordinary heroism in action on 26 June 1944, near Suvereto, Italy. Private First Class Muranaga's company encountered a strong enemy force in commanding positions and with superior firepower. An enemy 88mm self-propelled gun opened direct fire on the company, causing the men to disperse and seek cover. Private First Class Muranaga's mortar squad was ordered to action, but the terrain made it impossible to set up their weapons. The squad leader, realizing the vulnerability of the mortar position, moved his men away from the gun to positions of relative safety. Because of the heavy casualties being inflicted on his company, Private First Class Muranaga, who served as a gunner, attempted to neutralize the 88mm weapon alone. Voluntarily remaining at his gun position, Private First Class Muranaga manned the mortar himself and opened fire on the enemy gun at a range of approximately 400 yards. …", "facts": [["Recipient", "Kiyoshi K. Muranaga"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Suvereto, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Kiyoshi K. Muranaga": "Kiyoshi_K._Muranaga"}},
  {"id": "1944-07-04-ono-frank-h", "date": "1944-07-04", "title": "Private First Class Frank H. Ono", "type": "loss", "theater": "Army", "location": {"name": "Near Castellina, Italy (approx.)", "lat": 43.47, "lng": 11.29}, "zoom": 9, "summary": "Private First Class Frank H. Ono distinguished himself by extraordinary heroism in action on 4 July 1944, near Castellina, Italy. In attacking a heavily defended hill, Private First Class Ono's squad was caught in a hail of formidable fire from the well-entrenched enemy. Private First Class Ono opened fire with his automatic rifle and silenced one machine gun 300 hundred yards to the right front. Advancing through incessant fire, he killed a sniper with another burst of fire, and while his squad leader reorganized the rest of the platoon in the rear, he alone defended the critical position. His weapon was then wrenched from his grasp by a burst of enemy machine pistol fire as enemy troops attempted to close in on him. Hurling hand grenades, Private First Class Ono forced the enemy to abandon the attempt, resolutely defending the newly won ground until the rest of the platoon moved forward. Taking a wounded comrade's rifle, Private First Class Ono again joined in the assault. …", "facts": [["Recipient", "Frank H. Ono"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Castellina, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Frank H. Ono": "Frank_H._Ono"}},
  {"id": "1944-07-04-nakamura-william-k", "date": "1944-07-04", "title": "Private First Class William K. Nakamura", "type": "loss", "theater": "Army", "location": {"name": "Near Castellina, Italy (approx.)", "lat": 43.47, "lng": 11.29}, "zoom": 9, "summary": "Private First Class William K. Nakamura distinguished himself by extraordinary heroism in action on 4 July 1944, near Castellina, Italy. During a fierce firefight, Private First Class Nakamura's platoon became pinned down by enemy machine gun fire from a concealed position. On his own initiative, Private First Class Nakamura crawled 20 yards toward the hostile nest with fire from the enemy machine gun barely missing him. Reaching a point 15 yards from the position, he quickly raised himself to a kneeling position and threw four hand grenades, killing or wounding at least three of the enemy soldiers. The enemy weapon silenced, Private First Class Nakamura crawled back to his platoon, which was able to continue its advance as a result of his courageous action. Later, his company was ordered to withdraw from the crest of a hill so that a mortar barrage could be placed on the ridge. On his own initiative, Private First Class Nakamura remained in position to cover his comrades' withdrawal. …", "facts": [["Recipient", "William K. Nakamura"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Castellina, Italy"], ["Awarded", "Posthumously"]], "wiki": {"William K. Nakamura": "William_K._Nakamura"}},
  {"id": "1944-07-07-salomon-benjamin-l", "date": "1944-07-07", "title": "Captain Benjamin L. Salomon", "type": "loss", "theater": "Army", "location": {"name": "Saipan, Mariana Islands", "lat": 15.1833, "lng": 145.75}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty: Captain Ben L. Salomon was serving at Saipan, in the Marianas Islands on July 7, 1944, as the Surgeon for the 2nd Battalion, 105th Infantry Regiment, 27th Infantry Division. The Regiment’s 1st and 2d Battalions were attacked by an overwhelming force estimated between 3,000 and 5,000 Japanese soldiers. It was one of the largest attacks attempted in the Pacific Theater during World War II. Although both units fought furiously, the enemy soon penetrated the Battalions’ combined perimeter and inflicted overwhelming casualties. In the first minutes of the attack, approximately 30 wounded soldiers walked, crawled, or were carried into Captain Salomon’s aid station, and the small tent soon filled with wounded men. As the perimeter began to be overrun, it became increasingly difficult for Captain Salomon to work on the wounded. He then saw a Japanese soldier bayoneting one of the wounded soldiers lying near the tent. …", "facts": [["Recipient", "Benjamin L. Salomon"], ["Rank", "Captain"], ["Service", "Army"], ["Place of action", "Saipan, Mariana Islands"], ["Awarded", "Posthumously"]], "wiki": {"Benjamin L. Salomon": "Ben_L._Salomon"}},
  {"id": "1944-07-07-agerholm-harold-c", "date": "1944-07-07", "title": "Private First Class Harold C. Agerholm", "type": "loss", "theater": "Marine Corps", "location": {"name": "Saipan, Mariana Islands", "lat": 15.1833, "lng": 145.75}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the 4th Battalion, 10th Marines, 2nd Marine Division, in action against enemy Japanese forces on Saipan, Marianas Islands, July 7, 1944. When the enemy launched a fierce, determined counterattack against our positions and overran a neighboring artillery battalion, PFC Agerholm immediately volunteered to assist in the efforts to check the hostile attack and evacuate our wounded. Locating and appropriating an abandoned ambulance jeep, he repeatedly made extremely perilous trips under heavy rifle and mortar fire and single-handedly loaded and evacuated approximately forty-five casualties, working tirelessly and with utter disregard for his own safety during a grueling period of more than three hours. Despite intense, persistent enemy fire, he ran out to aid two men whom he believed to be wounded Marines but was himself mortally wounded by a Japanese sniper while carrying out his hazardous mission. …", "facts": [["Recipient", "Harold C. Agerholm"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Saipan, Mariana Islands"], ["Awarded", "Posthumously"]], "wiki": {"Harold C. Agerholm": "Harold_C._Agerholm"}},
  {"id": "1944-07-07-moto-kaoru", "date": "1944-07-07", "title": "Private First Class Kaoru Moto", "type": "attack", "theater": "Army", "location": {"name": "Near Castellina, Italy (approx.)", "lat": 43.47, "lng": 11.29}, "zoom": 9, "summary": "Private First Class Kaoru Moto distinguished himself by extraordinary heroism in action on 7 July 1944, near Castellina, Italy. While serving as first scout, Private First Class Moto observed a machine gun nest that was hindering his platoon's progress. On his own initiative, he made his way to a point ten paces from the hostile position, and killed the enemy machine gunner. Immediately, the enemy assistant gunner opened fire in the direction of Private First Class Moto. Crawling to the rear of the position, Private First Class Moto surprised the enemy soldier, who quickly surrendered. Taking his prisoner with him, Private First Class Moto took a position a few yards from a house to prevent the enemy from using the building as an observation post. While guarding the house and his prisoner, he observed an enemy machine gun team moving into position. He engaged them, and with deadly fire forced the enemy to withdraw. …", "facts": [["Recipient", "Kaoru Moto"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Castellina, Italy"]], "wiki": {"Kaoru Moto": "Kaoru_Moto"}},
  {"id": "1944-07-07-tanouye-ted-t", "date": "1944-07-07", "title": "Technical Sergeant Ted T. Tanouye", "type": "loss", "theater": "Army", "location": {"name": "Near Molino A Ventoabbto, Italy (approx.)", "lat": 44.1, "lng": 11.0}, "zoom": 9, "summary": "Technical Sergeant Ted T. Tanouye distinguished himself by extraordinary heroism in action on 7 July 1944, near Molino A Ventoabbto, Italy. Technical Sergeant Tanouye led his platoon in an attack to capture the crest of a strategically important hill that afforded little cover. Observing an enemy machine gun crew placing its gun in position to his left front, Technical Sergeant Tanouye crept forward a few yards and opened fire on the position, killing or wounding three and causing two others to disperse. Immediately, an enemy machine pistol opened fire on him. He returned the fire and killed or wounded three more enemy soldiers. While advancing forward, Technical Sergeant Tanouye was subjected to grenade bursts, which severely wounded his left arm. Sighting an enemy-held trench, he raked the position with fire from his submachine gun and wounded several of the enemy. Running out of ammunition, he crawled 20 yards to obtain several clips from a comrade on his left flank. …", "facts": [["Recipient", "Ted T. Tanouye"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Molino A Ventoabbto, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Ted T. Tanouye": "Ted_T._Tanouye"}},
  {"id": "1944-07-08-timmerman-grant-f", "date": "1944-07-08", "title": "Sergeant Grant F. Timmerman", "type": "loss", "theater": "Marine Corps", "location": {"name": "Saipan, Mariana Islands", "lat": 15.1833, "lng": 145.75}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Tank Commander serving with the Second Battalion, Sixth Marines, Second Marine Division, during action against enemy Japanese forces on Saipan, Marianas Islands, on 8 July 1944. Advancing with his tank a few yards ahead of the infantry in support of a vigorous attack on hostile positions, Sergeant Timmerman maintained steady fire from his antiaircraft sky mount machine gun until progress was impeded by a series of enemy trenches and pillboxes. Observing a target of opportunity, he immediately ordered the tank stopped and, mindful of the danger from the muzzle blast as he prepared to open fire with the 75-mm., fearlessly stood up in the exposed turret and ordered the infantry to hit the deck. …", "facts": [["Recipient", "Grant F. Timmerman"], ["Rank", "Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Saipan, Mariana Islands"], ["Awarded", "Posthumously"]], "wiki": {"Grant F. Timmerman": "Grant_F._Timmerman"}},
  {"id": "1944-07-09-pucket-donald-d", "date": "1944-07-09", "title": "First Lieutenant Donald D. Pucket", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Ploiești Raid, Romania (approx.)", "lat": 44.94, "lng": 26.03}, "zoom": 9, "summary": "He took part in a highly effective attack against vital oil installation in Ploesti, Rumania, on 9 July 1944. Just after \"bombs away,\" the plane received heavy and direct hits from antiaircraft fire. One crewmember was instantly killed and 6 others severely wounded. The airplane was badly damaged, 2 were knocked out, the control cables cut, the oxygen system on fire, and the bomb bay flooded with gas and hydraulic fluid. Regaining control of his crippled plane, 1st Lt. Pucket turned its direction over to the copilot. He calmed the crew, administered first aid, and surveyed the damage. Finding the bomb bay doors jammed, he used the hand crank to open them to allow the gas to escape. He jettisoned all guns and equipment but the plane continued to lose altitude rapidly. Realizing that it would be impossible to reach friendly territory he ordered the crew to abandon ship. Three of the crew, uncontrollable from fright or shock, would not leave. 1st Lt. Pucket urged the others to jump. …", "facts": [["Recipient", "Donald D. Pucket"], ["Rank", "First Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Ploiești Raid, Romania"], ["Awarded", "Posthumously"]], "wiki": {"Donald D. Pucket": "Donald_D._Pucket"}},
  {"id": "1944-07-11-endl-gerald-l", "date": "1944-07-11", "title": "Staff Sergeant Gerald L. Endl", "type": "loss", "theater": "Army", "location": {"name": "Near Anamo, New Guinea (approx.)", "lat": -3.13, "lng": 142.43}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty near Anamo, New Guinea, on 11 July 1944. S/Sgt. Endl was at the head of the leading platoon of his company advancing along a jungle trail when enemy troops were encountered and a fire fight developed. The enemy attacked in force under heavy rifle, machinegun, and grenade fire. His platoon leader wounded, S/Sgt. Endl immediately assumed command and deployed his platoon on a firing line at the fork in the trail toward which the enemy attack was directed. The dense jungle terrain greatly restricted vision and movement, and he endeavored to penetrate down the trail toward an open clearing of Kunai grass. As he advanced, he detected the enemy, supported by at least 6 light and 2 heavy machineguns, attempting an enveloping movement around both flanks. …", "facts": [["Recipient", "Gerald L. Endl"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Anamo, New Guinea"], ["Awarded", "Posthumously"]], "wiki": {"Gerald L. Endl": "Gerald_L._Endl"}},
  {"id": "1944-07-12-harmon-roy-w", "date": "1944-07-12", "title": "Sergeant Roy W. Harmon", "type": "loss", "theater": "Army", "location": {"name": "Near Casaglia, Italy (approx.)", "lat": 44.07, "lng": 11.3}, "zoom": 9, "summary": "He was an acting squad leader when heavy machinegun fire from enemy positions, well dug in on commanding ground and camouflaged by haystacks, stopped his company's advance and pinned down 1 platoon where it was exposed to almost certain annihilation. Ordered to rescue the beleaguered platoon by neutralizing the German automatic fire, he led his squad forward along a draw to the right of the trapped unit against 3 key positions which poured murderous fire into his helpless comrades. When within range, his squad fired tracer bullets in an attempt to set fire to the 3 haystacks which were strung out in a loose line directly to the front, 75, 150, and 250 yards away. Realizing that this attack was ineffective, Sgt. Harmon ordered his squad to hold their position and voluntarily began a 1-man assault. Carrying white phosphorus grenades and a submachine gun, he skillfully took advantage of what little cover the terrain afforded and crept to within 25 yards of the first position. …", "facts": [["Recipient", "Roy W. Harmon"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Casaglia, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Roy W. Harmon": "Roy_W._Harmon"}},
  {"id": "1944-07-15-otani-kazuo", "date": "1944-07-15", "title": "Staff Sergeant Kazuo Otani", "type": "loss", "theater": "Army", "location": {"name": "Near Pieve Di S. Luce, Italy (approx.)", "lat": 43.47, "lng": 10.56}, "zoom": 9, "summary": "Staff Sergeant Kazuo Otani distinguished himself by extraordinary heroism in action on 15 July 1944, near Pieve Di S. Luce, Italy. Advancing to attack a hill objective, Staff Sergeant Otani's platoon became pinned down in a wheat field by concentrated fire from enemy machine gun and sniper positions. Realizing the danger confronting his platoon, Staff Sergeant Otani left his cover and shot and killed a sniper who was firing with deadly effect upon the platoon. Followed by a steady stream of machine gun bullets, Staff Sergeant Otani then dashed across the open wheat field toward the foot of a cliff, and directed his men to crawl to the cover of the cliff. When the movement of the platoon drew heavy enemy fire, he dashed along the cliff toward the left flank, exposing himself to enemy fire. By attracting the attention of the enemy, he enabled the men closest to the cliff to reach cover. …", "facts": [["Recipient", "Kazuo Otani"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Pieve Di S. Luce, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Kazuo Otani": "Kazuo_Otani"}},
  {"id": "1944-07-16-christensen-dale-e", "date": "1944-07-16", "title": "Second Lieutenant Dale E. Christensen", "type": "loss", "theater": "Army", "location": {"name": "Driniumor River, New Guinea (approx.)", "lat": -3.15, "lng": 142.45}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty along the Driniumor River, New Guinea, from 16-July 19, 1944. 2d Lt. Christensen repeatedly distinguished himself by conspicuous gallantry above and beyond the call of duty in the continuous heavy fighting which occurred in this area from 16-July 19,. On July 16, his platoon engaged in a savage fire fight in which much damage was caused by 1 enemy machinegun effectively placed. 2d Lt. Christensen ordered his men to remain under cover, crept forward under fire, and at a range of 15 yards put the gun out of action with hand grenades. Again, on July 19, while attacking an enemy position strong in mortars and machineguns, his platoon was pinned to the ground by intense fire. Ordering his men to remain under cover, he crept forward alone to locate definitely the enemy automatic weapons and the best direction from which to attack. …", "facts": [["Recipient", "Dale E. Christensen"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Driniumor River, New Guinea"], ["Awarded", "Posthumously"]], "wiki": {"Dale E. Christensen": "Dale_Eldon_Christensen"}},
  {"id": "1944-07-21-skaggs-jr-luther", "date": "1944-07-21", "title": "Private First Class Luther Skaggs Jr.", "type": "attack", "theater": "Marine Corps", "location": {"name": "Asan-Adelup beachhead, Guam, Mariana Islands", "lat": 13.5, "lng": 144.8}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving as Squad Leader with a Mortar Section of Kilo Company in the Third Battalion, Third Marines, Third Marine Division, during action against enemy Japanese forces on the Asan-Adelup Beachhead, Guam, Marianas Islands, on 21–22 July 1944. When the section leader became a casualty under a heavy mortar barrage shortly after landing, Private First Class Skaggs promptly assumed command and led the section through intense fire for a distance of 200 yards to a position from which to deliver effective coverage of the assault on a strategic cliff. Valiantly defending this vital position against strong enemy counterattacks during the night, Private First Class Skaggs was critically wounded when a Japanese grenade lodged in his foxhole and exploded, shattering the lower part of one leg. …", "facts": [["Recipient", "Luther Skaggs Jr."], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Asan-Adelup beachhead, Guam, Mariana Islands"]], "wiki": {"Luther Skaggs Jr.": "Luther_Skaggs_Jr."}},
  {"id": "1944-07-22-lobaugh-donald-r", "date": "1944-07-22", "title": "Private Donald R. Lobaugh", "type": "loss", "theater": "Army", "location": {"name": "Near Afua, New Guinea (approx.)", "lat": -3.14, "lng": 142.47}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty near Afua, New Guinea, on July 22, 1944. While Pvt. Lobaugh's company was withdrawing from its position on July 21, the enemy attacked and cut off approximately 1 platoon of our troops. The platoon immediately occupied, organized, and defended a position, which it held throughout the night. Early on July 22, an attempt was made to effect its withdrawal, but during the preparation therefor, the enemy emplaced a machinegun, protected by the fire of rifles and automatic weapons, which blocked the only route over which the platoon could move. Knowing that it was the key to the enemy position, Pvt. Lobaugh volunteered to attempt to destroy this weapon, even though in order to reach it he would be forced to work his way about 30 yards over ground devoid of cover. …", "facts": [["Recipient", "Donald R. Lobaugh"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Afua, New Guinea"], ["Awarded", "Posthumously"]], "wiki": {"Donald R. Lobaugh": "Donald_R._Lobaugh"}},
  {"id": "1944-07-22-mason-leonard-f", "date": "1944-07-22", "title": "Private First Class Leonard F. Mason", "type": "loss", "theater": "Marine Corps", "location": {"name": "Asan-Adelup Beachhead, Guam, Mariana Islands", "lat": 13.5, "lng": 144.8}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as an automatic rifleman serving with the 2d Battalion, 3d Marines, 3d Marine Division, in action against enemy Japanese forces on the Asan-Adelup Beachhead, Guam, Marianas Islands on 22 July 1944. Suddenly taken under fire by 2 enemy machineguns not more than 15 yards away while clearing out hostile positions holding up the advance of his platoon through a narrow gully, Pfc. Mason, alone and entirely on his own initiative, climbed out of the gully and moved parallel to it toward the rear of the enemy position. Although fired upon immediately by hostile riflemen from a higher position and wounded repeatedly in the arm and shoulder, Pfc. Mason grimly pressed forward and had just reached his objective when hit again by a burst of enemy machinegun fire, causing a critical wound to which he later succumbed. …", "facts": [["Recipient", "Leonard F. Mason"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Asan-Adelup Beachhead, Guam, Mariana Islands"], ["Awarded", "Posthumously"]], "wiki": {"Leonard F. Mason": "Leonard_F._Mason"}},
  {"id": "1944-07-23-boyce-jr-george-w-g", "date": "1944-07-23", "title": "Second Lieutenant George W. G. Boyce Jr.", "type": "loss", "theater": "Army", "location": {"name": "Near Afua, New Guinea (approx.)", "lat": -3.14, "lng": 142.47}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of his life above and beyond the call of duty near Afua, New Guinea, on 23 July 1944. 2d Lt. Boyce's troop, having been ordered to the relief of another unit surrounded by superior enemy forces, moved out, and upon gaining contact with the enemy, the two leading platoons deployed and built up a firing line. 2d Lt. Boyce was ordered to attack with his platoon and make the main effort on the right of the troop. He launched his attack but after a short advance encountered such intense rifle, machinegun, and mortar fire that the forward movement of his platoon was temporarily halted. A shallow depression offered a route of advance and he worked his squad up this avenue of approach in order to close with the enemy. He was promptly met by a volley of hand grenades, 1 falling between himself and the men immediately following. …", "facts": [["Recipient", "George W. G. Boyce Jr."], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Near Afua, New Guinea"], ["Awarded", "Posthumously"]], "wiki": {"George W. G. Boyce Jr.": "George_W._G._Boyce_Jr."}},
  {"id": "1944-07-23-eubanks-ray-e", "date": "1944-07-23", "title": "Sergeant Ray E. Eubanks", "type": "loss", "theater": "Army", "location": {"name": "Noemfoor Island, Dutch New Guinea", "lat": -1.03, "lng": 134.88}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty at Noemfoor Island, Dutch New Guinea, 23 July 1944. While moving to the relief of a platoon isolated by the enemy, his company encountered a strong enemy position supported by machinegun, rifle, and mortar fire. Sgt. Eubanks was ordered to make an attack with 1 squad to neutralize the enemy by fire in order to assist the advance of his company. He maneuvered his squad to within 30 yards of the enemy where heavy fire checked his advance. Directing his men to maintain their fire, he and 2 scouts worked their way forward up a shallow depression to within 25 yards of the enemy. Directing the scouts to remain in place, Sgt. Eubanks armed himself with an automatic rifle and worked himself forward over terrain swept by intense fire to within 15 yards of the enemy position when he opened fire with telling effect. …", "facts": [["Recipient", "Ray E. Eubanks"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Noemfoor Island, Dutch New Guinea"], ["Awarded", "Posthumously"]], "wiki": {"Ray E. Eubanks": "Ray_E._Eubanks"}},
  {"id": "1944-07-25-wilson-jr-louis-h", "date": "1944-07-25", "title": "Captain Louis H. Wilson Jr.", "type": "attack", "theater": "Marine Corps", "location": {"name": "Fonte Hill, Guam, Mariana Islands", "lat": 13.5, "lng": 144.8}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Commanding Officer of Company F, Second Battalion, Ninth Marines, Third Marine Division, in action against enemy Japanese forces at Fonte Hill, Guam, Marianas Islands, 25 and July 26, 1944. Ordered to take that portion of the hill within his zone of action, Captain Wilson initiated his attack in midafternoon, pushed up the rugged, open terrain against terrific machine-gun and rifle fire for 300 yards and successfully captured the objective. Promptly assuming command of other disorganized units and motorized equipment in addition to his own company and one reinforcing platoon, he organized his night defenses in the face of continuous hostile fire and, although wounded three times during this five-hour period, completed his disposition of men and guns before retiring to the company command post for medical attention. …", "facts": [["Recipient", "Louis H. Wilson Jr."], ["Rank", "Captain"], ["Service", "Marine Corps"], ["Place of action", "Fonte Hill, Guam, Mariana Islands"]], "wiki": {"Louis H. Wilson Jr.": "Louis_H._Wilson_Jr."}},
  {"id": "1944-07-29-whittington-hulon-b", "date": "1944-07-29", "title": "Sergeant Hulon B. Whittington", "type": "attack", "theater": "Army", "location": {"name": "Near Grimesnil, France", "lat": 48.9547, "lng": -1.3489}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of life above and beyond the call of duty. On the night of 29 July 1944, near Grimesnil, France, during an enemy armored attack, Sgt. Whittington, a squad leader, assumed command of his platoon when the platoon leader and platoon sergeant became missing in action. He reorganized the defense and, under fire, courageously crawled between gun positions to check the actions of his men. When the advancing enemy attempted to penetrate a roadblock, Sgt. Whittington, completely disregarding intense enemy action, mounted a tank and by shouting through the turret, directed it into position to fire pointblank at the leading Mark V German tank. The destruction of this vehicle blocked all movement of the remaining enemy column consisting of over 100 vehicles of a Panzer unit. The blocked vehicles were then destroyed by hand grenades, bazooka, tank, and artillery fire and large numbers of enemy personnel were wiped out by a bold and resolute bayonet charge inspired by Sgt. Whittington. …", "facts": [["Recipient", "Hulon B. Whittington"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Grimesnil, France"]], "wiki": {"Hulon B. Whittington": "Hulon_B._Whittington"}},
  {"id": "1944-07-30-ozbourn-joseph-w", "date": "1944-07-30", "title": "Private Joseph W. Ozbourn", "type": "loss", "theater": "Marine Corps", "location": {"name": "Tinian, Mariana Islands", "lat": 15, "lng": 145.6333}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as a Browning Automatic Rifleman serving with the First Battalion, Twenty-Third Marines, Fourth Marine Division, during the battle for enemy Japanese-held Tinian Island, Marianas Islands, 30 July 1944. As a member of a platoon assigned the mission of clearing the remaining Japanese troops from dugouts and pillboxes along a tree line, Private Ozbourn, flanked by two men on either side, was moving forward to throw an armed hand grenade into a dugout when a terrific blast from the entrance severely wounded the four men and himself. Unable to throw the grenade into the dugout and with no place to hurl it without endangering the other men, Private Ozbourn unhesitatingly grasped it close to his body and fell upon it, sacrificing his own life to absorb the full impact of the explosion but saving his comrades. …", "facts": [["Recipient", "Joseph W. Ozbourn"], ["Rank", "Private"], ["Service", "Marine Corps"], ["Place of action", "Tinian, Mariana Islands"], ["Awarded", "Posthumously"]], "wiki": {"Joseph W. Ozbourn": "Joseph_W._Ozbourn"}},
  {"id": "1944-07-31-ramage-lawson-p", "date": "1944-07-31", "title": "Commander Lawson P. Ramage", "type": "attack", "theater": "Navy", "location": {"name": "USS Parche (SS-384), south of Taiwan", "lat": 24, "lng": 121}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as commanding officer of the U.S.S. Parche in a predawn attack on a Japanese convoy, 31 July 1944. Boldly penetrating the screen of a heavily escorted convoy, Comdr. Ramage launched a perilous surface attack by delivering a crippling stern shot into a freighter and quickly following up with a series of bow and stern torpedoes to sink the leading tanker and damage the second one. Exposed by the light of bursting flares and bravely defiant of terrific shellfire passing close overhead, he struck again, sinking a transport by two forward reloads. In the mounting fury of fire from the damaged and sinking tanker, he calmly ordered his men below, remaining on the bridge to fight it out with an enemy now disorganized and confused. Swift to act as a fast transport closed in to ram, Comdr. …", "facts": [["Recipient", "Lawson P. Ramage"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "USS Parche (SS-384), south of Taiwan"]], "wiki": {"Lawson P. Ramage": "Lawson_P._Ramage"}},
  {"id": "1944-08-03-witek-frank-p", "date": "1944-08-03", "title": "Private First Class Frank P. Witek", "type": "loss", "theater": "Marine Corps", "location": {"name": "Battle of Finegayen, Guam, Mariana Islands", "lat": 13.5, "lng": 144.8}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the First Battalion, Ninth Marines, Third Marine Division, during the Battle of Finegayan at Guam, Marianas, on 3 August 1944. When his rifle platoon was halted by heavy surprise fire from well camouflaged enemy positions, Private First Class Witek daringly remained standing to fire a full magazine from his automatic point-blank range into a depression housing Japanese troops, killing eight of the enemy and enabling the greater part of his platoon to take cover. During his platoon's withdrawal for consolidation of lines, he remained to safeguard a severely wounded comrade, courageously returning the enemy's fire until the arrival of stretcher bearers and then covering the evacuation by sustained fire as he moved backward toward his own lines. …", "facts": [["Recipient", "Frank P. Witek"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Battle of Finegayen, Guam, Mariana Islands"], ["Awarded", "Posthumously"]], "wiki": {"Frank P. Witek": "Frank_P._Witek"}},
  {"id": "1944-08-03-wilson-robert-l", "date": "1944-08-03", "title": "Private First Class Robert L. Wilson", "type": "loss", "theater": "Marine Corps", "location": {"name": "Tinian, Mariana Islands", "lat": 15, "lng": 145.6333}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the Second Battalion, Sixth Marines, Second Marine Division, during action against enemy Japanese forces on Tinian Island, Marianas Group, on August 3, 1944. As one of a group of Marines advancing through heavy underbrush to neutralize isolated points of resistance, Private First Class Wilson daringly preceded his companions toward a pile of rocks where Japanese troops were supposed to be hiding. Fully aware of the danger involved, he was moving forward while the remainder of the squad armed with automatic rifles closed together in the rear, when an enemy grenade landed in the midst of the group. Quick to act, Private First Class Wilson cried a warning to the men and unhesitatingly threw himself on the grenade, heroically sacrificing his own life so that the others might live and fulfill their mission. …", "facts": [["Recipient", "Robert L. Wilson"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Tinian, Mariana Islands"], ["Awarded", "Posthumously"]], "wiki": {"Robert L. Wilson": "Robert_L._Wilson"}},
  {"id": "1944-08-09-lindsey-darrell-r", "date": "1944-08-09", "title": "Captain Darrell R. Lindsey", "type": "loss", "theater": "Army Air Forces", "location": {"name": "L'Isle Adam railroad bridge over the Seine, France (approx.)", "lat": 49.11, "lng": 2.22}, "zoom": 9, "summary": "On August 9, Captain Lindsey, a veteran of 45 combat missions, flew as group leader to destroy the railroad bridge over the Seine River at L'Isle Adam northwest of Paris. The bridge, one of the last over the Seine still standing, was heavily defended by German anti-aircraft units. Leading a formation of 30 aircraft, Lindsey's B-26 was heavily damaged and both the right engine and wing set afire during the bombing run. Although knocked out of formation, Lindsey recovered his place and led the group over the target, then stabilized the aircraft so that his crew could parachute. According to the crew's bombardier, Lindsey severely lessened his own chance to escape to prevent the aircraft from spinning, which proved fatal when a fuel tank exploded just after the last crewman exited the aircraft. Captain Lindsey's body was not recovered and he was listed as missing-in-action and presumed killed. …", "facts": [["Recipient", "Darrell R. Lindsey"], ["Rank", "Captain"], ["Service", "Army Air Forces"], ["Place of action", "L'Isle Adam railroad bridge over the Seine, France"], ["Awarded", "Posthumously"]], "wiki": {"Darrell R. Lindsey": "Darrell_R._Lindsey"}},
  {"id": "1944-08-15-connor-james-p", "date": "1944-08-15", "title": "Sergeant James P. Connor", "type": "attack", "theater": "Army", "location": {"name": "Cape Cavalaire, southern France (approx.)", "lat": 43.17, "lng": 6.53}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. On 15 August 1944, Sgt. Connor, through sheer grit and determination, led his platoon in clearing an enemy vastly superior in numbers and firepower from strongly entrenched positions on Cape Cavalaire, removing a grave enemy threat to his division during the amphibious landing in southern France, and thereby insured safe and uninterrupted landings for the huge volume of men and materiel which followed. His battle patrol landed on \"Red Beach\" with the mission of destroying the strongly fortified enemy positions on Cape Cavalaire with utmost speed. From the peninsula the enemy had commanding observation and seriously menaced the vast landing operations taking place. Though knocked down and seriously wounded in the neck by a hanging mine which killed his platoon lieutenant, Sgt. Connor refused medical aid and with his driving spirit practically carried the platoon across several thousand yards of mine-saturated beach through intense fire from mortars, 20-mm. flak guns, machineguns, and snipers. …", "facts": [["Recipient", "James P. Connor"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Cape Cavalaire, southern France"], ["Awarded", "G.O. No. 18, 15 March 1945"]], "wiki": {"James P. Connor": "James_Phillip_Connor"}},
  {"id": "1944-08-17-bender-stanley", "date": "1944-08-17", "title": "Staff Sergeant Stanley Bender", "type": "attack", "theater": "Army", "location": {"name": "Near La Londe les maures, France (approx.)", "lat": 43.14, "lng": 6.23}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. On 17 August 1944, near La Londe-les-Maures, France, he climbed on top of a knocked-out tank, in the face of withering machinegun fire which had halted the advance of his company, in an effort to locate the source of this fire. Although bullets ricocheted off the turret at his feet, he nevertheless remained standing upright in full view of the enemy for over 2 minutes. Locating the enemy machineguns on a knoll 200 yards away, he ordered 2 squads to cover him and led his men down an irrigation ditch, running a gauntlet of intense machinegun fire, which completely blanketed 50 yards of his advance and wounded 4 of his men. While the Germans hurled hand grenades at the ditch, he stood his ground until his squad caught up with him, then advanced alone, in a wide flanking approach, to the rear of the knoll. …", "facts": [["Recipient", "Stanley Bender"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near La Londe les maures, France"]], "wiki": {"Stanley Bender": "Stanley_Bender"}},
  {"id": "1944-08-19-nakae-masato", "date": "1944-08-19", "title": "Private Masato Nakae", "type": "loss", "theater": "Army", "location": {"name": "Near Pisa, Italy", "lat": 43.7167, "lng": 10.4}, "zoom": 9, "summary": "The President of the United States of America, authorized by Act of Congress, March 3, 1963, has awarded in the name of The Congress the Medal of Honor to for conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty: Private Masato Nakae distinguished himself by extraordinary heroism in action on August 19, 1944, near Pisa, Italy. When his submachine gun was damaged by a shell fragment during a fierce attack by a superior enemy force, Private Nakae quickly picked up his wounded comrade’s M-1 rifle and fired rifle grenades at the steadily advancing enemy. As the hostile force continued to close in on his position, Private Nakae threw six grenades and forced them to withdraw. During a concentrated enemy mortar barrage that preceded the next assault by the enemy force, a mortar shell fragment seriously wounded Private Nakae. Despite his injury, he refused to surrender his position and continued firing at the advancing enemy. …", "facts": [["Recipient", "Masato Nakae"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Pisa, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Masato Nakae": "Masato_Nakae"}},
  {"id": "1944-08-20-hawk-john-d", "date": "1944-08-20", "title": "Sergeant John D. Hawk", "type": "attack", "theater": "Army", "location": {"name": "Near Chambois, France (approx.)", "lat": 48.81, "lng": 0.11}, "zoom": 9, "summary": "He manned a light machinegun on 20 August 1944, near Chambois, France, a key point in the encirclement which created the Falaise Pocket. During an enemy counterattack, his position was menaced by a strong force of tanks and infantry. His fire forced the infantry to withdraw, but an artillery shell knocked out his gun and wounded him in the right thigh. Securing a bazooka, he and another man stalked the tanks and forced them to retire to a wooded section. In the lull which followed, Sgt. Hawk reorganized 2 machinegun squads and, in the face of intense enemy fire, directed the assembly of 1 workable weapon from 2 damaged guns. When another enemy assault developed, he was forced to pull back from the pressure of spearheading armor. Two of our tank destroyers were brought up. Their shots were ineffective because of the terrain until Sgt. …", "facts": [["Recipient", "John D. Hawk"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Chambois, France"]], "wiki": {"John D. Hawk": "John_D._Hawk"}},
  {"id": "1944-08-23-carey-alvin-p", "date": "1944-08-23", "title": "Staff Sergeant Alvin P. Carey", "type": "loss", "theater": "Army", "location": {"name": "Near Plougastel, Brittany, France", "lat": 48.3733, "lng": -4.3694}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life, above and beyond the call of duty, on August 23, 1944. S/Sgt. Carey, leader of a machinegun section, was advancing with his company in the attack on the strongly held enemy hill 154, near Plougastel, Brittany, France. The advance was held up when the attacking units were pinned down by intense enemy machinegun fire from a pillbox 200 yards up the hill. From his position covering the right flank, S/Sgt. Carey displaced his guns to an advanced position and then, upon his own initiative, armed himself with as many hand grenades as he could carry and without regard for his personal safety started alone up the hill toward the pillbox. Crawling forward under its withering fire, he proceeded 150 yards when he met a German rifleman whom he killed with his carbine. …", "facts": [["Recipient", "Alvin P. Carey"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Plougastel, Brittany, France"], ["Awarded", "Posthumously, G.O. No. 37, May 11, 1945"]], "wiki": {"Alvin P. Carey": "Alvin_P._Carey"}},
  {"id": "1944-08-25-garman-harold-a", "date": "1944-08-25", "title": "Private Harold A. Garman", "type": "attack", "theater": "Army", "location": {"name": "Near Montereau, France (approx.)", "lat": 48.38, "lng": 2.95}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty. On 25 August 1944, in the vicinity of Montereau, France, the enemy was sharply contesting any enlargement of the bridgehead which our forces had established on the northern bank of the Seine River in this sector. Casualties were being evacuated to the southern shore in assault boats paddled by litter bearers from a medical battalion. Pvt. Garman, also a litter bearer in this battalion, was working on the friendly shore carrying the wounded from the boats to waiting ambulances. As 1 boatload of wounded reached midstream, a German machinegun suddenly opened fire upon it from a commanding position on the northern bank 100 yards away. All of the men in the boat immediately took to the water except 1 man who was so badly wounded he could not rise from his litter. Two other patients who were unable to swim because of their wounds clung to the sides of the boat. …", "facts": [["Recipient", "Harold A. Garman"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Montereau, France"]], "wiki": {"Harold A. Garman": "Harold_A._Garman"}},
  {"id": "1944-08-27-gregg-stephen-r", "date": "1944-08-27", "title": "Technical Sergeant Stephen R. Gregg", "type": "attack", "theater": "Army", "location": {"name": "Near Montelimar, France", "lat": 44.5581, "lng": 4.7508}, "zoom": 9, "summary": "Second Lieutenant (Infantry), [then Technical Sergeant] Stephen Raymond Gregg, United States Army, for conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty on 27 August 1944, while serving with Company L, 143d Infantry Regiment, 36th Infantry Division, in action in the vicinity of Montelimar, France. As his platoon advanced upon the enemy positions; the leading scout was fired upon and Second Lieutenant Gregg immediately put his machineguns into action to cover the advance of the riflemen. The Germans, who were at close range, threw hand grenades at the riflemen, killing some and wounding seven. Each time a medical aid man attempted to reach the wounded, the Germans fired at him. Realizing the seriousness of the situation, Second Lieutenant Gregg took one of the light .30-caliber machineguns, and firing from the hip, started boldly up the hill with the medical aid man following him. …", "facts": [["Recipient", "Stephen R. Gregg"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Montelimar, France"]], "wiki": {"Stephen R. Gregg": "Stephen_R._Gregg"}},
  {"id": "1944-08-29-mcveigh-john-j", "date": "1944-08-29", "title": "Sergeant John J. McVeigh", "type": "loss", "theater": "Army", "location": {"name": "Near Brest, France (approx.)", "lat": 48.39, "lng": -4.49}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of his life above and beyond the call of duty near Brest, France, on 29 August 1944. Shortly after dusk an enemy counterattack of platoon strength was launched against 1 platoon of Company G, 23d Infantry. Since the Company G platoon was not dug in and had just begun to assume defensive positions along a hedge, part of the line sagged momentarily under heavy fire from small arms and 2 flak guns, leaving a section of heavy machineguns holding a wide frontage without rifle protection. The enemy drive moved so swiftly that German riflemen were soon almost on top of 1 machinegun position. Sgt. McVeigh, heedless of a tremendous amount of small arms and flak fire directed toward him, stood up in full view of the enemy and directed the fire of his squad on the attacking Germans until his position was almost overrun. He then drew his trench knife, and single-handed charged several of the enemy. …", "facts": [["Recipient", "John J. McVeigh"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Brest, France"], ["Awarded", "Posthumously"]], "wiki": {"John J. McVeigh": "John_J._McVeigh"}},
  {"id": "1944-09-02-lee-daniel-w", "date": "1944-09-02", "title": "Second Lieutenant Daniel W. Lee", "type": "attack", "theater": "Army", "location": {"name": "Montreval, France", "lat": 46.3375, "lng": 5.1289}, "zoom": 9, "summary": "1st Lt. (then 2d Lt.) Daniel W. Lee was leader of Headquarters Platoon, Troop A, 117th Cavalry Reconnaissance Squadron, Mechanized, at Montrevel, France, on September 2, 1944, when the Germans mounted a strong counterattack, isolating the town and engaging its outnumbered defenders in a pitched battle. After the fight had raged for hours and our forces had withstood heavy shelling and armor-supported infantry attacks, 2d Lt. Lee organized a patrol to knock out mortars which were inflicting heavy casualties on the beleaguered reconnaissance troops. He led the small group to the edge of the town, sweeping enemy riflemen out of position on a ridge from which he observed 7 Germans manning 2 large mortars near an armored half-track about 100 yards down the reverse slope. Armed with a rifle and grenades, he left his men on the high ground and crawled to within 30 yards of the mortars, where the enemy discovered him and unleashed machine-pistol fire which shattered his right thigh. …", "facts": [["Recipient", "Daniel W. Lee"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Montreval, France"]], "wiki": {"Daniel W. Lee": "Daniel_W._Lee"}},
  {"id": "1944-09-04-merli-gino-j", "date": "1944-09-04", "title": "Private First Class Gino J. Merli", "type": "attack", "theater": "Army", "location": {"name": "Near Sars la Bruyere, Belgium (approx.)", "lat": 50.37, "lng": 3.88}, "zoom": 9, "summary": "He was serving as a machine gunner in the vicinity of Sars la Bruyere, Belgium, on the night of 4–5 September 1944, when his company was attacked by a superior German force. Its position was overrun and he was surrounded when our troops were driven back by overwhelming numbers and firepower. Disregarding the fury of the enemy fire concentrated on him he maintained his position, covering the withdrawal of our riflemen and breaking the force of the enemy pressure. His assistant machine gunner was killed and the position captured; the other 8 members of the section were forced to surrender. Pfc. Merli slumped down beside the dead assistant gunner and feigned death. No sooner had the enemy group withdrawn then he was up and firing in all directions. Once more his position was taken and the captors found 2 apparently lifeless bodies. Throughout the night Pfc. Merli stayed at his weapon. …", "facts": [["Recipient", "Gino J. Merli"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Sars la Bruyere, Belgium"]], "wiki": {"Gino J. Merli": "Gino_J._Merli"}},
  {"id": "1944-09-07-maxwell-robert-d", "date": "1944-09-07", "title": "Technician 5th Grade Robert D. Maxwell", "type": "attack", "theater": "Army", "location": {"name": "Near Besançon, France", "lat": 47.24, "lng": 6.02}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty on 7 September 1944, near Besancon, France. Technician 5th Grade Maxwell and 3 other soldiers, armed only with .45 caliber automatic pistols, defended the battalion observation post against an overwhelming onslaught by enemy infantrymen in approximately platoon strength, supported by 20mm. flak and machinegun fire, who had infiltrated through the battalion's forward companies and were attacking the observation post with machinegun, machine pistol, and grenade fire at ranges as close as 10 yards. Despite a hail of fire from automatic weapons and grenade launchers, Technician 5th Grade Maxwell aggressively fought off advancing enemy elements and, by his calmness, tenacity, and fortitude, inspired his fellows to continue the unequal struggle. When an enemy hand grenade was thrown in the midst of his squad, Technician 5th Grade Maxwell unhesitatingly hurled himself squarely upon it, using his blanket and his unprotected body to absorb the full force of the explosion. …", "facts": [["Recipient", "Robert D. Maxwell"], ["Rank", "Technician 5th Grade"], ["Service", "Army"], ["Place of action", "Near Besançon, France"], ["Awarded", "G.O. No. 24, 6 April 1945"]], "wiki": {"Robert D. Maxwell": "Robert_D._Maxwell"}},
  {"id": "1944-09-08-prussman-ernest-w", "date": "1944-09-08", "title": "Private First Class Ernest W. Prussman", "type": "loss", "theater": "Army", "location": {"name": "Near Les Coates, Brittany, France (approx.)", "lat": 48.4, "lng": -4.5}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty on September 8, 1944, near Les Coates, Brittany, France. When the advance of the flank companies of 2 battalions was halted by intense enemy mortar, machinegun, and sniper fire from a fortified position on his left, Pfc. Prussman maneuvered his squad to assault the enemy fortifications. Hurdling a hedgerow, he came upon 2 enemy riflemen whom he disarmed. After leading his squad across an open field to the next hedgerow, he advanced to a machinegun position, destroyed the gun, captured its crew and 2 riflemen. Again advancing ahead of his squad in the assault, he was mortally wounded by an enemy rifleman, but as he fell to the ground he threw a handgrenade, killing his opponent. His superb leadership and heroic action at the cost of his life so demoralized the enemy that resistance at this point collapsed, permitting the 2 battalions to continue their advance.", "facts": [["Recipient", "Ernest W. Prussman"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Les Coates, Brittany, France"], ["Awarded", "Posthumously"]], "wiki": {"Ernest W. Prussman": "Ernest_W._Prussman"}},
  {"id": "1944-09-12-tominac-john-j", "date": "1944-09-12", "title": "First Lieutenant John J. Tominac", "type": "attack", "theater": "Army", "location": {"name": "Saulx de Vesoul, France (approx.)", "lat": 47.7, "lng": 6.27}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty on September 12, 1944, in an attack on Saulx de Vesoul, France 1st Lt. Tominac charged alone over 50 yards of exposed terrain onto an enemy roadblock to dispatch a 3-man crew of German machine gunners with a single burst from his Thompson machinegun. After smashing the enemy outpost, he led 1 of his squads in the annihilation of a second hostile group defended by mortar, machinegun, automatic pistol, rifle and grenade fire, killing about 30 of the enemy. Reaching the suburbs of the town, he advanced 50 yards ahead of his men to reconnoiter a third enemy position which commanded the road with a 77-mm. SP gun supported by infantry elements. The SP gun opened fire on his supporting tank, setting it afire with a direct hit. A fragment from the same shell painfully wounded 1st Lt. Tominac in the shoulder, knocking him to the ground. …", "facts": [["Recipient", "John J. Tominac"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Saulx de Vesoul, France"]], "wiki": {"John J. Tominac": "John_J._Tominac"}},
  {"id": "1944-09-12-fisher-almond-e", "date": "1944-09-12", "title": "Second Lieutenant Almond E. Fisher", "type": "attack", "theater": "Army", "location": {"name": "Near Grammont, France (approx.)", "lat": 47.6, "lng": 6.6}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty on the night of 12-September 13, 1944, near Grammont, France. In the darkness of early morning, 2d Lt. Fisher was leading a platoon of Company E, 157th Infantry, in single column to the attack of a strongly defended hill position. At 2:30 A.M., the forward elements were brought under enemy machinegun fire from a distance of not more than 20 yards. Working his way alone to within 20 feet of the gun emplacement, he opened fire with his carbine and killed the entire guncrew. A few minutes after the advance was resumed, heavy machinegun fire was encountered from the left flank. Again crawling forward alone under withering fire, he blasted the gun and crew from their positions with hand grenades. After a halt to replenish ammunition, the advance was again resumed and continued for 1 hour before being stopped by intense machinegun and rifle fire. …", "facts": [["Recipient", "Almond E. Fisher"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Near Grammont, France"]], "wiki": {"Almond E. Fisher": "Almond_E._Fisher"}},
  {"id": "1944-09-12-zussman-raymond", "date": "1944-09-12", "title": "Second Lieutenant Raymond Zussman", "type": "loss", "theater": "Army", "location": {"name": "Noroy le Bourg, France", "lat": 47.6156, "lng": 6.3061}, "zoom": 9, "summary": "On 12 September 1944, 2d Lt. Zussman was in command of 2 tanks operating with an infantry company in the attack on enemy forces occupying the town of Noroy le Bourg, France. At 7 p.m., his command tank bogged down. Throughout the ensuing action, armed only with a carbine, he reconnoitered alone on foot far in advance of his remaining tank and the infantry. Returning only from time to time to designate targets, he directed the action of the tank and turned over to the infantry the numerous German soldiers he had caused to surrender. He located a road block and directed his tanks to destroy it. Fully exposed to fire from enemy positions only 50 yards distant, he stood by his tank directing its fire. Three Germans were killed and 8 surrendered. Again he walked before his tank, leading it against an enemy-held group of houses, machine gun and small arms fire kicking up dust at his feet. The tank fire broke the resistance and 20 enemy surrendered. …", "facts": [["Recipient", "Raymond Zussman"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Noroy le Bourg, France"], ["Awarded", "Posthumously"]], "wiki": {"Raymond Zussman": "Raymond_Zussman"}},
  {"id": "1944-09-12-clark-francis-j", "date": "1944-09-12", "title": "Technical Sergeant Francis J. Clark", "type": "attack", "theater": "Army", "location": {"name": "Near Kalborn, Luxembourg and near Sevenig, Germany", "lat": 50.1, "lng": 6.1167}, "zoom": 9, "summary": "He fought gallantly in Luxembourg and Germany. On 12 September 1944, Company K began fording the Our River near Kalborn, Luxembourg, to take high ground on the opposite bank. Covered by early morning fog, the 3d Platoon, in which T/Sgt. Clark was squad leader, successfully negotiated the crossing; but when the 2d Platoon reached the shore, withering automatic and small-arms fire ripped into it, eliminating the platoon leader and platoon sergeant and pinning down the troops in the open. From his comparatively safe position, T/Sgt. Clark crawled alone across a field through a hail of bullets to the stricken troops. He led the platoon to safety and then unhesitatingly returned into the fire-swept area to rescue a wounded soldier, carrying him to the American line while hostile gunners tried to cut him down. Later, he led his squad and men of the 2d Platoon in dangerous sorties against strong enemy positions to weaken them by lightning-like jabs. He assaulted an enemy machinegun with hand grenades, killing 2 Germans. …", "facts": [["Recipient", "Francis J. Clark"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Kalborn, Luxembourg and near Sevenig, Germany"]], "wiki": {"Francis J. Clark": "Francis_J._Clark"}},
  {"id": "1944-09-13-hallman-sherwood-h", "date": "1944-09-13", "title": "Staff Sergeant Sherwood H. Hallman", "type": "loss", "theater": "Army", "location": {"name": "Brest, Brittany, France (approx.)", "lat": 48.39, "lng": -4.49}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty. On 13 September 1944, in Brittany, France, the 2d Battalion in its attack on the fortified city of Brest was held up by a strongly defended enemy position which had prevented its advance despite repeated attacks extending over 3-days. Finally, Company F advanced to within several hundred yards of the enemy position but was again halted by intense fire. Realizing that the position must be neutralized without delay, S/Sgt. Hallman ordered his squad to cover his movements with fire while he advanced alone to a point from which he could make the assault. Without hesitating, S/Sgt. Hallman leaped over a hedgerow into a sunken road, the central point of the German defenses which was known to contain an enemy machinegun position and at least 30 enemy riflemen. Firing his carbine and hurling grenades, S/Sgt. Hallman, unassisted, killed or wounded 4 of the enemy, then ordered the remainder to surrender. …", "facts": [["Recipient", "Sherwood H. Hallman"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Brest, Brittany, France"], ["Awarded", "Posthumously"]], "wiki": {"Sherwood H. Hallman": "Sherwood_H._Hallman"}},
  {"id": "1944-09-14-lloyd-edgar-h", "date": "1944-09-14", "title": "First Lieutenant Edgar H. Lloyd", "type": "loss", "theater": "Army", "location": {"name": "Near Pompey, France (approx.)", "lat": 48.77, "lng": 6.12}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty. On September 14, 1944, Company E, 319th Infantry, with which 1st Lt. Lloyd was serving as a rifle platoon leader, was assigned the mission of expelling an estimated enemy force of 200 men from a heavily fortified position near Pompey, France. As the attack progressed, 1st Lt. Lloyd's platoon advanced to within 50 yards of the enemy position where they were caught in a withering machinegun and rifle crossfire which inflicted heavy casualties and momentarily disorganized the platoon. With complete disregard for his own safety, 1st Lt. Lloyd leaped to his feet and led his men on a run into the raking fire, shouting encouragement to them. He jumped into the first enemy machinegun position, knocked out the gunner with his fist, dropped a grenade, and jumped out before it exploded. …", "facts": [["Recipient", "Edgar H. Lloyd"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Pompey, France"], ["Awarded", "Posthumously"]], "wiki": {"Edgar H. Lloyd": "Edgar_H._Lloyd"}},
  {"id": "1944-09-14-wigle-thomas-w", "date": "1944-09-14", "title": "Second Lieutenant Thomas W. Wigle", "type": "loss", "theater": "Army", "location": {"name": "Monte Frassino, Italy (approx.)", "lat": 41.35, "lng": 13.8}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of life above and beyond the call of duty in the vicinity of Monte Frassino, Italy. The 3d Platoon, in attempting to seize a strongly fortified hill position protected by 3 parallel high terraced stone walls, was twice thrown back by the withering crossfire. 2d Lt. Wigle, acting company executive, observing that the platoon was without an officer, volunteered to command it on the next attack. Leading his men up the bare, rocky slopes through intense and concentrated fire, he succeeded in reaching the first of the stone walls. Having himself boosted to the top and perching there in full view of the enemy, he drew and returned their fire while his men helped each other up and over. Following the same method, he successfully negotiated the second. Upon reaching the top of the third wall, he faced 3 houses which were the key point of the enemy defense. …", "facts": [["Recipient", "Thomas W. Wigle"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Monte Frassino, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Thomas W. Wigle": "Thomas_W._Wigle"}},
  {"id": "1944-09-14-sadowski-joseph-j", "date": "1944-09-14", "title": "Sergeant Joseph J. Sadowski", "type": "loss", "theater": "Army", "location": {"name": "Valhey, France", "lat": 48.68, "lng": 6.4919}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty at Valhey, France. On the afternoon of 14 September 1944, Sgt. Sadowski as a tank commander was advancing with the leading elements of Combat Command A, 4th Armored Division, through an intensely severe barrage of enemy fire from the streets and buildings of the town of Valhey. As Sgt. Sadowski's tank advanced through the hail of fire, it was struck by a shell from an 88-mm. gun fired at a range of 20 yards. The tank was disabled and burst into flames. The suddenness of the enemy attack caused confusion and hesitation among the crews of the remaining tanks of our forces. Sgt. Sadowski immediately ordered his crew to dismount and take cover in the adjoining buildings. After his crew had dismounted, Sgt. Sadowski discovered that 1 member of the crew, the bow gunner, had been unable to leave the tank. …", "facts": [["Recipient", "Joseph J. Sadowski"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Valhey, France"], ["Awarded", "Posthumously"]], "wiki": {"Joseph J. Sadowski": "Joseph_J._Sadowski"}},
  {"id": "1944-09-14-keathley-george-d", "date": "1944-09-14", "title": "Staff Sergeant George D. Keathley", "type": "loss", "theater": "Army", "location": {"name": "Mt. Altuzzo, Italy (approx.)", "lat": 44.08, "lng": 11.38}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty, in action on the western ridge of Mount Altuzzo, Italy. After bitter fighting his company had advanced to within 50 yards of the objective, where it was held up due to intense enemy sniper, automatic, small arms, and mortar fire. The enemy launched 3 desperate counterattacks in an effort to regain their former positions, but all 3 were repulsed with heavy casualties on both sides. All officers and noncommissioned officers of the 2d and 3d platoons of Company B had become casualties, and S/Sgt. Keathley, guide of the 1st platoon, moved up and assumed command of both the 2d and 3d platoons, reduced to 20 men. The remnants of the 2 platoons were dangerously low on ammunition, so S/Sgt. Keathley, under deadly small arms and mortar fire, crawled from 1 casualty to another, collecting their ammunition and administering first aid. …", "facts": [["Recipient", "George D. Keathley"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Mt. Altuzzo, Italy"], ["Awarded", "Posthumously"]], "wiki": {"George D. Keathley": "George_D._Keathley"}},
  {"id": "1944-09-15-bausell-lewis-k", "date": "1944-09-15", "title": "Corporal Lewis K. Bausell", "type": "loss", "theater": "Marine Corps", "location": {"name": "Peleliu Island, Palau Group", "lat": 7, "lng": 134.25}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the First Battalion, Fifth Marines, First Marine Division, during action against enemy Japanese forces on Peleliu Island, Palau Group, September 15, 1944. Valiantly placing himself at the head of his squad, Corporal Bausell led the charge forward against a hostile pillbox which was covering a vital sector of the beach and, as the first to reach the emplacement, immediately started firing his automatic into the aperture while the remainder of his men closed in on the enemy. Swift to act as a Japanese grenade was hurled into their midst, Corporal Bausell threw himself on the deadly weapon, taking the full blast of the explosion and sacrificing his own life to save his men. His unwavering loyalty and inspiring courage reflect the highest credit upon Corporal Bausell and the United States Naval Service. He gallantly gave his life for his country.", "facts": [["Recipient", "Lewis K. Bausell"], ["Rank", "Corporal"], ["Service", "Marine Corps"], ["Place of action", "Peleliu Island, Palau Group"], ["Awarded", "Posthumously"]], "wiki": {"Lewis K. Bausell": "Lewis_K._Bausell"}},
  {"id": "1944-09-15-rouh-carlton-r", "date": "1944-09-15", "title": "First Lieutenant Carlton R. Rouh", "type": "attack", "theater": "Marine Corps", "location": {"name": "Peleliu Island, Palau Group", "lat": 7, "lng": 134.25}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while attached to the First Battalion, Fifth Marines, First Marine Division, during action against enemy Japanese forces on Peleliu Island, Palau Group, 15 September 1944. Before permitting his men to use an enemy dugout as a position for an 81-mm. mortar observation post, First Lieutenant Rouh made a personal reconnaissance of the pillbox and, upon entering, was severely wounded by Japanese rifle fire from within. Emerging from the dugout, he was immediately assisted by two Marines to a less exposed area, but while receiving first aid, was further endangered by an enemy grenade which was thrown into their midst. Quick to act in spite of his weakened condition, he lurched to a crouching position and thrust both men aside, placing his own body between them and the grenade and taking the full blast of the explosion himself. …", "facts": [["Recipient", "Carlton R. Rouh"], ["Rank", "First Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Peleliu Island, Palau Group"]], "wiki": {"Carlton R. Rouh": "Carlton_R._Rouh"}},
  {"id": "1944-09-16-preston-arthur-m", "date": "1944-09-16", "title": "Lieutenant Arthur M. Preston", "type": "attack", "theater": "Navy", "location": {"name": "Wasile Bay, Halmahera Island", "lat": 0.65, "lng": 127.9}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as commander, Motor Torpedo Boat Squadron 33, while effecting the rescue of a Navy pilot shot down in Wasile Bay, Halmahera Island, less than 200 yards from a strongly defended Japanese dock and supply area, September 16, 1944. Volunteering for a perilous mission unsuccessfully attempted by the pilot's squadron mates and a PBY plane, Lt. Comdr. (then Lieutenant) Preston led PT-489 and PT-363 through 60 miles of restricted, heavily mined waters. Twice turned back while running the gauntlet of fire from powerful coastal defense guns guarding the 11-mile strait at the entrance to the bay, he was again turned back by furious fire in the immediate area of the downed airman. Aided by an aircraft smoke screen, he finally succeeded in reaching his objective and, under vicious fire delivered at 150-yard range, took the pilot aboard and cleared the area, sinking a small hostile cargo vessel with 40-mm. fire during retirement. …", "facts": [["Recipient", "Arthur M. Preston"], ["Rank", "Lieutenant"], ["Service", "Navy"], ["Place of action", "Wasile Bay, Halmahera Island"]], "wiki": {"Arthur M. Preston": "Arthur_Murray_Preston"}},
  {"id": "1944-09-16-johnson-oscar-g", "date": "1944-09-16", "title": "Private First Class Oscar G. Johnson", "type": "attack", "theater": "Navy", "location": {"name": "Near Scarperia, Italy (approx.)", "lat": 43.99, "lng": 11.36}, "zoom": 9, "summary": "He practically single-handed protected the left flank of his company's position in the offensive to break the German's gothic line. Company B was the extreme left assault unit of the corps. The advance was stopped by heavy fire from Monticelli Ridge, and the company took cover behind an embankment. Sgt. Johnson, a mortar gunner, having expended his ammunition, assumed the duties of a rifleman. As leader of a squad of 7 men he was ordered to establish a combat post 50 yards to the left of the company to cover its exposed flank. Repeated enemy counterattacks, supported by artillery, mortar, and machinegun fire from the high ground to his front, had by the afternoon of 16 September killed or wounded all his men. Collecting weapons and ammunition from his fallen comrades, in the face of hostile fire, he held his exposed position and inflicted heavy casualties upon the enemy, who several times came close enough to throw hand grenades. …", "facts": [["Recipient", "Oscar G. Johnson"], ["Rank", "Private First Class"], ["Service", "Navy"], ["Place of action", "Near Scarperia, Italy"]], "wiki": {"Oscar G. Johnson": "Oscar_G._Johnson"}},
  {"id": "1944-09-17-schwab-donald-k", "date": "1944-09-17", "title": "First Lieutenant Donald K. Schwab", "type": "loss", "theater": "Army", "location": {"name": "Near Lure, Haute-Saône, France (approx.)", "lat": 47.68, "lng": 6.5}, "zoom": 9, "summary": "First Lieutenant Donald K. Schwab distinguished himself by acts of gallantry and intrepidity above and beyond the call of duty while serving as the Commander of Company E, 15th Infantry Regiment, 3d Infantry Division, during combat operations against an armed enemy near Lure, France on September 17, 1944. That afternoon, as First Lieutenant Schwab led his company across four hundred yards of exposed ground, an intense, grazing burst of machinegun and machine-pistol fire sprung forth without warning from a fringe of woods directly in front of the American force. First Lieutenant Schwab quickly extricated his men from the attempted ambush and led them back to a defiladed position. Soon after, he was ordered to overwhelm the enemy line. He rapidly organized his men into a skirmish line and, with indomitable courage, again led them forward into the lethal enemy fire. When halted a second time, First Lieutenant Schwab moved from man to man to supervise collection of the wounded and organize his company’s withdrawal. …", "facts": [["Recipient", "Donald K. Schwab"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Lure, Haute-Saône, France"], ["Awarded", "Posthumously"]], "wiki": {"Donald K. Schwab": "Donald_K._Schwab"}},
  {"id": "1944-09-17-messerschmidt-harold-o", "date": "1944-09-17", "title": "Sergeant Harold O. Messerschmidt", "type": "loss", "theater": "Army", "location": {"name": "Near Radden, France (approx.)", "lat": 48.7, "lng": 6.6}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity above and beyond the call of duty. Braving machinegun, machine pistol, and rifle fire, he moved fearlessly and calmly from man to man along his 40-yard squad front, encouraging each to hold against the overwhelming assault of a fanatical foe surging up the hillside. Knocked to the ground by a burst from an enemy automatic weapon, he immediately jumped to his feet, and ignoring his grave wounds, fired his submachine gun at the enemy that was now upon them, killing 5 and wounding many others before his ammunition was spent. Virtually surrounded by a frenzied foe and all of his squad now casualties, he elected to fight alone, using his empty submachine gun as a bludgeon against his assailants. Spotting 1 of the enemy about to kill a wounded comrade, he felled the German with a blow of his weapon. …", "facts": [["Recipient", "Harold O. Messerschmidt"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Radden, France"], ["Awarded", "Posthumously"]], "wiki": {"Harold O. Messerschmidt": "Harold_O._Messerschmidt"}},
  {"id": "1944-09-18-jackson-arthur-j", "date": "1944-09-18", "title": "Private First Class Arthur J. Jackson", "type": "attack", "theater": "Marine Corps", "location": {"name": "Peleliu Island, Palau Group", "lat": 7, "lng": 134.25}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the Third Battalion, Seventh Marines, First Marine Division, in action against enemy Japanese forces on the Island of Peleliu in the Palau Group, September 18, 1944. Boldly taking the initiative when his platoon's left flank advance was held up by the fire of Japanese troops concealed in strongly fortified positions, Private First Class Jackson unhesitatingly proceeded forward of our lines and, courageously defying the heavy barrages, charged a large pillbox housing approximately thirty-five enemy soldiers. Pouring his automatic fire into the opening of the fixed installation to trap the occupying troops, he hurled white phosphorus grenades and explosive charges brought up by a fellow Marine, demolishing the pillbox and killing all of the enemy. Advancing alone under the continuous fire from other hostile emplacements, he employed a similar means to smash two smaller positions in the immediate vicinity. …", "facts": [["Recipient", "Arthur J. Jackson"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Peleliu Island, Palau Group"]], "wiki": {"Arthur J. Jackson": "Arthur_J._Jackson"}},
  {"id": "1944-09-18-roan-charles-h", "date": "1944-09-18", "title": "Private First Class Charles H. Roan", "type": "loss", "theater": "Marine Corps", "location": {"name": "Peleliu Island, Palau Group", "lat": 7, "lng": 134.25}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the Second Battalion, Seventh Marines, First Marine Division, in action against enemy Japanese Forces on Peleliu, Palau Islands, 18 September 1944. Shortly after his leader ordered a withdrawal upon discovering that the squad was partly cut off from their company as a result of their rapid advance along an exposed ridge during an aggressive attack on the strongly entrenched enemy, Private First Class Roan and his companions were suddenly engaged in a furious exchange of hand grenades with Japanese forces emplaced in a cave on higher ground and the rear of the squad. …", "facts": [["Recipient", "Charles H. Roan"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Peleliu Island, Palau Group"], ["Awarded", "Posthumously"]], "wiki": {"Charles H. Roan": "Charles_H._Roan"}},
  {"id": "1944-09-18-mann-joe-e", "date": "1944-09-18", "title": "Private First Class Joe E. Mann", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Best, Holland (approx.)", "lat": 51.51, "lng": 5.39}, "zoom": 9, "summary": "He distinguished himself by conspicuous gallantry above and beyond the call of duty. On 18 September 1944, in the vicinity of Best, Holland [sic], his platoon, attempting to seize the bridge across the Wilhelmina Canal, was surrounded and isolated by an enemy force greatly superior in personnel and firepower. Acting as lead scout, Pfc. Mann boldly crept to within rocket-launcher range of an enemy artillery position and, in the face of heavy enemy fire, destroyed an 88mm gun and an ammunition dump. Completely disregarding the great danger involved, he remained in his exposed position, and, with his M-1 rifle, killed the enemy one by one until he was wounded 4 times. Taken to a covered position, he insisted on returning to a forward position to stand guard during the night. On the following morning the enemy launched a concerted attack and advanced to within a few yards of the position, throwing hand grenades as they approached. One of these landed within a few feet of Pfc. Joe E. Mann. …", "facts": [["Recipient", "Joe E. Mann"], ["Rank", "Private First Class"], ["Service", "Army Air Forces"], ["Place of action", "Best, Holland"], ["Awarded", "Posthumously"]], "wiki": {"Joe E. Mann": "Joe_E._Mann"}},
  {"id": "1944-09-19-pope-everett-p", "date": "1944-09-19", "title": "Captain Everett P. Pope", "type": "attack", "theater": "Marine Corps", "location": {"name": "Peleliu Island, Palau Group", "lat": 7, "lng": 134.25}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving as Commanding Officer of Company C, First Battalion, First Marines, First Marine Division, during action against enemy Japanese forces on Peleliu Island, Palau Group, on 19–20 September 1944. Subjected to point-blank cannon fire which caused heavy casualties and badly disorganized his company while assaulting a steep coral hill, Captain Pope rallied his men and gallantly led them to the summit in the face of machine-gun, mortar, and sniper fire. Forced by widespread hostile attack to deploy the remnants of his company thinly in order to hold the ground won, and with his machine-guns out of action and insufficient water and ammunition, he remained on the exposed hill with twelve men and one wounded officer, determined to hold through the night. …", "facts": [["Recipient", "Everett P. Pope"], ["Rank", "Captain"], ["Service", "Marine Corps"], ["Place of action", "Peleliu Island, Palau Group"]], "wiki": {"Everett P. Pope": "Everett_P._Pope"}},
  {"id": "1944-09-21-towle-john-r", "date": "1944-09-21", "title": "Private John R. Towle", "type": "loss", "theater": "Army", "location": {"name": "Near Oosterhout, Holland", "lat": 51.6333, "lng": 4.8667}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of life above and beyond the call of duty on 21 September 1944, near Oosterhout, Holland. The rifle company in which Pvt. Towle served as rocket launcher gunner was occupying a defensive position in the west sector of the recently established Nijmegen bridgehead when a strong enemy force of approximately 100 infantry supported by two tanks and a half-track formed a counterattack. With full knowledge of the disastrous consequences resulting not only to his company but to the entire bridgehead by an enemy breakthrough, Pvt. Towle immediately and without orders left his foxhole and moved 200 yards in the face of intense small-arms fire to a position on an exposed dike roadbed. From this precarious position Pvt. Towle fired his rocket launcher at and hit both tanks to his immediate front. Armored skirting on both tanks prevented penetration by the projectiles, but both vehicles withdrew slightly damaged. Still under intense fire and fully exposed to the enemy, Pvt. …", "facts": [["Recipient", "John R. Towle"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Oosterhout, Holland"], ["Awarded", "Posthumously"]], "wiki": {"John R. Towle": "John_R._Towle"}},
  {"id": "1944-09-22-bloch-orville-e", "date": "1944-09-22", "title": "First Lieutenant Orville E. Bloch", "type": "attack", "theater": "Army", "location": {"name": "Near Firenzuola, Italy", "lat": 44.1167, "lng": 11.3833}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. 1st Lt. Bloch undertook the task of wiping out 5 enemy machinegun nests that had held up the advance in that particular sector for 1 day. Gathering 3 volunteers from his platoon, the patrol snaked their way to a big rock, behind which a group of 3 buildings and 5 machinegun nests were located. Leaving the 3 men behind the rock, he attacked the first machinegun nest alone charging into furious automatic fire, kicking over the machinegun, and capturing the machinegun crew of 5. Pulling the pin from a grenade, he held it ready in his hand and dashed into the face of withering automatic fire toward this second enemy machinegun nest located at the corner of an adjacent building 15 yards distant. When within 20 feet of the machinegun he hurled the grenade, wounding the machinegunner, the other 2 members of the crew fleeing into a door of the house. …", "facts": [["Recipient", "Orville E. Bloch"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Firenzuola, Italy"]], "wiki": {"Orville E. Bloch": "Orville_Emil_Bloch"}},
  {"id": "1944-09-24-schaefer-joseph-e", "date": "1944-09-24", "title": "Staff Sergeant Joseph E. Schaefer", "type": "attack", "theater": "Army", "location": {"name": "Near Stolberg, Germany (approx.)", "lat": 50.77, "lng": 6.23}, "zoom": 9, "summary": "He was in charge of a squad of the 2d Platoon in the vicinity of Stolberg, Germany, early in the morning of 24 September 1944, when 2 enemy companies supported by machineguns launched an attack to seize control of an important crossroads which was defended by his platoon. One American squad was forced back, another captured, leaving only SSG Schaefer's men to defend the position. To shift his squad into a house which would afford better protection, he crawled about under heavy small-arms and machinegun fire, instructed each individual, and moved to the building. A heavy concentration of enemy artillery fire scored hits on his strong point. S/Sgt. Schaefer assigned his men to positions and selected for himself the most dangerous one at the door. With his M1 rifle, he broke the first wave of infantry thrown toward the house. The Germans attacked again with grenades and flame throwers but were thrown back a second time, S/Sgt. Schaefer killing and wounding several. …", "facts": [["Recipient", "Joseph E. Schaefer"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Stolberg, Germany"]], "wiki": {"Joseph E. Schaefer": "Joseph_E._Schaefer"}},
  {"id": "1944-09-25-new-john-d", "date": "1944-09-25", "title": "Private First Class John D. New", "type": "loss", "theater": "Marine Corps", "location": {"name": "Peleliu Island, Palau Group", "lat": 7, "lng": 134.25}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his own life above and beyond the call of duty while serving with the Second Battalion, Seventh Marines, First Marine Division, in action against enemy Japanese forces on Peleliu Island, Palau Group, 25 September 1944. When a Japanese soldier emerged from a cave in a cliff directly below an observation post and suddenly hurled a grenade into the position from which two of our men were directing mortar fire against enemy emplacements, Private First Class New instantly perceived the dire peril to the other Marines and, with utter disregard for his own safety, unhesitatingly flung himself upon the grenade and absorbed the full impact of the explosion, thus saving the lives of the two observers. Private First Class New's great personal valor and selfless conduct in the face of almost certain death reflect the highest credit upon himself and the United States Naval Service. He gallantly gave his life for his country.", "facts": [["Recipient", "John D. New"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Peleliu Island, Palau Group"], ["Awarded", "Posthumously"]], "wiki": {"John D. New": "John_D._New"}},
  {"id": "1944-09-27-roeder-robert-e", "date": "1944-09-27", "title": "Captain Robert E. Roeder", "type": "loss", "theater": "Army", "location": {"name": "Mt. Battaglia, Italy (approx.)", "lat": 44.22, "lng": 11.62}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. Capt. Roeder commanded his company in defense of the strategic Mount Battaglia. Shortly after the company had occupied the hill, the Germans launched the first of a series of determined counterattacks to regain this dominating height. Completely exposed to ceaseless enemy artillery and small-arms fire, Capt. Roeder constantly circulated among his men, encouraging them and directing their defense against the persistent enemy. During the sixth counterattack, the enemy, by using flamethrowers and taking advantage of the fog, succeeded in overrunning the position. Capt. Roeder led his men in a fierce battle at close quarters, to repulse the attack with heavy losses to the Germans. The following morning, while the company was engaged in repulsing an enemy counterattack in force, Capt. Roeder was seriously wounded and rendered unconscious by shell fragments. He was carried to the company command post, where he regained consciousness. Refusing medical treatment, he insisted on rejoining his men. …", "facts": [["Recipient", "Robert E. Roeder"], ["Rank", "Captain"], ["Service", "Army"], ["Place of action", "Mt. Battaglia, Italy"], ["Awarded", "Posthumously, G.O. No. 31, 17 April 1945"]], "wiki": {"Robert E. Roeder": "Robert_E._Roeder"}},
  {"id": "1944-09-27-fields-james-h", "date": "1944-09-27", "title": "First Lieutenant James H. Fields", "type": "attack", "theater": "Army", "location": {"name": "Rechicourt, France (approx.)", "lat": 48.68, "lng": 6.84}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty, at Rechicourt, France. On September 27, 1944, during a sharp action with the enemy infantry and tank forces, 1st Lt. Fields personally led his platoon in a counterattack on the enemy position. Although his platoon had been seriously depleted, the zeal and fervor of his leadership was such as to inspire his small force to accomplish their mission in the face of overwhelming enemy opposition. Seeing that one of the men had been wounded, he left his slit trench and with complete disregard for his personal safety attended the wounded man and administered first aid. While returning to his slit trench he was seriously wounded by a shell burst, the fragments of which cut through his face and head, tearing his teeth, gums, and nasal passage. Although rendered speechless by his wounds, 1st Lt. Fields refused to be evacuated and continued to lead his platoon by the use of hand signals. …", "facts": [["Recipient", "James H. Fields"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Rechicourt, France"]], "wiki": {"James H. Fields": "James_H._Fields"}},
  {"id": "1944-10-01-carr-chris", "date": "1944-10-01", "title": "Sergeant Chris Carr", "type": "attack", "theater": "Army", "location": {"name": "Near Guignola, Italy (approx.)", "lat": 44.15, "lng": 11.4}, "zoom": 9, "summary": "Leading a squad of Company L, he gallantly cleared the way for his company's approach along a ridge toward its objective, the Casoni di Romagna. When his platoon was pinned down by heavy fire from enemy mortars, machineguns, machine pistols, and rifles, he climbed in advance of his squad on a maneuver around the left flank to locate and eliminate the enemy gun positions. Undeterred by deadly fire that ricocheted off the barren rocky hillside, he crept to the rear of the first machinegun and charged, firing his submachinegun. In this surprise attack he captured 8 prisoners and turned them over to his squad before striking out alone for a second machinegun. Discovered in his advance and subjected to direct fire from the hostile weapon, he leaped to his feet and ran forward, weaving and crouching, pouring automatic fire into the emplacement that killed 4 of its defenders and forced the surrender of a lone survivor. He again moved forward through heavy fire to attack a third machinegun. …", "facts": [["Recipient", "Chris Carr"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Guignola, Italy"]], "wiki": {"Chris Carr": "Chris_Carr_(Medal_of_Honor)"}},
  {"id": "1944-10-02-kiner-harold-g", "date": "1944-10-02", "title": "Private Harold G. Kiner", "type": "loss", "theater": "Army", "location": {"name": "Near Palenberg, Germany", "lat": 50.9197, "lng": 6.1194}, "zoom": 9, "summary": "With 4 other men, he was leading in a frontal assault 2 October 1944, on a Siegfried Line pillbox near Palenberg, Germany. Machinegun fire from the strongly defended enemy position 25 yards away pinned down the attackers. The Germans threw hand grenades, 1 of which dropped between Pvt. Kiner and 2 other men. With no hesitation, Private Kiner hurled himself upon the grenade, smothering the explosion. By his gallant action and voluntary sacrifice of his own life, he saved his 2 comrades from serious injury or death.", "facts": [["Recipient", "Harold G. Kiner"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Palenberg, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Harold G. Kiner": "Harold_G._Kiner"}},
  {"id": "1944-10-03-kraus-richard-e", "date": "1944-10-03", "title": "Private First Class Richard E. Kraus", "type": "loss", "theater": "Marine Corps", "location": {"name": "Peleliu Island, Palau Group", "lat": 7, "lng": 134.25}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the Eighth Amphibian Tractor Battalion, Third Amphibious Corps, Fleet Marine Force, in action against enemy Japanese forces on Peleliu, Palau Islands, on 5 October 1944. Unhesitatingly volunteering for the extremely hazardous mission of evacuating a wounded comrade from the front lines, Private First Class Kraus and three companions courageously made their way forward and successfully penetrated the lines for some distance before the enemy opened with an intense, devastating barrage of hand grenades which forced the stretcher party to take cover and subsequently abandon the mission. While returning to the rear, they observed two men approaching who appeared to be Marines and immediately demanded the password. …", "facts": [["Recipient", "Richard E. Kraus"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Peleliu Island, Palau Group"], ["Awarded", "Posthumously"]], "wiki": {"Richard E. Kraus": "Richard_E._Kraus"}},
  {"id": "1944-10-04-mendoza-manuel-v", "date": "1944-10-04", "title": "Master Sergeant Manuel V. Mendoza", "type": "attack", "theater": "Army", "location": {"name": "Mt. Battaglia, Italy (approx.)", "lat": 44.22, "lng": 11.62}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty: Staff Sergeant Manuel V. Mendoza distinguished himself by acts of gallantry and intrepidity above and beyond the call of duty while serving as a Platoon Sergeant with Company B, 350th Infantry, 88th Infantry Division during combat operations against an armed enemy on Mt. Battaglia, Italy on October 4, 1944. That afternoon, the enemy launched a violent counterattack preceded by a heavy mortar barrage. Staff Sergeant Mendoza, already wounded in the arm and leg, grabbed a Thompson sub-machinegun and ran to the crest of the hill where he saw approximately 200 enemy troops charging up the slopes employing flame-throwers, machine pistols, rifles, and hand grenades. Staff Sergeant Mendoza immediately began to engage the enemy, firing five clips and killing ten enemy soldiers. After exhausting his ammunition, he picked up a carbine and emptied its magazine at the enemy. …", "facts": [["Recipient", "Manuel V. Mendoza"], ["Rank", "Master Sergeant"], ["Service", "Army"], ["Place of action", "Mt. Battaglia, Italy"]], "wiki": {"Manuel V. Mendoza": "Manuel_V._Mendoza"}},
  {"id": "1944-10-04-phelps-wesley", "date": "1944-10-04", "title": "Private First Class Wesley Phelps", "type": "loss", "theater": "Marine Corps", "location": {"name": "Peleliu Island, Palau Group", "lat": 7, "lng": 134.25}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the Third Battalion, Seventh Marines, First Marine Division, in action against enemy Japanese forces on Peleliu Island, Palau Group, during a savage hostile counterattack on the night of October 4, 1944. Stationed with another Marine in an advanced position when a Japanese hand grenade landed in his foxhole, Private First Class Phelps instantly shouted a warning to his comrade and rolled over on the deadly bomb, absorbing with his own Body the full, shattering impact of the exploding charge. Courageous and indomitable, Private First Class Phelps fearlessly gave his life that another might be spared serious injury and his great valor and heroic devotion to duty in the face of certain death reflected the highest credit upon himself and the United States Naval Service. He gallantly gave his life for his country.", "facts": [["Recipient", "Wesley Phelps"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Peleliu Island, Palau Group"], ["Awarded", "Posthumously"]], "wiki": {"Wesley Phelps": "Wesley_Phelps"}},
  {"id": "1944-10-07-harris-james-l", "date": "1944-10-07", "title": "Second Lieutenant James L. Harris", "type": "loss", "theater": "Army", "location": {"name": "Vagney, France", "lat": 48.0092, "lng": 6.7172}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty on 7 October 1944, in Vagney, France. At 9 p.m. an enemy raiding party, comprising a tank and 2 platoons of infantry, infiltrated through the lines under cover of mist and darkness and attacked an infantry battalion command post with hand grenades, retiring a short distance to an ambush position on hearing the approach of the M-4 tank commanded by 2d Lt. Harris. Realizing the need for bold aggressive action, 2d Lt. Harris ordered his tank to halt while he proceeded on foot, fully 10 yards ahead of his 6-man patrol and armed only with a service pistol, to probe the darkness for the enemy. Although struck down and mortally wounded by machinegun bullets which penetrated his solar plexus, he crawled back to his tank, leaving a trail of blood behind him, and, too weak to climb inside it, issued fire orders while lying on the road between the 2 contending armored vehicles. …", "facts": [["Recipient", "James L. Harris"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Vagney, France"], ["Awarded", "Posthumously"]], "wiki": {"James L. Harris": "James_L._Harris"}},
  {"id": "1944-10-08-brown-bobbie-e", "date": "1944-10-08", "title": "Captain Bobbie E. Brown", "type": "attack", "theater": "Army", "location": {"name": "Crucifix Hill, Aachen, Germany", "lat": 50.7993, "lng": 6.1394}, "zoom": 9, "summary": "He commanded Company C, 18th Infantry Regiment, on October 8, 1944, when it, with the Ranger Platoon of the 1st Battalion, attacked Crucifix Hill, a key point in the enemy's defense of Aachen, Germany. As the leading rifle platoon assaulted the first of many pillboxes studding the rising ground, heavy fire from a flanking emplacement raked it. An intense artillery barrage fell on the American troops which had been pinned down in an exposed position. Seeing that the pillboxes must be neutralized to prevent the slaughter of his men, Capt. Brown obtained a pole charge and started forward alone toward the first pillbox, about 100 yards away. Hugging the ground while enemy bullets whipped around him, he crawled and then ran toward the aperture of the fortification, rammed his explosive inside and jumped back as the pillbox and its occupants were blown up. He rejoined the assault platoon, secured another pole charge, and led the way toward the next pillbox under continuous artillery mortar, automatic, and small-arms fire. …", "facts": [["Recipient", "Bobbie E. Brown"], ["Rank", "Captain"], ["Service", "Army"], ["Place of action", "Crucifix Hill, Aachen, Germany"], ["Awarded", "G.O. No. 74, September 1, 1945"]], "wiki": {"Bobbie E. Brown": "Bobbie_E._Brown"}},
  {"id": "1944-10-09-kandle-victor-l", "date": "1944-10-09", "title": "First Lieutenant Victor L. Kandle", "type": "loss", "theater": "Army", "location": {"name": "Near La Forge, France (approx.)", "lat": 48.3, "lng": 6.7}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of his life above and beyond the call of duty. On 9 October 1944, at about noon, near La Forge, France, 1st Lt. Kandle, while leading a reconnaissance patrol into enemy territory, engaged in a duel at pointblank range with a German field officer and killed him. Having already taken 5 enemy prisoners that morning, he led a skeleton platoon of 16 men, reinforced with a light machinegun squad, through fog and over precipitous mountain terrain to fall on the rear of a German quarry stronghold which had checked the advance of an infantry battalion for 2 days. Rushing forward, several yards ahead of his assault elements, 1st Lt. Kandle fought his way into the heart of the enemy strongpoint, and, by his boldness and audacity, forced the Germans to surrender. …", "facts": [["Recipient", "Victor L. Kandle"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near La Forge, France"], ["Awarded", "Posthumously"]], "wiki": {"Victor L. Kandle": "Victor_L._Kandle"}},
  {"id": "1944-10-10-bong-richard-i", "date": "1944-10-10", "title": "Major Richard I. Bong", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Over Borneo and Leyte (approx.)", "lat": 8.0, "lng": 122.0}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity in action above and beyond the call of duty in the Southwest Pacific area from October 10, to November 15, 1944. Though assigned to duty as gunnery instructor and neither required nor expected to perform combat duty, Maj. Bong voluntarily and at his own urgent request engaged in repeated combat missions, including unusually hazardous sorties over Balikpapan, Borneo, and in the Leyte area of the Philippines. His aggressiveness and daring resulted in his shooting down 8 enemy airplanes during this period.", "facts": [["Recipient", "Richard I. Bong"], ["Rank", "Major"], ["Service", "Army Air Forces"], ["Place of action", "Over Borneo and Leyte"], ["Awarded", "G.O. No. 90, December 8, 1944"]], "wiki": {"Richard I. Bong": "Richard_Bong"}},
  {"id": "1944-10-12-pendleton-jack-j", "date": "1944-10-12", "title": "Staff Sergeant Jack J. Pendleton", "type": "loss", "theater": "Army", "location": {"name": "Bardenberg, Germany (approx.)", "lat": 50.84, "lng": 6.12}, "zoom": 9, "summary": "When his company was stopped by a German machine gun in Bardenberg, he led his squad against it. Badly wounded, he ordered his men to stay back and crawled on alone, drawing the gun’s fire so that another squad could move up and destroy it. He was killed by its fire.", "facts": [["Recipient", "Jack J. Pendleton"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Bardenberg, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Jack J. Pendleton": "Jack_J._Pendleton"}},
  {"id": "1944-10-13-burt-james-m", "date": "1944-10-13", "title": "Captain James M. Burt", "type": "attack", "theater": "Army", "location": {"name": "Near Wurselen, Germany", "lat": 50.8167, "lng": 6.1333}, "zoom": 9, "summary": "Capt. James M. Burt was in command of Company B, 66th Armored Regiment on the western outskirts of Wurselen, Germany, on 13 October 1944, when his organization participated in a coordinated infantry-tank attack destined to isolate the large German garrison which was tenaciously defending the city of Aachen. In the first day's action, when infantrymen ran into murderous small-arms and mortar fire, Capt. Burt dismounted from his tank about 200 yards to the rear and moved forward on foot beyond the infantry positions, where, as the enemy concentrated a tremendous volume of fire upon him, he calmly motioned his tanks into good firing positions. As our attack gained momentum, he climbed aboard his tank and directed the action from the rear deck, exposed to hostile volleys which finally wounded him painfully in the face and neck. …", "facts": [["Recipient", "James M. Burt"], ["Rank", "Captain"], ["Service", "Army"], ["Place of action", "Near Wurselen, Germany"], ["Awarded", "G.O. No. 95, October 30, 1945"]], "wiki": {"James M. Burt": "James_M._Burt"}},
  {"id": "1944-10-18-thompson-max", "date": "1944-10-18", "title": "Sergeant Max Thompson", "type": "attack", "theater": "Army", "location": {"name": "Near Haaren, Germany (approx.)", "lat": 50.8, "lng": 6.13}, "zoom": 9, "summary": "On 18 October 1944, Company K, 18th Infantry, occupying a position on a hill near Haaren, Germany, was attacked by an enemy infantry battalion supported by tanks. The assault was preceded by an artillery concentration, lasting an hour, which inflicted heavy casualties on the company. While engaged in moving wounded men to cover, Sgt. Thompson observed that the enemy had overrun the positions of the 3d Platoon. He immediately attempted to stem the enemy's advance single-handedly. He manned an abandoned machinegun and fired on the enemy until a direct hit from a hostile tank destroyed the gun. Shaken and dazed, Sgt. Thompson picked up an automatic rifle and although alone against the enemy force which was pouring into the gap in our lines, he fired burst after burst, halting the leading elements of the attack and dispersing those following. Throwing aside his automatic rifle, which had jammed, he took up a rocket gun, fired on a light tank, setting it on fire. …", "facts": [["Recipient", "Max Thompson"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Haaren, Germany"]], "wiki": {"Max Thompson": "Max_Thompson_(Medal_of_Honor)"}},
  {"id": "1944-10-19-hajiro-barney-f", "date": "1944-10-19", "title": "Private Barney F. Hajiro", "type": "attack", "theater": "Army", "location": {"name": "Near Bruyeres and Biffontaine, eastern France", "lat": 48.2083, "lng": 6.721}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of his life above and beyond the call of duty. Private Barney F. Hajiro distinguished himself by extraordinary heroism in action on 19, 22, and October 29, 1944, in the vicinity of Bruyeres and Biffontaine, eastern France. Private Hajiro, while acting as a sentry on top of an embankment on October 19, 1944, in the vicinity of Bruyeres, France, rendered assistance to allied troops attacking a house 200 yards away by exposing himself to enemy fire and directing fire at an enemy strong point. He assisted the unit on his right by firing his automatic rifle and killing or wounding two enemy snipers. On October 22, 1944, he and one comrade took up an outpost security position about 50 yards to the right front of their platoon, concealed themselves, and ambushed an 18-man, heavily armed, enemy patrol, killing two, wounding one, and taking the remainder as prisoners. …", "facts": [["Recipient", "Barney F. Hajiro"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Bruyeres and Biffontaine, eastern France"]], "wiki": {"Barney F. Hajiro": "Barney_F._Hajiro"}},
  {"id": "1944-10-20-wai-francis-b", "date": "1944-10-20", "title": "Captain Francis B. Wai", "type": "loss", "theater": "Army", "location": {"name": "Leyte, Philippines (approx.)", "lat": 11.0, "lng": 124.85}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity at risk of his life above and beyond the call of duty. Captain Francis B. Wai distinguished himself by extraordinary heroism in action, on 20 October 1944, in Leyte, Philippine Islands. Captain Wai landed at Red Beach, Leyte, in the face of accurate, concentrated enemy fire from gun positions advantageously located in a palm grove bounded by submerged rice paddies. Finding the first four waves of American soldiers leaderless, disorganized, and pinned down on the open beach, he immediately assumed command. Issuing clear and concise orders, and disregarding heavy enemy machine gun and rifle fire, he began to move inland through the rice paddies without cover. The men, inspired by his cool demeanor and heroic example, rose from their positions and followed him. During the advance, Captain Wai repeatedly determined the locations of enemy strong points by deliberately exposing himself to draw their fire. In leading an assault upon the last remaining Japanese pillbox in the area, he was killed by its occupants. …", "facts": [["Recipient", "Francis B. Wai"], ["Rank", "Captain"], ["Service", "Army"], ["Place of action", "Leyte, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Francis B. Wai": "Francis_B._Wai"}},
  {"id": "1944-10-20-kuroda-robert-t", "date": "1944-10-20", "title": "Staff Sergeant Robert T. Kuroda", "type": "loss", "theater": "Army", "location": {"name": "Near Bruyeres, France", "lat": 48.2083, "lng": 6.721}, "zoom": 9, "summary": "Staff Sergeant Robert T. Kuroda distinguished himself by extraordinary heroism in action, on 20 October 1944, near Bruyeres, France. Leading his men in an advance to destroy snipers and machine gun nests, Staff Sergeant Kuroda encountered heavy fire from enemy soldiers occupying a heavily wooded slope. Unable to pinpoint the hostile machine gun, he boldly made his way through heavy fire to the crest of the ridge. Once he located the machine gun, Staff Sergeant Kuroda advanced to a point within ten yards of the nest and killed three enemy gunners with grenades. He then fired clip after clip of rifle ammunition, killing or wounding at least three of the enemy. As he expended the last of his ammunition, he observed that an American officer had been struck by a burst of fire from a hostile machine gun located on an adjacent hill. Rushing to the officer's assistance, he found that the officer had been killed. …", "facts": [["Recipient", "Robert T. Kuroda"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Bruyeres, France"], ["Awarded", "Posthumously"]], "wiki": {"Robert T. Kuroda": "Robert_T._Kuroda"}},
  {"id": "1944-10-21-moon-jr-harold-h", "date": "1944-10-21", "title": "Private Harold H. Moon Jr.", "type": "loss", "theater": "Army", "location": {"name": "Pawig, Leyte, Philippines (approx.)", "lat": 11.1, "lng": 125.0}, "zoom": 9, "summary": "He fought with conspicuous gallantry and intrepidity when powerful Japanese counterblows were being struck in a desperate effort to annihilate a newly won beachhead. In a forward position, armed with a submachinegun, he met the brunt of a strong, well-supported night attack which quickly enveloped his platoon's flanks. Many men in nearby positions were killed or injured, and Pvt. Moon was wounded as his foxhole became the immediate object of a concentration of mortar and machinegun fire. Nevertheless, he maintained his stand, poured deadly fire into the enemy, daringly exposed himself to hostile fire time after time to exhort and inspire what American troops were left in the immediate area. A Japanese officer, covered by machinegun fire and hidden by an embankment, attempted to knock out his position with grenades, but Pvt. Moon, after protracted and skillful maneuvering, killed him. …", "facts": [["Recipient", "Harold H. Moon Jr."], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Pawig, Leyte, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Harold H. Moon Jr.": "Harold_H._Moon_Jr."}},
  {"id": "1944-10-23-o-kane-richard-h", "date": "1944-10-23", "title": "Commander Richard H. O'Kane", "type": "attack", "theater": "Navy", "location": {"name": "Philippines (approx.)", "lat": 12.0, "lng": 122.5}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as commanding officer of the U.S.S. Tang operating against 2 enemy Japanese convoys on 23 October and 24 October 1944, during her fifth and last war patrol. Boldly maneuvering on the surface into the midst of a heavily escorted convoy, CMDR O'Kane stood in the fusillade of bullets and shells from all directions to launch smashing hits on 3 tankers, coolly swung his ship to fire at a freighter and, in a split-second decision, shot out of the path of an onrushing transport, missing it by inches. Boxed in by blazing tankers, a freighter, transport, and several destroyers, he blasted 2 of the targets with his remaining torpedoes and, with pyrotechnics bursting on all sides, cleared the area. Twenty-four hours later, he again made contact with a heavily escorted convoy steaming to support the Leyte campaign with reinforcements and supplies and with crated planes piled high on each unit. …", "facts": [["Recipient", "Richard H. O'Kane"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "Philippines"]], "wiki": {"Richard H. O'Kane": "Richard_O'Kane"}},
  {"id": "1944-10-24-coolidge-charles-h", "date": "1944-10-24", "title": "Technical Sergeant Charles H. Coolidge", "type": "attack", "theater": "Army", "location": {"name": "East of Belmont sur Buttant, France (approx.)", "lat": 48.2, "lng": 6.8}, "zoom": 9, "summary": "On October 24, 1944, Coolidge was a technical sergeant in charge of a group of machine-gunners and riflemen of M Company, who were to hold a vital hilltop position in France near the German border. During four days of attacks at Hill 623, east of Belmont-sur-Buttant in the Vosges Mountains in France, Coolidge and his group held off numerous enemy infantrymen, plus two tanks on October 27 using grenades. One tank unsuccessfully fired five separate rounds directly at Coolidge. For his actions above and beyond the call of duty during the battle, Coolidge was presented the Medal of Honor by Lieutenant General Wade H. Haislip during a ceremony at an airfield near Dornstadt, Germany on June 18, 1945.", "facts": [["Recipient", "Charles H. Coolidge"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "East of Belmont sur Buttant, France"], ["Awarded", "G.O. No. 53, July 1945"]], "wiki": {"Charles H. Coolidge": "Charles_H._Coolidge"}},
  {"id": "1944-10-25-evans-ernest-e", "date": "1944-10-25", "title": "Commander Ernest E. Evans", "type": "loss", "theater": "Navy", "location": {"name": "USS Johnston, off Samar", "lat": 12, "lng": 125}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as commanding officer of the U.S.S. Johnston in action against major units of the enemy Japanese fleet during the battle off Samar on 25 October 1944. The first to lay a smokescreen and to open fire as an enemy task force, vastly superior in number, firepower and armor, rapidly approached. Comdr. Evans gallantly diverted the powerful blasts of hostile guns from the lightly armed and armored carriers under his protection, launching the first torpedo attack when the Johnston came under straddling Japanese shellfire. …", "facts": [["Recipient", "Ernest E. Evans"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "USS Johnston, off Samar"], ["Awarded", "Posthumously"]], "wiki": {"Ernest E. Evans": "Ernest_E._Evans"}},
  {"id": "1944-10-25-choate-clyde-l", "date": "1944-10-25", "title": "Staff Sergeant Clyde L. Choate", "type": "attack", "theater": "Army", "location": {"name": "Near Bruyeres, France", "lat": 48.2083, "lng": 6.721}, "zoom": 9, "summary": "He commanded a tank destroyer near Bruyeres, France, on October 25, 1944. Our infantry occupied a position on a wooded hill when, at dusk, an enemy Mark IV tank and a company of infantry attacked, threatening to overrun the American position and capture a command post 400 yards to the rear. S/Sgt. Choate's tank destroyer, the only weapon available to oppose the German armor, was set afire by 2 hits. Ordering his men to abandon the destroyer, S/Sgt. Choate reached comparative safety. He returned to the burning destroyer to search for comrades possibly trapped in the vehicle risking instant death in an explosion which was imminent and braving enemy fire which ripped his jacket and tore the helmet from his head. Completing the search and seeing the tank and its supporting infantry overrunning our infantry in their shallow foxholes, he secured a bazooka and ran after the tank, dodging from tree to tree and passing through the enemy's loose skirmish line. …", "facts": [["Recipient", "Clyde L. Choate"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Bruyeres, France"]], "wiki": {"Clyde L. Choate": "Clyde_L._Choate"}},
  {"id": "1944-10-26-carswell-jr-horace-s", "date": "1944-10-26", "title": "Major Horace S. Carswell Jr.", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Over the South China Sea (approx.)", "lat": 12, "lng": 113}, "zoom": 6, "summary": "He piloted a B-24 bomber in a one-plane strike against a Japanese convoy in the South China Sea on the night of 26 October 1944. Taking the enemy force of 12 ships escorted by at least 2 destroyers by surprise, he made 1 bombing run at 600 feet, scoring a near miss on 1 warship and escaping without drawing fire. He circled. and fully realizing that the convoy was thoroughly alerted and would meet his next attack with a barrage of antiaircraft fire, began a second low-level run which culminated in 2 direct hits on a large tanker. A hail of steel from Japanese guns, riddled the bomber, knocking out 2 engines, damaging a third, crippling the hydraulic system, puncturing 1 gasoline tank, ripping uncounted holes in the aircraft, and wounding the copilot; but by magnificent display of flying skill, Major Carswell controlled the plane's plunge toward the sea and carefully forced it into a halting climb in the direction of the China shore. …", "facts": [["Recipient", "Horace S. Carswell Jr."], ["Rank", "Major"], ["Service", "Army Air Forces"], ["Place of action", "Over the South China Sea"], ["Awarded", "Posthumously, G.O. No. 14, February 4, 1946"]], "wiki": {"Horace S. Carswell Jr.": "Horace_S._Carswell_Jr."}},
  {"id": "1944-10-28-thorson-john-f", "date": "1944-10-28", "title": "Private First Class John F. Thorson", "type": "loss", "theater": "Army", "location": {"name": "Dagami, Leyte, Philippines", "lat": 11.0611, "lng": 124.9031}, "zoom": 9, "summary": "John F. Thorson (May 10, 1920 – October 28, 1944) was a United States Army infantry soldier who was killed in action on October 28, 1944, in World War II. He was a posthumous recipient of the United States military's highest decoration for valor—the Medal of Honor—for his heroic actions above and beyond the call of duty during the war.", "facts": [["Recipient", "John F. Thorson"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Dagami, Leyte, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"John F. Thorson": "John_F._Thorson"}},
  {"id": "1944-10-28-brostrom-leonard-c", "date": "1944-10-28", "title": "Private First Class Leonard C. Brostrom", "type": "loss", "theater": "Army", "location": {"name": "Near Dagami, Leyte, Philippines", "lat": 11.0611, "lng": 124.9031}, "zoom": 9, "summary": "Leonard C. Brostrom (November 23, 1919 – October 28, 1944) was a United States Army infantry soldier who was killed in action near Dagami, Leyte, Philippine Islands, now the Republic of the Philippines, during the Philippines Campaign of 1944–45, in World War II. He received the Medal of Honor posthumously for his heroic actions above and beyond the call of duty. Brostrom was a member of and served a mission for the Church of Jesus Christ of Latter-day Saints before he entered the Army.", "facts": [["Recipient", "Leonard C. Brostrom"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Dagami, Leyte, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Leonard C. Brostrom": "Leonard_C._Brostrom"}},
  {"id": "1944-10-28-adams-lucian", "date": "1944-10-28", "title": "Staff Sergeant Lucian Adams", "type": "attack", "theater": "Army", "location": {"name": "Near St. Dié, France (approx.)", "lat": 48.28, "lng": 6.95}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty on 28 October 1944, near St. Die, France. When his company was stopped in its effort to drive through the Mortagne Forest to reopen the supply line to the isolated third battalion, S/Sgt. Adams braved the concentrated fire of machineguns in a lone assault on a force of German troops. Although his company had progressed less than 10 yards and had lost 3 killed and 6 wounded, S/Sgt. Adams charged forward dodging from tree to tree firing a borrowed BAR from the hip. Despite intense machinegun fire which the enemy directed at him and rifle grenades which struck the trees over his head showering him with broken twigs and branches, S/Sgt. Adams made his way to within 10 yards of the closest machinegun and killed the gunner with a hand grenade. An enemy soldier threw hand grenades at him from a position only 10 yards distant; however, S/Sgt. …", "facts": [["Recipient", "Lucian Adams"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near St. Dié, France"]], "wiki": {"Lucian Adams": "Lucian_Adams"}},
  {"id": "1944-10-28-okubo-james-k", "date": "1944-10-28", "title": "Technician 5th Grade James K. Okubo", "type": "loss", "theater": "Army", "location": {"name": "Foret Domaniale de Champ, near Biffontaine, France", "lat": 48.2119, "lng": 6.805}, "zoom": 9, "summary": "Technician Fifth Grade James K. Okubo distinguished himself by extraordinary heroism in action on 28 and 29 October and 4 November 1944, in the Foret Domaniale de Champ, near Biffontaine, eastern France. On 28 October, under strong enemy fire coming from behind mine fields and roadblocks, Technician Fifth Grade Okubo, a medic, crawled 150 yards to within 40 yards of the enemy lines. Two grenades were thrown at him while he left his last covered position to carry back wounded comrades. Under constant barrages of enemy small arms and machine gun fire, he treated 17 men on 28 October and 8 more men on 29 October. On 4 November, Technician Fifth Grade Okubo ran 75 yards under grazing machine gun fire and, while exposed to hostile fire directed at him, evacuated and treated a seriously wounded crewman from a burning tank, who otherwise would have died. Technician Fifth Grade James K. …", "facts": [["Recipient", "James K. Okubo"], ["Rank", "Technician 5th Grade"], ["Service", "Army"], ["Place of action", "Foret Domaniale de Champ, near Biffontaine, France"], ["Awarded", "Posthumously"]], "wiki": {"James K. Okubo": "James_K._Okubo"}},
  {"id": "1944-10-29-sakato-george-t", "date": "1944-10-29", "title": "Private George T. Sakato", "type": "attack", "theater": "Army", "location": {"name": "Hill 617, near Biffontaine, France", "lat": 48.2119, "lng": 6.805}, "zoom": 9, "summary": "Private George T. Sakato distinguished himself by extraordinary heroism in action on 29 October 1944, on hill 617 in the vicinity of Biffontaine, France. After his platoon had virtually destroyed two enemy defense lines, during which he personally killed five enemy soldiers and captured four, his unit was pinned down by heavy enemy fire. Disregarding the enemy fire, Private Sakato made a one-man rush that encouraged his platoon to charge and destroy the enemy strongpoint. While his platoon was reorganizing, he proved to be the inspiration of his squad in halting a counter-attack on the left flank during which his squad leader was killed. Taking charge of the squad, he continued his relentless tactics, using an enemy rifle and P-38 pistol to stop an organized enemy attack. During this entire action, he killed 12 and wounded two, personally captured four and assisted his platoon in taking 34 prisoners. …", "facts": [["Recipient", "George T. Sakato"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Hill 617, near Biffontaine, France"]], "wiki": {"George T. Sakato": "George_T._Sakato"}},
  {"id": "1944-10-30-ross-wilburn-k", "date": "1944-10-30", "title": "Private Wilburn K. Ross", "type": "attack", "theater": "Army", "location": {"name": "Near St. Jacques, France (approx.)", "lat": 47.0, "lng": 2.5}, "zoom": 9, "summary": "Private Wilburn Kirby Ross, United States Army, for conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty while serving with Company G, 2d Battalion, 30th Infantry, 3d Infantry Division, in action near St. Jacques, France. At 11:30 a.m. on 30 October 1944, after his company had lost 55 out of 88 men in an attack on an entrenched, full-strength German company of elite mountain troops, Private Ross placed his light machinegun ten yards in advance of the foremost supporting riflemen in order to absorb the initial impact of an enemy counterattack. With machinegun and small-arms fire striking the earth near him, he fired with deadly effect on the assaulting force and repelled it. Despite the hail of automatic fire and the explosion of rifle grenades within a stone’s throw of his position, he continued to man his machine gun alone, holding off six more German attacks. When the eighth assault was launched, most of his supporting riflemen were out of ammunition. …", "facts": [["Recipient", "Wilburn K. Ross"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near St. Jacques, France"]], "wiki": {"Wilburn K. Ross": "Wilburn_K._Ross"}},
  {"id": "1944-11-02-bolton-cecil-h", "date": "1944-11-02", "title": "First Lieutenant Cecil H. Bolton", "type": "attack", "theater": "Army", "location": {"name": "Mark River, Holland", "lat": 51.6587, "lng": 4.3689}, "zoom": 9, "summary": "As leader of the weapons platoon of Company E, 413th Infantry, on the night of November 2, 1944, he fought gallantly in a pitched battle which followed the crossing of the Mark River in the Netherlands. When 2 machineguns pinned down his company, he tried to eliminate, with mortar fire, their grazing fire which was inflicting serious casualties and preventing the company's advance from an area rocked by artillery shelling. In the moonlight it was impossible for him to locate accurately the enemy's camouflaged positions; but he continued to direct fire until wounded severely in the legs and rendered unconscious by a German shell. When he recovered consciousness he instructed his unit and then crawled to the forward rifle platoon positions. Taking a two-man bazooka team on his voluntary mission, he advanced chest deep in chilling water along a canal toward 1 enemy machinegun. While the bazooka team covered him, he approached alone to within 15 yards of the hostile emplacement in a house. …", "facts": [["Recipient", "Cecil H. Bolton"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Mark River, Holland"]], "wiki": {"Cecil H. Bolton": "Cecil_H._Bolton"}},
  {"id": "1944-11-02-femoyer-robert-e", "date": "1944-11-02", "title": "Second Lieutenant Robert E. Femoyer", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Over Merseburg, Germany (approx.)", "lat": 51.3544, "lng": 11.9928}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty near Merseburg, Germany, on 2 November 1944. While on a mission, the bomber, of which 2d Lt. Femoyer was the navigator, was struck by 3 enemy antiaircraft shells. The plane suffered serious damage and 2d Lt. Femoyer was severely wounded in the side and back by shell fragments which penetrated his body. In spite of extreme pain and great loss of blood he refused an offered injection of morphine. He was determined to keep his mental faculties clear in order that he might direct his plane out of danger and so save his comrades. Not being able to arise from the floor, he asked to be propped up in order to enable him to see his charts and instruments. He successfully directed the navigation of his lone bomber for 2 1/2 hours so well it avoided enemy flak and returned to the field without further damage. …", "facts": [["Recipient", "Robert E. Femoyer"], ["Rank", "Second Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Over Merseburg, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Robert E. Femoyer": "Robert_Edward_Femoyer"}},
  {"id": "1944-11-03-mower-charles-e", "date": "1944-11-03", "title": "Sergeant Charles E. Mower", "type": "loss", "theater": "Army", "location": {"name": "Near Capoocan, Leyte, Philippines", "lat": 11.2944, "lng": 124.6419}, "zoom": 9, "summary": "He was an assistant squad leader in an attack against strongly defended enemy positions on both sides of a stream running through a wooded gulch. As the squad advanced through concentrated fire, the leader was killed and Sgt. Mower assumed command. In order to bring direct fire upon the enemy, he had started to lead his men across the stream, which by this time was churned by machinegun and rifle fire, but he was severely wounded before reaching the opposite bank. After signaling his unit to halt, he realized his own exposed position was the most advantageous point from which to direct the attack, and stood fast. Half submerged, gravely wounded, but refusing to seek shelter or accept aid of any kind, he continued to shout and signal to his squad as he directed it in the destruction of 2 enemy machineguns and numerous riflemen. …", "facts": [["Recipient", "Charles E. Mower"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Capoocan, Leyte, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Charles E. Mower": "Charles_E._Mower"}},
  {"id": "1944-11-04-leonard-turney-w", "date": "1944-11-04", "title": "First Lieutenant Turney W. Leonard", "type": "loss", "theater": "Army", "location": {"name": "Kommerscheidt, Germany (approx.)", "lat": 50.64, "lng": 6.41}, "zoom": 9, "summary": "He displayed extraordinary heroism while commanding a platoon of mobile weapons at Kommerscheidt, Germany, on 4, 5, and 6 November 1944. During the fierce 3-day engagement, he repeatedly braved overwhelming enemy fire in advance of his platoon to direct the fire of his tank destroyer from exposed, dismounted positions. He went on lone reconnaissance missions to discover what opposition his men faced, and on 1 occasion, when fired upon by a hostile machinegun, advanced alone and eliminated the enemy emplacement with a hand grenade. When a strong German attack threatened to overrun friendly positions, he moved through withering artillery, mortar, and small arms fire, reorganized confused infantry units whose leaders had become casualties, and exhorted them to hold firm. Although wounded early in battle, he continued to direct fire from his advanced position until he was disabled by a high-explosive shell which shattered his arm, forcing him to withdraw. He was last seen at a medical aid station which was subsequently captured by the enemy. …", "facts": [["Recipient", "Turney W. Leonard"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Kommerscheidt, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Turney W. Leonard": "Turney_W._Leonard"}},
  {"id": "1944-11-07-nishimoto-joe-m", "date": "1944-11-07", "title": "Private First Class Joe M. Nishimoto", "type": "loss", "theater": "Army", "location": {"name": "Near La Houssiere, France", "lat": 48.1961, "lng": 6.8542}, "zoom": 9, "summary": "Private First Class Joe M. Nishimoto distinguished himself by extraordinary heroism in action on 7 November 1944, near La Houssiere, France. After three days of unsuccessful attempts by his company to dislodge the enemy from a strongly defended ridge, Private First Class Nishimoto, as acting squad leader, boldly crawled forward through a heavily mined and booby-trapped area. Spotting a machine gun nest, he hurled a grenade and destroyed the emplacement. Then, circling to the rear of another machine gun position, he fired his submachine gun at point-blank range, killing one gunner and wounding another. Pursuing two enemy riflemen, Private First Class Nishimoto killed one, while the other hastily retreated. Continuing his determined assault, he drove another machine gun crew from its position. The enemy, with their key strong points taken, were forced to withdraw from this sector. Private First Class Nishimoto's extraordinary heroism and devotion to duty are in keeping with the highest traditions of military service and reflect great credit on him, his unit, and the United States Army.", "facts": [["Recipient", "Joe M. Nishimoto"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near La Houssiere, France"], ["Awarded", "Posthumously"]], "wiki": {"Joe M. Nishimoto": "Joe_M._Nishimoto"}},
  {"id": "1944-11-07-leonard-william-f", "date": "1944-11-07", "title": "Staff Sergeant William F. Leonard", "type": "attack", "theater": "Army", "location": {"name": "Near St. Die, France (approx.)", "lat": 48.28, "lng": 6.95}, "zoom": 9, "summary": "Private First Class William F. Leonard distinguished himself by acts of gallantry and intrepidity above and beyond the call of duty while serving as a Squad Leader in Company C, 30th Infantry Regiment, 3d Infantry Division during combat operations against an armed enemy near St. Die, France on November 7, 1944. Private First Class Leonard's platoon was reduced to eight men as a result of blistering artillery, mortar, machinegun, and rifle fire. Private First Class Leonard led the survivors in an assault over a hill covered by trees and shrubs which the enemy continuously swept with automatic weapons fire. Ignoring bullets which pierced his pack, Private First Class Leonard killed two snipers at ranges of fifty and seventy-five yards and engaged and destroyed a machinegun nest with grenades, killing its two-man crew. Though momentarily stunned by an exploding bazooka shell, Private First Class Leonard relentlessly advanced, ultimately knocking out a second machinegun nest and capturing the roadblock objective. …", "facts": [["Recipient", "William F. Leonard"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near St. Die, France"]], "wiki": {"William F. Leonard": "William_F._Leonard"}},
  {"id": "1944-11-08-wilson-alfred-l", "date": "1944-11-08", "title": "Technician 5th Grade Alfred L. Wilson", "type": "loss", "theater": "Army", "location": {"name": "Near Bezange la Petite, France (approx.)", "lat": 48.75, "lng": 6.48}, "zoom": 9, "summary": "He volunteered to assist as an aid man a company other than his own, which was suffering casualties from constant artillery fire. He administered to the wounded and returned to his own company when a shellburst injured a number of its men. While treating his comrades he was seriously wounded, but refused to be evacuated by litter bearers sent to relieve him. In spite of great pain and loss of blood, he continued to administer first aid until he was too weak to stand. Crawling from one patient to another, he continued his work until excessive loss of blood prevented him from moving. He then verbally directed unskilled enlisted men in continuing the first aid for the wounded. Still refusing assistance himself, he remained to instruct others in dressing the wounds of his comrades until he was unable to speak above a whisper and finally lapsed into unconsciousness. The effects of his injury later caused his death. …", "facts": [["Recipient", "Alfred L. Wilson"], ["Rank", "Technician 5th Grade"], ["Service", "Army"], ["Place of action", "Near Bezange la Petite, France"], ["Awarded", "Posthumously"]], "wiki": {"Alfred L. Wilson": "Alfred_L._Wilson"}},
  {"id": "1944-11-09-gott-donald-j", "date": "1944-11-09", "title": "First Lieutenant Donald J. Gott", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Saarbrücken, Germany", "lat": 49.2333, "lng": 7}, "zoom": 9, "summary": "On a bombing run upon the marshaling yards at Saarbrücken a B-17 aircraft piloted by 1st. Lt. Gott was seriously damaged by antiaircraft fire. Three of the aircraft's engines were damaged beyond control and on fire; dangerous flames from the No. 4 engine were leaping back as far as the tail assembly. Flares in the cockpit were ignited and a fire raged therein, which was further increased by free-flowing fluid from damaged hydraulic lines. The interphone system was rendered useless. In addition to these serious mechanical difficulties the engineer was wounded in the leg and the radio operator's arm was severed below the elbow. Suffering from intense pain, despite the application of a tourniquet, the radio operator fell unconscious. Faced with the imminent explosion of his aircraft, and death to his entire crew, mere seconds before bombs away on the target, 1st. Lt. Gott and his copilot conferred. Something had to be done immediately to save the life of the wounded radio operator. …", "facts": [["Recipient", "Donald J. Gott"], ["Rank", "First Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Saarbrücken, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Donald J. Gott": "Donald_J._Gott"}},
  {"id": "1944-11-09-metzger-jr-william-e", "date": "1944-11-09", "title": "Second Lieutenant William E. Metzger Jr.", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Saarbrücken, Germany", "lat": 49.2333, "lng": 7}, "zoom": 9, "summary": "On a bombing run upon the marshaling yards at Saarbrücken, Germany, on 9 November 1944, a B17 aircraft on which 2d Lt. Metzger was serving as copilot was seriously damaged by antiaircraft fire. Three of the aircraft's engines were damaged beyond control and on fire; dangerous flames from the No. 4 engine were leaping back as far as the tail assembly. Flares in the cockpit were ignited and a fire roared therein which was further increased by free-flowing fluid from damaged hydraulic lines. The interphone system was rendered useless. In addition to these serious mechanical difficulties the engineer was wounded in the leg and the radio operator's arm was severed below the elbow. Suffering from intense pain, despite the application of a tourniquet, the radio operator fell unconscious. Faced with the imminent explosion of his aircraft and death to his entire crew, mere seconds before bombs away on the target, 2d Lt. Metzger and his pilot conferred. …", "facts": [["Recipient", "William E. Metzger Jr."], ["Rank", "Second Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Saarbrücken, Germany"], ["Awarded", "Posthumously"]], "wiki": {"William E. Metzger Jr.": "William_E._Metzger_Jr."}},
  {"id": "1944-11-12-sayers-foster-j", "date": "1944-11-12", "title": "Private First Class Foster J. Sayers", "type": "loss", "theater": "Army", "location": {"name": "Near Thionville, France", "lat": 49.3589, "lng": 6.1692}, "zoom": 9, "summary": "He displayed conspicuous gallantry above and beyond the call of duty in combat on 12 November 1944, near Thionville, France. During an attack on strong hostile forces entrenched on a hill he fearlessly ran up the steep approach toward his objective and set up his machinegun 20 yards from the enemy. Realizing it would be necessary to attract full attention of the dug-in Germans while his company crossed an open area and flanked the enemy, he picked up his gun, charged through withering machinegun and rifle fire to the very edge of the emplacement, and there killed 12 German soldiers with devastating close-range fire. He took up a position behind a log and engaged the hostile infantry from the flank in an heroic attempt to distract their attention while his comrades attained their objective at the crest of the hill. …", "facts": [["Recipient", "Foster J. Sayers"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Thionville, France"], ["Awarded", "Posthumously, G.O. No. 89, October 19, 1945"]], "wiki": {"Foster J. Sayers": "Foster_J._Sayers"}},
  {"id": "1944-11-12-everhart-forrest-e", "date": "1944-11-12", "title": "Technical Sergeant Forrest E. Everhart", "type": "attack", "theater": "Army", "location": {"name": "Near Kerling, France (approx.)", "lat": 49.39, "lng": 6.36}, "zoom": 9, "summary": "He commanded a platoon that bore the brunt of a desperate enemy counterattack near Korling, France, before dawn on 12 November 1944. When German tanks and self-propelled guns penetrated his left flank and overwhelming infantry forces threatened to overrun the 1 remaining machinegun in that section, he ran 400 yards through woods churned by artillery and mortar concentrations to strengthen the defense. With the 1 remaining gunner, he directed furious fire into the advancing hordes until they swarmed close to the position. He left the gun, boldly charged the attackers and, after a 15-minute exchange of hand grenades, forced them to withdraw leaving 30 dead behind. He re-crossed the fire-swept terrain to his then threatened right flank, exhorted his men and directed murderous fire from the single machinegun at that position. There, in the light of bursting mortar shells, he again closed with the enemy in a hand grenade duel and, after a fierce 30-minute battle, forced the Germans to withdraw leaving another 20 dead. …", "facts": [["Recipient", "Forrest E. Everhart"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Kerling, France"]], "wiki": {"Forrest E. Everhart": "Forrest_E._Everhart"}},
  {"id": "1944-11-13-spurrier-junior-j", "date": "1944-11-13", "title": "Staff Sergeant Junior J. Spurrier", "type": "attack", "theater": "Army", "location": {"name": "Achain, France", "lat": 48.9144, "lng": 6.5928}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of his life above and beyond the call of duty in action against the enemy at Achain, France, on 13 November 1944. At 2 p.m., Company G attacked the village of Achain from the east. S/Sgt. Spurrier armed with a BAR passed around the village and advanced alone. Attacking from the west, he immediately killed 3 Germans. From this time until dark, S/Sgt. Spurrier, using at different times his BAR and M1 rifle, American and German rocket launchers, a German automatic pistol, and hand grenades, continued his solitary attack against the enemy regardless of all types of small-arms and automatic-weapons fire. As a result of his heroic actions he killed an officer and 24 enlisted men and captured 2 officers and 2 enlisted men. His valor has shed fresh honor on the U.S. Armed Forces.", "facts": [["Recipient", "Junior J. Spurrier"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Achain, France"]], "wiki": {"Junior J. Spurrier": "Junior_J._Spurrier"}},
  {"id": "1944-11-15-rivers-ruben", "date": "1944-11-15", "title": "Staff Sergeant Ruben Rivers", "type": "loss", "theater": "Army", "location": {"name": "Toward Guebling, France (approx.)", "lat": 48.87, "lng": 6.73}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty: Staff Sergeant Rivers distinguished himself by extraordinary heroism in action during 16–19 November 1944, while serving with Company A, 761st Tank Battalion. On 16 November 1944, while advancing toward the town of Guebling, France, Staff Sergeant Rivers' tank hit a mine at a railroad crossing. Although severely wounded, his leg slashed to the bone, Staff Sergeant Rivers declined an injection of morphine, refused to be evacuated, took command of another tank, and advanced with his company into Guebling the next day. Repeatedly refusing evacuation, Staff Sergeant Rivers continued to direct his tank's fire at enemy positions beyond the town through the morning of 19 November 1944. At dawn that day, Company A's tanks advanced toward Bourgaltroff, their next objective, but were stopped by enemy fire. Captain David J. Williams, the Company Commander, ordered his tanks to withdraw and take cover. …", "facts": [["Recipient", "Ruben Rivers"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Toward Guebling, France"], ["Awarded", "Posthumously"]], "wiki": {"Ruben Rivers": "Ruben_Rivers"}},
  {"id": "1944-11-16-miller-andrew", "date": "1944-11-16", "title": "Staff Sergeant Andrew Miller", "type": "loss", "theater": "Army", "location": {"name": "From Woippy, France to Kerprich Hemmersdorf, Germany (approx.)", "lat": 49.15, "lng": 6.15}, "zoom": 9, "summary": "For performing a series of heroic deeds from 16 to 29 November 1944, during his company's relentless drive from Woippy, France, through Metz to Kerprich Hemmersdorf, Germany. As he led a rifle squad on 16 November at Woippy, a crossfire from enemy machineguns pinned down his unit. Ordering his men to remain under cover, he went forward alone, entered a building housing 1 of the guns and forced 5 Germans to surrender at bayonet point. He then took the second gun single-handedly by hurling grenades into the enemy position, killing 2, wounding 3 more, and taking 2 additional prisoners. At the outskirts of Metz the next day, when his platoon, confused by heavy explosions and the withdrawal of friendly tanks, retired, he fearlessly remained behind armed with an automatic rifle and exchanged bursts with a German machinegun until he silenced the enemy weapon. His quick action in covering his comrades gave the platoon time to regroup and carry on the fight. On 19 November S/Sgt. …", "facts": [["Recipient", "Andrew Miller"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "From Woippy, France to Kerprich Hemmersdorf, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Andrew Miller": "Andrew_Miller_(Medal_of_Honor,_1944)"}},
  {"id": "1944-11-16-horner-freeman-v", "date": "1944-11-16", "title": "Staff Sergeant Freeman V. Horner", "type": "attack", "theater": "Army", "location": {"name": "Wurselen, Germany", "lat": 50.8167, "lng": 6.1333}, "zoom": 9, "summary": "S/Sgt. Horner and other members of his company were attacking Wurselen, Germany, against stubborn resistance on 16 November 1944, when machinegun fire from houses on the edge of the town pinned the attackers in flat, open terrain 100 yards from their objective. As they lay in the field, enemy artillery observers directed fire upon them, causing serious casualties. Realizing that the machineguns must be eliminated in order to permit the company to advance from its precarious position, S/Sgt. Horner voluntarily stood up with his submachine gun and rushed into the teeth of concentrated fire, burdened by a heavy load of ammunition and hand grenades. Just as he reached a position of seeming safety, he was fired on by a machinegun which had remained silent up until that time. He coolly wheeled in his fully exposed position while bullets barely missed him and killed 2 hostile gunners with a single, devastating burst. …", "facts": [["Recipient", "Freeman V. Horner"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Wurselen, Germany"]], "wiki": {"Freeman V. Horner": "Freeman_V._Horner"}},
  {"id": "1944-11-16-lindsey-jake-w", "date": "1944-11-16", "title": "Technical Sergeant Jake W. Lindsey", "type": "attack", "theater": "Army", "location": {"name": "Near Hamich, Germany (approx.)", "lat": 50.78, "lng": 6.31}, "zoom": 9, "summary": "For gallantry and intrepidity at the risk of his life above and beyond the call of duty on November 16, 1944, in Germany. T/Sgt. Lindsey assumed a position about 10 yards to the front of his platoon during an intense enemy infantry-tank counterattack, and by his unerringly accurate fire destroyed 2 enemy machinegun nests, forced the withdrawal of 2 tanks, and effectively halted enemy flanking patrols. Later, although painfully wounded, he engaged 8 Germans, who were reestablishing machinegun positions, in hand-to-hand combat, killing 3, capturing 3, and causing the other 2 to flee. By his gallantry, T/Sgt. Lindsey secured his unit's position, and reflected great credit upon himself and the U.S. Army.", "facts": [["Recipient", "Jake W. Lindsey"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Hamich, Germany"]], "wiki": {"Jake W. Lindsey": "Jake_W._Lindsey"}},
  {"id": "1944-11-17-ray-bernard-j", "date": "1944-11-17", "title": "First Lieutenant Bernard J. Ray", "type": "loss", "theater": "Army", "location": {"name": "Hurtgen Forest near Schevenhütte, Germany (approx.)", "lat": 50.76, "lng": 6.33}, "zoom": 9, "summary": "He was platoon leader with Company F, 8th Infantry, on November 17, 1944, during the drive through the Hurtgen Forest near Schevenhutte, Germany. The American forces attacked in wet, bitterly cold weather over rough, wooded terrain, meeting brutal resistance from positions spaced throughout the forest behind minefields and wire obstacles. Small arms, machinegun, mortar, and artillery fire caused heavy casualties in the ranks when Company F was halted by a concertina-type wire barrier. Under heavy fire, 1st Lt. Ray reorganized his men and prepared to blow a path through the entanglement, a task which appeared impossible of accomplishment and from which others tried to dissuade him. With implacable determination to clear the way, he placed explosive caps in his pockets, obtained several bangalore torpedoes, and then wrapped a length of highly explosive primer cord about his body. He dashed forward under direct fire, reached the barbed wire and prepared his demolition charge as mortar shells, which were being aimed at him alone, came steadily nearer his completely exposed position. …", "facts": [["Recipient", "Bernard J. Ray"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Hurtgen Forest near Schevenhütte, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Bernard J. Ray": "Bernard_J._Ray"}},
  {"id": "1944-11-18-nietzel-alfred-b", "date": "1944-11-18", "title": "Sergeant Alfred B. Nietzel", "type": "loss", "theater": "Army", "location": {"name": "Heistern, Germany (approx.)", "lat": 50.81, "lng": 6.33}, "zoom": 9, "summary": "When a German assault threatened to overrun his unit near Heistern, he covered his squad's withdrawal, firing until his ammunition ran out and holding his post until he was killed. His Distinguished Service Cross was upgraded to the Medal of Honor in 2014.", "facts": [["Recipient", "Alfred B. Nietzel"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Heistern, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Alfred B. Nietzel": "Alfred_B._Nietzel"}},
  {"id": "1944-11-19-mcgraw-francis-x", "date": "1944-11-19", "title": "Private First Class Francis X. McGraw", "type": "loss", "theater": "Army", "location": {"name": "Near Schevenhütte, Germany", "lat": 50.7667, "lng": 6.2333}, "zoom": 9, "summary": "He manned a heavy machine gun in a foxhole near Schevenhutte, Germany, on 19 November 1944, when the enemy launched a fierce counterattack. Braving an intense hour-long preparatory barrage, he maintained his stand and poured deadly accurate fire into the advancing foot troops, until they faltered and came to a halt. The hostile forces brought up a machine gun in an effort to dislodge him but were frustrated when he lifted his gun to an exposed but advantageous position atop a log, courageously stood up in his foxhole and knocked out the enemy weapon. A rocket blasted his gun from position, but he retrieved it and continued firing. He silenced a second machine gun and then made repeated trips over fire-swept terrain to replenish his ammunition supply. Wounded painfully in this dangerous task, he disregarded his injury and hurried back to his post, where his weapon was showered with mud when another rocket barely missed him. …", "facts": [["Recipient", "Francis X. McGraw"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Schevenhütte, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Francis X. McGraw": "Francis_X._McGraw"}},
  {"id": "1944-11-20-mabry-jr-george-l", "date": "1944-11-20", "title": "Lieutenant Colonel George L. Mabry Jr.", "type": "attack", "theater": "Army", "location": {"name": "Hurtgen Forest near Schevenhütte, Germany (approx.)", "lat": 50.76, "lng": 6.33}, "zoom": 9, "summary": "He was commanding the 2d Battalion, 8th Infantry, in an attack through the Hurtgen Forest near Schevenhutte, Germany, on 20 November 1944. During the early phases of the assault, the leading elements of his battalion were halted by a minefield and immobilized by heavy hostile fire. Advancing alone into the mined area, Col. Mabry established a safe route of passage. He then moved ahead of the foremost scouts, personally leading the attack, until confronted by a boobytrapped double concertina obstacle. With the assistance of the scouts, he disconnected the explosives and cut a path through the wire. Upon moving through the opening, he observed 3 enemy in foxholes whom he captured at bayonet point. Driving steadily forward he paced the assault against 3 log bunkers which housed mutually supported automatic weapons. Racing up a slope ahead of his men, he found the initial bunker deserted, then pushed on to the second where he was suddenly confronted by 9 onrushing enemy. …", "facts": [["Recipient", "George L. Mabry Jr."], ["Rank", "Lieutenant Colonel"], ["Service", "Army"], ["Place of action", "Hurtgen Forest near Schevenhütte, Germany"]], "wiki": {"George L. Mabry Jr.": "George_L._Mabry_Jr."}},
  {"id": "1944-11-20-briles-herschel-f", "date": "1944-11-20", "title": "Staff Sergeant Herschel F. Briles", "type": "attack", "theater": "Army", "location": {"name": "Near Scherpenseel, Germany", "lat": 50.9197, "lng": 6.1194}, "zoom": 9, "summary": "He was leading a platoon of destroyers across an exposed slope near Scherpenseel, Germany, on 20 November 1944, when they came under heavy enemy artillery fire. A direct hit was scored on 1 of the vehicles, killing 1 man, seriously wounding 2 others, and setting the destroyer afire. With a comrade, S/Sgt. Briles left the cover of his own armor and raced across ground raked by artillery and small-arms fire to the rescue of the men in the shattered destroyer. Without hesitation, he lowered himself into the burning turret, removed the wounded and then extinguished the fire. From a position he assumed the next morning, he observed hostile infantrymen advancing. With his machinegun, he poured such deadly fire into the enemy ranks that an entire pocket of 55 Germans surrendered, clearing the way for a junction between American units which had been held up for 2 days. Later that day, when another of his destroyers was hit by a concealed enemy tank, he again left protection to give assistance. …", "facts": [["Recipient", "Herschel F. Briles"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Scherpenseel, Germany"]], "wiki": {"Herschel F. Briles": "Herschel_F._Briles"}},
  {"id": "1944-11-21-minick-john-w", "date": "1944-11-21", "title": "Staff Sergeant John W. Minick", "type": "loss", "theater": "Army", "location": {"name": "Near Hurtgen, Germany (approx.)", "lat": 50.7, "lng": 6.36}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity at the risk of his own life, above and beyond the call of duty, in action involving actual conflict with the enemy on 21 November 1944, near Hurtgen, Germany. S/Sgt. Minick's battalion was halted in its advance by extensive minefields, exposing troops to heavy concentrations of enemy artillery and mortar fire. Further delay in the advance would result in numerous casualties and a movement through the minefield was essential. Voluntarily, S/Sgt. Minick led 4 men through hazardous barbed wire and debris, finally making his way through the minefield for a distance of 300 yards. When an enemy machinegun opened fire, he signaled his men to take covered positions, edged his way alone toward the flank of the weapon and opened fire, killing 2 members of the guncrew and capturing 3 others. Moving forward again, he encountered and engaged single-handedly an entire company killing 20 Germans and capturing 20, and enabling his platoon to capture the remainder of the hostile group. …", "facts": [["Recipient", "John W. Minick"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Hurtgen, Germany"], ["Awarded", "Posthumously"]], "wiki": {"John W. Minick": "John_W._Minick"}},
  {"id": "1944-11-23-silk-edward-a", "date": "1944-11-23", "title": "First Lieutenant Edward A. Silk", "type": "attack", "theater": "Army", "location": {"name": "Near St. Pravel, France (approx.)", "lat": 47.0, "lng": 2.5}, "zoom": 9, "summary": "1st Lt. Edward A. Silk commanded the weapons platoon of Company E, 398th Infantry, on 23 November 1944, when the end battalion was assigned the mission of seizing high ground overlooking Moyenmoutier, France, prior to an attack on the city itself. His company jumped off in the lead at dawn and by noon had reached the edge of a woods in the vicinity of St. Pravel where scouts saw an enemy sentry standing guard before a farmhouse in a valley below. One squad, engaged in reconnoitering the area, was immediately pinned down by intense machinegun and automatic-weapons fire from within the house. Skillfully deploying his light machinegun section, 1st Lt. Silk answered enemy fire, but when 15 minutes had elapsed with no slackening of resistance, he decided to eliminate the strong point by a one-man attack. …", "facts": [["Recipient", "Edward A. Silk"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near St. Pravel, France"]], "wiki": {"Edward A. Silk": "Edward_A._Silk"}},
  {"id": "1944-11-26-sheridan-carl-v", "date": "1944-11-26", "title": "Private First Class Carl V. Sheridan", "type": "loss", "theater": "Army", "location": {"name": "Frenzenberg Castle, Weisweiler, Germany", "lat": 50.8167, "lng": 6.2833}, "zoom": 9, "summary": "Attached to the 2d Battalion of the 47th Infantry on November 26, 1944, for the attack on Frenzenberg Castle, in the vicinity of Weisweiler, Germany, Company K, after an advance of 1,000 yards through a shattering barrage of enemy artillery and mortar fire, had captured 2 buildings in the courtyard of the castle but was left with an effective fighting strength of only 35 men. During the advance, Pfc. Sheridan, acting as a bazooka gunner, had braved the enemy fire to stop and procure the additional rockets carried by his ammunition bearer who was wounded. Upon rejoining his company in the captured buildings, he found it in a furious fight with approximately 70 enemy paratroopers occupying the castle gate house. This was a solidly built stone structure surrounded by a deep water-filled moat 20 feet wide. The only approach to the heavily defended position was across the courtyard and over a drawbridge leading to a barricaded oaken door. Pfc. …", "facts": [["Recipient", "Carl V. Sheridan"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Frenzenberg Castle, Weisweiler, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Carl V. Sheridan": "Carl_V._Sheridan"}},
  {"id": "1944-11-27-garcia-marcario", "date": "1944-11-27", "title": "Private Marcario Garcia", "type": "attack", "theater": "Army", "location": {"name": "Near Grosshau, Germany (approx.)", "lat": 50.72, "lng": 6.38}, "zoom": 9, "summary": "Staff Sergeant Marcario García, Company B, 22nd Infantry, in action involving actual conflict with the enemy in the vicinity of Grosshau, Germany, 27 November 1944. While an acting squad leader, he single-handedly assaulted two enemy machine gun emplacements. Attacking prepared positions on a wooded hill, which could be approached only through meager cover. His company was pinned down by intense machine-gun fire and subjected to a concentrated artillery and mortar barrage. Although painfully wounded, he refused to be evacuated and on his own initiative crawled forward alone until he reached a position near an enemy emplacement. Hurling grenades, he boldly assaulted the position, destroyed the gun, and with his rifle killed three of the enemy who attempted to escape. When he rejoined his company, a second machine-gun opened fire and again the intrepid soldier went forward, utterly disregarding his own safety. He stormed the position and destroyed the gun, killed three more Germans, and captured four prisoners. …", "facts": [["Recipient", "Marcario Garcia"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Grosshau, Germany"]], "wiki": {"Marcario Garcia": "Marcario_García"}},
  {"id": "1944-12-02-cano-pedro", "date": "1944-12-02", "title": "Private Pedro Cano", "type": "loss", "theater": "Army", "location": {"name": "Schevenhütte, Germany", "lat": 50.7667, "lng": 6.2333}, "zoom": 9, "summary": "President Barack Obama posthumously bestowed the Medal of Honor upon Private Pedro Cano at a ceremony on March 18, 2014, in the East Room of the White House. Pedro's eldest daughter, Dominga, accepted the Medal of Honor for her father. Descendants of Pedro Cano joined other honorees' families at the White House ceremony. President Obama awarded the Medal of Honor to 24 Army veterans in recognition of their valor during major combat operations in World War II, the Korean War, and the Vietnam War. They were overlooked for the Medal of Honor due to their racial or ethnic backgrounds. The ceremony on March 18 followed a 12-year Pentagon review, ordered by Congress, of past discrimination in the military. \"No nation is perfect,\" the President said at the ceremony. …", "facts": [["Recipient", "Pedro Cano"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Schevenhütte, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Pedro Cano": "Pedro_Cano"}},
  {"id": "1944-12-03-henry-robert-t", "date": "1944-12-03", "title": "Private Robert T. Henry", "type": "loss", "theater": "Army", "location": {"name": "Luchem, Germany (approx.)", "lat": 50.84, "lng": 6.38}, "zoom": 9, "summary": "Near Luchem, Germany, he volunteered to attempt the destruction of a nest of 5 enemy machineguns located in a bunker 150 yards to the flank which had stopped the advance of his platoon. Stripping off his pack, overshoes, helmet, and overcoat, he sprinted alone with his rifle and hand grenades across the open terrain toward the enemy emplacement. Before he had gone half the distance he was hit by a burst of machinegun fire. Dropping his rifle, he continued to stagger forward until he fell mortally wounded only 10 yards from the enemy emplacement. His single-handed attack forced the enemy to leave the machineguns. During this break in hostile fire the platoon moved forward and overran the position. Pvt. Henry, by his gallantry and intrepidity and utter disregard for his own life, enabled his company to reach its objective, capturing this key defense and 70 German prisoners.", "facts": [["Recipient", "Robert T. Henry"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Luchem, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Robert T. Henry": "Robert_T._Henry"}},
  {"id": "1944-12-03-weicht-ellis-r", "date": "1944-12-03", "title": "Sergeant Ellis R. Weicht", "type": "loss", "theater": "Army", "location": {"name": "St. Hippolyte, France (approx.)", "lat": 48.23, "lng": 7.37}, "zoom": 9, "summary": "For commanding an assault squad in Company F's attack against the strategically important Alsace town of St. Hippolyte on December 3, 1944. He aggressively led his men down a winding street, clearing the houses of opposition as he advanced. Upon rounding a bend, the group was suddenly brought under the fire of 2 machineguns emplaced in the door and window of a house 100 yards distant. While his squad members took cover, Sgt. Weicht moved rapidly forward to a high rock wall and, fearlessly exposing himself to the enemy action, fired 2 clips of ammunition from his rifle. His fire proving ineffective, he entered a house opposite the enemy gun position, and, firing from a window, killed the 2 hostile gunners. Continuing the attack, the advance was again halted when two 20-mm. guns opened fire on the company. An artillery observer ordered friendly troops to evacuate the area and then directed artillery fire upon the gun positions. Sgt. …", "facts": [["Recipient", "Ellis R. Weicht"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "St. Hippolyte, France"], ["Awarded", "Posthumously"]], "wiki": {"Ellis R. Weicht": "Ellis_R._Weicht"}},
  {"id": "1944-12-05-mcwhorter-william-a", "date": "1944-12-05", "title": "Private First Class William A. McWhorter", "type": "loss", "theater": "Army", "location": {"name": "Leyte, Philippines (approx.)", "lat": 11.0, "lng": 124.85}, "zoom": 6, "summary": "He displayed gallantry and intrepidity at the risk of his life above and beyond the call of duty while engaged in operations against the enemy. Pfc. McWhorter, a machine gunner, was emplaced in a defensive position with 1 assistant when the enemy launched a heavy attack. Manning the gun and opening fire, he killed several members of an advancing demolition squad, when 1 of the enemy succeeded in throwing a fused demolition charge in the entrenchment. Without hesitation and with complete disregard for his own safety, Pfc. McWhorter picked up the improvised grenade and deliberately held it close to his body, bending over and turning away from his companion. The charge exploded, killing him instantly, but leaving his assistant unharmed. Pfc. McWhorter's outstanding heroism and supreme sacrifice in shielding a comrade reflect the highest traditions of the military service.", "facts": [["Recipient", "William A. McWhorter"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Leyte, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"William A. McWhorter": "William_A._McWhorter"}},
  {"id": "1944-12-08-fryar-elmer-e", "date": "1944-12-08", "title": "Private Elmer E. Fryar", "type": "loss", "theater": "Army", "location": {"name": "Leyte, Philippines (approx.)", "lat": 11.0, "lng": 124.85}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty. Pvt. Fryar's battalion encountered the enemy strongly entrenched in a position supported by mortars and automatic weapons. The battalion attacked, but in spite of repeated efforts was unable to take the position. Pvt. Fryar's company was ordered to cover the battalion's withdrawal to a more suitable point from which to attack, but the enemy launched a strong counterattack which threatened to cut off the company. Seeing an enemy platoon moving to outflank his company, he moved to higher ground and opened heavy and accurate fire. He was hit, and wounded, but continuing his attack he drove the enemy back with a loss of 27 killed. While withdrawing to overtake his squad, he found a seriously wounded comrade, helped him to the rear, and soon overtook his platoon leader, who was assisting another wounded. …", "facts": [["Recipient", "Elmer E. Fryar"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Leyte, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Elmer E. Fryar": "Elmer_E._Fryar"}},
  {"id": "1944-12-08-kelley-ova-a", "date": "1944-12-08", "title": "Private Ova A. Kelley", "type": "loss", "theater": "Army", "location": {"name": "Leyte, Philippines (approx.)", "lat": 11.0, "lng": 124.85}, "zoom": 6, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty. Before dawn, near the edge of the enemy-held Buri airstrip, the company was immobilized by heavy, accurate rifle and machinegun fire from hostile troops entrenched in bomb craters and a ditch less than 100 yards distant. The company commander ordered a mortar concentration which destroyed 1 machinegun but failed to dislodge the main body of the enemy. At this critical moment Pvt. Kelley, on his own initiative, left his shallow foxhole with an armload of hand grenades and began a 1-man assault on the foe. Throwing his missiles with great accuracy, he moved forward, killed or wounded 5 men, and forced the remainder to flee in a disorganized route. He picked up a M-1 rifle and emptied its clip at the running Japanese, killing 3. Discarding this weapon, he took a carbine and killed 3 more of the enemy. …", "facts": [["Recipient", "Ova A. Kelley"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Leyte, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Ova A. Kelley": "Ova_A._Kelley"}},
  {"id": "1944-12-14-thomas-charles-l", "date": "1944-12-14", "title": "First Lieutenant Charles L. Thomas", "type": "loss", "theater": "Army", "location": {"name": "Near Climbach, France", "lat": 49.0181, "lng": 7.8511}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty: Then Lieutenant Charles L. Thomas distinguished himself by extraordinary heroism in action on 14 December 1944. One platoon of Company C, 614th Tank Destroyer Battalion, was designated as the lead element in a task force formed to storm and capture the village of Climbach, France. Lieutenant Thomas, the Commanding Officer of Company C, realized, with the obscurity of information regarding the enemy and a complete lack of reconnaissance, the mission would be an extremely dangerous one. Fully cognizant of the danger, Lieutenant Thomas volunteered to command the selected platoon of his company and ride in the column's leading vehicle - a highly maneuverable, but equally vulnerable, M-20 scout car. Lieutenant Thomas knew that if there was a concentration of enemy armor in the village, as was believed, he would absorb the initial shock of the first enemy resistance. …", "facts": [["Recipient", "Charles L. Thomas"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Climbach, France"], ["Awarded", "Posthumously"]], "wiki": {"Charles L. Thomas": "Charles_L._Thomas"}},
  {"id": "1944-12-14-nett-robert-b", "date": "1944-12-14", "title": "First Lieutenant Robert B. Nett", "type": "attack", "theater": "Army", "location": {"name": "Near Cognon, Leyte, Philippines (approx.)", "lat": 11.1, "lng": 124.8}, "zoom": 9, "summary": "He commanded Company E in an attack against a reinforced enemy battalion which had held up the American advance for 2 days from its entrenched positions around a 3-story concrete building. With another infantry company and armored vehicles, Company E advanced against heavy machinegun and other automatic weapons fire with Lt. Nett spearheading the assault against the strongpoint. During the fierce hand-to-hand encounter which ensued, he killed 7 deeply entrenched Japanese with his rifle and bayonet and, although seriously wounded, gallantly continued to lead his men forward, refusing to relinquish his command. Again he was severely wounded, but, still unwilling to retire, pressed ahead with his troops to assure the capture of the objective. Wounded once more in the final assault, he calmly made all arrangements for the resumption of the advance, turned over his command to another officer, and then walked unaided to the rear for medical treatment. By his remarkable courage in continuing forward through sheer determination despite successive wounds, Lt. …", "facts": [["Recipient", "Robert B. Nett"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Cognon, Leyte, Philippines"]], "wiki": {"Robert B. Nett": "Robert_B._Nett"}},
  {"id": "1944-12-14-neppel-ralph-g", "date": "1944-12-14", "title": "Sergeant Ralph G. Neppel", "type": "attack", "theater": "Army", "location": {"name": "Birgel, Germany", "lat": 50.3222, "lng": 6.6222}, "zoom": 9, "summary": "He was leader of a machinegun squad defending an approach to the village of Birgel, Germany, on 14 December 1944, when an enemy tank, supported by 20 infantrymen, counterattacked. He held his fire until the Germans were within 100 yards and then raked the foot soldiers beside the tank killing several of them. The enemy armor continued to press forward and, at the pointblank range of 30 yards, fired a high-velocity shell into the American emplacement, wounding the entire squad. Sgt. Neppel, blown 10 yards from his gun, had 1 leg severed below the knee and suffered other wounds. Despite his injuries and the danger from the onrushing tank and infantry, he dragged himself back to his position on his elbows, remounted his gun and killed the remaining enemy riflemen. Stripped of its infantry protection, the tank was forced to withdraw. By his superb courage and indomitable fighting spirit, Sgt. Neppel inflicted heavy casualties on the enemy and broke a determined counterattack.", "facts": [["Recipient", "Ralph G. Neppel"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Birgel, Germany"]], "wiki": {"Ralph G. Neppel": "Ralph_G._Neppel"}},
  {"id": "1944-12-15-vlug-dirk-j", "date": "1944-12-15", "title": "Private First Class Dirk J. Vlug", "type": "attack", "theater": "Army", "location": {"name": "Near Limon, Leyte, Philippines (approx.)", "lat": 11.2, "lng": 124.75}, "zoom": 9, "summary": "Serving with the 126th Infantry, 32nd Infantry Division, near Limon, he single-handedly destroyed five Japanese tanks with a rocket launcher.", "facts": [["Recipient", "Dirk J. Vlug"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Limon, Leyte, Philippines"]], "wiki": {"Dirk J. Vlug": "Dirk_J._Vlug"}},
  {"id": "1944-12-15-johnson-leroy", "date": "1944-12-15", "title": "Sergeant Leroy Johnson", "type": "loss", "theater": "Army", "location": {"name": "Near Limon, Leyte, Philippines (approx.)", "lat": 11.2, "lng": 124.75}, "zoom": 9, "summary": "He was squad leader of a 9-man patrol sent to reconnoiter a ridge held by a well-entrenched enemy force. Seeing an enemy machinegun position, he ordered his men to remain behind while he crawled to within 6 yards of the gun. One of the enemy crew jumped up and prepared to man the weapon. Quickly withdrawing, Sgt. Johnson rejoined his patrol and reported the situation to his commanding officer. Ordered to destroy the gun, which covered the approaches to several other enemy positions, he chose 3 other men, armed them with hand grenades, and led them to a point near the objective. After taking partial cover behind a log, the men had knocked out the gun and begun an assault when hostile troops on the flank hurled several grenades. As he started for cover, Sgt. Johnson saw 2 unexploded grenades which had fallen near his men. …", "facts": [["Recipient", "Leroy Johnson"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Limon, Leyte, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Leroy Johnson": "Leroy_Johnson_(Medal_of_Honor)"}},
  {"id": "1944-12-16-murray-jr-charles-p", "date": "1944-12-16", "title": "First Lieutenant Charles P. Murray Jr.", "type": "attack", "theater": "Army", "location": {"name": "Near Kaysersberg, France", "lat": 48.14, "lng": 7.26}, "zoom": 9, "summary": "For commanding Company C, 30th Infantry, displaying supreme courage and heroic initiative near Kaysersberg, France, on 16 December 1944, while leading a reinforced platoon into enemy territory. Descending into a valley beneath hilltop positions held by our troops, he observed a force of 200 Germans pouring deadly mortar, bazooka, machinegun, and small arms fire into an American battalion occupying the crest of the ridge. The enemy's position in a sunken road, though hidden from the ridge, was open to a flank attack by 1st Lt. Murray's patrol but he hesitated to commit so small a force to battle with the superior and strongly disposed enemy. Crawling out ahead of his troops to a vantage point, he called by radio for artillery fire. His shells bracketed the German force, but when he was about to correct the range his radio went dead. He returned to his patrol, secured grenades and a rifle to launch them and went back to his self-appointed outpost. …", "facts": [["Recipient", "Charles P. Murray Jr."], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Kaysersberg, France"]], "wiki": {"Charles P. Murray Jr.": "Charles_P._Murray_Jr."}},
  {"id": "1944-12-16-mcgarity-vernon", "date": "1944-12-16", "title": "Technical Sergeant Vernon McGarity", "type": "attack", "theater": "Army", "location": {"name": "Near Krinkelt, Belgium (approx.)", "lat": 50.44, "lng": 6.32}, "zoom": 9, "summary": "He was painfully wounded in an artillery barrage that preceded the powerful counteroffensive launched by the Germans near Krinkelt, Belgium, on the morning of 16 December 1944. He made his way to an aid station, received treatment, and then refused to be evacuated, choosing to return to his hard-pressed men, instead. The fury of the enemy's great Western Front offensive swirled about the position held by T/Sgt. McGarity's small force, but so tenaciously did these men fight on orders to stand firm at all costs that they could not be dislodged despite murderous enemy fire and the breakdown of their communications. During the day, the heroic squad leader rescued one of his friends, who had been wounded in a forward position, and throughout the night, he exhorted his comrades to repulse the enemy's attempts at infiltration. …", "facts": [["Recipient", "Vernon McGarity"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Krinkelt, Belgium"]], "wiki": {"Vernon McGarity": "Vernon_McGarity"}},
  {"id": "1944-12-17-cowan-richard-e", "date": "1944-12-17", "title": "Private First Class Richard E. Cowan", "type": "loss", "theater": "Army", "location": {"name": "Near Krinkelter Wald, Belgium (approx.)", "lat": 50.44, "lng": 6.36}, "zoom": 9, "summary": "He was a heavy machinegunner in a section attached to Company I in the vicinity of Krinkelter Wald, Belgium, 17 December 1944, when that company was attacked by a numerically superior force of German infantry and tanks. The first 6 waves of hostile infantrymen were repulsed with heavy casualties, but a seventh drive with tanks killed or wounded all but 3 of his section, leaving Pvt. Cowan to man his gun, supported by only 15 to 20 riflemen of Company I. He maintained his position, holding off the Germans until the rest of the shattered force had set up a new line along a firebreak. Then, unaided, he moved his machinegun and ammunition to the second position. At the approach of a Royal Tiger tank, he held his fire until about 80 enemy infantrymen supporting the tank appeared at a distance of about 150 yards. His first burst killed or wounded about half of these infantrymen. His position was rocked by an 88mm. …", "facts": [["Recipient", "Richard E. Cowan"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Krinkelter Wald, Belgium"], ["Awarded", "Posthumously, G.O. No. 48, 23 June 1945"]], "wiki": {"Richard E. Cowan": "Richard_Cowan_(soldier)"}},
  {"id": "1944-12-17-soderman-william-a", "date": "1944-12-17", "title": "Private First Class William A. Soderman", "type": "attack", "theater": "Army", "location": {"name": "Near Rocherath, Belgium (approx.)", "lat": 50.44, "lng": 6.3}, "zoom": 9, "summary": "Armed with a bazooka, he defended a key road junction near Rocherath, Belgium, on 17 December 1944, during the German Ardennes counteroffensive. After a heavy artillery barrage had wounded and forced the withdrawal of his assistant, he heard enemy tanks approaching the position where he calmly waited in the gathering darkness of early evening until the 5 Mark V tanks which made up the hostile force were within pointblank range. He then stood up, completely disregarding the firepower that could be brought to bear upon him, and launched a rocket into the lead tank, setting it afire and forcing its crew to abandon it as the other tanks pressed on before Pfc. Soderman could reload. The daring bazookaman remained at his post all night under severe artillery, mortar, and machinegun fire, awaiting the next onslaught, which was made shortly after dawn by 5 more tanks. …", "facts": [["Recipient", "William A. Soderman"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Rocherath, Belgium"]], "wiki": {"William A. Soderman": "William_A._Soderman"}},
  {"id": "1944-12-17-lopez-jose-m", "date": "1944-12-17", "title": "Sergeant Jose M. Lopez", "type": "attack", "theater": "Army", "location": {"name": "Near Krinkelt, Belgium (approx.)", "lat": 50.44, "lng": 6.32}, "zoom": 9, "summary": "On his own initiative, he carried his heavy machine gun from Company K's right flank to its left in order to protect that flank, which was in danger of being overrun by advancing enemy infantry supported by tanks. Occupying a shallow hole offering no protection above his waist, he cut down a group of 10 Germans. Ignoring enemy fire from an advancing tank, he held his position and cut down 25 more enemy infantry attempting to turn his flank. Glancing to his right, he saw a large number of infantry swarming in from the front. Although dazed and shaken from the enemy artillery fire that had crashed into the ground only a few yards away, he realized that his position would soon be outflanked. Again, alone, he carried his machine gun to a position to the right rear of the sector; enemy tanks and infantry were forcing a withdrawal. Blown backward by the concussion of enemy fire, he immediately reset his gun and continued his fire. …", "facts": [["Recipient", "Jose M. Lopez"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Krinkelt, Belgium"], ["Awarded", "G.O. No. 47, June 18, 1945"]], "wiki": {"Jose M. Lopez": "José_M._López"}},
  {"id": "1944-12-18-bell-bernard-p", "date": "1944-12-18", "title": "Technical Sergeant Bernard P. Bell", "type": "attack", "theater": "Army", "location": {"name": "Mittelwihr, France", "lat": 48.1514, "lng": 7.3203}, "zoom": 9, "summary": "For fighting gallantly at Mittelwihr, France. On the morning of December 18, 1944, he led a squad against a schoolhouse held by enemy troops. While his men covered him, he dashed toward the building, surprised two guards at the door and took them prisoner without firing a shot. He found that other Germans were in the cellar. These he threatened with hand grenades, forcing 26 in all to emerge and surrender. His squad then occupied the building and prepared to defend it against powerful enemy action. The next day, the enemy poured artillery and mortar barrages into the position, disrupting communications which T/Sgt. Bell repeatedly repaired under heavy small-arms fire as he crossed dangerous terrain to keep his company commander informed of the squad's situation. During the day, several prisoners were taken and other Germans killed when hostile forces were attracted to the schoolhouse by the sound of captured German weapons fired by the Americans. At dawn the next day the enemy prepared to assault the building. …", "facts": [["Recipient", "Bernard P. Bell"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Mittelwihr, France"], ["Awarded", "G.O. No. 73, August 30, 1945"]], "wiki": {"Bernard P. Bell": "Bernard_P._Bell"}},
  {"id": "1944-12-19-fluckey-eugene-b", "date": "1944-12-19", "title": "Commander Eugene B. Fluckey", "type": "attack", "theater": "Navy", "location": {"name": "USS Barb (SS-220), along east coast of China (approx.)", "lat": 26.5, "lng": 120.3}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as commanding officer of the U.S.S. Barb during her 11th war patrol along the east coast of China from 19 December 1944 to 15 February 1945. After sinking a large enemy ammunition ship and damaging additional tonnage during a running 2-hour night battle on 8 January, Comdr. Fluckey, in an exceptional feat of brilliant deduction and bold tracking on 25 January, located a concentration of more than 30 enemy ships in the lower reaches of Nankuan Chiang (Mamkwan Harbor). Fully aware that a safe retirement would necessitate an hour's run at full speed through the uncharted, mined, and rock-obstructed waters, he bravely ordered, \"Battle station — torpedoes!\" In a daring penetration of the heavy enemy screen, and riding in 5 fathom of water, he launched the Barb's last forward torpedoes at range. …", "facts": [["Recipient", "Eugene B. Fluckey"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "USS Barb (SS-220), along east coast of China"]], "wiki": {"Eugene B. Fluckey": "Eugene_B._Fluckey"}},
  {"id": "1944-12-19-gerstung-robert-e", "date": "1944-12-19", "title": "Technical Sergeant Robert E. Gerstung", "type": "attack", "theater": "Army", "location": {"name": "Siegfried Line near Berg, Germany (approx.)", "lat": 50.6, "lng": 6.2}, "zoom": 9, "summary": "On 19 December 1944 he was ordered with his heavy machinegun squad to the support of an infantry company attacking the outer defense of the Siegfried Line near Berg, Germany. For 8 hours he maintained a position made almost untenable by the density of artillery and mortar fire concentrated upon it and the proximity of enemy troops who threw hand grenades into the emplacement. While all other members of his squad became casualties, he remained at his gun. When he ran out of ammunition, he fearlessly dashed across bullet-swept, open terrain to secure a new supply from a disabled friendly tank. A fierce barrage pierced the water jacket of his gun, but he continued to fire until the weapon overheated and jammed. Instead of withdrawing, he crawled 50 yards across coverless ground to another of his company's machineguns which had been silenced when its entire crew was killed. He continued to man this gun, giving support vitally needed by the infantry. …", "facts": [["Recipient", "Robert E. Gerstung"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Siegfried Line near Berg, Germany"]], "wiki": {"Robert E. Gerstung": "Robert_E._Gerstung"}},
  {"id": "1944-12-19-kimbro-truman", "date": "1944-12-19", "title": "Technician 4th Grade Truman Kimbro", "type": "loss", "theater": "Army", "location": {"name": "Near Rocherath, Belgium", "lat": 50.4, "lng": 6.25}, "zoom": 9, "summary": "On 19 December 1944, as scout, he led a squad assigned to the mission of mining a vital crossroads near Rocherath, Belgium. At the first attempt to reach the objective, he discovered it was occupied by an enemy tank and at least 20 infantrymen. Driven back by withering fire, Technician 4th Grade Kimbro made 2 more attempts to lead his squad to the crossroads but all approaches were covered by intense enemy fire. Although warned by our own infantrymen of the great danger involved, he left his squad in a protected place and, laden with mines, crawled alone toward the crossroads. When nearing his objective he was severely wounded, but he continued to drag himself forward and laid his mines across the road. As he tried to crawl from the objective his body was riddled with rifle and machinegun fire. The mines laid by his act of indomitable courage delayed the advance of enemy armor and prevented the rear of our withdrawing columns from being attacked by the enemy.", "facts": [["Recipient", "Truman Kimbro"], ["Rank", "Technician 4th Grade"], ["Service", "Army"], ["Place of action", "Near Rocherath, Belgium"], ["Awarded", "Posthumously"]], "wiki": {"Truman Kimbro": "Truman_Kimbro"}},
  {"id": "1944-12-20-warner-henry-f", "date": "1944-12-20", "title": "Corporal Henry F. Warner", "type": "loss", "theater": "Army", "location": {"name": "Near Dom Butgenbach, Belgium (approx.)", "lat": 50.43, "lng": 6.18}, "zoom": 9, "summary": "Serving as 57-mm. antitank gunner with the 2d Battalion, he was a major factor in stopping enemy tanks during heavy attacks against the battalion position near Dom Butgenbach, Belgium, on 20–21 December 1944. In the first attack, launched in the early morning of the 20th, enemy tanks succeeded in penetrating parts of the line. Cpl. Warner, disregarding the concentrated cannon and machinegun fire from 2 tanks bearing down on him, and ignoring the imminent danger of being overrun by the infantry moving under tank cover, destroyed the first tank and scored a direct and deadly hit upon the second. A third tank approached to within 5 yards of his position while he was attempting to clear a jammed breach lock. Jumping from his gun pit, he engaged in a pistol duel with the tank commander standing in the turret, killing him and forcing the tank to withdraw. …", "facts": [["Recipient", "Henry F. Warner"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Near Dom Butgenbach, Belgium"], ["Awarded", "Posthumously"]], "wiki": {"Henry F. Warner": "Henry_F._Warner"}},
  {"id": "1944-12-21-thorne-horace-m", "date": "1944-12-21", "title": "Corporal Horace M. Thorne", "type": "loss", "theater": "Army", "location": {"name": "Near Grufflingen, Belgium (approx.)", "lat": 50.25, "lng": 6.06}, "zoom": 9, "summary": "He was the leader of a combat patrol on 21 December 1944 near Grufflingen, Belgium, with the mission of driving German forces from dug-in positions in a heavily wooded area. As he advanced his light machinegun, a German Mark III tank emerged from the enemy position and was quickly immobilized by fire from American light tanks supporting the patrol. Two of the enemy tankmen attempted to abandon their vehicle but were killed by Cpl. Thorne's shots before they could jump to the ground. To complete the destruction of the tank and its crew, Cpl. Thorne left his covered position and crept forward alone through intense machinegun fire until close enough to toss 2 grenades into the tank's open turret, killing 2 more Germans. He returned across the same fire-beaten zone as heavy mortar fire began falling in the area, seized his machinegun and, without help, dragged it to the knocked-out tank and set it up on the vehicle's rear deck. …", "facts": [["Recipient", "Horace M. Thorne"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Near Grufflingen, Belgium"], ["Awarded", "Posthumously"]], "wiki": {"Horace M. Thorne": "Horace_M._Thorne"}},
  {"id": "1944-12-21-benjamin-jr-george", "date": "1944-12-21", "title": "Private First Class George Benjamin Jr.", "type": "loss", "theater": "Army", "location": {"name": "Leyte, Philippines (approx.)", "lat": 11.0, "lng": 124.85}, "zoom": 6, "summary": "He was a radio operator, advancing in the rear of his company as it engaged a well-defended Japanese strong point holding up the progress of the entire battalion. When a rifle platoon supporting a light tank hesitated in its advance, he voluntarily and with utter disregard for personal safety left his comparatively secure position and ran across bullet-whipped terrain to the tank, waving and shouting to the men of the platoon to follow. Carrying his bulky radio and armed only with a pistol, he fearlessly penetrated intense machinegun and rifle fire to the enemy position, where he killed 1 of the enemy in a foxhole and moved on to annihilate the crew of a light machinegun. Heedless of the terrific fire now concentrated on him, he continued to spearhead the assault, killing 2 more of the enemy and exhorting the other men to advance, until he fell mortally wounded. After being evacuated to an aid station, his first thought was still of the American advance. …", "facts": [["Recipient", "George Benjamin Jr."], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Leyte, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"George Benjamin Jr.": "George_Benjamin_Jr."}},
  {"id": "1944-12-21-currey-francis-s", "date": "1944-12-21", "title": "Sergeant Francis S. Currey", "type": "attack", "theater": "Army", "location": {"name": "Malmedy, Belgium", "lat": 50.4167, "lng": 6.0167}, "zoom": 9, "summary": "He was an automatic rifleman with the 3rd Platoon defending a strong point near Malmedy, Belgium, on 21 December 1944, when the enemy launched a powerful attack. Overrunning tank destroyers and antitank guns located near the strong point, German tanks advanced to the 3rd Platoon's position, and, after prolonged fighting, forced the withdrawal of this group to a nearby factory. Sgt. Currey found a bazooka in the building and crossed the street to secure rockets meanwhile enduring intense fire from enemy tanks and hostile infantrymen who had taken up a position at a house a short distance away. In the face of small-arms, machinegun, and artillery fire, he, with a companion, knocked out a tank with 1 shot. Moving to another position, he observed 3 Germans in the doorway of an enemy-held house. He killed or wounded all 3 with his automatic rifle. He emerged from cover and advanced alone to within 50 yards of the house, intent on wrecking it with rockets. …", "facts": [["Recipient", "Francis S. Currey"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Malmedy, Belgium"], ["Awarded", "G.O. No. 69, August 17, 1945"]], "wiki": {"Francis S. Currey": "Francis_S._Currey"}},
  {"id": "1944-12-22-dalessandro-peter-j", "date": "1944-12-22", "title": "Technical Sergeant Peter J. Dalessandro", "type": "attack", "theater": "Army", "location": {"name": "Near Kalterherberg, Germany (approx.)", "lat": 50.52, "lng": 6.21}, "zoom": 9, "summary": "He was with the 1st Platoon holding an important road junction on high ground near Kalterherberg, Germany, on 22 December 1944. In the early morning hours, the enemy after laying down an intense artillery and mortar barrage, followed through with an all-out attack that threatened to overwhelm the position. T/Sgt. Dalessandro, seeing that his men were becoming disorganized, braved the intense fire to move among them with words of encouragement. Advancing to a fully exposed observation post, he adjusted mortar fire upon the attackers, meanwhile firing upon them with his rifle and encouraging his men in halting and repulsing the attack. Later in the day the enemy launched a second determined attack. Once again, T/Sgt. Dalessandro, in the face of imminent death, rushed to his forward position and immediately called for mortar fire. After exhausting his rifle ammunition, he crawled 30 yards over exposed ground to secure a light machine gun, returned to his position, and fired upon the enemy at almost point blank range until the gun jammed. …", "facts": [["Recipient", "Peter J. Dalessandro"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Kalterherberg, Germany"], ["Awarded", "G.O. No. 73, August 30, 1945"]], "wiki": {"Peter J. Dalessandro": "Peter_J._Dalessandro"}},
  {"id": "1944-12-23-biddle-melvin-e", "date": "1944-12-23", "title": "Private First Class Melvin E. Biddle", "type": "attack", "theater": "Army", "location": {"name": "Near Soy, Belgium (approx.)", "lat": 50.29, "lng": 5.52}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity in action against the enemy near Soy, Belgium, on 23 and 24 December 1944. Serving as lead scout during an attack to relieve the enemy-encircled town of Hotton, he aggressively penetrated a densely wooded area, advanced 400 yards until he came within range of intense enemy rifle fire, and within 20 yards of enemy positions killed 3 snipers with unerring marksmanship. Courageously continuing his advance an additional 200 yards, he discovered a hostile machine-gun position and dispatched its 2 occupants. He then located the approximate position of a well-concealed enemy machine-gun nest, and crawling forward threw hand grenades which killed two Germans and fatally wounded a third. After signaling his company to advance, he entered a determined line of enemy defense, coolly and deliberately shifted his position, and shot 3 more enemy soldiers. …", "facts": [["Recipient", "Melvin E. Biddle"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Soy, Belgium"]], "wiki": {"Melvin E. Biddle": "Melvin_E._Biddle"}},
  {"id": "1944-12-23-kefurt-gus", "date": "1944-12-23", "title": "Staff Sergeant Gus Kefurt", "type": "loss", "theater": "Army", "location": {"name": "Near Bennwihr, France", "lat": 48.1442, "lng": 7.3261}, "zoom": 9, "summary": "He distinguished himself by conspicuous gallantry and intrepidity above and beyond the call of duty on 23 and 24 December 1944, near Bennwihr, France. Early in the attack S/Sgt. Kefurt jumped through an opening in a wall to be confronted by about 15 Germans. Although outnumbered he opened fire, killing 10 and capturing the others. During a seesaw battle which developed he effectively adjusted artillery fire on an enemy tank close to his position although exposed to small arms fire. When night fell he maintained a 3-man outpost in the center of the town in the middle of the German positions and successfully fought off several hostile patrols attempting to penetrate our lines. Assuming command of his platoon the following morning he led it in hand-to-hand fighting through the town until blocked by a tank. Using rifle grenades he forced surrender of its crew and some supporting infantry. He then continued his attack from house to house against heavy machinegun and rifle fire. …", "facts": [["Recipient", "Gus Kefurt"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Bennwihr, France"], ["Awarded", "Posthumously"]], "wiki": {"Gus Kefurt": "Gus_Kefurt"}},
  {"id": "1944-12-23-bolden-paul-l", "date": "1944-12-23", "title": "Staff Sergeant Paul L. Bolden", "type": "attack", "theater": "Army", "location": {"name": "Petit-Coo, Belgium (approx.)", "lat": 50.42, "lng": 5.86}, "zoom": 9, "summary": "He voluntarily attacked a formidable enemy strong point in Petit-Coo, Belgium, on 23 December 1944, when his company was pinned down by extremely heavy automatic and small-arms fire coming from a house 200 yards to the front. Mortar and tank artillery shells pounded the unit, when S/Sgt. Bolden and a comrade, on their own initiative, moved forward into a hail of bullets to eliminate the ever-increasing fire from the German position. Crawling ahead to close with what they knew was a powerfully armed, vastly superior force, the pair reached the house and took up assault positions, S/Sgt. Bolden under a window, his comrade across the street where he could deliver covering fire. In rapid succession, S/Sgt. Bolden hurled a fragmentation grenade and a white phosphorus grenade into the building; and then, fully realizing that he faced tremendous odds, rushed to the door, threw it open and fired into 35 SS troopers who were trying to reorganize themselves after the havoc wrought by the grenades. …", "facts": [["Recipient", "Paul L. Bolden"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Petit-Coo, Belgium"]], "wiki": {"Paul L. Bolden": "Paul_L._Bolden"}},
  {"id": "1944-12-24-castle-frederick-w", "date": "1944-12-24", "title": "Brigadier General Frederick W. Castle", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Germany (approx.)", "lat": 51.0, "lng": 10.0}, "zoom": 6, "summary": "He was air commander and leader of more than 2,000 heavy bombers in a strike against German airfields on 24 December 1944. En route to the target, the failure of 1 engine forced him to relinquish his place at the head of the formation. In order not to endanger friendly troops on the ground below, he refused to jettison his bombs to gain speed maneuverability. His lagging, unescorted aircraft became the target of numerous enemy fighters which ripped the left wing with cannon shells, set the oxygen system afire, and wounded 2 members of the crew. Repeated attacks started fires in 2 engines, leaving the Flying Fortress in imminent danger of exploding. Realizing the hopelessness of the situation, the bail-out order was given. Without regard for his personal safety he gallantly remained alone at the controls to afford all other crewmembers an opportunity to escape. Still another attack exploded gasoline tanks in the right wing, and the bomber plunged earthward, carrying Gen. Castle to his death. …", "facts": [["Recipient", "Frederick W. Castle"], ["Rank", "Brigadier General"], ["Service", "Army Air Forces"], ["Place of action", "Germany"], ["Awarded", "Posthumously, G.O. No. 22, February 28, 1947"]], "wiki": {"Frederick W. Castle": "Frederick_Walker_Castle"}},
  {"id": "1944-12-25-mcguire-jr-thomas-b", "date": "1944-12-25", "title": "Major Thomas B. McGuire Jr.", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Over Luzon, Philippines (approx.)", "lat": 16.0, "lng": 121.0}, "zoom": 6, "summary": "He fought with conspicuous gallantry and intrepidity over Luzon, Philippine Islands. Voluntarily, he led a squadron of 15 P-38's as top cover for heavy bombers striking Mabalacat Airdrome, where his formation was attacked by 20 aggressive Japanese fighters. In the ensuing action he repeatedly flew to the aid of embattled comrades, driving off enemy assaults while himself under attack and at times outnumbered 3 to 1, and even after his guns jammed, continuing the fight by forcing a hostile plane into his wingman's line of fire. Before he started back to his base he had shot down 3 Zeros. The next day he again volunteered to lead escort fighters on a mission to strongly defended Clark Field. During the resultant engagement he again exposed himself to attacks so that he might rescue a crippled bomber. …", "facts": [["Recipient", "Thomas B. McGuire Jr."], ["Rank", "Major"], ["Service", "Army Air Forces"], ["Place of action", "Over Luzon, Philippines"], ["Awarded", "Posthumously, G.O. No. 24, March 7, 1946"]], "wiki": {"Thomas B. McGuire Jr.": "Thomas_McGuire"}},
  {"id": "1944-12-25-wiedorfer-paul-j", "date": "1944-12-25", "title": "Private Paul J. Wiedorfer", "type": "attack", "theater": "Army", "location": {"name": "Near, Chaumont, Belgium (approx.)", "lat": 49.99, "lng": 5.66}, "zoom": 9, "summary": "He alone made it possible for his company to advance until its objective was seized. Company G had cleared a wooded area of snipers, and 1 platoon was advancing across an open clearing toward another wood when it was met by heavy machinegun fire from 2 German positions dug in at the edge of the second wood. These positions were flanked by enemy riflemen. The platoon took cover behind a small ridge approximately 40 yards from the enemy position. There was no other available protection and the entire platoon was pinned down by the German fire. It was about noon and the day was clear, but the terrain extremely difficult due to a 3-inch snowfall the night before over ice-covered ground. Pvt. Wiedorfer, realizing that the platoon advance could not continue until the 2 enemy machinegun nests were destroyed, voluntarily charged alone across the slippery open ground with no protecting cover of any kind. …", "facts": [["Recipient", "Paul J. Wiedorfer"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near, Chaumont, Belgium"]], "wiki": {"Paul J. Wiedorfer": "Paul_J._Wiedorfer"}},
  {"id": "1944-12-26-fox-john-r", "date": "1944-12-26", "title": "First Lieutenant John R. Fox", "type": "loss", "theater": "Army", "location": {"name": "Near Sommocolonia, Italy", "lat": 44.0922, "lng": 10.4914}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty: First Lieutenant John R. Fox distinguished himself by extraordinary heroism at the risk of his own life on 26 December 1944 in the Serchio River Valley Sector, in vicinity of Sommocolonia, Italy. Lieutenant Fox was a member of Cannon Company, 366th Infantry, 92nd Infantry Division, acting as a forward observer, while attached to the 598th Field Artillery Battalion. Christmas Day in the Serchio Valley was spent in positions which had been occupied for some weeks. During Christmas night, there was a gradual influx of enemy soldiers in civilian clothes and by early morning the town was largely in enemy hands. An organized attack by uniformed German formations was launched around 0400 hours, 26 December 1944. Reports were received that the area was being heavily shelled by everything the Germans had, and although most of the U.S. …", "facts": [["Recipient", "John R. Fox"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Sommocolonia, Italy"], ["Awarded", "Posthumously"]], "wiki": {"John R. Fox": "John_R._Fox"}},
  {"id": "1944-12-26-ware-keith-l", "date": "1944-12-26", "title": "Lieutenant Colonel Keith L. Ware", "type": "attack", "theater": "Army", "location": {"name": "Near Sigolsheim, France", "lat": 48.1347, "lng": 7.3017}, "zoom": 9, "summary": "Commanding the 1st Battalion, 15th Infantry, attacking a strongly held enemy position on a hill near Sigolsheim, France, on 26 December 1944, found that 1 of his assault companies had been stopped and forced to dig in by a concentration of enemy artillery, mortar, and machinegun fire. The company had suffered casualties in attempting to take the hill. Realizing that his men must be inspired to new courage, Lt. Col. Ware went forward 150 yards beyond the most forward elements of his command, and for 2 hours reconnoitered the enemy positions, deliberately drawing fire upon himself which caused the enemy to disclose his dispositions. Returning to his company, he armed himself with an automatic rifle and boldly advanced upon the enemy, followed by 2 officers, 9 enlisted men, and a tank. Approaching an enemy machinegun, Lt. Col. Ware shot 2 German riflemen and fired tracers into the emplacement, indicating its position to his tank, which promptly knocked the gun out of action. Lt. Col. …", "facts": [["Recipient", "Keith L. Ware"], ["Rank", "Lieutenant Colonel"], ["Service", "Army"], ["Place of action", "Near Sigolsheim, France"]], "wiki": {"Keith L. Ware": "Keith_L._Ware"}},
  {"id": "1944-12-26-hendrix-james-r", "date": "1944-12-26", "title": "Private James R. Hendrix", "type": "attack", "theater": "Army", "location": {"name": "Near Assenois, Belgium (approx.)", "lat": 49.97, "lng": 5.69}, "zoom": 9, "summary": "On the night of 26 December 1944, near Assenois, Belgium, he was with the leading element engaged in the final thrust to break through to the besieged garrison at Bastogne when halted by a fierce combination of artillery and small arms fire. He dismounted from his half-track and advanced against two 88mm. guns, and, by the ferocity of his rifle fire, compelled the guncrews to take cover and then to surrender. Later in the attack he again left his vehicle, voluntarily, to aid 2 wounded soldiers, helpless and exposed to intense machinegun fire. Effectively silencing 2 hostile machineguns, he held off the enemy by his own fire until the wounded men were evacuated. Pvt. Hendrix again distinguished himself when he hastened to the aid of still another soldier who was trapped in a burning half-track. Braving enemy sniper fire and exploding mines and ammunition in the vehicle, he extricated the wounded man and extinguished his flaming clothing, thereby saving the life of his fellow soldier. Pvt. …", "facts": [["Recipient", "James R. Hendrix"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Assenois, Belgium"]], "wiki": {"James R. Hendrix": "James_R._Hendrix"}},
  {"id": "1944-12-27-whiteley-eli-l", "date": "1944-12-27", "title": "First Lieutenant Eli L. Whiteley", "type": "attack", "theater": "Army", "location": {"name": "Sigolsheim, France", "lat": 48.1347, "lng": 7.3017}, "zoom": 9, "summary": "While leading his platoon on December 27, 1944, in savage house-to-house fighting through the fortress town of Sigolsheim, France, he attacked a building through a street swept by withering mortar and automatic weapons fire. He was hit and severely wounded in the arm and shoulder; but he charged into the house alone and killed its 2 defenders. Hurling smoke and fragmentation grenades before him, he reached the next house and stormed inside, killing 2 and capturing 11 of the enemy. He continued leading his platoon in the extremely dangerous task of clearing hostile troops from strong points along the street until he reached a building held by fanatical Nazi troops. Although suffering from wounds which had rendered his left arm useless, he advanced on this strongly defended house, and after blasting out a wall with bazooka fire, charged through a hail of bullets. …", "facts": [["Recipient", "Eli L. Whiteley"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Sigolsheim, France"]], "wiki": {"Eli L. Whiteley": "Eli_L._Whiteley"}},
  {"id": "1945-01-01-macgillivary-charles-a", "date": "1945-01-01", "title": "Sergeant Charles A. MacGillivary", "type": "attack", "theater": "Army", "location": {"name": "Near Woelfling, France (approx.)", "lat": 49.1, "lng": 7.17}, "zoom": 9, "summary": "He led a squad when his unit moved forward in darkness to meet the threat of a breakthrough by elements of the 17th German Panzer Grenadier Division. Assigned to protect the left flank, he discovered hostile troops digging in. As he reported this information, several German machine guns opened fire, stopping the American advance. Knowing the position of the enemy, Sgt. MacGillivary volunteered to knock out one of the guns while another company closed in from the right to assault the remaining strongpoints. He circled from the left through woods and snow, carefully worked his way to the emplacement, and shot the two camouflaged gunners at a range of three feet as other enemy forces withdrew. Early in the afternoon of the same day, Sgt. MacGillivary was dispatched on reconnaissance and found that Company I was being opposed by about six machine guns reinforcing a company of fanatically fighting Germans. His unit began to attack but was pinned down by furious automatic and small-arms fire. …", "facts": [["Recipient", "Charles A. MacGillivary"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Woelfling, France"]], "wiki": {"Charles A. MacGillivary": "Charles_Andrew_MacGillivary"}},
  {"id": "1945-01-03-turner-george-b", "date": "1945-01-03", "title": "Private First Class George B. Turner", "type": "attack", "theater": "Marine Corps", "location": {"name": "Philippsbourg, France", "lat": 48.98, "lng": 7.57}, "zoom": 9, "summary": "His MOH citation read: “The President of the United States takes pleasure in awarding the MEDAL of HONOR to PRIVATE FIRST CLASS GEORGE B. TURNER, BTRY. C, 499th ARMORED FIELD ARTILLERY BN. UNITED STATES ARMY for service as set forth in the following CITATION: :Private Turner, at Phillippsbourg, France, on 3 January 1945 was cut off from his artillery unit by an enemy armored infantry attack. Coming upon a friendly infantry company withdrawing under the vicious onslaught, he noticed two German tanks and approximately seventy-five supporting foot soldiers advancing down the main street of the village. Seizing a rocket launcher, he advanced under intense small arms and cannon fire to meet the tanks and standing in the middle of the road, fired at them, destroying one and disabling the second. From a nearby half-track he then dismounted a machine gun, placed it in the open street and fired into the enemy infantrymen, killing or wounding a great number and breaking up the attack. …", "facts": [["Recipient", "George B. Turner"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Philippsbourg, France"]], "wiki": {"George B. Turner": "George_B._Turner"}},
  {"id": "1945-01-04-jachman-isadore-s", "date": "1945-01-04", "title": "Staff Sergeant Isadore S. Jachman", "type": "loss", "theater": "Army", "location": {"name": "Flamierge, Belgium (approx.)", "lat": 50.02, "lng": 5.62}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity above and beyond the call of duty at Flamierge, Belgium, on 4 January 1945, when his company was pinned down by enemy artillery, mortar, and small arms fire, 2 hostile tanks attacked the unit, inflicting heavy. casualties. S/Sergeant. Jachman, seeing the desperate plight of his comrades, left his place of cover and with total disregard for his own safety dashed across open ground through a hail of fire and seizing a bazooka from a fallen comrade advanced on the tanks, which concentrated their fire on him. Firing the weapon alone, he damaged one and forced both to retire. S/Sergeant. Jachman's heroic action, in which he suffered fatal wounds, disrupted the entire enemy attack, reflecting the highest credit upon himself and the parachute infantry.", "facts": [["Recipient", "Isadore S. Jachman"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Flamierge, Belgium"], ["Awarded", "Posthumously"]], "wiki": {"Isadore S. Jachman": "Isadore_S._Jachman"}},
  {"id": "1945-01-06-davis-george-f", "date": "1945-01-06", "title": "Commander George F. Davis", "type": "loss", "theater": "Navy", "location": {"name": "USS Walke, Lingayen Gulf, Luzon, Philippines", "lat": 16.2833, "lng": 120.2}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Commanding Officer of the U.S.S. Walke engaged in a detached mission in support of minesweeping operations to clear the waters for entry of our heavy surface and amphibious forces preparatory to the invasion of Lingayen Gulf, Luzon, Philippine Islands, 6 January 1945. Operating without gun support of other surface ships when four Japanese suicide planes were detected flying low overland to attack simultaneously, Commander Davis boldly took his position in the exposed wings of the bridge and directed control to pick up the leading plane and open fire. Alert and fearless as the Walkes deadly fire sent the first target crashing into the water and caught the second as it passed close over the bridge to plunge into the sea off portside, he remained steadfast in the path of the third plane plunging swiftly to crash the after end of the bridge structure. …", "facts": [["Recipient", "George F. Davis"], ["Rank", "Commander"], ["Service", "Navy"], ["Place of action", "USS Walke, Lingayen Gulf, Luzon, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"George F. Davis": "George_Fleming_Davis"}},
  {"id": "1945-01-07-shoup-curtis-f", "date": "1945-01-07", "title": "Staff Sergeant Curtis F. Shoup", "type": "loss", "theater": "Army", "location": {"name": "Near Tillet, Belgium (approx.)", "lat": 50.0, "lng": 5.53}, "zoom": 9, "summary": "On January 7, 1945, near Tillet, Belgium, his company attacked German troops on rising ground. Intense hostile machinegun fire pinned down and threatened to annihilate the American unit in an exposed position where frozen ground made it impossible to dig in for protection. Heavy mortar and artillery fire from enemy batteries was added to the storm of destruction falling on the Americans. Realizing that the machinegun must be silenced at all costs, S/Sgt. Shoup, armed with an automatic rifle, crawled to within 75 yards of the enemy emplacement. He found that his fire was ineffective from this position, and completely disregarding his own safety, stood up and grimly strode ahead into the murderous stream of bullets, firing his low-held weapon as he went. He was hit several times and finally was knocked to the ground. But he struggled to his feet and staggered forward until close enough to hurl a grenade, wiping out the enemy machinegun nest with his dying action. …", "facts": [["Recipient", "Curtis F. Shoup"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Tillet, Belgium"], ["Awarded", "Posthumously, G.O. No. 60, July 25, 1945"]], "wiki": {"Curtis F. Shoup": "Curtis_F._Shoup"}},
  {"id": "1945-01-08-turner-day-g", "date": "1945-01-08", "title": "Sergeant Day G. Turner", "type": "loss", "theater": "Army", "location": {"name": "Dahl, Luxembourg (approx.)", "lat": 49.94, "lng": 5.98}, "zoom": 9, "summary": "He commanded a 9-man squad with the mission of holding a critical flank position. When overwhelming numbers of the enemy attacked under cover of withering artillery, mortar, and rocket fire, he withdrew his squad into a nearby house, determined to defend it to the last man. The enemy attacked again and again and were repulsed with heavy losses. Supported by direct tank fire, they finally gained entrance, but the intrepid sergeant refused to surrender although 5 of his men were wounded and 1 was killed. He boldly flung a can of flaming oil at the first wave of attackers, dispersing them, and fought doggedly from room to room, closing with the enemy in fierce hand-to-hand encounters. He hurled handgrenade for handgrenade, bayoneted 2 fanatical Germans who rushed a doorway he was defending and fought on with the enemy's weapons when his own ammunition was expended. The savage fight raged for 4 hours, and finally, when only 3 men of the defending squad were left unwounded, the enemy surrendered. …", "facts": [["Recipient", "Day G. Turner"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Dahl, Luxembourg"], ["Awarded", "Posthumously"]], "wiki": {"Day G. Turner": "Day_G._Turner"}},
  {"id": "1945-01-08-carey-jr-charles-f", "date": "1945-01-08", "title": "Technical Sergeant Charles F. Carey Jr.", "type": "loss", "theater": "Army", "location": {"name": "Rimling, France", "lat": 49.0967, "lng": 7.265}, "zoom": 9, "summary": "He was in command of an antitank platoon when about 200 enemy infantrymen and 12 tanks attacked his battalion, overrunning part of its position. After losing his guns, T/Sgt. Carey, acting entirely on his own initiative, organized a patrol and rescued 2 of his squads from a threatened sector, evacuating those who had been wounded. He organized a second patrol and advanced against an enemy-held house from which vicious fire issued, preventing the free movement of our troops. Covered by fire from his patrol, he approached the house, killed 2 snipers with his rifle, and threw a grenade in the door. He entered alone and a few minutes later emerged with 16 prisoners. Acting on information he furnished, the American forces were able to capture an additional 41 Germans in adjacent houses. He assembled another patrol, and, under covering fire, moved to within a few yards of an enemy tank and damaged it with a rocket. …", "facts": [["Recipient", "Charles F. Carey Jr."], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Rimling, France"], ["Awarded", "Posthumously"]], "wiki": {"Charles F. Carey Jr.": "Charles_F._Carey_Jr."}},
  {"id": "1945-01-08-dunham-russell-e", "date": "1945-01-08", "title": "Technical Sergeant Russell E. Dunham", "type": "attack", "theater": "Army", "location": {"name": "Near Kayserberg, France (approx.)", "lat": 48.14, "lng": 7.26}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of life above and beyond the call of duty. At about 1430 hours on 8 January 1945, during an attack on Hill 616, near Kayserberg, France, T/Sgt. Dunham single-handedly assaulted 3 enemy machine guns. Wearing a white robe made of a mattress cover, carrying 12 carbine magazines and with a dozen hand grenades snagged in his belt, suspenders, and buttonholes, T/Sgt. Dunham advanced in the attack up a snow-covered hill under fire from 2 machine guns and supporting riflemen. His platoon 35 yards behind him, T/Sgt. Dunham crawled 75 yards under heavy direct fire toward the timbered emplacement shielding the left machine gun. As he jumped to his feet 10 yards from the gun and charged forward, machine gun fire tore through his camouflage robe and a rifle bullet seared a 10-inch gash across his back sending him spinning 15 yards down hill into the snow. …", "facts": [["Recipient", "Russell E. Dunham"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Kayserberg, France"], ["Awarded", "G.O. No. 37, 11 May 1945"]], "wiki": {"Russell E. Dunham": "Russell_E._Dunham"}},
  {"id": "1945-01-09-bertoldo-vito-r", "date": "1945-01-09", "title": "Master Sergeant Vito R. Bertoldo", "type": "attack", "theater": "Army", "location": {"name": "Hatten, France (approx.)", "lat": 48.9, "lng": 7.98}, "zoom": 9, "summary": "He fought with extreme gallantry while guarding 2 command posts against the assault of powerful infantry and armored forces which had overrun the battalion's main line of resistance. On the close approach of enemy soldiers, he left the protection of the building he defended and set up his gun in the street, there to remain for almost 12 hours driving back attacks while in full view of his adversaries and completely exposed to 88-mm., machinegun and small-arms fire. He moved back inside the command post, strapped his machinegun to a table and covered the main approach to the building by firing through a window, remaining steadfast even in the face of 88-mm. fire from tanks only 75 yards away. One shell blasted him across the room, but he returned to his weapon. …", "facts": [["Recipient", "Vito R. Bertoldo"], ["Rank", "Master Sergeant"], ["Service", "Army"], ["Place of action", "Hatten, France"]], "wiki": {"Vito R. Bertoldo": "Vito_Bertoldo"}},
  {"id": "1945-01-11-shomo-william-a", "date": "1945-01-11", "title": "Major William A. Shomo", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Over Luzon, Philippines (approx.)", "lat": 16.0, "lng": 121.0}, "zoom": 6, "summary": "Two days after his first victory, on January 11, 1945, Captain Shomo and his wingman, Lieutenant Paul Lipscomb, were heading north for the Japanese airfields at Tuguegarao, Aparri, and Laoag, when they saw several enemy planes flying south at about 2500 ft. Despite being outnumbered, they immediately pulled Immelman turns and found themselves behind 11 Kawasaki Ki-61 \"Tonys\" and one Nakajima Ki-44 \"Tojo\" escorting a Mitsubishi G4M \"Betty\" bomber. On their first pass through the formation, Shomo closed to less than 40 yd before opening fire. He shot down four Tonys, then came up under the bomber, firing into its belly. The bomber caught fire and began to lose altitude as its pilot attempted to crash-land the plane. Two of the Tonys escorting the bomber stayed with it as it went down. Shomo pulled up in a tight vertical spiral to gain altitude while the Tojo turned to engage him. The Japanese fighter fired until it stalled and slipped into the clouds. …", "facts": [["Recipient", "William A. Shomo"], ["Rank", "Major"], ["Service", "Army Air Forces"], ["Place of action", "Over Luzon, Philippines"]], "wiki": {"William A. Shomo": "William_A._Shomo"}},
  {"id": "1945-01-11-gammon-archer-t", "date": "1945-01-11", "title": "Staff Sergeant Archer T. Gammon", "type": "loss", "theater": "Army", "location": {"name": "Near Bastogne, Belgium", "lat": 50.0042, "lng": 5.72}, "zoom": 9, "summary": "He charged 30 yards through hip-deep snow to knock out a machinegun and its 3-man crew with grenades, saving his platoon from being decimated and allowing it to continue its advance from an open field into some nearby woods. The platoon's advance through the woods had only begun when a machinegun supported by riflemen opened fire and a Tiger Royal tank sent 88mm. shells screaming at the unit from the left flank. S/Sgt. Gammon, disregarding all thoughts of personal safety, rushed forward, then cut to the left, crossing the width of the platoon's skirmish line in an attempt to get within grenade range of the tank and its protecting foot troops. Intense fire was concentrated on him by riflemen and the machinegun emplaced near the tank. He charged the automatic weapon, wiped out its crew of 4 with grenades, and, with supreme daring, advanced to within 25 yards of the armored vehicle, killing 2 hostile infantrymen with rifle fire as he moved forward. …", "facts": [["Recipient", "Archer T. Gammon"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Bastogne, Belgium"], ["Awarded", "Posthumously"]], "wiki": {"Archer T. Gammon": "Archer_T._Gammon"}},
  {"id": "1945-01-12-laws-robert-e", "date": "1945-01-12", "title": "Staff Sergeant Robert E. Laws", "type": "attack", "theater": "Army", "location": {"name": "Pangasinan Province, Luzon, Philippines", "lat": 15.92, "lng": 120.33}, "zoom": 9, "summary": "He led the assault squad when Company G attacked enemy hill positions. The enemy force, estimated to be a reinforced infantry company, was well supplied with machineguns, ammunition, grenades, and blocks of TNT and could be attacked only across a narrow ridge 70 yards long. At the end of this ridge an enemy pillbox and rifle positions were set in rising ground. Covered by his squad, S/Sgt Laws traversed the hogback through vicious enemy fire until close to the pillbox, where he hurled grenades at the fortification. Enemy grenades wounded him, but he persisted in his assault until 1 of his missiles found its mark and knocked out the pillbox. With more grenades, passed to him by members of his squad who had joined him, he led the attack on the entrenched riflemen. In the advance up the hill, he suffered additional wounds in both arms and legs, about the body and in the head, as grenades and TNT charges exploded near him. …", "facts": [["Recipient", "Robert E. Laws"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Pangasinan Province, Luzon, Philippines"]], "wiki": {"Robert E. Laws": "Robert_E._Laws"}},
  {"id": "1945-01-15-beyer-arthur-o", "date": "1945-01-15", "title": "Corporal Arthur O. Beyer", "type": "attack", "theater": "Army", "location": {"name": "Near Arloncourt, Belgium (approx.)", "lat": 50.04, "lng": 5.79}, "zoom": 9, "summary": "He displayed conspicuous gallantry in action. His platoon, in which he was a tank-destroyer gunner, was held up by antitank, machinegun, and rifle fire from enemy troops dug in along a ridge about 200 yards to the front. Noting a machinegun position in this defense line, he fired upon it with his 76-mm. gun killing 1 man and silencing the weapon. He dismounted from his vehicle and, under direct enemy observation, crossed open ground to capture the 2 remaining members of the crew. Another machinegun, about 250 yards to the left, continued to fire on him. Through withering fire, he advanced on the position. Throwing a grenade into the emplacement, he killed 1 crewmember and again captured the 2 survivors. He was subjected to concentrated small-arms fire but, with great bravery, he worked his way a quarter mile along the ridge, attacking hostile soldiers in their foxholes with his carbine and grenades. …", "facts": [["Recipient", "Arthur O. Beyer"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Near Arloncourt, Belgium"]], "wiki": {"Arthur O. Beyer": "Arthur_O._Beyer"}},
  {"id": "1945-01-18-parrish-laverne", "date": "1945-01-18", "title": "Technician 4th Grade Laverne Parrish", "type": "loss", "theater": "Army", "location": {"name": "Binalonan, Luzon, Philippines", "lat": 16.05, "lng": 120.6}, "zoom": 9, "summary": "He was medical aid man with Company C during the fighting in Binalonan, Luzon, Philippine Islands. On the 18th, he observed 2 wounded men under enemy fire and immediately went to their rescue. After moving 1 to cover, he crossed 25 yards of open ground to administer aid to the second. In the early hours of the 24th, his company, crossing an open field near San Manuel, encountered intense enemy fire and was ordered to withdraw to the cover of a ditch. While treating the casualties, Technician Parrish observed 2 wounded still in the field. Without hesitation he left the ditch, crawled forward under enemy fire, and in 2 successive trips brought both men to safety. He next administered aid to 12 casualties in the same field, crossing and re-crossing the open area raked by hostile fire. Making successive trips, he then brought 3 wounded in to cover. …", "facts": [["Recipient", "Laverne Parrish"], ["Rank", "Technician 4th Grade"], ["Service", "Army"], ["Place of action", "Binalonan, Luzon, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Laverne Parrish": "Laverne_Parrish"}},
  {"id": "1945-01-23-oresko-nicholas", "date": "1945-01-23", "title": "Master Sergeant Nicholas Oresko", "type": "attack", "theater": "Army", "location": {"name": "Near Tettingen, Germany", "lat": 49.4667, "lng": 6.3667}, "zoom": 9, "summary": "M/Sgt. Oresko was a platoon leader with Company C, in an attack against strong enemy positions. Deadly automatic fire from the flanks pinned down his unit. Realizing that a machinegun in a nearby bunker must be eliminated, he swiftly worked ahead alone, braving bullets which struck about him, until close enough to throw a grenade into the German position. He rushed the bunker and, with pointblank rifle fire, killed all the hostile occupants who survived the grenade blast. Another machinegun opened up on him, knocking him down and seriously wounding him in the hip. Refusing to withdraw from the battle, he placed himself at the head of his platoon to continue the assault. As withering machinegun and rifle fire swept the area, he struck out alone in advance of his men to a second bunker. With a grenade, he crippled the dug-in machinegun defending this position and then wiped out the troops manning it with his rifle, completing his second self-imposed, 1-man attack. …", "facts": [["Recipient", "Nicholas Oresko"], ["Rank", "Master Sergeant"], ["Service", "Army"], ["Place of action", "Near Tettingen, Germany"]], "wiki": {"Nicholas Oresko": "Nicholas_Oresko"}},
  {"id": "1945-01-24-conner-garlin-murl", "date": "1945-01-24", "title": "First Lieutenant Garlin Murl Conner", "type": "attack", "theater": "Army", "location": {"name": "Houssen, France", "lat": 48.1264, "lng": 7.3789}, "zoom": 9, "summary": "First Lieutenant Garlin M. Conner distinguished himself by acts of gallantry and intrepidity while serving with Company K, 3d Battalion, 7th Infantry Regiment, 3d Infantry Division. On the morning of January 24, 1945, near the town of Houssen, France, German forces ferociously counterattacked the front left flank of the 7th Infantry Regiment with 600 infantry troops, six Mark VI tanks, and tank destroyers. Lieutenant Conner, having recently returned to his unit after recovering from a wound received in an earlier battle, was working as the Intelligence Officer in the 3d Battalion Command Post at the time of the attack. Understanding the devastating effect that the advancing enemy armor could have on the Battalion, Lieutenant Conner immediately volunteered to run straight into the heart of the enemy assault to get to a position from which he could direct friendly artillery on the advancing enemy forces. …", "facts": [["Recipient", "Garlin Murl Conner"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Houssen, France"]], "wiki": {"Garlin Murl Conner": "Garlin_Murl_Conner"}},
  {"id": "1945-01-25-valdez-jose-f", "date": "1945-01-25", "title": "Private First Class Jose F. Valdez", "type": "loss", "theater": "Army", "location": {"name": "Near Rosenkrantz, France (approx.)", "lat": 48.15, "lng": 7.38}, "zoom": 9, "summary": "He was on outpost duty with 5 others when the enemy counterattacked with overwhelming strength. From his position near some woods 500 yards beyond the American lines he observed a hostile tank about 75 yards away, and raked it with automatic rifle fire until it withdrew. Soon afterward he saw 3 Germans stealthily approaching through the woods. Scorning cover as the enemy soldiers opened up with heavy automatic weapons fire from a range of 30 yards, he engaged in a fire fight with the attackers until he had killed all 3. The enemy quickly launched an attack with 2 full companies of infantrymen, blasting the patrol with murderous concentrations of automatic and rifle fire and beginning an encircling movement which forced the patrol leader to order a withdrawal. Despite the terrible odds, Pfc. Valdez immediately volunteered to cover the maneuver, and as the patrol 1 by 1 plunged through a hail of bullets toward the American lines, he fired burst after burst into the swarming enemy. …", "facts": [["Recipient", "Jose F. Valdez"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Rosenkrantz, France"], ["Awarded", "Posthumously, G.O. No. 16, February 8, 1946"]], "wiki": {"Jose F. Valdez": "Jose_F._Valdez"}},
  {"id": "1945-01-26-murphy-audie-l", "date": "1945-01-26", "title": "Second Lieutenant Audie L. Murphy", "type": "attack", "theater": "Marine Corps", "location": {"name": "Near Holtzwihr, France", "lat": 48.1131, "lng": 7.4214}, "zoom": 9, "summary": "Commanding Company B near Holtzwihr as six German tanks and waves of infantry attacked, he ordered his men back to the woods and stayed forward to direct artillery fire by telephone. He then climbed onto a burning tank destroyer and, alone and exposed on three sides, held off the attack for an hour with its machine gun, killing or wounding about 50 Germans. Wounded in the leg, he fought on until his ammunition ran out, then rejoined his company and led a counterattack that drove the Germans back.", "facts": [["Recipient", "Audie L. Murphy"], ["Rank", "Second Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Near Holtzwihr, France"]], "wiki": {"Audie L. Murphy": "Audie_Murphy"}},
  {"id": "1945-01-27-edmonds-roddie", "date": "1945-01-27", "title": "Master Sergeant Roddie Edmonds", "type": "attack", "theater": "Army", "location": {"name": "Ziegenhain, Germany", "lat": 50.6761, "lng": 7.5256}, "zoom": 9, "summary": "Master Sergeant Roderick W. Edmonds distinguished himself by acts of gallantry and intrepidity above and beyond the call of duty from January 27, 1945, to March 30, 1945, as a prisoner of war in Germany, while assigned to Headquarters and Headquarters Company, 422d Infantry Regiment, 106th Infantry Division. Upon arrival at Stalag IXA in Ziegenhain, Germany, he was soon put to the test as Senior Non-Commissioned Officer. On the evening of January 26, 1945, the Germans announced that only Jewish-American prisoners would fall out for roll call the following morning, at the threat of execution. Master Sergeant Edmonds quickly understood that segregating more than 200 Jewish-American prisoners of war would likely result in their persecution and possible death, so he directed his senior leaders to have all 1,200 American prisoners present themselves for roll call. The following morning, the Nazi Commandant became incredulous after realizing that so many Americans were standing in formation. …", "facts": [["Recipient", "Roddie Edmonds"], ["Rank", "Master Sergeant"], ["Service", "Army"], ["Place of action", "Ziegenhain, Germany"]], "wiki": {"Roddie Edmonds": "Roddie_Edmonds"}},
  {"id": "1945-01-29-funk-jr-leonard-a", "date": "1945-01-29", "title": "First Sergeant Leonard A. Funk Jr.", "type": "attack", "theater": "Army", "location": {"name": "Holzheim, Belgium (approx.)", "lat": 50.36, "lng": 6.3}, "zoom": 9, "summary": "He distinguished himself by gallant, intrepid actions against the enemy. After advancing 15 miles in a driving snowstorm, the American force prepared to attack through waist-deep drifts. The company executive officer became a casualty, and 1st Sgt. Funk immediately assumed his duties, forming headquarters soldiers into a combat unit for an assault in the face of direct artillery shelling and harassing fire from the right flank. Under his skillful and courageous leadership, this miscellaneous group and the 3d Platoon attacked 15 houses, cleared them, and took 30 prisoners without suffering a casualty. The fierce drive of Company C quickly overran Holzheim, netting some 80 prisoners, who were placed under a 4-man guard, all that could be spared, while the rest of the understrength unit went about mopping up isolated points of resistance. An enemy patrol, by means of a ruse, succeeded in capturing the guards and freeing the prisoners, and had begun preparations to attack Company C from the rear when 1st Sgt. …", "facts": [["Recipient", "Leonard A. Funk Jr."], ["Rank", "First Sergeant"], ["Service", "Army"], ["Place of action", "Holzheim, Belgium"]], "wiki": {"Leonard A. Funk Jr.": "Leonard_A._Funk_Jr."}},
  {"id": "1945-01-30-kelley-jonah-e", "date": "1945-01-30", "title": "Staff Sergeant Jonah E. Kelley", "type": "loss", "theater": "Navy", "location": {"name": "Kesternich, Germany (approx.)", "lat": 50.61, "lng": 6.31}, "zoom": 9, "summary": "In charge of the leading squad of Company E, he heroically spearheaded the attack in furious house-to-house fighting. Early on 30 January, he led his men through intense mortar and small arms fire in repeated assaults on barricaded houses. Although twice wounded, once when struck in the back, the second time when a mortar shell fragment passed through his left hand and rendered it practically useless, he refused to withdraw and continued to lead his squad after hasty dressings had been applied. His serious wounds forced him to fire his rifle with 1 hand, resting it on rubble or over his left forearm. To blast his way forward with hand grenades, he set aside his rifle to pull the pins with his teeth while grasping the missiles with his good hand. Despite these handicaps, he created tremendous havoc in the enemy ranks. He rushed l house, killing 3 of the enemy and clearing the way for his squad to advance. …", "facts": [["Recipient", "Jonah E. Kelley"], ["Rank", "Staff Sergeant"], ["Service", "Navy"], ["Place of action", "Kesternich, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Jonah E. Kelley": "Jonah_Edward_Kelley"}},
  {"id": "1945-02-01-bennett-edward-a", "date": "1945-02-01", "title": "Corporal Edward A. Bennett", "type": "attack", "theater": "Army", "location": {"name": "Heckhuscheid, Germany", "lat": 50.1786, "lng": 6.2233}, "zoom": 9, "summary": "He was advancing with Company B across open ground to assault Heckhuscheid, Germany, just after dark when vicious enemy machinegun fire from a house on the outskirts of the town pinned down the group and caused several casualties. He began crawling to the edge of the field in an effort to flank the house, persisting in this maneuver even when the hostile machinegunners located him by the light of burning buildings and attempted to cut him down as he made for the protection of some trees. Reaching safety, he stealthily made his way by a circuitous route to the rear of the building occupied by the German gunners. With his trench knife he killed a sentry on guard there and then charged into the darkened house. In a furious hand-to-hand struggle he stormed about a single room which harbored 7 Germans. Three he killed with rifle fire, another he clubbed to death with the butt of his gun, and the 3 others he dispatched with his .45 caliber pistol. …", "facts": [["Recipient", "Edward A. Bennett"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Heckhuscheid, Germany"]], "wiki": {"Edward A. Bennett": "Edward_A._Bennett"}},
  {"id": "1945-02-01-deleau-jr-emile", "date": "1945-02-01", "title": "Sergeant Emile Deleau Jr.", "type": "loss", "theater": "Army", "location": {"name": "Oberhoffen, France (approx.)", "lat": 48.78, "lng": 7.86}, "zoom": 9, "summary": "He led a squad in the night attack on Oberhoffen, France, where fierce house-to-house fighting took place. After clearing 1 building of opposition, he moved his men toward a second house from which heavy machine-gun fire came. He courageously exposed himself to hostile bullets and, firing his submachinegun as he went, advanced steadily toward the enemy position until close enough to hurl grenades through a window, killing 3 Germans and wrecking their gun. His progress was stopped by heavy rifle and machinegun fire from another house. Sgt. Deleau dashed through the door with his gun blazing. Within, he captured 10 Germans. The squad then took up a position for the night and awaited daylight to resume the attack. At dawn of 2 February Sgt. Deleau pressed forward with his unit, killing 2 snipers as he advanced to a point where machinegun fire from a house barred the way. Despite vicious small-arms fire, Sgt. …", "facts": [["Recipient", "Emile Deleau Jr."], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Oberhoffen, France"], ["Awarded", "Posthumously, G.O. No. 60, July 25, 1945"]], "wiki": {"Emile Deleau Jr.": "Emile_Deleau_Jr."}},
  {"id": "1945-02-02-knight-jack-l", "date": "1945-02-02", "title": "First Lieutenant Jack L. Knight", "type": "loss", "theater": "Army", "location": {"name": "Near LoiKang, Burma (approx.)", "lat": 23.95, "lng": 97.65}, "zoom": 9, "summary": "He led his cavalry troop against heavy concentrations of enemy mortar, artillery, and small arms fire. After taking the troop's objective and while making preparations for a defense, he discovered a nest of Japanese pillboxes and foxholes to the right front. Preceding his men by at least 10 feet, he immediately led an attack. Single-handedly he knocked out 2 enemy pillboxes and killed the occupants of several foxholes. While attempting to knock out a third pillbox, he was struck and blinded by an enemy grenade. Although unable to see, he rallied his platoon and continued forward in the assault on the remaining pillboxes. Before the task was completed he fell mortally wounded. 1st Lt. Knight's gallantry and intrepidity were responsible for the successful elimination of most of the Japanese positions and served as an inspiration to officers and men of his troop.", "facts": [["Recipient", "Jack L. Knight"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near LoiKang, Burma"], ["Awarded", "Posthumously"]], "wiki": {"Jack L. Knight": "Jack_L._Knight"}},
  {"id": "1945-02-03-peden-forrest-e", "date": "1945-02-03", "title": "Technician 5th Grade Forrest E. Peden", "type": "loss", "theater": "Army", "location": {"name": "Near Biesheim, France", "lat": 48.0417, "lng": 7.5439}, "zoom": 9, "summary": "When his artillery unit's observation party was ambushed near Biesheim, he gave first aid to two wounded men, then ran through heavy fire to find help. He guided a friendly tank back to the ambush site and was killed when it was hit.", "facts": [["Recipient", "Forrest E. Peden"], ["Rank", "Technician 5th Grade"], ["Service", "Army"], ["Place of action", "Near Biesheim, France"], ["Awarded", "Posthumously"]], "wiki": {"Forrest E. Peden": "Forrest_E._Peden"}},
  {"id": "1945-02-05-viale-robert-m", "date": "1945-02-05", "title": "Second Lieutenant Robert M. Viale", "type": "loss", "theater": "Army", "location": {"name": "Manila, Luzon, Philippines", "lat": 14.5958, "lng": 120.9772}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity above and beyond the call of duty. Forced by the enemy's detonation of prepared demolitions to shift the course of his advance through the city, he led the 1st platoon toward a small bridge, where heavy fire from 3 enemy pillboxes halted the unit. With 2 men he crossed the bridge behind screening grenade smoke to attack the pillboxes. The first he knocked out himself while covered by his men's protecting fire; the other 2 were silenced by 1 of his companions and a bazooka team which he had called up. He suffered a painful wound in the right arm during the action. After his entire platoon had joined him, he pushed ahead through mortar fire and encircling flames. Blocked from the only escape route by an enemy machinegun placed at a street corner, he entered a nearby building with his men to explore possible means of reducing the emplacement. …", "facts": [["Recipient", "Robert M. Viale"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Manila, Luzon, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Robert M. Viale": "Robert_M._Viale"}},
  {"id": "1945-02-05-rudolph-donald-e", "date": "1945-02-05", "title": "Technical Sergeant Donald E. Rudolph", "type": "attack", "theater": "Army", "location": {"name": "Munoz, Luzon, Philippines (approx.)", "lat": 15.72, "lng": 120.9}, "zoom": 9, "summary": "While giving first aid to wounded men near Muñoz, he worked his way across open ground under fire and destroyed a series of Japanese pillboxes in turn with grenades, then a Japanese tank, allowing his company to advance.", "facts": [["Recipient", "Donald E. Rudolph"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Munoz, Luzon, Philippines"]], "wiki": {"Donald E. Rudolph": "Donald_Rudolph"}},
  {"id": "1945-02-07-mcgaha-charles-l", "date": "1945-02-07", "title": "Master Sergeant Charles L. McGaha", "type": "attack", "theater": "Army", "location": {"name": "Near Lupao, Luzon, Philippines", "lat": 15.8794, "lng": 120.8994}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity. His platoon and 1 other from Company G were pinned down in a roadside ditch by heavy fire from 5 Japanese tanks supported by 10 machine guns and a platoon of riflemen. When 1 of his men fell wounded 40 yd away, he unhesitatingly crossed the road under a hail of bullets and moved the man 75 yd to safety. Although he had suffered a deep arm wound, he returned to his post. Finding the platoon leader seriously wounded, he assumed command and rallied his men. Once more he braved the enemy fire to go to the aid of a litter party removing another wounded soldier. A shell exploded in their midst, wounding him in the shoulder and killing 2 of the party. He picked up the remaining man, carried him to cover, and then moved out in front deliberately to draw the enemy fire while the American forces, thus protected, withdrew to safety. …", "facts": [["Recipient", "Charles L. McGaha"], ["Rank", "Master Sergeant"], ["Service", "Army"], ["Place of action", "Near Lupao, Luzon, Philippines"]], "wiki": {"Charles L. McGaha": "Charles_L._McGaha"}},
  {"id": "1945-02-09-rodriguez-cleto-l", "date": "1945-02-09", "title": "Private Cleto L. Rodriguez", "type": "attack", "theater": "Army", "location": {"name": "Paco Railroad Station, Manila, Philippines", "lat": 14.5958, "lng": 120.9772}, "zoom": 9, "summary": "He was an automatic rifleman when his unit attacked the strongly defended Paco Railroad Station during the battle for Manila, Philippines. While making a frontal assault across an open field; his platoon was halted 100 yards from the station by intense enemy fire. On his own initiative, he left the platoon, accompanied by a comrade, and continued forward to a house 60 yards from the objective. Although under constant enemy observation, the 2 men remained in this position for an hour; firing at targets of opportunity, killing more than 35 hostile soldiers and wounding many more. Moving closer to the station and discovering a group of Japanese replacements attempting to reach pillboxes, they opened heavy fire, killed more than 40 and stopped all subsequent attempts to man the emplacements. Enemy fire became more intense as they advanced to within 20 yards of the station. Then, covered by his companion, Pvt. …", "facts": [["Recipient", "Cleto L. Rodriguez"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Paco Railroad Station, Manila, Philippines"]], "wiki": {"Cleto L. Rodriguez": "Cleto_Rodríguez"}},
  {"id": "1945-02-09-reese-jr-john-n", "date": "1945-02-09", "title": "Private First Class John N. Reese Jr.", "type": "loss", "theater": "Army", "location": {"name": "Paco Railroad Station, Manila, Philippines", "lat": 14.5958, "lng": 120.9772}, "zoom": 9, "summary": "He was engaged in the attack on the Paco Railroad Station, which was strongly defended by 300 determined enemy soldiers with machineguns and rifles, supported by several pillboxes, 3 20mm. guns, 1 37-mm. gun and heavy mortars. While making a frontal assault across an open field, his platoon was halted 100 yards from the station by intense enemy fire. On his own initiative he left the platoon, accompanied by a comrade, and continued forward to a house 60 yards from the objective. Although under constant enemy observation, the 2 men remained in this position for an hour, firing at targets of opportunity, killing more than 35 Japanese and wounding many more. Moving closer to the station and discovering a group of Japanese replacements attempting to reach pillboxes, they opened heavy fire, killed more than 40 and stopped all subsequent attempts to man the emplacements. Enemy fire became more intense as they advanced to within 20 yards of the station. From that point Pfc. …", "facts": [["Recipient", "John N. Reese Jr."], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Paco Railroad Station, Manila, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"John N. Reese Jr.": "John_N._Reese_Jr."}},
  {"id": "1945-02-09-cicchetti-joseph-j", "date": "1945-02-09", "title": "Private First Class Joseph J. Cicchetti", "type": "loss", "theater": "Army", "location": {"name": "South Manila, Luzon, Philippines (approx.)", "lat": 14.56, "lng": 121.0}, "zoom": 9, "summary": "He was with troops assaulting the first important line of enemy defenses. The Japanese had converted the partially destroyed Manila Gas Works and adjacent buildings into a formidable system of mutually supporting strongpoints from which they were concentrating machinegun, mortar, and heavy artillery fire on the American forces. Casualties rapidly mounted, and the medical aid men, finding it increasingly difficult to evacuate the wounded, called for volunteer litter bearers. Pfc. Cicchetti immediately responded, organized a litter team and skillfully led it for more than 4 hours in rescuing 14 wounded men, constantly passing back and forth over a 400-yard route which was the impact area for a tremendous volume of the most intense enemy fire. On one return trip the path was blocked by machinegun fire, but Pfc. Cicchetti deliberately exposed himself to draw the automatic fire which he neutralized with his own rifle while ordering the rest of the team to rush past to safety with the wounded. …", "facts": [["Recipient", "Joseph J. Cicchetti"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "South Manila, Luzon, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Joseph J. Cicchetti": "Joseph_J._Cicchetti"}},
  {"id": "1945-02-11-dahlgren-edward-c", "date": "1945-02-11", "title": "Sergeant Edward C. Dahlgren", "type": "attack", "theater": "Army", "location": {"name": "Oberhoffen, France (approx.)", "lat": 48.78, "lng": 7.86}, "zoom": 9, "summary": "He led the 3d Platoon to the rescue of a similar unit which had been surrounded in an enemy counterattack at Oberhoffen, France. As he advanced along a street, he observed several Germans crossing a field about 100 yards away. Running into a barn, he took up a position in a window and swept the hostile troops with submachine gun fire, killing 6, wounding others, and completely disorganizing the group. His platoon then moved forward through intermittent sniper fire and made contact with the besieged Americans. When the 2 platoons had been reorganized, Sgt. Dahlgren continued to advance along the street until he drew fire from an enemy-held house. In the face of machine pistol and rifle fire, he ran toward the building, hurled a grenade through the door, and blasted his way inside with his gun. This aggressive attack so rattled the Germans that all 8 men who held the strongpoint immediately surrendered. As Sgt. Dahlgren started toward the next house, hostile machinegun fire drove him to cover. …", "facts": [["Recipient", "Edward C. Dahlgren"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Oberhoffen, France"]], "wiki": {"Edward C. Dahlgren": "Edward_C._Dahlgren"}},
  {"id": "1945-02-13-perez-jr-manuel", "date": "1945-02-13", "title": "Private First Class Manuel Perez Jr.", "type": "loss", "theater": "Army", "location": {"name": "Fort William McKinley, Luzon, Philippines", "lat": 14.5325, "lng": 121.045}, "zoom": 9, "summary": "Private First Class Manuel Perez, Jr., United States Army, for conspicuous gallantry and intrepidity in action above and beyond the call of duty on 13 February 1945, while serving with Company A, 511th Parachute Infantry Regiment, 11th Airborne Division. Private First Class Perez was lead scout for Company A, which had destroyed 11 of 12 pillboxes in a strongly fortified sector defending the approach to enemy-held Fort William McKinley on Luzon, Philippine Islands. In the reduction of these pillboxes, he killed five Japanese in the open and blasted others in pillboxes with grenades. Realizing the urgent need for taking the last emplacement, which contained two twin-mount .50-caliber dual-purpose machineguns, he took a circuitous route to within 20 yards of the position, killing four of the enemy in his advance. He threw a grenade into the pillbox, and, as the crew started withdrawing through a tunnel just to the rear of the emplacement, shot and killed four before exhausting his clip. …", "facts": [["Recipient", "Manuel Perez Jr."], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Fort William McKinley, Luzon, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Manuel Perez Jr.": "Manuel_Pérez_Jr."}},
  {"id": "1945-02-14-bigelow-elmer-c", "date": "1945-02-14", "title": "Watertender First Class Elmer C. Bigelow", "type": "loss", "theater": "Navy", "location": {"name": "USS Fletcher, off Corregidor Island, Philippines", "lat": 14.3856, "lng": 120.5731}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving on board the U.S.S. Fletcher during action against enemy Japanese forces off Corregidor Island in the Philippines, February 14, 1945. Standing topside when an enemy shell struck the Fletcher, BIGELOW, acting instantly as the deadly projectile exploded into fragments which penetrated the No. 1 gun magazine and set fire to several powder cases, picked up a pair of fire extinguishers and rushed below in a resolute attempt to quell the raging flames. Refusing to waste the precious time required to don rescue-breathing apparatus, he plunged through the blinding smoke billowing out of the magazine hatch and dropped into the blazing compartment. Despite the acrid, burning powder smoke which seared his lungs with every agonizing breath, he worked rapidly and with instinctive sureness and succeeded in quickly extinguishing the fires and in cooling the cases and bulkheads, thereby preventing further damage to the stricken ship. …", "facts": [["Recipient", "Elmer C. Bigelow"], ["Rank", "Watertender First Class"], ["Service", "Navy"], ["Place of action", "USS Fletcher, off Corregidor Island, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Elmer C. Bigelow": "Elmer_Charles_Bigelow"}},
  {"id": "1945-02-16-mccarter-lloyd-g", "date": "1945-02-16", "title": "Private Lloyd G. McCarter", "type": "attack", "theater": "Army", "location": {"name": "Corregidor, Philippines", "lat": 14.3856, "lng": 120.5731}, "zoom": 9, "summary": "He was a scout with the regiment which seized the fortress of Corregidor, Philippine Islands. Shortly after the initial parachute assault on 16 February 1945, he crossed 30 yards of open ground under intense enemy fire, and at pointblank range silenced a machinegun with hand grenades. On the afternoon of 18 February he killed 6 snipers. That evening, when a large force attempted to bypass his company, he voluntarily moved to an exposed area and opened fire. The enemy attacked his position repeatedly throughout the night and was each time repulsed. By 2 o'clock in the morning, all the men about him had been wounded; but shouting encouragement to his comrades and defiance at the enemy, he continued to bear the brunt of the attack, fearlessly exposing himself to locate enemy soldiers and then pouring heavy fire on them. He repeatedly crawled back to the American line to secure more ammunition. …", "facts": [["Recipient", "Lloyd G. McCarter"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Corregidor, Philippines"], ["Awarded", "G.O. No. 77, September 10, 1945"]], "wiki": {"Lloyd G. McCarter": "Lloyd_G._McCarter"}},
  {"id": "1945-02-17-hammerberg-owen-f-p", "date": "1945-02-17", "title": "Boatswain's mate Second class Owen F. P. Hammerberg", "type": "loss", "theater": "Navy", "location": {"name": "West Loch, Pearl Harbor", "lat": 21.3679, "lng": -157.9771}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as a diver engaged in rescue operations at West Loch, Pearl Harbor, 17 February 1945. Aware of the danger when 2 fellow divers were hopelessly trapped in a cave-in of steel wreckage while tunneling with jet nozzles under an LST sunk in 40 ft of water and 20 ft of mud. Hammerberg unhesitatingly went overboard in a valiant attempt to effect their rescue despite the certain hazard of additional cave-ins and the risk of fouling his lifeline on jagged pieces of steel imbedded in the shifting mud. Washing a passage through the original excavation, he reached the first of the trapped men, freed him from the wreckage and, working desperately in pitch-black darkness, finally effected his release from fouled lines, thereby enabling him to reach the surface. …", "facts": [["Recipient", "Owen F. P. Hammerberg"], ["Rank", "Boatswain's mate Second class"], ["Service", "Navy"], ["Place of action", "West Loch, Pearl Harbor"], ["Awarded", "Posthumously"]], "wiki": {"Owen F. P. Hammerberg": "Francis_P._Hammerberg"}},
  {"id": "1945-02-17-herring-rufus-g", "date": "1945-02-17", "title": "Lieutenant, Junior Grade Rufus G. Herring", "type": "attack", "theater": "Navy", "location": {"name": "As commanding officer aboard a landing craft, USS LCI (G) 449, Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Commanding Officer of LCI (G) 449 operating as a unit of LCI (G) Group EIGHT, during the preinvasion attack on Iwo Jima on 17 February 1945. Boldly closing the strongly fortified shores under the devastating fire of Japanese coastal defense guns, Lieutenant (then Lieutenant, Junior Grade,) Herring directed shattering barrages of 40-mm. and 20-mm. gunfire against hostile beaches until struck down by the enemy's savage counterfire which blasted the 449s heavy guns and whipped her decks into sheets of flame. Regaining consciousness despite profuse bleeding he was again critically wounded when a Japanese mortar crashed the conning station, instantly killing or fatally wounding most of the officers and leaving the ship wallowing without navigational control. …", "facts": [["Recipient", "Rufus G. Herring"], ["Rank", "Lieutenant, Junior Grade"], ["Service", "Navy"], ["Place of action", "As commanding officer aboard a landing craft, USS LCI (G) 449, Iwo Jima, Volcano Islands"]], "wiki": {"Rufus G. Herring": "Rufus_G._Herring"}},
  {"id": "1945-02-19-stein-tony", "date": "1945-02-19", "title": "Corporal Tony Stein", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with Company A, 1st Battalion, 28th Marines, 5th Marine Division, in action against enemy Japanese forces on Iwo Jima, in the Volcano Islands, 19 February 1945. The first man of his unit to be on station after hitting the beach in the initial assault, Cpl. Stein, armed with a personally improvised aircraft-type weapon, provided rapid covering fire as the remainder of his platoon attempted to move into position. When his comrades were stalled by a concentrated machinegun and mortar barrage, he gallantly stood upright and exposed himself to the enemy's view, thereby drawing the hostile fire to his own person and enabling him to observe the location of the furiously blazing hostile guns. Determined to neutralize the strategically placed weapons, he boldly charged the enemy pillboxes 1 by 1 and succeeded in killing 20 of the enemy during the furious single-handed assault. …", "facts": [["Recipient", "Tony Stein"], ["Rank", "Corporal"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"Tony Stein": "Tony_Stein"}},
  {"id": "1945-02-19-chambers-justice-m", "date": "1945-02-19", "title": "Lieutenant Colonel Justice M. Chambers", "type": "attack", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as commanding officer of the 3d Assault Battalion Landing Team, 25th Marines, 4th Marine Division, in action against enemy Japanese forces on Iwo Jima, Volcano Islands, from 19 to 22 February 1945. Under a furious barrage of enemy machinegun and small-arms fire from the commanding cliffs on the right, Col. Chambers (then Lt. Col.) landed immediately after the initial assault waves of his battalion on D-day to find the momentum of the assault threatened by heavy casualties from withering Japanese artillery, mortar rocket, machinegun, and rifle fire. Exposed to relentless hostile fire, he coolly reorganized his battle-weary men, inspiring them to heroic efforts by his own valor and leading them in an attack on the critical, impregnable high ground from which the enemy was pouring an increasing volume of fire directly onto troops ashore as well as amphibious craft in succeeding waves. …", "facts": [["Recipient", "Justice M. Chambers"], ["Rank", "Lieutenant Colonel"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"Justice M. Chambers": "Justice_M._Chambers"}},
  {"id": "1945-02-19-ruhl-donald-j", "date": "1945-02-19", "title": "Private First Class Donald J. Ruhl", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving as a Rifleman in an Assault Platoon of Company E, Twenty-eight Marines, Fifth Marine Division, in action against enemy Japanese Forces on Iwo Jima, Volcano Islands, from 19 to February 21, 1945. Quick to press the advantage after eight Japanese had been driven from a blockhouse on D-Day, Private First Class Ruhl singlehandedly attacked the group, killing one of the enemy with his bayonet and another by rifle fire in his determined attempt to annihilate the escaping troops. Cool and undaunted as the fury of hostile resistance steadily increased throughout the night, he voluntarily left the shelter of his tank trap early in the morning of D-Day plus 1 and moved out under tremendous volume of mortar and machine-gun fire to rescue a wounded Marine lying in an exposed position approximately forty yards forward of the line. …", "facts": [["Recipient", "Donald J. Ruhl"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"Donald J. Ruhl": "Donald_J._Ruhl"}},
  {"id": "1945-02-19-cole-darrell-s", "date": "1945-02-19", "title": "Sergeant Darrell S. Cole", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving as Leader of a Machine-gun Section of Company B, First Battalion, Twenty-Third Marines, Fourth Marine Division, in action against enemy Japanese forces during the assault on Iwo Jima in the Volcano Islands, 19 February 1945. Assailed by a tremendous volume of small-arms, mortar and artillery fire as he advanced with one squad of his section in the initial assault wave, Sergeant Cole boldly led his men up the sloping beach toward Airfield Number One despite the blanketing curtain of flying shrapnel and, personally destroying with hand grenades two hostile emplacements which menaced the progress of his unit, continued to move forward until a merciless barrage of fire emanating from three Japanese pillboxes halted the advance. …", "facts": [["Recipient", "Darrell S. Cole"], ["Rank", "Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"Darrell S. Cole": "Darrell_S._Cole"}},
  {"id": "1945-02-20-dunlap-robert-h", "date": "1945-02-20", "title": "Captain Robert H. Dunlap", "type": "attack", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Commanding Officer of Company C, First Battalion, Twenty-Sixth Marines, Fifth Marine Division, in action against enemy Japanese forces during the seizure of Iwo Jima in the Volcano Islands, on 20 and 21 February 1945. Defying uninterrupted blasts of Japanese artillery, mortar, rifle and machine gun fire, Captain Dunlap led his troops in a determined advance from low ground uphill toward the steep cliffs from which the enemy poured a devastating rain of shrapnel and bullets, steadily inching forward until the tremendous volume of enemy fire from the caves located high to his front temporarily halted his progress. Determined not to yield, he crawled alone approximately 200 yards forward of his front lines, took observation at the base of the cliff 50 yards from Japanese lines, located the enemy gun position and returned to his own lines where he relayed the vital information to supporting artillery and naval gunfire units. …", "facts": [["Recipient", "Robert H. Dunlap"], ["Rank", "Captain"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"Robert H. Dunlap": "Robert_Hugo_Dunlap"}},
  {"id": "1945-02-20-lucas-jacklyn-h", "date": "1945-02-20", "title": "Private First Class Jacklyn H. Lucas", "type": "attack", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the First Battalion, Twenty-sixth Marines, Fifth Marine Division, during action against enemy Japanese forces on Iwo Jima, Volcano Islands 20 February 1945. While creeping through a treacherous, twisting ravine which ran in close proximity to a fluid and uncertain front line on D-plus-1 Day, Private First Class Lucas and three other men were suddenly ambushed by a hostile patrol which savagely attacked with rifle fire and grenades. Quick to act when the lives of the small group were endangered by two grenades which landed directly in front of them, Private First Class Lucas unhesitatingly hurled himself over his comrades upon one grenade and pulled the other one under him, absorbing the whole blasting force of the explosions in his own body in order to shield his companions from the concussion and murderous flying fragments. …", "facts": [["Recipient", "Jacklyn H. Lucas"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"Jacklyn H. Lucas": "Jacklyn_H._Lucas"}},
  {"id": "1945-02-21-mccarthy-joseph-j", "date": "1945-02-21", "title": "Captain Joseph J. McCarthy", "type": "attack", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as commanding officer of a rifle company attached to the 2nd Battalion 24th Marines|, 4th Marine Division, in action against enemy Japanese forces during the seizure of Iwo Jima, Volcano Islands, on 21 February 1945. Determined to break through the enemy's cross-island defenses, Capt. McCarthy acted on his own initiative when his company advance was held up by uninterrupted Japanese rifle, machine gun, and high-velocity 47mm. fire during the approach to Motoyama Airfield No. 2. Quickly organizing a demolitions and flamethrower team to accompany his picked rifle squad, he fearlessly led the way across 75 yards of fire-swept ground, charged a heavily fortified pillbox on the ridge of the front, and, personally hurling hand grenades into the emplacement as he directed the combined operations of his small assault group, completely destroyed the hostile installation. …", "facts": [["Recipient", "Joseph J. McCarthy"], ["Rank", "Captain"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"Joseph J. McCarthy": "Joseph_J._McCarthy"}},
  {"id": "1945-02-21-gray-ross-f", "date": "1945-02-21", "title": "Sergeant Ross F. Gray", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Acting Platoon Sergeant serving with Company A, First Battalion, Twenty-Fifth Marines, Fourth Marine Division, in action against enemy Japanese forces on Iwo Jima, Volcano Islands, February 21, 1945. Shrewdly gauging the tactical situation when his platoon was held up by a sudden barrage of hostile grenades while advancing toward the high ground northeast of Airfield Number One, Sergeant Gray promptly organized the withdrawal of his men from enemy grenade range, quickly moved forward alone to reconnoiter and discovered a heavily mined area extending along the front of a strong network of emplacements joined by covered communication trenches. Although assailed by furious gunfire, he cleared a path leading through the mine field to one of the fortifications then returned to the platoon position and, informing his leader of the serious situation, volunteered to initiate an attack while being covered by three fellow Marines. …", "facts": [["Recipient", "Ross F. Gray"], ["Rank", "Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"Ross F. Gray": "Ross_F._Gray"}},
  {"id": "1945-02-23-williams-hershel-w", "date": "1945-02-23", "title": "Corporal Hershel W. Williams", "type": "attack", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Demolition Sergeant serving with the First Battalion, Twenty-First Marines, Third Marine Division, in action against enemy Japanese forces on Iwo Jima, Volcano Island, 23 February 1945. Quick to volunteer his services when our tanks were maneuvering vainly to open a lane for the infantry through the network of reinforced concrete pillboxes, buried mines and black, volcanic sands, Corporal Williams daringly went forward alone to attempt the reduction of devastating machine-gun fire from the unyielding positions. Covered only by four riflemen, he fought desperately for four hours under terrific enemy small-arms fire and repeatedly returned to his own lines to prepare demolition charges and obtain serviced flame throwers, struggling back, frequently to the rear of hostile emplacements, to wipe out one position after another. …", "facts": [["Recipient", "Hershel W. Williams"], ["Rank", "Corporal"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"Hershel W. Williams": "Hershel_W._Williams"}},
  {"id": "1945-02-23-grabiarz-william-j", "date": "1945-02-23", "title": "Private First Class William J. Grabiarz", "type": "loss", "theater": "Army", "location": {"name": "Manila, Luzon, Philippines", "lat": 14.5958, "lng": 120.9772}, "zoom": 9, "summary": "He was a scout when the unit advanced with tanks along a street in Manila, Luzon, Philippine Islands. Without warning, enemy machinegun and rifle fire from concealed positions in the Customs building swept the street, striking down the troop commander and driving his men to cover. As the officer lay in the open road, unable to move and completely exposed to the pointblank enemy fire, Pfc. Grabiarz voluntarily ran from behind a tank to carry him to safety, but was himself wounded in the shoulder. Ignoring both the pain in his injured useless arm and his comrades' shouts to seek the cover which was only a few yards distant, the valiant rescuer continued his efforts to drag his commander out of range. Finding this impossible, he rejected the opportunity to save himself and deliberately covered the officer with his own body to form a human shield, calling as he did so for a tank to maneuver into position between him and the hostile emplacement. …", "facts": [["Recipient", "William J. Grabiarz"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Manila, Luzon, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"William J. Grabiarz": "William_J._Grabiarz"}},
  {"id": "1945-02-24-cooley-raymond-h", "date": "1945-02-24", "title": "Staff Sergeant Raymond H. Cooley", "type": "attack", "theater": "Army", "location": {"name": "Near Lumboy, Luzon, Philippines (approx.)", "lat": 16.0, "lng": 120.45}, "zoom": 9, "summary": "He was a platoon guide in an assault on a camouflaged entrenchment defended by machineguns, rifles, and mortars. When his men were pinned down by 2 enemy machineguns, he voluntarily advanced under heavy fire to within 20 yards of 1 of the guns and attacked it with a hand grenade. The enemy, however, threw the grenade back at him before it could explode. Arming a second grenade, he held it for several seconds of the safe period and then hurled it into the enemy position, where it exploded instantaneously, destroying the gun and crew. He then moved toward the remaining gun, throwing grenades into enemy foxholes as he advanced. Inspired by his actions, 1 squad of his platoon joined him. After he had armed another grenade and was preparing to throw it into the second machinegun position, 6 enemy soldiers rushed at him. …", "facts": [["Recipient", "Raymond H. Cooley"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Lumboy, Luzon, Philippines"], ["Awarded", "G.O. No. 77, September 10, 1945"]], "wiki": {"Raymond H. Cooley": "Raymond_H._Cooley"}},
  {"id": "1945-02-26-jacobson-douglas-t", "date": "1945-02-26", "title": "Private First Class Douglas T. Jacobson", "type": "attack", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the Third Battalion, Twenty-Third Marines, Fourth Marine Division, in combat against enemy Japanese forces during the seizure of Iwo Jima in the Volcano Islands, February 26, 1945. Promptly destroying a stubborn 20-mm. antiaircraft gun and its crew after assuming the duties of a bazooka man who had been killed, Private First Class Jacobson waged a relentless battle as his unit fought desperately toward the summit of Hill 382 in an effort to penetrate the heart of Japanese cross-island defenses. Employing his weapon with ready accuracy when his platoon was halted by overwhelming enemy fire on February 26, he first destroyed two hostile machine-gun positions, then attacked a large blockhouse, completely neutralizing the fortification before dispatching the five-man crew of a pillbox and exploding the installation with a terrific demolitions blast. …", "facts": [["Recipient", "Douglas T. Jacobson"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"Douglas T. Jacobson": "Douglas_T._Jacobson"}},
  {"id": "1945-02-26-watson-wilson-d", "date": "1945-02-26", "title": "Private Wilson D. Watson", "type": "attack", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Automatic Rifleman serving with the Second Battalion, Ninth Marines, Third Marine Division, during action against enemy Japanese forces on Iwo Jima, Volcano Islands, 26 and 27 February 1945. With his squad abruptly halted by intense fire from enemy fortifications in the high rocky ridges and crags commanding the line of advance, Private Watson boldly rushed one pillbox and fired into the embrasure with his weapon, keeping the enemy pinned down single-handedly until he was in a position to hurl in a grenade and then running to the rear of the emplacement to destroy the retreating Japanese and enable his platoon to take its objective. Again pinned down at the foot of a small hill, he dauntlessly scaled the jagged incline under fierce mortar and machine-gun barrages and with his assistant automatic rifleman charged the crest of the hill, firing from his hip. …", "facts": [["Recipient", "Wilson D. Watson"], ["Rank", "Private"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"Wilson D. Watson": "Wilson_D._Watson"}},
  {"id": "1945-02-27-walsh-william-g", "date": "1945-02-27", "title": "Gunnery Sergeant William G. Walsh", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Leader of an Assault Platoon, serving with Company G, Third Battalion, Twenty-seventh Marines, Fifth Marine Division, in action against enemy Japanese forces at Iwo Jima, Volcano Islands, on 27 February 1945. With the advance of his company toward Hill 362 disrupted by vicious machine-gun fire from a forward position which guarded the approaches to this key enemy stronghold, Gunnery Sergeant Walsh fearlessly charged at the head of his platoon against the Japanese entrenched on the ridge above him, utterly oblivious to the unrelenting fury of hostile automatic weapons and hand grenades employed with fanatic desperation to smash his daring assault. …", "facts": [["Recipient", "William G. Walsh"], ["Rank", "Gunnery Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"William G. Walsh": "William_G._Walsh"}},
  {"id": "1945-02-27-wallace-herman-c", "date": "1945-02-27", "title": "Private First Class Herman C. Wallace", "type": "loss", "theater": "Army", "location": {"name": "Near Prümzurlay, Germany", "lat": 49.8689, "lng": 6.4383}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity. While helping clear enemy mines from a road, he stepped on a well-concealed S-type antipersonnel mine. Hearing the characteristic noise indicating that the mine had been activated and, if he stepped aside, would be thrown upward to explode above ground and spray the area with fragments, surely killing 2 comrades directly behind him and endangering other members of his squad, he deliberately placed his other foot on the mine even though his best chance for survival was to fall prone. Pvt. Wallace was killed when the charge detonated, but his supreme heroism at the cost of his life confined the blast to the ground and his own body and saved his fellow soldiers from death or injury.|Harry S. Truman", "facts": [["Recipient", "Herman C. Wallace"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Prümzurlay, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Herman C. Wallace": "Herman_C._Wallace"}},
  {"id": "1945-02-28-willis-john-h", "date": "1945-02-28", "title": "Pharmacist's Mate First class John H. Willis", "type": "loss", "theater": "Navy", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Platoon Corpsman serving with the 3d Battalion, 27th Marines, 5th Marine Division, during operations against enemy Japanese forces on Iwo Jima, Volcano Islands, 28 February 1945. Constantly imperiled by artillery and mortar fire from strong and mutually supporting pillboxes and caves studding Hill 362 in the enemy's cross-island defenses, Willis resolutely administered first aid to the many marines wounded during the furious close-in fighting until he himself was struck by shrapnel and was ordered back to the battle-aid station. Without waiting for official medical release, he quickly returned to his company and, during a savage hand-to-hand enemy counterattack, daringly advanced to the extreme frontlines under mortar and sniper fire to aid a marine lying wounded in a shellhole. …", "facts": [["Recipient", "John H. Willis"], ["Rank", "Pharmacist's Mate First class"], ["Service", "Navy"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"John H. Willis": "John_Harlan_Willis"}},
  {"id": "1945-03-03-berry-charles-j", "date": "1945-03-03", "title": "Corporal Charles J. Berry", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as a member of a Machine-gun Crew, serving with the First Battalion, Twenty-Sixth Marines, Fifth Marine Division, in action enemy Japanese forces during the seizure of Iwo Jima in the Volcano Islands, on 3 March 1945. Stationed in the front lines, Corporal Berry manned his weapon with alert readiness as he maintained a constant vigil with other members of his gun crew during the hazardous night hours. When infiltrating Japanese soldiers launched a surprise attack shortly after midnight in an attempt to overrun his position, he engaged in a pitched hand grenade duel, returning the dangerous weapons with prompt and deadly accuracy until an enemy grenade landed in the foxhole. Determined to save his comrades, he unhesitatingly chose to sacrifice himself and immediately dived on the deadly missile, absorbing the shattering violence of the exploding charge in his own body and protecting the others from serious injury. …", "facts": [["Recipient", "Charles J. Berry"], ["Rank", "Corporal"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"Charles J. Berry": "Charles_J._Berry"}},
  {"id": "1945-03-03-wahlen-george-e", "date": "1945-03-03", "title": "Pharmacist's Mate Second class George E. Wahlen", "type": "attack", "theater": "Navy", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the 2d Battalion, 26th Marines, 5th Marine Division, during action against enemy Japanese forces on Iwo Jima in the Volcano group on 3 March 1945. Painfully wounded in the bitter action on 26 February, Wahlen remained on the battlefield, advancing well forward of the frontlines to aid a wounded marine and carrying him back to safety despite a terrific concentration of fire. Tireless in his ministrations, he consistently disregarded all danger to attend his fighting comrades as they fell under the devastating rain of shrapnel and bullets, and rendered prompt assistance to various elements of his combat group as required. When an adjacent platoon suffered heavy casualties, he defied the continuous pounding of heavy mortars and deadly fire of enemy rifles to care for the wounded, working rapidly in an area swept by constant fire and treating 14 casualties before returning to his own platoon. …", "facts": [["Recipient", "George E. Wahlen"], ["Rank", "Pharmacist's Mate Second class"], ["Service", "Navy"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"George E. Wahlen": "George_Edward_Wahlen"}},
  {"id": "1945-03-03-williams-jack", "date": "1945-03-03", "title": "Pharmacist's Mate Third class Jack Williams", "type": "loss", "theater": "Navy", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the 3rd Battalion 28th Marines, 5th Marine Division, during the occupation of Iwo Jima Volcano Islands, March 3, 1945. Gallantly going forward on the frontlines under intense enemy small-arms fire to assist a marine wounded in a fierce grenade battle, Williams dragged the man to a shallow depression and was kneeling, using his own body as a screen from the sustained fire as he administered first aid, when struck in the abdomen and groin 3 times by hostile rifle fire. Momentarily stunned, he quickly recovered and completed his ministration before applying battle dressings to his own multiple wounds. Unmindful of his own urgent need for medical attention, he remained in the perilous fire-swept area to care for another marine casualty. …", "facts": [["Recipient", "Jack Williams"], ["Rank", "Pharmacist's Mate Third class"], ["Service", "Navy"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"Jack Williams": "Jack_Williams_(Medal_of_Honor)"}},
  {"id": "1945-03-03-caddy-william-r", "date": "1945-03-03", "title": "Private First Class William R. Caddy", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving as a Rifleman with Company I, Third Battalion, Twenty-sixth Marines, Fifth Marine Division, in action against enemy Japanese forces during the seizure of Iwo Jima in the Volcano Islands, 3 March 1945. Consistently aggressive, Private First Class Caddy boldly defied shattering Japanese machine-gun and small-arms fire to move forward with his platoon leader and another Marine during a determined advance of his company through an isolated sector and, gaining the comparative safety of a shell hole, took temporary cover with his comrades. Immediately pinned down by deadly sniper fire from a well-concealed position, he made several unsuccessful attempts to again move forward and then, joined by his platoon leader, engaged the enemy in a fierce exchange of hand grenades until a Japanese grenade fell in the shell hole. …", "facts": [["Recipient", "William R. Caddy"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"William R. Caddy": "William_R._Caddy"}},
  {"id": "1945-03-03-harrell-william-g", "date": "1945-03-03", "title": "Sergeant William G. Harrell", "type": "attack", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Leader of an Assault Group, serving with the First Battalion, Twenty-Eight Marines, Fifth Marine Division, during hand- to-hand combat with enemy Japanese at Iwo Jima, Volcano Islands, on March 3, 1945. Standing watch alternately with another Marine in a terrain studded with caves and ravines, Sergeant Harrell was holding a position in a perimeter defense around the company command post when Japanese troops infiltrated our lines in the early hours of dawn. Awakened by a sudden attack, he quickly opened fire with his carbine and killed two of the enemy as they emerged from a ravine in the light of a star-shell burst. Unmindful of his danger as hostile grenades fell closer, he waged a fierce lone battle until an exploding missile tore off his left hand and fractured his thigh; he was attempting to reload the carbine when his companion returned from the command post with another weapon. …", "facts": [["Recipient", "William G. Harrell"], ["Rank", "Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"William G. Harrell": "William_G._Harrell"}},
  {"id": "1945-03-07-leims-john-h", "date": "1945-03-07", "title": "Second Lieutenant John H. Leims", "type": "attack", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Commanding Officer of Company B, First Battalion, Ninth Marines, Third Marine Division, in action against enemy Japanese forces on Iwo Jima in the Volcano Islands, on 7 March 1945. Launching a surprise attack against the rock-embedded fortifications of a dominating Japanese hill position, Second Lieutenant Leims spurred his company forward with indomitable determination and, skillfully directing his assault platoons against the cave-emplaced enemy troops and heavily fortified pillboxes, succeeded in capturing the objective in the late afternoon. When it became apparent that his assault platoons were cut off in this newly won position, approximately four hundred yards forward of adjacent units and lacked all communication with the command post, he personally advanced and laid telephone lines across the isolating expanse of open, fire-swept terrain. Ordered to withdraw his command after he had joined his forward platoons, he immediately complied, adroitly effecting the withdrawal of his troops without incident. …", "facts": [["Recipient", "John H. Leims"], ["Rank", "Second Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"John H. Leims": "John_H._Leims"}},
  {"id": "1945-03-08-lummus-jack", "date": "1945-03-08", "title": "First Lieutenant Jack Lummus", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as leader of a Rifle Platoon attached to the 2d Battalion, 27th Marines, 5th Marine Division, in action against enemy Japanese forces on Iwo Jima in the Volcano Islands, 8 March 1945. Resuming his assault tactics with bold decision after fighting without respite for 2 days and nights, 1st Lt. Lummus slowly advanced his platoon against an enemy deeply entrenched in a network of mutually supporting positions. Suddenly halted by a terrific concentration of hostile fire, he unhesitatingly moved forward of his front lines in an effort to neutralize the Japanese position. Although knocked to the ground when an enemy grenade exploded close by, he immediately recovered himself and, again moving forward despite the intensified barrage, quickly located, attacked, and destroyed the occupied emplacement. …", "facts": [["Recipient", "Jack Lummus"], ["Rank", "First Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"Jack Lummus": "Jack_Lummus"}},
  {"id": "1945-03-08-la-belle-james-d", "date": "1945-03-08", "title": "Private First Class James D. La Belle", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the Weapons Company, twenty-seventh Marines, Fifth Marine Division, in action against enemy Japanese forces during the seizure of Iwo Jima in the Volcano Islands, 8 March 1945. Filling a gap in the front lines during a critical phase of the battle, Private First Class LaBelle had dug into a foxhole with two other Marines and grimly aware of the enemy's persistent attempts to blast a way through our lines with hand grenades, applied himself with steady concentration to maintaining a sharply vigilant watch during the hazardous night hours. Suddenly a hostile grenade landed beyond reach in his foxhole. Quickly estimating the situation, he determined to save the others if possible, shouted a warning and instantly dived on the missile, absorbing the exploding charge in his own body and thereby protecting his comrades from serious injury. …", "facts": [["Recipient", "James D. La Belle"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"James D. La Belle": "James_D._La_Belle"}},
  {"id": "1945-03-09-julian-joseph-r", "date": "1945-03-09", "title": "Platoon Sergeant Joseph R. Julian", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "Following basic training at Parris Island, South Carolina, he became a Drill Instructor, and, later, was assigned to the 5th Marine Division. He was killed in action on Iwo Jima on March 9, 1945, following a one-man assault on enemy-occupied trenches and fortified positions. The Medal of Honor was awarded him posthumously for heroism above and beyond the call of duty.", "facts": [["Recipient", "Joseph R. Julian"], ["Rank", "Platoon Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"Joseph R. Julian": "Joseph_R._Julian"}},
  {"id": "1945-03-10-atkins-thomas-e", "date": "1945-03-10", "title": "Private First Class Thomas E. Atkins", "type": "attack", "theater": "Army", "location": {"name": "Villa Verde Trail, Luzon, Philippines (approx.)", "lat": 16.1, "lng": 120.9}, "zoom": 9, "summary": "He fought gallantly on the Villa Verde Trail, Luzon, Philippine Islands. With 2 companions he occupied a position on a ridge outside the perimeter defense established by the 1st Platoon on a high hill. At about 3 a.m., 2 companies of Japanese attacked with rifle and machinegun fire, grenades, TNT charges, and land mines, severely wounding Pfc. Tom Atkins and killing his 2 companions. Despite the intense hostile fire and pain from his deep wound, he held his ground and returned heavy fire. After the attack was repulsed, he remained in his precarious position to repel any subsequent assaults instead of returning to the American lines for medical treatment. An enemy machinegun, set up within 20 yards of his foxhole, vainly attempted to drive him off or silence his gun. The Japanese repeatedly made fierce attacks, but for 4 hours, Pfc. Tom Atkins determinedly remained in his fox hole, bearing the brunt of each assault and maintaining steady and accurate fire until each charge was repulsed. …", "facts": [["Recipient", "Thomas E. Atkins"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Villa Verde Trail, Luzon, Philippines"]], "wiki": {"Thomas E. Atkins": "Thomas_E._Atkins"}},
  {"id": "1945-03-13-crain-morris-e", "date": "1945-03-13", "title": "Technical Sergeant Morris E. Crain", "type": "loss", "theater": "Army", "location": {"name": "Haguenau, France", "lat": 48.82, "lng": 7.79}, "zoom": 9, "summary": "He led his platoon against powerful German forces during the struggle to enlarge the bridgehead across the Moder River. With great daring and aggressiveness he spearheaded the platoon in killing 10 enemy soldiers, capturing 12 more and securing its objective near an important road junction. Although heavy concentrations of artillery, mortar, and self-propelled gunfire raked the area, he moved about among his men during the day, exhorting them to great efforts and encouraging them to stand firm. He carried ammunition and maintained contact with the company command post, exposing himself to deadly enemy fire. At nightfall the enemy barrage became more intense and tanks entered the fray to cover foot troops while they bombarded our positions with grenades and rockets. As buildings were blasted by the Germans, the Americans fell back from house to house. T/Sgt. Crain deployed another platoon which had been sent to his support and then rushed through murderous tank and small-arms fire to the foremost house, which was being defended by 5 of his men. …", "facts": [["Recipient", "Morris E. Crain"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Haguenau, France"], ["Awarded", "Posthumously"]], "wiki": {"Morris E. Crain": "Morris_E._Crain"}},
  {"id": "1945-03-14-sigler-franklin-e", "date": "1945-03-14", "title": "Private Franklin E. Sigler", "type": "attack", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with the Second Battalion, Twenty-sixth Marines, Fifth Marine Division, in action against enemy Japanese forces during the seizure of Iwo Jima in the Volcano Islands on 14 March 1945. Voluntarily taking command of his rifle squad when the leader became a casualty, Private Sigler fearlessly led a bold charge against an enemy gun installation which had held up the advance of his company for several days and, reaching the position in advance of the others, assailed the emplacement with hand grenades and personally annihilated the entire crew. As additional Japanese troops opened fire from concealed tunnels and caves above, he quickly scaled the rocks leading to the attacking guns, surprised the enemy with a furious one-man assault and, although severely wounded in the encounter, deliberately crawled back to his squad position where he steadfastly refused evacuation, persistently directing heavy machine-gun and rocket barrages on the Japanese cave entrances. …", "facts": [["Recipient", "Franklin E. Sigler"], ["Rank", "Private"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"Franklin E. Sigler": "Franklin_E._Sigler"}},
  {"id": "1945-03-14-phillips-george", "date": "1945-03-14", "title": "Private George Phillips", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with Second Battalion, Twenty-eight Marines, Fifth Marine Division, in action against enemy Japanese forces during the seizure of Iwo Jima in the Volcano Islands, on 14 March 1945. Standing the fox-hole watch while other members of his squad rested after a night of bitter hand grenade fighting against infiltrating Japanese troops, Private Phillips was the only member of his unit alerted when an enemy hand grenade was tossed into their midst. Instantly shouting a warning, he unhesitatingly threw himself on the deadly missile, absorbing the shattering violence of the exploding charge in his own body and protecting his comrades from serious injury. …", "facts": [["Recipient", "George Phillips"], ["Rank", "Private"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"George Phillips": "George_Phillips_(USMC)"}},
  {"id": "1945-03-14-michael-harry-j", "date": "1945-03-14", "title": "Second Lieutenant Harry J. Michael", "type": "loss", "theater": "Army", "location": {"name": "Near Neiderzerf, Germany (approx.)", "lat": 49.57, "lng": 6.66}, "zoom": 9, "summary": "He was serving as a rifle platoon leader when his company began an assault on a wooded ridge northeast of the village of Neiderzerf, Germany, early on 13 March 1945. A short distance up the side of the hill, 2d Lt. Michael, at the head of his platoon, heard the click of an enemy machinegun bolt. Quietly halting the company, he silently moved off into the woods and discovered 2 enemy machineguns and crews. Executing a sudden charge, he completely surprised the enemy and captured the guns and crews. At daybreak, enemy voices were heard in the thick woods ahead. Leading his platoon in a flanking movement, they charged the enemy with hand grenades and, after a bitter fight, captured 25 members of an SS mountain division, 3 artillery pieces, and 20 horses. While his company was establishing its position, 2d Lt. Michael made 2 personal reconnaissance missions of the wood on his left flank. …", "facts": [["Recipient", "Harry J. Michael"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Near Neiderzerf, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Harry J. Michael": "Harry_J._Michael"}},
  {"id": "1945-03-15-pierce-francis-j", "date": "1945-03-15", "title": "Pharmacist's Mate First class Francis J. Pierce", "type": "attack", "theater": "Navy", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while attached to the 2d Battalion, 24th Marines, 4th Marine Division, during the Iwo Jima campaign, 15 and 16 March 1945. Almost continuously under fire while carrying out the most dangerous volunteer assignments, Pierce gained valuable knowledge of the terrain and disposition of troops. Caught in heavy enemy rifle and machinegun fire which wounded a corpsman and 2 of the 8 stretcher bearers who were carrying 2 wounded marines to a forward aid station on 15 March, Pierce quickly took charge of the party, carried the newly wounded men to a sheltered position, and rendered first aid. After directing the evacuation of 3 of the casualties, he stood in the open to draw the enemy's fire and, with his weapon blasting, enabled the litter bearers to reach cover. …", "facts": [["Recipient", "Francis J. Pierce"], ["Rank", "Pharmacist's Mate First class"], ["Service", "Navy"], ["Place of action", "Iwo Jima, Volcano Islands"]], "wiki": {"Francis J. Pierce": "Francis_Junior_Pierce"}},
  {"id": "1945-03-15-herrera-silvestre-s", "date": "1945-03-15", "title": "Private First Class Silvestre S. Herrera", "type": "attack", "theater": "Army", "location": {"name": "Near Mertzwiller, France", "lat": 48.8636, "lng": 7.6806}, "zoom": 9, "summary": "Silvestre Herrera was twenty-seven years old, married with three children, and working in his hometown of Phoenix, Arizona, when he was drafted into the Army in January 1944. Men with families were no longer exempt from the service in basic training, he met another draftee who said he was the father of eight. Private First Class Herrera's company landed in Italy, by this time largely under Allied control, as part of the 142nd Infantry in the summer of 1944. That fall they landed in France at Marseille and took a troop train to the front. By the end of the year, as his unit reached France, it began to encounter resistance from the retreating Germans. When the fighting became heavy by the spring of 1945, Herrera had to concede a grudging respect for the enemy, regarding them as \"muy machos.\" On March 15, Herrera's platoon was advancing along a wooded road near the French town of Mertzwiller when it ran into two German machine-gun emplace-ments. …", "facts": [["Recipient", "Silvestre S. Herrera"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Mertzwiller, France"], ["Awarded", "G.O. No. 75, September 5, 1945"]], "wiki": {"Silvestre S. Herrera": "Silvestre_S._Herrera"}},
  {"id": "1945-03-18-wilkin-edward-g", "date": "1945-03-18", "title": "Corporal Edward G. Wilkin", "type": "loss", "theater": "Army", "location": {"name": "Siegfried Line in Germany (approx.)", "lat": 50.4, "lng": 6.4}, "zoom": 6, "summary": "He spearheaded his unit's assault of the Siegfried Line in Germany. Heavy fire from enemy riflemen and camouflaged pillboxes had pinned down his comrades when he moved forward on his own initiative to reconnoiter a route of advance. He cleared the way into an area studded with pillboxes, where he repeatedly stood up and walked into vicious enemy fire, storming 1 fortification after another with automatic rifle fire and grenades, killing enemy troops, taking prisoners as the enemy defense became confused, and encouraging his comrades by his heroic example. When halted by heavy barbed wire entanglements, he secured bangalore torpedoes and blasted a path toward still more pillboxes, all the time braving bursting grenades and mortar shells and direct rifle and automatic-weapons fire. …", "facts": [["Recipient", "Edward G. Wilkin"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Siegfried Line in Germany"], ["Awarded", "Posthumously"]], "wiki": {"Edward G. Wilkin": "Edward_G._Wilkin"}},
  {"id": "1945-03-18-treadwell-jack-l", "date": "1945-03-18", "title": "First Lieutenant Jack L. Treadwell", "type": "attack", "theater": "Army", "location": {"name": "Near Nieder-Wurzbach, Germany (approx.)", "lat": 49.24, "lng": 7.2}, "zoom": 9, "summary": "By March 18, 1945 was serving as a first lieutenant in command of Company F, 180th Infantry Regiment, 45th Infantry Division. During a battle on that day, near Nieder-Wurzbach in Germany, Treadwell single-handedly captured six German bunkers. He was subsequently promoted to captain and, on September 14, 1945, awarded the Medal of Honor. Treadwell was wounded in March 1945, and after hospitalization, he returned to duty with the Infantry School at Fort Benning in March 1946. According to Signal Corps photo 210821, Treadwell received his MOH from President Truman on 23 August 1945.", "facts": [["Recipient", "Jack L. Treadwell"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Nieder-Wurzbach, Germany"]], "wiki": {"Jack L. Treadwell": "Jack_L._Treadwell"}},
  {"id": "1945-03-18-murphy-frederick-c", "date": "1945-03-18", "title": "Private First Class Frederick C. Murphy", "type": "loss", "theater": "Army", "location": {"name": "Siegfried Line at Saarlautern, Germany (approx.)", "lat": 49.31, "lng": 6.75}, "zoom": 9, "summary": "An aid man, he was wounded in the right shoulder soon after his comrades had jumped off in a dawn attack 18 March 1945, against the Siegfried Line at Saarlautern, Germany. He refused to withdraw for treatment and continued forward, administering first aid under heavy machinegun, mortar, and artillery fire. When the company ran into a thickly sown antipersonnel minefield and began to suffer more and more casualties, he continued to disregard his own wound and unhesitatingly braved the danger of exploding mines, moving about through heavy fire and helping the injured until he stepped on a mine which severed one of his feet. In spite of his grievous wounds, he struggled on with his work, refusing to be evacuated and crawling from man to man administering to them while in great pain and bleeding profusely. He was killed by the blast of another mine which he had dragged himself across in an effort to reach still another casualty. …", "facts": [["Recipient", "Frederick C. Murphy"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Siegfried Line at Saarlautern, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Frederick C. Murphy": "Frederick_C._Murphy"}},
  {"id": "1945-03-18-mcgee-william-d", "date": "1945-03-18", "title": "Private William D. McGee", "type": "loss", "theater": "Army", "location": {"name": "Near Mulheim, Germany", "lat": 51.4275, "lng": 6.8825}, "zoom": 9, "summary": "A medical aid man, he made a night crossing of the Moselle River with troops endeavoring to capture the town of Mulheim. The enemy had retreated in the sector where the assault boats landed, but had left the shore heavily strewn with antipersonnel mines. Two men of the first wave attempting to work their way forward detonated mines which wounded them seriously, leaving them bleeding and in great pain beyond the reach of their comrades. Entirely on his own initiative, Pvt. McGee entered the minefield, brought out 1 of the injured to comparative safety, and had returned to rescue the second victim when he stepped on a mine and was severely wounded in the resulting explosion. Although suffering intensely and bleeding profusely, he shouted orders that none of his comrades was to risk his life by entering the death-sown field to render first aid that might have saved his life. In making the supreme sacrifice, Pvt. …", "facts": [["Recipient", "William D. McGee"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Mulheim, Germany"], ["Awarded", "Posthumously"]], "wiki": {"William D. McGee": "William_D._McGee"}},
  {"id": "1945-03-19-o-callahan-joseph-t", "date": "1945-03-19", "title": "Lieutenant Commander Joseph T. O'Callahan", "type": "attack", "theater": "Navy", "location": {"name": "Near Kobe, Japan", "lat": 34.69, "lng": 135.1956}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving as chaplain on board the U.S.S. Franklin when that vessel was fiercely attacked by enemy Japanese aircraft during offensive operations near Kobe, Japan, on 19 March 1945. A valiant and forceful leader, calmly braving the perilous barriers of flame and twisted metal to aid his men and his ship, Lt. Comdr. O'Callahan groped his way through smoke-filled corridors to the open flight deck and into the midst of violently exploding bombs, shells, rockets, and other armament. …", "facts": [["Recipient", "Joseph T. O'Callahan"], ["Rank", "Lieutenant Commander"], ["Service", "Navy"], ["Place of action", "Near Kobe, Japan"]], "wiki": {"Joseph T. O'Callahan": "Joseph_T._O'Callahan"}},
  {"id": "1945-03-19-gary-donald-a", "date": "1945-03-19", "title": "Lieutenant, Junior Grade Donald A. Gary", "type": "attack", "theater": "Navy", "location": {"name": "Japanese home islands near Kobe, Japan (approx.)", "lat": 34.69, "lng": 135.19}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as an Engineering Officer attached to the U.S.S. Franklin when that vessel was fiercely attacked by enemy aircraft during the operations against the Japanese Home Islands near Kobe, Japan, March 19, 1945. Stationed on the third deck when the ship was rocked by a series of violent explosions set off in her own ready bombs, rockets and ammunition by the hostile attack, Lieutenant Gary unhesitatingly risked his life to assist several hundred men trapped in a messing compartment filled with smoke, and with no apparent egress. As the imperiled men below decks became increasingly panic-stricken under the raging fury of incessant explosions, he confidently assured them he would find a means of effecting their release and, groping through the dark, debris-filled corridors, ultimately discovered an escapeway. …", "facts": [["Recipient", "Donald A. Gary"], ["Rank", "Lieutenant, Junior Grade"], ["Service", "Navy"], ["Place of action", "Japanese home islands near Kobe, Japan"]], "wiki": {"Donald A. Gary": "Donald_A._Gary"}},
  {"id": "1945-03-19-burr-herbert-h", "date": "1945-03-19", "title": "Staff Sergeant Herbert H. Burr", "type": "attack", "theater": "Army", "location": {"name": "Near Dorrmoschel, Germany", "lat": 49.6188, "lng": 7.7522}, "zoom": 9, "summary": "He displayed conspicuous gallantry during action when the tank in which he was bow gunner was hit by an enemy rocket, which severely wounded the platoon sergeant and forced the remainder of the crew to abandon the vehicle. Deafened, but otherwise unhurt, S/Sgt. Burr immediately climbed into the driver's seat and continued on the mission of entering the town to reconnoiter road conditions. As he rounded a turn he encountered an 88-mm. antitank gun at pointblank range. Realizing that he had no crew, no one to man the tank's guns, he heroically chose to disregard his personal safety in a direct charge on the German weapon. At considerable speed he headed straight for the loaded gun, which was fully manned by enemy troops who had only to pull the lanyard to send a shell into his vehicle. So unexpected and daring was his assault that he was able to drive his tank completely over the gun, demolishing it and causing its crew to flee in confusion. …", "facts": [["Recipient", "Herbert H. Burr"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Dorrmoschel, Germany"]], "wiki": {"Herbert H. Burr": "Herbert_H._Burr"}},
  {"id": "1945-03-20-villegas-ysmael-r", "date": "1945-03-20", "title": "Staff Sergeant Ysmael R. Villegas", "type": "loss", "theater": "Army", "location": {"name": "Villa Verde Trail, Luzon, Philippines (approx.)", "lat": 16.1, "lng": 120.9}, "zoom": 9, "summary": "He was a squad leader when his unit, in a forward position, clashed with an enemy strongly entrenched in connected caves and foxholes on commanding ground. He moved boldly from man to man, in the face of bursting grenades and demolition charges, through heavy machinegun and rifle fire, to bolster the spirit of his comrades. Inspired by his gallantry, his men pressed forward to the crest of the hill. Numerous enemy riflemen, refusing to flee, continued firing from their foxholes. S/Sgt. Villegas, with complete disregard for his own safety and the bullets which kicked up the dirt at his feet, charged an enemy position, and, firing at point-blank range killed the Japanese in a foxhole. He rushed a second foxhole while bullets missed him by inches, and killed 1 more of the enemy. In rapid succession he charged a third, a fourth, a fifth foxhole, each time destroying the enemy within. The fire against him increased in intensity, but he pressed onward to attack a sixth position. …", "facts": [["Recipient", "Ysmael R. Villegas"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Villa Verde Trail, Luzon, Philippines"], ["Awarded", "Posthumously, G.O. No. 89, October 19, 1945"]], "wiki": {"Ysmael R. Villegas": "Ysmael_R._Villegas"}},
  {"id": "1945-03-23-carter-jr-edward-a", "date": "1945-03-23", "title": "Staff Sergeant Edward A. Carter Jr.", "type": "attack", "theater": "Army", "location": {"name": "Near Speyer, Germany", "lat": 49.3194, "lng": 8.4311}, "zoom": 9, "summary": "Staff Sergeant Edward A. Carter Jr., United States Army For conspicuous gallantry and intrepidity at the risk of his own life above and beyond the call of duty in action on 23 March 1945. At approximately 0830 hours, 23 March 1945, near Speyer, Germany, the tank upon which Staff Sergeant Carter was riding received bazooka and small arms fire from the vicinity of a large warehouse to its left front. Staff Sergeant Carter and his squad took cover behind an intervening road bank. Staff Sergeant Carter volunteered to lead a three-man patrol to the warehouse where other unit members noticed the original bazooka fire. From here they were to ascertain the location and strength of the opposing position and advance approximately 150 yards across an open field. Enemy small arms fire covered this field. As the patrol left this covered position, they received intense enemy small arms fire killing one member of the patrol instantly. …", "facts": [["Recipient", "Edward A. Carter Jr."], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Speyer, Germany"]], "wiki": {"Edward A. Carter Jr.": "Edward_A._Carter_Jr."}},
  {"id": "1945-03-24-stryker-stuart-s", "date": "1945-03-24", "title": "Private First Class Stuart S. Stryker", "type": "loss", "theater": "Army", "location": {"name": "Near Wesel, Germany", "lat": 51.6586, "lng": 6.6178}, "zoom": 9, "summary": "He was a platoon runner, when the unit assembled near Wesel, Germany after a descent east of the Rhine. Attacking along a railroad, Company E reached a point about 250 yards from a large building used as an enemy headquarters and manned by a powerful force of Germans with rifles, machineguns, and 4 field pieces. One platoon made a frontal assault but was pinned down by intense fire from the house after advancing only 50 yards. So badly stricken that it could not return the raking fire, the platoon was at the mercy of German machine gunners when Pfc. Stryker voluntarily left a place of comparative safety, and, armed with a carbine, ran to the head of the unit. In full view of the enemy and under constant fire, he exhorted the men to get to their feet and follow him. Inspired by his fearlessness, they rushed after him in a desperate charge through an increased hail of bullets. …", "facts": [["Recipient", "Stuart S. Stryker"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Wesel, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Stuart S. Stryker": "Stuart_S._Stryker"}},
  {"id": "1945-03-24-peters-george-j", "date": "1945-03-24", "title": "Private George J. Peters", "type": "loss", "theater": "Army", "location": {"name": "Near Fluren, Germany (approx.)", "lat": 51.68, "lng": 6.58}, "zoom": 9, "summary": "Pvt. Peters, a platoon radio operator with Company G, made a descent into Germany near Fluren, east of the Rhine. With 10 others, he landed in a field about 75 yards from a German machinegun supported by riflemen, and was immediately pinned down by heavy, direct fire. The position of the small unit seemed hopeless with men struggling to free themselves of their parachutes in a hail of bullets that cut them off from their nearby equipment bundles, when Pvt. Peters stood up without orders and began a 1-man charge against the hostile emplacement armed only with a rifle and grenades. His single-handed assault immediately drew the enemy fire away from his comrades. He had run halfway to his objective, pitting rifle fire against that of the machinegun, when he was struck and knocked to the ground by a burst. Heroically, he regained his feet and struggled onward. Once more he was torn by bullets, and this time he was unable to rise. …", "facts": [["Recipient", "George J. Peters"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Fluren, Germany"], ["Awarded", "Posthumously"]], "wiki": {"George J. Peters": "George_J._Peters"}},
  {"id": "1945-03-26-martin-harry-l", "date": "1945-03-26", "title": "First Lieutenant Harry L. Martin", "type": "loss", "theater": "Marine Corps", "location": {"name": "Iwo Jima, Volcano Islands", "lat": 24.7803, "lng": 141.3244}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Platoon Leader attached to Company C, Fifth Pioneer Battalion, Fifth Marine Division, in action against enemy Japanese forces on Iwo Jima, Volcano Islands, 26 March 1945. With his sector of the Fifth Pioneer Battalion bivouac area penetrated by a concentrated enemy attack launched a few minutes before dawn, First Lieutenant Martin instantly organized a firing line with the Marines nearest his foxhole and succeeded, in checking momentarily the headlong rush of the Japanese. Determined to rescue several of his men trapped in positions overrun by the enemy, he defied intense hostile fire to work his way through the Japanese to the surrounded Marines. Although sustaining two severe wounds, he blasted the Japanese who attempted to intercept him, located his beleaguered men and directed them to their own lines. …", "facts": [["Recipient", "Harry L. Martin"], ["Rank", "First Lieutenant"], ["Service", "Marine Corps"], ["Place of action", "Iwo Jima, Volcano Islands"], ["Awarded", "Posthumously"]], "wiki": {"Harry L. Martin": "Harry_L._Martin"}},
  {"id": "1945-03-27-hedrick-clinton-m", "date": "1945-03-27", "title": "Technical Sergeant Clinton M. Hedrick", "type": "loss", "theater": "Army", "location": {"name": "Near Lembeck, Germany", "lat": 51.7589, "lng": 6.9992}, "zoom": 9, "summary": "He displayed extraordinary heroism and gallantry in action on 27 – March 28, 1945, in Germany. Following an airborne landing near Wesel, his unit was assigned as the assault platoon for the assault on Lembeck. Three times the landing elements were pinned down by intense automatic weapons fire from strongly defended positions. Each time, T/Sgt. Hedrick fearlessly charged through heavy fire, shooting his automatic rifle from his hip. His courageous action so inspired his men that they reduced the enemy positions in rapid succession. When 6 of the enemy attempted a surprise, flanking movement, he quickly turned and killed the entire party with a burst of fire. Later, the enemy withdrew across a moat into Lembeck Castle. T/Sgt. Hedrick, with utter disregard for his own safety, plunged across the drawbridge alone in pursuit. When a German soldier, with hands upraised, declared the garrison wished to surrender, he entered the castle yard with 4 of his men to accept the capitulation. …", "facts": [["Recipient", "Clinton M. Hedrick"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Lembeck, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Clinton M. Hedrick": "Clinton_M._Hedrick"}},
  {"id": "1945-03-29-dietz-robert-h", "date": "1945-03-29", "title": "Staff Sergeant Robert H. Dietz", "type": "loss", "theater": "Army", "location": {"name": "Kirchain, Germany (approx.)", "lat": 50.82, "lng": 8.92}, "zoom": 9, "summary": "He was a squad leader when the task force to which his unit was attached encountered resistance in its advance on Kirchhain, Germany. Between the town's outlying buildings 300 yards distant and the stalled armored column were a minefield and 2 bridges defended by German rocket-launching teams and riflemen. From the town itself came heavy small-arms fire. Moving forward with his men to protect engineers while they removed the minefield and the demolition charges attached to the bridges, S/Sgt. Dietz came under intense fire. On his own initiative he advanced alone, scorning the bullets which struck all around him, until he was able to kill the bazooka team defending the first bridge. He continued ahead and had killed another bazooka team, bayoneted an enemy soldier armed with a panzerfaust and shot 2 Germans when he was knocked to the ground by another blast of another panzerfaust. …", "facts": [["Recipient", "Robert H. Dietz"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Kirchain, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Robert H. Dietz": "Robert_H._Dietz"}},
  {"id": "1945-03-30-will-walter-j", "date": "1945-03-30", "title": "First Lieutenant Walter J. Will", "type": "loss", "theater": "Army", "location": {"name": "Near Eisern, Germany (approx.)", "lat": 50.83, "lng": 8.02}, "zoom": 9, "summary": "He displayed conspicuous gallantry during an attack on powerful enemy positions. He courageously exposed himself to withering hostile fire to rescue 2 wounded men and then, although painfully wounded himself, made a third trip to carry another soldier to safety from an open area. Ignoring the profuse bleeding of his wound, he gallantly led men of his platoon forward until they were pinned down by murderous flanking fire from 2 enemy machine guns. He fearlessly crawled alone to within 30 feet of the first enemy position, killed the crew of 4 and silenced the gun with accurate grenade fire. He continued to crawl through intense enemy fire to within 20 feet of the second position where he leaped to his feet, made a lone, ferocious charge and captured the gun and its 9-man crew. …", "facts": [["Recipient", "Walter J. Will"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Eisern, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Walter J. Will": "Walter_J._Will"}},
  {"id": "1945-03-30-peterson-george", "date": "1945-03-30", "title": "Staff Sergeant George Peterson", "type": "loss", "theater": "Army", "location": {"name": "Near Eisern, Germany (approx.)", "lat": 50.83, "lng": 8.02}, "zoom": 9, "summary": "He was an acting platoon sergeant with Company K, near Eisern, Germany. When his company encountered an enemy battalion and came under heavy small-arms, machinegun, and mortar fire, the 2d Platoon was given the mission of flanking the enemy positions while the remaining units attacked frontally. S/Sgt. Peterson crept and crawled to a position in the lead and motioned for the 2d Platoon to follow. A mortar shell fell close by and severely wounded him in the legs, but, although bleeding and suffering intense pain, he refused to withdraw and continued forward. Two hostile machineguns went into action at close range. Braving this grazing fire, he crawled steadily toward the guns and worked his way alone to a shallow draw, where, despite the hail of bullets, he raised himself to his knees and threw a grenade into the nearest machinegun nest, silencing the weapon and killing or wounding all its crew. …", "facts": [["Recipient", "George Peterson"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Eisern, Germany"], ["Awarded", "Posthumously"]], "wiki": {"George Peterson": "George_Peterson_(Medal_of_Honor)"}},
  {"id": "1945-03-31-shockley-william-r", "date": "1945-03-31", "title": "Private First Class William R. Shockley", "type": "loss", "theater": "Army", "location": {"name": "Villa Verde Trail, Luzon, Philippines (approx.)", "lat": 16.1, "lng": 120.9}, "zoom": 9, "summary": "He was in position with his unit on a hill when the enemy, after a concentration of artillery fire, launched a counterattack. He maintained his position under intense enemy fire and urged his comrades to withdraw, saying that he would \"remain to the end\" to provide cover. Although he had to clear two stoppages which impeded the reloading of his weapon, he halted one enemy charge. Hostile troops then began moving in on his left flank, and he quickly shifted his gun to fire on them. Knowing that the only route of escape was being cut off by the enemy, he ordered the remainder of his squad to withdraw to safety and deliberately remained at his post. He continued to fire until he was killed during the ensuing enemy charge. Later, four Japanese were found dead in front of his position. Pfc. Shockley, facing certain death, sacrificed himself to save his fellow soldiers, but the heroism and gallantry displayed by him enabled his squad to reorganize and continue its attack.", "facts": [["Recipient", "William R. Shockley"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Villa Verde Trail, Luzon, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"William R. Shockley": "William_R._Shockley"}},
  {"id": "1945-04-03-wetzel-walter-c", "date": "1945-04-03", "title": "Private First Class Walter C. Wetzel", "type": "loss", "theater": "Army", "location": {"name": "Birken, Germany (approx.)", "lat": 50.82, "lng": 7.73}, "zoom": 9, "summary": "Pfc. Wetzel, an acting squad leader with the Antitank Company of the 13th Infantry, was guarding his platoon's command post in a house at Birken, Germany, during the early morning hours of 3 April 1945, when he detected strong enemy forces moving in to attack. He ran into the house, alerted the occupants and immediately began defending the post against heavy automatic weapons fire coming from the hostile troops. Under cover of darkness the Germans forced their way close to the building where they hurled grenades, 2 of which landed in the room where Pfc. Wetzel and the others had taken up firing positions. Shouting a warning to his fellow soldiers, Pfc. Wetzel threw himself on the grenades and, as they exploded, absorbed their entire blast, suffering wounds from which he died. The supreme gallantry of Pfc. …", "facts": [["Recipient", "Walter C. Wetzel"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Birken, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Walter C. Wetzel": "Walter_C._Wetzel"}},
  {"id": "1945-04-05-kelly-thomas-j", "date": "1945-04-05", "title": "Corporal Thomas J. Kelly", "type": "attack", "theater": "Army", "location": {"name": "Alemert, Germany (approx.)", "lat": 50.8, "lng": 6.2}, "zoom": 9, "summary": "He was an aid man with the 1st Platoon of Company C during an attack on the town of Alemert, Germany. The platoon, committed in a flanking maneuver, had advanced down a small, open valley overlooked by wooded slopes hiding enemy machineguns and tanks, when the attack was stopped by murderous fire that inflicted heavy casualties in the American ranks. Ordered to withdraw, Cpl. Kelly reached safety with uninjured remnants of the unit, but, on realizing the extent of casualties suffered by the platoon, voluntarily retraced his steps and began evacuating his comrades under direct machinegun fire. He was forced to crawl, dragging the injured behind him for most of the 300 yards separating the exposed area from a place of comparative safety. Two other volunteers who attempted to negotiate the hazardous route with him were mortally wounded, but he kept on with his herculean task after dressing their wounds and carrying them to friendly hands. …", "facts": [["Recipient", "Thomas J. Kelly"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Alemert, Germany"]], "wiki": {"Thomas J. Kelly": "Thomas_J._Kelly_(Medal_of_Honor)"}},
  {"id": "1945-04-05-munemori-sadao-s", "date": "1945-04-05", "title": "Private First Class Sadao S. Munemori", "type": "loss", "theater": "Army", "location": {"name": "Near Seravezza, Italy (approx.)", "lat": 43.99, "lng": 10.23}, "zoom": 9, "summary": "Private First Class Sadao S. Munemori, United States Army, for conspicuous gallantry and intrepidity in action above and beyond the call of duty while serving with Company A, 100th Infantry Battalion, 442d Regimental Combat Team, attached to the 92d Infantry Division, in action against the enemy on 5 April 1945. Private First Class Munemori fought with great gallantry and intrepidity near Seravezza, Italy. When his unit was pinned down by grazing fire from the enemy's strong mountain defense and command of the squad devolved on him with the wounding of its regular leader, he made frontal, one-man attacks through direct fire and knocked out two machine guns with grenades. Withdrawing under murderous fire and showers of grenades from other enemy emplacements, he had nearly reached a shell crater occupied by two of his men when an unexploded grenade bounced on his helmet and rolled toward his helpless comrades. He arose into the withering fire, dived for the grenade, and smothered its blast with his body. …", "facts": [["Recipient", "Sadao S. Munemori"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Seravezza, Italy"], ["Awarded", "Posthumously, G.O. No. 24, 7 March 1946"]], "wiki": {"Sadao S. Munemori": "Sadao_Munemori"}},
  {"id": "1945-04-05-baker-vernon-j", "date": "1945-04-05", "title": "Second Lieutenant Vernon J. Baker", "type": "attack", "theater": "Army", "location": {"name": "Near Viareggio, Italy", "lat": 43.8667, "lng": 10.2333}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty: First Lieutenant Vernon J. Baker distinguished himself by extraordinary heroism in action on 5 and 6 April 1945. At 0500 hours on 5 April 1945, Lieutenant Baker advanced at the head of his weapons platoon, along with Company C's three rifle platoons, towards their objective, Castle Aghinolfi – a German mountain strong point on the high ground just east of the coastal highway and about two miles from the 370th Infantry Regiment's line of departure. Moving more rapidly than the rest of the company, Lieutenant Baker and about 25 men reached the south side of a draw some 250 yards from the castle within two hours. In reconnoitering for a suitable position to set up a machine gun, Lieutenant Baker observed two cylindrical objects pointing out a slit in a mount at the edge of a hill. …", "facts": [["Recipient", "Vernon J. Baker"], ["Rank", "Second Lieutenant"], ["Service", "Army"], ["Place of action", "Near Viareggio, Italy"]], "wiki": {"Vernon J. Baker": "Vernon_Baker"}},
  {"id": "1945-04-06-robinson-jr-james-e", "date": "1945-04-06", "title": "First Lieutenant James E. Robinson Jr.", "type": "loss", "theater": "Army", "location": {"name": "Near Untergriesheim, Germany (approx.)", "lat": 49.24, "lng": 9.2}, "zoom": 9, "summary": "He was a field artillery forward observer attached to Company A, 253d Infantry, near Untergriesheim, Germany, on 6 April 1945. Eight hours of desperate fighting over open terrain swept by German machinegun, mortar, and small-arms fire had decimated Company A, robbing it of its commanding officer and most of its key enlisted personnel when 1st Lt. Robinson rallied the 23 remaining uninjured riflemen and a few walking wounded, and, while carrying his heavy radio for communication with American batteries, led them through intense fire in a charge against the objective. Ten German infantrymen in foxholes threatened to stop the assault, but the gallant leader killed them all at point-blank range with rifle and pistol fire and then pressed on with his men to sweep the area of all resistance. Soon afterward he was ordered to seize the defended town of Kressbach. He went to each of the 19 exhausted survivors with cheering words, instilling in them courage and fortitude, before leading the little band forward once more. …", "facts": [["Recipient", "James E. Robinson Jr."], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Near Untergriesheim, Germany"], ["Awarded", "Posthumously"]], "wiki": {"James E. Robinson Jr.": "James_E._Robinson_Jr."}},
  {"id": "1945-04-06-beaudoin-raymond-o", "date": "1945-04-06", "title": "First Lieutenant Raymond O. Beaudoin", "type": "loss", "theater": "Army", "location": {"name": "Hamelin, Germany", "lat": 52.1, "lng": 9.3667}, "zoom": 9, "summary": "First Lieutenant Raymond O. Beaudoin was leading the 2d Platoon of Company F, 119th Infantry, on April 6, 1945 over flat, open terrain to Hamelin, Germany, when the enemy went into action with machineguns and automatic weapons, laying down a devastating curtain of fire which pinned his unit to the ground. By rotating men in firing positions he made it possible for his entire platoon to dig in, defying all the while the murderous enemy fire to encourage his men and to distribute ammunition. He then dug in himself at the most advanced position, where he kept up a steady fire, killing 6 hostile soldiers, and directing his men in inflicting heavy casualties on the numerically superior opposing force. Despite these defensive measures, however, the position of the platoon became more precarious, for the enemy had brought up strong reinforcements and was preparing a counterattack. Three men, sent back at intervals to obtain ammunition and reinforcements, were killed by sniper fire. …", "facts": [["Recipient", "Raymond O. Beaudoin"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Hamelin, Germany"], ["Awarded", "Posthumously, G.O. No. 9, 25 January 1946"]], "wiki": {"Raymond O. Beaudoin": "Raymond_O._Beaudoin"}},
  {"id": "1945-04-07-colalillo-mike", "date": "1945-04-07", "title": "Private First Class Mike Colalillo", "type": "attack", "theater": "Army", "location": {"name": "Near Untergriesheim, Germany (approx.)", "lat": 49.24, "lng": 9.2}, "zoom": 9, "summary": "Private Michael \"Mike\" Colalillo, United States Army, for conspicuous gallantry and intrepidity in action above and beyond the call of duty on 7 April 1945, while serving with Company C, 1st Battalion, 398th Infantry, 100th Infantry Division. Private Colalillo was pinned down with other members of his company during an attack against strong enemy positions in the vicinity of Untergriesheim, Germany. Heavy artillery, mortar, and machine gun fire made any move hazardous when he stood up, shouted to the company to follow, and ran forward in the wake of a supporting tank, firing his machine pistol. Inspired by his example, his comrades advanced in the face of savage enemy fire. …", "facts": [["Recipient", "Mike Colalillo"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Untergriesheim, Germany"]], "wiki": {"Mike Colalillo": "Mike_Colalillo"}},
  {"id": "1945-04-07-james-jr-willy-f", "date": "1945-04-07", "title": "Private First Class Willy F. James Jr.", "type": "loss", "theater": "Army", "location": {"name": "Near Lippoldsberg, Germany", "lat": 51.6333, "lng": 9.6}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at risk of his life above and beyond the call of duty: Private First Class Willy F. James, Jr. distinguished himself by extraordinary heroism at the risk of his own life on 7 April 1945 in the Weser River Valley, in the vicinity of Lippoldsberg, Germany. On 7 April 1945, Company G, 413th Infantry, fought its way across the Weser River in order to establish a crucial beachhead. The company then launched a fierce attack against the town of Lippoldsberg, possession of which was vital to securing and expanding the important bridgehead. Private First Class James was first scout of the lead squad in the assault platoon. The mission of the unit was to seize and secure a group of houses on the edge of town, a foothold from which the unit could launch an attack on the rest of the town. Far out in front, Private First Class James was the first to draw enemy fire. …", "facts": [["Recipient", "Willy F. James Jr."], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Lippoldsberg, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Willy F. James Jr.": "Willy_F._James_Jr."}},
  {"id": "1945-04-07-okutsu-yukio", "date": "1945-04-07", "title": "Technical Sergeant Yukio Okutsu", "type": "attack", "theater": "Army", "location": {"name": "On Mount Belvedere, Italy (approx.)", "lat": 44.24, "lng": 10.98}, "zoom": 9, "summary": "Technical Sergeant Yukio Okutsu distinguished himself by extraordinary heroism in action on 7 April 1945, on Mount Belvedere, Italy. While his platoon was halted by the crossfire of three machine guns, Technical Sergeant Okutsu boldly crawled to within 30 yards of the nearest enemy emplacement through heavy fire. He destroyed the position with two accurately placed hand grenades, killing three machine gunners. Crawling and dashing from cover to cover, he threw another grenade, silencing a second machine gun, wounding two enemy soldiers, and forcing two others to surrender. Seeing a third machine gun, which obstructed his platoon's advance, he moved forward through heavy small arms fire and was stunned momentarily by rifle fire, which glanced off his helmet. Recovering, he bravely charged several enemy riflemen with his submachine gun, forcing them to withdraw from their positions. Then, rushing the machine gun nest, he captured the weapon and its entire crew of four. By these single-handed actions he enabled his platoon to resume its assault on a vital objective. …", "facts": [["Recipient", "Yukio Okutsu"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "On Mount Belvedere, Italy"]], "wiki": {"Yukio Okutsu": "Yukio_Okutsu"}},
  {"id": "1945-04-08-crews-john-r", "date": "1945-04-08", "title": "Staff Sergeant John R. Crews", "type": "attack", "theater": "Army", "location": {"name": "Near Lobenbacherhof, Germany (approx.)", "lat": 49.15, "lng": 7.6}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty on 8 April 1945 near Lobenbacherhof, Germany. As his company was advancing toward the village under heavy fire, an enemy machinegun and automatic rifle with rifle support opened upon it from a hill on the right flank. Seeing that his platoon leader had been wounded by their fire, S/Sgt. Crews, acting on his own initiative, rushed the strongpoint with 2 men of his platoon. Despite the fact that 1 of these men was killed and the other was badly wounded, he continued his advance up the hill in the face of terrific enemy fire. Storming the well-dug-in position single-handedly, he killed 2 of the crew of the machinegun at pointblank range with his M 1 rifle and wrested the gun from the hands of the German whom he had already wounded. He then with his rifle charged the strongly emplaced automatic rifle. …", "facts": [["Recipient", "John R. Crews"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Lobenbacherhof, Germany"]], "wiki": {"John R. Crews": "John_R._Crews"}},
  {"id": "1945-04-09-moskala-edward-j", "date": "1945-04-09", "title": "Private First Class Edward J. Moskala", "type": "loss", "theater": "Army", "location": {"name": "Kakazu Ridge, Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "He was the leading element when grenade explosions and concentrated machinegun and mortar fire halted the unit's attack on Kakazu Ridge, Okinawa, Ryukyu Islands. With utter disregard for his personal safety, he charged 40 yards through withering, grazing fire and wiped out 2 machinegun nests with well-aimed grenades and deadly accurate fire from his automatic rifle. When strong counterattacks and fierce enemy resistance from other positions forced his company to withdraw, he voluntarily remained behind with 8 others to cover the maneuver. Fighting from a critically dangerous position for 3 hours, he killed more than 25 Japanese before following his surviving companions through screening smoke down the face of the ridge to a gorge where it was discovered that one of the group had been left behind, wounded. Unhesitatingly, Pvt. Moskala climbed the bullet-swept slope to assist in the rescue, and, returning to lower ground, volunteered to protect other wounded while the bulk of the troops quickly took up more favorable positions. …", "facts": [["Recipient", "Edward J. Moskala"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Kakazu Ridge, Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Edward J. Moskala": "Edward_J._Moskala"}},
  {"id": "1945-04-12-hastings-joe-r", "date": "1945-04-12", "title": "Private First Class Joe R. Hastings", "type": "loss", "theater": "Army", "location": {"name": "Drabenderhohe, Germany (approx.)", "lat": 50.93, "lng": 7.5}, "zoom": 9, "summary": "He fought gallantly during an attack against strong enemy forces defending Drabenderhöhe, Germany, from the dug-in positions on commanding ground. As squad leader of a light machinegun section supporting the advance of the 1st and 3d Platoons, he braved direct rifle, machinegun, 20mm., and mortar fire, some of which repeatedly missed him only by inches, and rushed forward over 350 yards of open, rolling fields to reach a position from which he could fire on the enemy troops. From this vantage point he killed the crews of a 20mm. gun and a machinegun, drove several enemy riflemen from their positions, and so successfully shielded the 1st Platoon, that it had time to reorganize and remove its wounded to safety. Observing that the 3d Platoon to his right was being met by very heavy 40mm and machine gun fire, he ran 150 yards with his gun to the leading elements of that unit, where he killed the crew of the 40mm. gun. …", "facts": [["Recipient", "Joe R. Hastings"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Drabenderhohe, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Joe R. Hastings": "Joe_R._Hastings"}},
  {"id": "1945-04-12-erwin-henry-e", "date": "1945-04-12", "title": "Staff Sergeant Henry E. Erwin", "type": "attack", "theater": "Army Air Forces", "location": {"name": "Koriyama, Japan", "lat": 37.4004, "lng": 140.3597}, "zoom": 9, "summary": "He was the radio operator of a B-29 airplane leading a group formation to attack Koriyama, Japan. He was charged with the additional duty of dropping phosphoresce smoke bombs to aid in assembling the group when the launching point was reached. Upon entering the assembly area, aircraft fire and enemy fighter opposition was encountered. Among the phosphoresce bombs launched by S/Sgt. Erwin, 1 proved faulty, exploding in the launching chute, and shot back into the interior of the aircraft, striking him in the face. The burning phosphoresce obliterated his nose and completely blinded him. Smoke filled the plane, obscuring the vision of the pilot. S/Sgt. Erwin realized that the aircraft and crew would be lost if the burning bomb remained in the plane. Without regard for his own safety, he picked it up and feeling his way, instinctively, crawled around the gun turret and headed for the copilot's window. He found the navigator's table obstructing his passage. …", "facts": [["Recipient", "Henry E. Erwin"], ["Rank", "Staff Sergeant"], ["Service", "Army Air Forces"], ["Place of action", "Koriyama, Japan"]], "wiki": {"Henry E. Erwin": "Henry_E._Erwin"}},
  {"id": "1945-04-13-kerstetter-dexter-j", "date": "1945-04-13", "title": "Private First Class Dexter J. Kerstetter", "type": "attack", "theater": "Army", "location": {"name": "Near Galiano, Luzon, Philippines (approx.)", "lat": 16.5, "lng": 120.75}, "zoom": 9, "summary": "He was with his unit in a dawn attack against hill positions approachable only along a narrow ridge paralleled on each side by steep cliffs which were heavily defended by enemy mortars, machineguns, and rifles in well-camouflaged spider holes and tunnels leading to caves. When the leading element was halted by intense fire that inflicted 5 casualties, Pfc. Kerstetter passed through the American line with his squad. Placing himself well in advance of his men, he grimly worked his way up the narrow steep hogback, meeting the brunt of enemy action. With well-aimed shots and rifle-grenade fire, he forced the Japs to take cover. He left the trail and moving down a cliff that offered only precarious footholds, dropped among 4 Japs at the entrance to a cave, fired his rifle from his hip and killed them all. Climbing back to the trail, he advanced against heavy enemy machinegun, rifle, and mortar fire to silence a heavy machinegun by killing its crew of 4 with rifle fire and grenades. …", "facts": [["Recipient", "Dexter J. Kerstetter"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Galiano, Luzon, Philippines"]], "wiki": {"Dexter J. Kerstetter": "Dexter_J._Kerstetter"}},
  {"id": "1945-04-13-anderson-beauford-t", "date": "1945-04-13", "title": "Technical Sergeant Beauford T. Anderson", "type": "attack", "theater": "Army", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity above and beyond the call of duty. When a powerfully conducted predawn Japanese counterattack struck his unit's flank, he ordered his men to take cover in an old tomb, and then, armed only with a carbine, faced the onslaught alone. After emptying 1 magazine at pointblank range into the screaming attackers, he seized an enemy mortar dud and threw it back among the charging Japs, killing several as it burst. Securing a box of mortar shells, he extracted the safety pins, banged the bases upon a rock to arm them and proceeded alternately to hurl shells and fire his piece among the fanatical foe, finally forcing them to withdraw. Despite the protests of his comrades, and bleeding profusely from a severe shrapnel wound, he made his way to his company commander to report the action. T/Sgt. …", "facts": [["Recipient", "Beauford T. Anderson"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Okinawa, Ryukyu Islands"]], "wiki": {"Beauford T. Anderson": "Beauford_T._Anderson"}},
  {"id": "1945-04-14-street-iii-george-l", "date": "1945-04-14", "title": "Lieutenant Commander George L. Street, III", "type": "attack", "theater": "Navy", "location": {"name": "Harbor of Quelpart Island, off the coast of Korea", "lat": 33.38, "lng": 126.53}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as commanding officer of the U.S.S. Tirante during the first war patrol of that vessel against enemy Japanese surface forces in the harbor of Cheju, Quelpart Island, off the coast of Korea, on 14 April 1945. With the crew at surface battle stations, Comdr. (then Lt. Comdr.) Street approached the hostile anchorage from the south within of the coast to complete a reconnoitering circuit of the island. Leaving the 10 fathom curve far behind he penetrated the mined and shoal-obstructed waters of the restricted harbor despite numerous patrolling vessels and in defiance of 5 shore-based radar stations and menacing aircraft. Prepared to fight it out on the surface if attacked, Comdr. Street went into action, sending 2 torpedoes with deadly accuracy into a large Japanese ammunition ship and exploding the target in a mountainous and blinding glare of white flames. …", "facts": [["Recipient", "George L. Street, III"], ["Rank", "Lieutenant Commander"], ["Service", "Navy"], ["Place of action", "Harbor of Quelpart Island, off the coast of Korea"]], "wiki": {"George L. Street, III": "George_L._Street_III"}},
  {"id": "1945-04-14-magrath-john-d", "date": "1945-04-14", "title": "Private First Class John D. Magrath", "type": "loss", "theater": "Army", "location": {"name": "Near Castel d'Aiano, Italy", "lat": 44.2767, "lng": 11.0003}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity above and beyond the call of duty when his company was pinned down by heavy artillery, mortar, and small arms fire, near Castel d'Aiano, Italy. Volunteering to act as a scout, armed with only a rifle, he charged headlong into withering fire, killing 2 Germans and wounding 3 in order to capture a machinegun. Carrying this enemy weapon across an open field through heavy fire, he neutralized 2 more machinegun nests; he then circled behind 4 other Germans, killing them with a burst as they were firing on his company. Spotting another dangerous enemy position to this right, he knelt with the machinegun in his arms and exchanged fire with the Germans until he had killed 2 and wounded 3. The enemy now poured increased mortar and artillery fire on the company's newly won position. Pfc. Magrath fearlessly volunteered again to brave the shelling in order to collect a report of casualties. …", "facts": [["Recipient", "John D. Magrath"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Castel d'Aiano, Italy"], ["Awarded", "Posthumously"]], "wiki": {"John D. Magrath": "John_D._Magrath"}},
  {"id": "1945-04-15-gonsalves-harold", "date": "1945-04-15", "title": "Private First Class Harold Gonsalves", "type": "loss", "theater": "Marine Corps", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Acting Scout Sergeant of a Forward Observer Team, serving with Battery L, Fourth Battalion, Fifteenth Marines, Sixth Marine Division, during action against enemy Japanese forces in Okinawa Shima in the Ryūkyū Chain, 15 April 1945. Undaunted by the powerfully organized opposition encountered on Motobu Peninsula during a fierce assault waged by a Marine infantry battalion against a Japanese strong-hold, Private First Class Gonsalves repeatedly braved the terrific hostile bombardment to aid his Forward Observation Team in directing well-placed artillery fire and, when his commanding officer determined to move into the front lines in order to register a more effective bombardment in the enemy's defensive position, unhesitatingly advanced uphill with the officer and another Marine despite a slashing barrage of enemy mortar and rifle fire. As they reached the front, a Japanese grenade fell close within the group. …", "facts": [["Recipient", "Harold Gonsalves"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Harold Gonsalves": "Harold_Gonsalves"}},
  {"id": "1945-04-16-bush-richard-e", "date": "1945-04-16", "title": "Corporal Richard E. Bush", "type": "attack", "theater": "Marine Corps", "location": {"name": "Mount Yaedake, Okinawa, Ryukyu Islands", "lat": 26.6356, "lng": 127.9283}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Squad Leader serving with the First Battalion, Fourth Marines, Sixth Marine Division, in action against Japanese forces during the final assault against Mt. Yaetake on Okinawa, Ryukyu Islands, April 16, 1945. Rallying his men forward with indomitable determination, Corporal Bush boldly defied the slashing fury of concentrated Japanese artillery fire pouring down from the gun-studded mountain fortress to lead his squad up the face of the rocky precipice, sweep over the ridge and drive the defending troops from their deeply entrenched position. With his unit, the first to break through to the inner defense of Mt. Yaetake, he fought relentlessly in the forefront of the action until seriously wounded and evacuated with others under protecting rocks. …", "facts": [["Recipient", "Richard E. Bush"], ["Rank", "Corporal"], ["Service", "Marine Corps"], ["Place of action", "Mount Yaedake, Okinawa, Ryukyu Islands"]], "wiki": {"Richard E. Bush": "Richard_E._Bush"}},
  {"id": "1945-04-17-burke-frank", "date": "1945-04-17", "title": "First Lieutenant Frank Burke", "type": "attack", "theater": "Army", "location": {"name": "Nuremberg, Germany", "lat": 49.4539, "lng": 11.0775}, "zoom": 9, "summary": "He fought with extreme gallantry in the streets of war-torn Nuremberg, Germany, where Company D, 1st Battalion, 15th Infantry, was engaged in rooting out fanatical defenders of the citadel of Nazism. As battalion transportation officer he had gone forward to select a motor-pool site, when, in a desire to perform more than his assigned duties and participate in the fight, he advanced beyond the lines of the forward riflemen. Detecting a group of about 10 Germans making preparations for a local counterattack, he rushed back to a nearby American company, secured a light machinegun with ammunition, and daringly opened fire on this superior force, which deployed and returned his fire with machine pistols, rifles, and rocket launchers. From another angle a German machinegun tried to blast him from his emplacement, but 1st Lt. Burke killed this guncrew and drove off the survivors of the unit he had originally attacked. …", "facts": [["Recipient", "Frank Burke"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Nuremberg, Germany"]], "wiki": {"Frank Burke": "Frank_Burke_(United_States_Army_officer)"}},
  {"id": "1945-04-18-daly-michael-j", "date": "1945-04-18", "title": "First Lieutenant Michael J. Daly", "type": "attack", "theater": "Army", "location": {"name": "Nuremberg, Germany (approx.)", "lat": 49.45, "lng": 11.08}, "zoom": 9, "summary": "Mr. Daly is a U.S. Army veteran of World War II who received the Congressional Medal of Honor for extreme heroism while leading his infantry company through the shell-battered, sniper-infested wreckage of Nuremberg, Germany, in April 1945. Following his distinctive military service, he became very involved in veterans' and community affairs, serving on the Board of Directors of St. Vincent's Hospital and founding the hospital's Daly Foundation. He has also provided decades of volunteer service to handicapped children, the Town of Fairfield and served as a member of the Connecticut Judicial Review Council.", "facts": [["Recipient", "Michael J. Daly"], ["Rank", "First Lieutenant"], ["Service", "Army"], ["Place of action", "Nuremberg, Germany"]], "wiki": {"Michael J. Daly": "Michael_J._Daly"}},
  {"id": "1945-04-18-merrell-joseph-f", "date": "1945-04-18", "title": "Private Joseph F. Merrell", "type": "loss", "theater": "Army", "location": {"name": "Near Lohe, Germany (approx.)", "lat": 50.9, "lng": 6.5}, "zoom": 9, "summary": "He made a gallant, 1-man attack against vastly superior enemy forces near Lohe, Germany. His unit, attempting a quick conquest of hostile hill positions that would open the route to Nuremberg before the enemy could organize his defense of that city, was pinned down by brutal fire from rifles, machine pistols, and 2 heavy machine guns. Entirely on his own initiative, Pvt. Merrell began a singlehanded assault. He ran 100 yards through concentrated fire, barely escaping death at each stride, and at point blank range engaged 4 German machine pistolmen with his rifle, killing all of them while their bullets ripped his uniform. As he started forward again, his rifle was smashed by a sniper's bullet, leaving him armed only with 3 grenades. But he did not hesitate. He zigzagged 200 yards through a hail of bullets to within 10 yards of the first machine gun, where he hurled 2 grenades and then rushed the position, ready to fight with his bare hands if necessary. …", "facts": [["Recipient", "Joseph F. Merrell"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Lohe, Germany"], ["Awarded", "Posthumously"]], "wiki": {"Joseph F. Merrell": "Joseph_F._Merrell"}},
  {"id": "1945-04-19-may-martin-o", "date": "1945-04-19", "title": "Private First Class Martin O. May", "type": "loss", "theater": "Army", "location": {"name": "Legusuku-Yama, Ie Shima, Ryukyu Islands", "lat": 26.7161, "lng": 127.7903}, "zoom": 9, "summary": "He gallantly maintained a 3-day stand in the face of terrible odds when American troops fought for possession of the rugged slopes of legusuku-Yama on Ie Shima, Ryukyu Islands. After placing his heavy machinegun in an advantageous yet vulnerable position on a ridge to support riflemen, he became the target of fierce mortar and small arms fire from counterattacking Japanese. He repulsed this assault by sweeping the enemy with accurate bursts while explosions and ricocheting bullets threw blinding dust and dirt about him. He broke up a second counterattack by hurling grenades into the midst of the enemy forces, and then refused to withdraw, volunteering to maintain his post and cover the movement of American riflemen as they reorganized to meet any further hostile action. The major effort of the enemy did not develop until the morning of 21 April. It found Pfc. May still supporting the rifle company in the face of devastating rifle, machinegun, and mortar fire. …", "facts": [["Recipient", "Martin O. May"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Legusuku-Yama, Ie Shima, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Martin O. May": "Martin_O._May"}},
  {"id": "1945-04-20-hayashi-joe", "date": "1945-04-20", "title": "Private Joe Hayashi", "type": "loss", "theater": "Army", "location": {"name": "Near Tendola, Italy (approx.)", "lat": 44.17, "lng": 10.03}, "zoom": 9, "summary": "Private Joe Hayashi distinguished himself by extraordinary heroism in action on 20 and 22 April 1945, near Tendola, Italy. On 20 April 1945, ordered to attack a strongly defended hill that commanded all approaches to the village of Tendola, Private Hayashi skillfully led his men to a point within 75 yards of enemy positions before they were detected and fired upon. After dragging his wounded comrades to safety, he returned alone and exposed himself to small arms fire in order to direct and adjust mortar fire against hostile emplacements. Boldly attacking the hill with the remaining men of his squad, he attained his objective and discovered that the mortars had neutralized three machine guns, killed 27 men, and wounded many others. On 22 April 1945, attacking the village of Tendola, Private Hayashi maneuvered his squad up a steep, terraced hill to within 100 yards of the enemy. …", "facts": [["Recipient", "Joe Hayashi"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Near Tendola, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Joe Hayashi": "Joe_Hayashi"}},
  {"id": "1945-04-22-thomas-william-h", "date": "1945-04-22", "title": "Private First Class William H. Thomas", "type": "loss", "theater": "Army", "location": {"name": "Zambales Mountains, Luzon, Philippines", "lat": 15.6833, "lng": 120.0833}, "zoom": 9, "summary": "He was a member of the leading squad of Company B, which was attacking along a narrow, wooded ridge. The enemy strongly entrenched in camouflaged emplacements on the hill beyond directed heavy fire and hurled explosive charges on the attacking riflemen. Pfc. Thomas, an automatic rifleman, was struck by 1 of these charges, which blew off both his legs below the knees. He refused medical aid and evacuation, and continued to fire at the enemy until his weapon was put out of action by an enemy bullet. Still refusing aid, he threw his last 2 grenades. He destroyed 3 of the enemy after suffering the wounds from which he died later that day. The effective fire of Pfc. Thomas prevented the repulse of his platoon and assured the capture of the hostile position. His magnificent courage and heroic devotion to duty provided a lasting inspiration for his comrades.", "facts": [["Recipient", "William H. Thomas"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Zambales Mountains, Luzon, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"William H. Thomas": "William_H._Thomas_(Medal_of_Honor)"}},
  {"id": "1945-04-24-knight-raymond-l", "date": "1945-04-24", "title": "First Lieutenant Raymond L. Knight", "type": "loss", "theater": "Army Air Forces", "location": {"name": "Northern Po Valley, Italy (approx.)", "lat": 45.0, "lng": 10.5}, "zoom": 6, "summary": "He piloted a fighter-bomber aircraft in a series of low-level strafing missions, destroying 14 grounded enemy aircraft and leading attacks which wrecked 10 others during a critical period of the Allied drive in northern Italy. On the morning of 24 April, he volunteered to lead 2 other aircraft against the strongly defended enemy airdrome at Ghedi. Ordering his fellow pilots to remain aloft, he skimmed the ground through a deadly curtain of antiaircraft fire to reconnoiter the field, locating 8 German aircraft hidden beneath heavy camouflage. He rejoined his flight, briefed them by radio, and then led them with consummate skill through the hail of enemy fire in a low-level attack, destroying 5 aircraft, while his flight accounted for 2 others. Returning to his base, he volunteered to lead 3 other aircraft in reconnaissance of Bergamo airfield, an enemy base near Ghedi and 1 known to be equally well defended. Again ordering his flight to remain out of range of antiaircraft fire, 1st Lt. …", "facts": [["Recipient", "Raymond L. Knight"], ["Rank", "First Lieutenant"], ["Service", "Army Air Forces"], ["Place of action", "Northern Po Valley, Italy"], ["Awarded", "Posthumously"]], "wiki": {"Raymond L. Knight": "Raymond_L._Knight"}},
  {"id": "1945-04-25-gonzales-david-m", "date": "1945-04-25", "title": "Private First Class David M. Gonzales", "type": "loss", "theater": "Army", "location": {"name": "Villa Verde Trail, Luzon, Philippines (approx.)", "lat": 16.1, "lng": 120.9}, "zoom": 9, "summary": "He was pinned down with his company. As enemy fire swept the area, making any movement extremely hazardous, a 500-pound bomb smashed into the company's perimeter, burying 5 men with its explosion. Pfc. Gonzales, without hesitation, seized an entrenching tool and under a hail of fire crawled 15 yards to his entombed comrades, where his commanding officer, who had also rushed forward, was beginning to dig the men out. Nearing his goal, he saw the officer struck and instantly killed by machinegun fire. Undismayed, he set to work swiftly and surely with his hands and the entrenching tool while enemy sniper and machinegun bullets struck all about him. He succeeded in digging one of the men out of the pile of rock and sand. To dig faster he stood up regardless of the greater danger from so exposing himself. He extricated a second man, and then another. …", "facts": [["Recipient", "David M. Gonzales"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Villa Verde Trail, Luzon, Philippines"], ["Awarded", "Posthumously, G.O. No. 115, December 8, 1945"]], "wiki": {"David M. Gonzales": "David_M._Gonzales"}},
  {"id": "1945-04-28-ruiz-alejandro-r", "date": "1945-04-28", "title": "Private First Class Alejandro R. Ruiz", "type": "attack", "theater": "Army", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "' :When his unit was stopped by a skillfully camouflaged enemy pillbox, he displayed conspicuous gallantry and intrepidity above and beyond the call of duty. His squad, suddenly brought under a hail of machinegun fire and a vicious grenade attack, was pinned down. Jumping to his feet, Pfc. Ruiz seized an automatic rifle and lunged through the flying grenades and rifle and automatic fire for the top of the emplacement. When an enemy soldier charged him, his rifle jammed. Undaunted, Pfc. Ruiz whirled on his assailant and clubbed him down. Then he ran back through bullets and grenades, seized more ammunition and another automatic rifle, and again made for the pillbox. Enemy fire now was concentrated on him, but he charged on, miraculously reaching the position, and in plain view he climbed to the top. Leaping from one opening to another, he sent burst after burst into the pillbox, killing 12 of the enemy and completely destroying the position. Pfc. …", "facts": [["Recipient", "Alejandro R. Ruiz"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "G.O. No. 60, June 26, 1946"]], "wiki": {"Alejandro R. Ruiz": "Alejandro_R._Ruiz"}},
  {"id": "1945-04-29-doss-desmond-t", "date": "1945-04-29", "title": "Private First Class Desmond T. Doss", "type": "attack", "theater": "Army", "location": {"name": "Near Urasoe Mura, Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "Private First Class Desmond T. Doss, United States Army, Medical Detachment, 307th Infantry, 77th Infantry Division. Near Urasoe-Mura, Okinawa, Ryukyu Islands, 29 April – 21 May 1945. He was a company aid man when the 1st Battalion assaulted a jagged escarpment 400 feet high. As our troops gained the summit, a heavy concentration of artillery, mortar and machinegun fire crashed into them, inflicting approximately 75 casualties and driving the others back. Private First Class Doss refused to seek cover and remained in the fire-swept area with the many stricken, carrying them one by one to the edge of the escarpment and there lowering them on a rope-supported litter down the face of a cliff to friendly hands. …", "facts": [["Recipient", "Desmond T. Doss"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Near Urasoe Mura, Okinawa, Ryukyu Islands"], ["Awarded", "G.O. No. 97, November 1, 1945"]], "wiki": {"Desmond T. Doss": "Desmond_Doss"}},
  {"id": "1945-05-02-bush-robert-e", "date": "1945-05-02", "title": "Hospital Apprentice First class Robert E. Bush", "type": "attack", "theater": "Navy", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving as Medical Corpsman with a rifle company, in action against enemy Japanese forces on Okinawa Jima, Ryukyu Islands, 2 May 1945. Fearlessly braving the fury of artillery, mortar, and machinegun fire from strongly entrenched hostile positions, Bush constantly and unhesitatingly moved from one casualty to another to attend the wounded falling under the enemy's murderous barrages. As the attack passed over a ridge top, Bush was advancing to administer blood plasma to a marine officer lying wounded on the skyline when the Japanese launched a savage counterattack. In this perilously exposed position, he resolutely maintained the flow of life-giving plasma. With the bottle held high in one hand, Bush drew his pistol with the other and fired into the enemy's ranks until his ammunition was expended. …", "facts": [["Recipient", "Robert E. Bush"], ["Rank", "Hospital Apprentice First class"], ["Service", "Navy"], ["Place of action", "Okinawa, Ryukyu Islands"]], "wiki": {"Robert E. Bush": "Robert_Eugene_Bush"}},
  {"id": "1945-05-02-foster-william-a", "date": "1945-05-02", "title": "Private First Class William A. Foster", "type": "loss", "theater": "Marine Corps", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as a Rifleman with Company K, Third Battalion, First Marines, First Marine Division, in action against enemy Japanese forces on Okinawa Shima in the Ryūkyū Chain, May 2, 1945. Dug in with another Marine on the point of the perimeter defense after waging a furious assault against a strongly fortified Japanese position, Private First Class Foster and comrade engaged in a fierce hand grenade duel with infiltrating enemy soldiers. Suddenly an enemy grenade landed beyond reach in the foxhole. Instantly diving on the deadly missile, Private First Class Foster absorbed the exploding charge in his own body, thereby protecting the other Marine from serious injury. …", "facts": [["Recipient", "William A. Foster"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"William A. Foster": "William_A._Foster"}},
  {"id": "1945-05-04-kinser-elbert-l", "date": "1945-05-04", "title": "Sergeant Elbert L. Kinser", "type": "loss", "theater": "Marine Corps", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while acting as Leader of a Rifle Platoon, serving with Company I, Third Battalion, First Marines, First Marine Division, in action against Japanese forces on Okinawa Shima in the Ryūkyū Chain, May 4, 1945. Taken under sudden, close attack by hostile troops entrenched on the reverse slope while moving up a strategic ridge along which his platoon was holding newly won positions, Sergeant Kinser engaged the enemy in a fierce hand grenade battle. Quick to act when a Japanese grenade landed in the immediate vicinity, Sergeant Kinser unhesitatingly threw himself on the deadly missile, absorbing the full charge of the shattering explosion in his own body and thereby protecting his men from serious injury and possible death. Stouthearted and indomitable, he had yielded his own chance of survival that his comrades might live to carry on the relentless battle against a fanatic enemy. …", "facts": [["Recipient", "Elbert L. Kinser"], ["Rank", "Sergeant"], ["Service", "Marine Corps"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Elbert L. Kinser": "Elbert_L._Kinser"}},
  {"id": "1945-05-07-fardy-john-p", "date": "1945-05-07", "title": "Corporal John P. Fardy", "type": "loss", "theater": "Marine Corps", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as a Squad Leader, serving with Company C, First Battalion, First Marines, First Marine Division, in action against enemy Japanese forces on Okinawa Shima in the Ryukyu Islands, 7 May 1945. When his squad was suddenly assailed by extremely heavy small-arms fire from the front during a determined advance against strongly fortified, fiercely defended Japanese positions, Corporal Fardy temporarily deployed his men along a near-by drainage ditch. Shortly thereafter, an enemy grenade fell among the Marines in the ditch. Instantly throwing himself upon the deadly missile, Corporal Fardy absorbed the exploding blast in his own body, thereby protecting his comrades from certain and perhaps fatal injuries. Concerned solely for the welfare of his men, he willingly relinquished his own hope of survival that his fellow Marines might live to carry on the fight against a fanatic enemy. …", "facts": [["Recipient", "John P. Fardy"], ["Rank", "Corporal"], ["Service", "Marine Corps"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"John P. Fardy": "John_P._Fardy"}},
  {"id": "1945-05-07-hansen-dale-m", "date": "1945-05-07", "title": "Private Dale M. Hansen", "type": "loss", "theater": "Marine Corps", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with Company E, Second Battalion, First Marines, First Marine Division, in action against enemy Japanese forces on Okinawa Shima in the Ryūkyū Chain, May 7, 1945. Cool and courageous in combat, Private Hansen unhesitatingly took the initiative during a critical stage of the action and, armed with a rocket launcher, crawled to an exposed position where he attacked and destroyed a strategically located hostile pillbox. With his weapon subsequently destroyed by enemy fire, he seized a rifle and continued his one-man assault. Reaching the crest of a ridge, he leaped across, opened fire on six Japanese and killed four before his rifle jammed. Attacked by the remaining two Japanese, he beat them off with the butt of his rifle and then climbed back to cover. …", "facts": [["Recipient", "Dale M. Hansen"], ["Rank", "Private"], ["Service", "Marine Corps"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Dale M. Hansen": "Dale_M._Hansen"}},
  {"id": "1945-05-07-schwab-albert-e", "date": "1945-05-07", "title": "Private First Class Albert E. Schwab", "type": "loss", "theater": "Marine Corps", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as a Flame Thrower Operator serving with Headquarters Company, First Battalion, Fifth Marines, First Marine Division, in action against enemy Japanese forces on Okinawa Shima on one of the Ryukyu Islands, May 7, 1945. Quick to take action when his company was pinned down in a valley and suffering resultant heavy casualties under blanketing machine-gun fire emanating from a high ridge to the front, Private First Class Schwab, unable to flank the enemy emplacement because of steep cliffs on either side, advanced up the face of the ridge in bold defiance of the intense barrage and, skillfully directing the fire of his flame thrower, quickly demolished the hostile gun position, thereby enabling his company to occupy the ridge. Suddenly a second Japanese machine gun opened fire, killing or wounding several Marines with its initial burst. …", "facts": [["Recipient", "Albert E. Schwab"], ["Rank", "Private First Class"], ["Service", "Marine Corps"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Albert E. Schwab": "Albert_E._Schwab"}},
  {"id": "1945-05-08-krotiak-anthony-l", "date": "1945-05-08", "title": "Private First Class Anthony L. Krotiak", "type": "loss", "theater": "Army", "location": {"name": "Balete Pass, Luzon, Philippines", "lat": 16.1331, "lng": 120.932}, "zoom": 9, "summary": "He was an acting squad leader, directing his men in consolidating a newly won position on Hill B when the enemy concentrated small arms fire and grenades upon him and 4 others, driving them to cover in an abandoned Japanese trench. A grenade thrown from above landed in the center of the group. Instantly pushing his comrades aside and jamming the grenade into the earth with his rifle butt, he threw himself over it, making a shield of his body to protect the other men. The grenade exploded under him, and he died a few minutes later. By his extraordinary heroism in deliberately giving his life to save those of his comrades, Pfc. Krotiak set an inspiring example of utter devotion and self-sacrifice which reflects the highest traditions of the military service.", "facts": [["Recipient", "Anthony L. Krotiak"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Balete Pass, Luzon, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Anthony L. Krotiak": "Anthony_L._Krotiak"}},
  {"id": "1945-05-08-diamond-james-h", "date": "1945-05-08", "title": "Private First Class James H. Diamond", "type": "loss", "theater": "Army", "location": {"name": "Mintal, Mindanao, Philippines (approx.)", "lat": 7.08, "lng": 125.5}, "zoom": 9, "summary": "As a member of the machinegun section, he displayed extreme gallantry and intrepidity above and beyond the call of duty . When a Japanese sniper rose from his foxhole to throw a grenade into their midst, this valiant soldier charged and killed the enemy with a burst from his submachine gun; then, by delivering sustained fire from his personal arm and simultaneously directing the fire of 105mm. and .50 caliber weapons upon the enemy pillboxes immobilizing this and another machinegun section, he enabled them to put their guns into action. When 2 infantry companies established a bridgehead, he voluntarily assisted in evacuating the wounded under heavy fire; and then, securing an abandoned vehicle, transported casualties to the rear through mortar and artillery fire so intense as to render the vehicle inoperative and despite the fact he was suffering from a painful wound. The following day he again volunteered, this time for the hazardous job of repairing a bridge under heavy enemy fire. …", "facts": [["Recipient", "James H. Diamond"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Mintal, Mindanao, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"James H. Diamond": "James_H._Diamond"}},
  {"id": "1945-05-10-halyburton-jr-william-d", "date": "1945-05-10", "title": "Pharmacist's Mate Second class William D. Halyburton Jr.", "type": "loss", "theater": "Navy", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with a Marine Rifle Company in the 2d Battalion, 5th Marines, 1st Marine Division, during action against enemy Japanese forces on Okinawa Shima in the Ryukyu Chain, 10 May 1945. Undaunted by the deadly accuracy of Japanese counterfire as his unit pushed the attack through a strategically important draw, Halyburton unhesitatingly dashed across the draw and up the hill into an open fire-swept field where the company advance squad was suddenly pinned down under a terrific concentration of mortar, machinegun and sniper fire with resultant severe casualties. Moving steadily forward despite the enemy's merciless barrage, he reached the wounded marine who lay farthest away and was rendering first aid when his patient was struck for the second time by a Japanese bullet. …", "facts": [["Recipient", "William D. Halyburton Jr."], ["Rank", "Pharmacist's Mate Second class"], ["Service", "Navy"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"William D. Halyburton Jr.": "William_D._Halyburton_Jr."}},
  {"id": "1945-05-11-terry-seymour-w", "date": "1945-05-11", "title": "Captain Seymour W. Terry", "type": "loss", "theater": "Army", "location": {"name": "Zebra Hill, Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "1st Lt. Terry was leading an attack against heavily defended Zebra Hill when devastating fire from 5 pillboxes halted the advance. He braved the hail of bullets to secure satchel charges and white phosphorus grenades, and then ran 30 yards directly at the enemy with an ignited charge to the first stronghold, demolished it, and moved on to the other pillboxes, bombarding them with his grenades and calmly cutting down their defenders with rifle fire as they attempted to escape. When he had finished this job by sealing the 4 pillboxes with explosives, he had killed 20 Japanese and destroyed 3 machineguns. The advance was again held up by an intense grenade barrage which inflicted several casualties. Locating the source of enemy fire in trenches on the reverse slope of the hill, 1st Lt. Terry, burdened by 6 satchel charges launched a 1-man assault. …", "facts": [["Recipient", "Seymour W. Terry"], ["Rank", "Captain"], ["Service", "Army"], ["Place of action", "Zebra Hill, Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Seymour W. Terry": "Seymour_W._Terry"}},
  {"id": "1945-05-11-mckinney-john-r", "date": "1945-05-11", "title": "Private John R. McKinney", "type": "attack", "theater": "Army", "location": {"name": "Tayabas Province, Luzon, Philippines", "lat": 13.93, "lng": 121.62}, "zoom": 9, "summary": "He fought with extreme gallantry to defend the outpost which had been established near Dingalan Bay. Just before daybreak approximately 100 Japanese stealthily attacked the perimeter defense, concentrating on a light machinegun position; having completed a long tour of duty at this gun, Pvt. McKinney was resting a few paces away when an enemy soldier dealt him a glancing blow on the head with a saber. Although dazed by the stroke, he seized his rifle, bludgeoned his attacker, and then shot another assailant who was charging him. Meanwhile, one of his comrades at the machinegun had been wounded and his other companion withdrew carrying the injured man to safety. Alone, Pvt. McKinney was confronted by ten infantrymen who had captured the machinegun with the evident intent of reversing it to fire into the perimeter. Leaping into the emplacement, he shot seven of them at pointblank range and killed three more with his rifle butt. …", "facts": [["Recipient", "John R. McKinney"], ["Rank", "Private"], ["Service", "Army"], ["Place of action", "Tayabas Province, Luzon, Philippines"]], "wiki": {"John R. McKinney": "John_R._McKinney"}},
  {"id": "1945-05-14-day-james-l", "date": "1945-05-14", "title": "Corporal James L. Day", "type": "attack", "theater": "Marine Corps", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as a squad leader serving with the Second Battalion, Twenty-Second Marines, Sixth Marine Division, in sustained combat operations against Japanese forces on Okinawa, Ryukyu Islands from 14 to 17 May 1945. On the first day, Corporal Day rallied his squad and the remnants of another unit and led them to a critical position forward of the front lines of Sugar Loaf Hill. Soon thereafter, they came under an intense mortar and artillery barrage that was quickly followed by a fanatical ground attack of about forty Japanese soldiers. Despite the loss of one-half of his men, Corporal Day remained at the forefront, shouting encouragement, hurling hand grenades, and directing deadly fire thereby repelling the determined enemy. Reinforced by six men, he led his squad in repelling three fierce night attacks but suffered five additional Marines killed and one wounded whom he assisted to safety. …", "facts": [["Recipient", "James L. Day"], ["Rank", "Corporal"], ["Service", "Marine Corps"], ["Place of action", "Okinawa, Ryukyu Islands"]], "wiki": {"James L. Day": "James_L._Day"}},
  {"id": "1945-05-14-hauge-jr-louis-j", "date": "1945-05-14", "title": "Corporal Louis J. Hauge Jr.", "type": "loss", "theater": "Marine Corps", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Leader of a Machine-Gun Squad serving with Company C, First Battalion, First Marines, First Marine Division, in action against enemy Japanese forces on Okinawa Shima in the Ryūkyū Chain on 14 May 1945. Alert and aggressive during a determined assault against a strongly fortified Japanese Hill position, Corporal Hauge boldly took the initiative when his company's left flank was pinned down under a heavy machine-gun and mortar barrage with resultant severe casualties and, quickly locating the two machine guns which were delivering the uninterrupted stream of enfilade fire, ordered his squad to maintain a covering barrage as he rushed across an exposed area toward the furiously blazing enemy weapons. Although painfully wounded as he charged the first machine-gun, he launched a vigorous single-handed grenade attack, destroyed the entire hostile gun position and moved relentlessly forward toward the other emplacement despite his wounds and the increasingly heavy Japanese fire. …", "facts": [["Recipient", "Louis J. Hauge Jr."], ["Rank", "Corporal"], ["Service", "Marine Corps"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Louis J. Hauge Jr.": "Louis_J._Hauge_Jr."}},
  {"id": "1945-05-14-courtney-jr-henry-a", "date": "1945-05-14", "title": "Major Henry A. Courtney Jr.", "type": "loss", "theater": "Marine Corps", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as Executive Officer of the Second Battalion, Twenty-Second Marines, Sixth Marine Division, in action against enemy Japanese forces on Okinawa Shima in the Ryukyu Islands, 14 and 15 May 1945. Ordered to hold for the night in static defense behind Sugar Loaf Hill after leading the forward elements of his command in a prolonged fire fight, Major Courtney weighed the effect of a hostile night counterattack against the tactical value of an immediate Marine assault, resolved to initiate the assault, and promptly obtained permission to advance and seize the forward slope of the hill. Quickly explaining the situation to his small remaining force, he declared his personal intention of moving forward and then proceeded on his way, boldly blasting near-by cave positions and neutralizing enemy guns as he went. …", "facts": [["Recipient", "Henry A. Courtney Jr."], ["Rank", "Major"], ["Service", "Marine Corps"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Henry A. Courtney Jr.": "Henry_A._Courtney_Jr."}},
  {"id": "1945-05-15-muller-joseph-e", "date": "1945-05-15", "title": "Sergeant Joseph E. Muller", "type": "loss", "theater": "Army", "location": {"name": "Near Ishimmi, Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity above and beyond the call of duty. When his platoon was stopped by deadly fire from a strongly defended ridge, he directed men to points where they could cover his attack. Then through the vicious machinegun and automatic fire, crawling forward alone, he suddenly jumped up, hurled his grenades, charged the enemy, and drove them into the open where his squad shot them down. Seeing enemy survivors about to man a machinegun, He fired his rifle at point-blank range, hurled himself upon them, and killed the remaining 4. Before dawn the next day, the enemy counterattacked fiercely to retake the position. Sgt. Muller crawled forward through the flying bullets and explosives, then leaping to his feet, hurling grenades and firing his rifle, he charged the Japs and routed them. As he moved into his foxhole shared with 2 other men, a lone enemy, who had been feigning death, threw a grenade. Quickly seeing the danger to his companions, Sgt. …", "facts": [["Recipient", "Joseph E. Muller"], ["Rank", "Sergeant"], ["Service", "Army"], ["Place of action", "Near Ishimmi, Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Joseph E. Muller": "Joseph_E._Muller"}},
  {"id": "1945-05-23-sjogren-john-c", "date": "1945-05-23", "title": "Staff Sergeant John C. Sjogren", "type": "attack", "theater": "Army", "location": {"name": "Near San Jose Hacienda, Negros, Philippines", "lat": 10, "lng": 123}, "zoom": 9, "summary": "He led an attack against a high precipitous ridge defended by a company of enemy riflemen, who were entrenched in spider holes and supported by well-sealed pillboxes housing automatic weapons with interlocking bands of fire. The terrain was such that only 1 squad could advance at one time; and from a knoll atop a ridge a pillbox covered the only approach with automatic fire. Against this enemy stronghold, S/Sgt. Sjogren led the first squad to open the assault. Deploying his men, he moved forward and was hurling grenades when he saw that his next in command, at the opposite flank, was gravely wounded. Without hesitation he crossed 20 yards of exposed terrain in the face of enemy fire and exploding dynamite charges, moved the man to cover and administered first aid. He then worked his way forward and, advancing directly into the enemy fire, killed 8 Japanese in spider holes guarding the approach to the pillbox. …", "facts": [["Recipient", "John C. Sjogren"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near San Jose Hacienda, Negros, Philippines"]], "wiki": {"John C. Sjogren": "John_C._Sjogren"}},
  {"id": "1945-05-31-craft-clarence-b", "date": "1945-05-31", "title": "Private First Class Clarence B. Craft", "type": "attack", "theater": "Army", "location": {"name": "Hen Hill, Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "He was a rifleman when his platoon spearheaded an attack on Hen Hill, the tactical position on which the entire Naha-Shuri-Yonaburu line of Japanese defense on Okinawa, Ryukyu Islands, was hinged. For 12 days our forces had been stalled, and repeated, heavy assaults by 1 battalion and then another had been thrown back by the enemy with serious casualties. With 5 comrades, Pfc. Craft was dispatched in advance of Company G to feel out the enemy resistance. The group had proceeded only a short distance up the slope when rifle and machinegun fire, coupled with a terrific barrage of grenades, wounded 3 and pinned down the others. Against odds that appeared suicidal, Pfc. Craft launched a remarkable 1-man attack. He stood up in full view of the enemy and began shooting with deadly marksmanship wherever he saw a hostile movement. …", "facts": [["Recipient", "Clarence B. Craft"], ["Rank", "Private First Class"], ["Service", "Army"], ["Place of action", "Hen Hill, Okinawa, Ryukyu Islands"]], "wiki": {"Clarence B. Craft": "Clarence_B._Craft"}},
  {"id": "1945-06-05-harr-harry-r", "date": "1945-06-05", "title": "Corporal Harry R. Harr", "type": "loss", "theater": "Army", "location": {"name": "Near Maglamin, Mindanao, Philippines (approx.)", "lat": 8.1, "lng": 124.6}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity. In a fierce counterattack, the Japanese closed in on his machinegun emplacement, hurling hand grenades, 1 of which exploded under the gun, putting it out of action and wounding 2 of the crew. While the remaining gunners were desperately attempting to repair their weapon another grenade landed squarely in the emplacement. Quickly realizing he could not safely throw the unexploded missile from the crowded position, Cpl. Harr unhesitatingly covered it with his body to smother the blast. His supremely courageous act, which cost him his life, saved 4 of his comrades and enabled them to continue their mission.", "facts": [["Recipient", "Harry R. Harr"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Near Maglamin, Mindanao, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Harry R. Harr": "Harry_R._Harr"}},
  {"id": "1945-06-06-woodford-howard-e", "date": "1945-06-06", "title": "Staff Sergeant Howard E. Woodford", "type": "loss", "theater": "Army", "location": {"name": "Near Tabio, Luzon, Philippines (approx.)", "lat": 16.62, "lng": 120.7}, "zoom": 9, "summary": "He volunteered to investigate the delay in a scheduled attack by an attached guerrilla battalion. Reaching the line of departure, he found that the lead company, in combat for the first time, was immobilized by intense enemy mortar, machinegun, and rifle fire which had caused casualties to key personnel. Knowing that further failure to advance would endanger the flanks of adjacent units, as well as delay capture of the objective, he immediately took command of the company, evacuated the wounded, reorganized the unit under fire, and prepared to attack. He repeatedly exposed himself to draw revealing fire from the Japanese strongpoints, and then moved forward with a 5-man covering force to determine exact enemy positions. Although intense enemy machinegun fire killed 2 and wounded his other 3 men, S/Sgt. Woodford resolutely continued his patrol before returning to the company. …", "facts": [["Recipient", "Howard E. Woodford"], ["Rank", "Staff Sergeant"], ["Service", "Army"], ["Place of action", "Near Tabio, Luzon, Philippines"], ["Awarded", "Posthumously"]], "wiki": {"Howard E. Woodford": "Howard_E._Woodford"}},
  {"id": "1945-06-07-mctureous-jr-robert-m", "date": "1945-06-07", "title": "Private Robert M. McTureous Jr.", "type": "loss", "theater": "Marine Corps", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving with Company H, Third Battalion, Twenty-ninth Marines, Sixth Marine Division, in action against enemy Japanese forces on Okinawa in the Ryūkyū Chain, June 7, 1945. Alert and ready for any hostile counteraction following his company's seizure of an important hill-objective Private McTureous was quick to observe the plight of company stretcher-bearers who were suddenly assailed by slashing machine-gun fire as they attempted to evacuate wounded at the rear of the nearby won position. Determined to prevent further casualties, he quickly filled his shirt with hand grenades and charged the enemy-occupied caves from which the concentrated barrage was emanating. …", "facts": [["Recipient", "Robert M. McTureous Jr."], ["Rank", "Private"], ["Service", "Marine Corps"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Robert M. McTureous Jr.": "Robert_M._McTureous_Jr."}},
  {"id": "1945-06-08-lester-fred-f", "date": "1945-06-08", "title": "Hospital Apprentice First class Fred F. Lester", "type": "loss", "theater": "Navy", "location": {"name": "Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty while serving as a Medical Corpsman with an Assault Rifle Platoon, attached to the First Battalion, Twenty-second Marines, SIXTH Marine Division, during action against enemy Japanese forces on Okinawa Shima in the Ryukyu Chain, 8 June 1945. Quick to spot a wounded marine lying in an open field beyond the front lines following the relentless assault against a strategic Japanese hill position, LESTER unhesitatingly crawled toward the casualty under a concentrated barrage from hostile machineguns, rifles, and grenades. Torn by enemy rifle bullets as he inched forward, he stoically disregarded the mounting fury of Japanese fire and his own pain to pull the wounded man toward a covered position. …", "facts": [["Recipient", "Fred F. Lester"], ["Rank", "Hospital Apprentice First class"], ["Service", "Navy"], ["Place of action", "Okinawa, Ryukyu Islands"], ["Awarded", "Posthumously"]], "wiki": {"Fred F. Lester": "Fred_Faulkner_Lester"}},
  {"id": "1945-06-10-mccool-richard-m", "date": "1945-06-10", "title": "Lieutenant Richard M. McCool", "type": "attack", "theater": "Navy", "location": {"name": "Off Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "For conspicuous gallantry and intrepidity at the risk of his life above and beyond the call of duty as commanding officer of the USS LCS(L)(3)-122 during operations against enemy Japanese forces in the Ryukyu chain, 10 and 11 June 1945. Sharply vigilant during hostile air raids against Allied ships on radar picket duty off Okinawa on 10 June, Lt. McCool aided materially in evacuating all survivors from a sinking destroyer which had sustained mortal damage under the devastating attacks. When his own craft was attacked simultaneously by 2 of the enemy's suicide squadron early in the evening of 11 June, he instantly hurled the full power of his gun batteries against the plunging aircraft, shooting down the first and damaging the second before it crashed his station in the conning tower and engulfed the immediate area in a mass of flames. …", "facts": [["Recipient", "Richard M. McCool"], ["Rank", "Lieutenant"], ["Service", "Navy"], ["Place of action", "Off Okinawa, Ryukyu Islands"]], "wiki": {"Richard M. McCool": "Richard_Miles_McCool"}},
  {"id": "1945-06-19-meagher-john-w", "date": "1945-06-19", "title": "Technical Sergeant John W. Meagher", "type": "attack", "theater": "Army", "location": {"name": "Near Ozato, Okinawa, Ryukyu Islands", "lat": 26.4794, "lng": 127.9278}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity above and beyond the call of duty. In the heat of the fight, he mounted an assault tank, and, with bullets splattering about him, designated targets to the gunner. Seeing an enemy soldier carrying an explosive charge dash for the tank treads, he shouted fire orders to the gunner, leaped from the tank, and bayoneted the charging soldier. Knocked unconscious and his rifle destroyed, he regained consciousness, secured a machinegun from the tank, and began a furious 1-man assault on the enemy. Firing from his hip, moving through vicious crossfire that ripped through his clothing, he charged the nearest pillbox, killing 6. Going on amid the hail of bullets and grenades, he dashed for a second enemy gun, running out of ammunition just as he reached the position. He grasped his empty gun by the barrel and in a violent onslaught killed the crew. By his fearless assaults T/Sgt. …", "facts": [["Recipient", "John W. Meagher"], ["Rank", "Technical Sergeant"], ["Service", "Army"], ["Place of action", "Near Ozato, Okinawa, Ryukyu Islands"]], "wiki": {"John W. Meagher": "John_W._Meagher"}},
  {"id": "1945-07-29-mayfield-melvin", "date": "1945-07-29", "title": "Corporal Melvin Mayfield", "type": "attack", "theater": "Army", "location": {"name": "Cordillera Mountains, Luzon, Philippines (approx.)", "lat": 17.0, "lng": 121.0}, "zoom": 9, "summary": "He displayed conspicuous gallantry and intrepidity above and beyond the call of duty while fighting in the Cordillera Mountains of Luzon, Philippine Islands. When 2 Filipino companies were pinned down under a torrent of enemy fire that converged on them from a circular ridge commanding their position, Cpl. Mayfield, in a gallant single-handed effort to aid them, rushed from shell hole to shell hole until he reached 4 enemy caves atop the barren fire-swept hill. With grenades and his carbine, he assaulted each of the caves while enemy fire pounded about him. However, before he annihilated the last hostile redoubt, a machinegun bullet destroyed his weapon and slashed his left hand. Disregarding his wound, he secured more grenades and dauntlessly charged again into the face of pointblank fire to help destroy a hostile observation post. By his gallant determination and heroic leadership, Cpl. Mayfield inspired the men to eliminate all remaining pockets of resistance in the area and to press the advance against the enemy.", "facts": [["Recipient", "Melvin Mayfield"], ["Rank", "Corporal"], ["Service", "Army"], ["Place of action", "Cordillera Mountains, Luzon, Philippines"]], "wiki": {"Melvin Mayfield": "Melvin_Mayfield"}},
];
